(window.PARENT_DIGEST = window.PARENT_DIGEST || {})[11] = {"grade":11,"subjects":[{"id":"toan","name":"Toán","b":[{"t":"Toán 11, tập 1","c":[{"t":"Chương I. Hàm số lượng giác và phương trình lượng giác","l":[{"t":"Bài 1. Giá trị lượng giác của góc lượng giác","req":["Đổi số đo giữa độ và rađian; tính độ dài cung tròn.","Tính các giá trị lượng giác của một góc từ giá trị đã biết, dùng đường tròn lượng giác và công thức góc liên quan."],"m":[{"t":"Đổi độ – rađian và tính độ dài cung","w":"Đề cho số đo bằng độ hoặc rađian cần đổi qua lại, hoặc hỏi độ dài cung, quãng đường bánh xe lăn, số vòng quay.","s":["Nhớ π rad = 180°.","Độ → rađian: nhân với π/180; rađian → độ: nhân với 180/π.","Độ dài cung l = R·α với α tính bằng rađian (đổi α về rađian trước).","Quãng đường bánh xe = số vòng × chu vi 2πR."],"n":["Tuyệt đối không thay α độ vào công thức l = Rα.","Giữ kết quả dạng kπ cho chính xác, chỉ lấy số thập phân khi đề yêu cầu."]},{"t":"Tính các giá trị lượng giác khi biết một giá trị","w":"Cho sin α (hoặc cos, tan, cot) và khoảng chứa α, yêu cầu tính các giá trị còn lại.","s":["Xác định góc phần tư của α từ khoảng đã cho để biết dấu của sin, cos, tan, cot.","Dùng sin²α + cos²α = 1 để tính giá trị còn thiếu (lấy căn rồi chọn dấu).","Tính tan α = sin α / cos α và cot α = 1 / tan α.","Kiểm tra lại bằng 1 + tan²α = 1/cos²α."],"n":["Bước chọn dấu là chỗ dễ sai nhất: luôn vẽ đường tròn lượng giác nháp.","Nếu đề chỉ cho tan α, dùng 1 + tan²α = 1/cos²α để tìm cos²α trước."]}],"sum":["Góc lượng giác (Ou, Ov) có số đo α + k·360° (hay α + k·2π, k ∈ ℤ). Đơn vị rađian: π rad = 180°, 1 rad = (180/π)° ≈ 57°17′45″.","Khái niệm: Góc lượng giác (Ou, Ov) có số đo α + k·360° (hay α + k·2π, k ∈ ℤ).","Đường tròn lượng giác là đường tròn…: Đường tròn lượng giác là đường tròn tâm O bán kính 1, chiều dương ngược chiều kim đồng hồ, điểm gốc A(1;","Giá trị đặc biệt: Sin 30° = 1/2, cos 60° = 1/2; sin 45° = cos 45° = √2/2; sin 60° = cos 30° = √3/2; tan 45° = 1; tan 30° = √3/3; tan 60° = √3."],"e":["Hay nhầm: Đảo thứ tự: hoành độ là cos α, không phải sin α.","Hay nhầm: tan, cot không phải toạ độ của M.","Hay nhầm: Tung độ của M là sin α, không phải tan α.","Hay nhầm: Góc phần tư II mới có sin > 0, cos < 0.","Hay nhầm: Góc phần tư IV mới có sin < 0, cos > 0.","Hay nhầm: Góc phần tư I mới có cả hai dương."],"q":{"n":20,"lv":{"Biết":6,"Hiểu":7,"Vận dụng":4,"Nâng cao":3}}},{"t":"Bài 2. Công thức lượng giác","req":["Vận dụng công thức cộng, nhân đôi, hạ bậc để tính giá trị và rút gọn biểu thức lượng giác.","Vận dụng công thức biến đổi tích thành tổng và tổng thành tích."],"m":[{"t":"Tính giá trị lượng giác bằng công thức cộng","w":"Cần tính sin, cos, tan của góc như 15°, 75°, 105°, hoặc của a ± b khi biết sin, cos của a và b.","s":["Tách góc thành tổng/hiệu của hai góc đặc biệt (15° = 45° − 30°, 75° = 45° + 30°).","Chọn công thức cộng phù hợp.","Thay các giá trị sin, cos đã biết (nếu thiếu, tính từ sin² + cos² = 1 và xét dấu).","Tính và rút gọn."],"n":["Cẩn thận dấu giữa hai số hạng của cos(a ± b): cos(a + b) có dấu TRỪ.","Khi biết sin a, cần xác định cos a theo góc phần tư trước."]},{"t":"Công thức nhân đôi và hạ bậc","w":"Cho sin a hoặc cos a (hoặc tổng sin a + cos a), cần tính sin 2a, cos 2a, tan 2a; hoặc cần hạ bậc sin², cos².","s":["Tính đủ sin a và cos a (xét dấu theo khoảng của a).","Áp dụng sin 2a = 2 sin a cos a, cos 2a = 1 − 2 sin²a (hoặc 2cos²a − 1).","tan 2a = sin 2a / cos 2a.","Hạ bậc: thay sin²a, cos²a bằng biểu thức theo cos 2a để tích phân, giải phương trình."],"n":["Có ba dạng của cos 2a: chọn dạng chỉ chứa giá trị đã biết.","Cho sin a + cos a = m thì sin a cos a = (m² − 1)/2."]}],"sum":["Các công thức chính của bài.","Công thức"],"e":["Hay nhầm: Dấu trừ là của sin(a − b).","Hay nhầm: Đây là công thức của cos(a − b).","Hay nhầm: Đây cũng là biểu thức của cos(a − b).","Hay nhầm: Đó là công thức của cos x + cos 3x.","Hay nhầm: Công thức tổng thành tích của sin + sin không cho tích hai sin.","Hay nhầm: sin 4x không bằng tổng sin x + sin 3x."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":3}}},{"t":"Bài 3. Hàm số lượng giác","req":["Tìm tập xác định, tập giá trị; xét tính chẵn lẻ và tính tuần hoàn của hàm số lượng giác.","Đọc đồ thị hàm y = sin x, cos x, tan x, cot x và dùng đồ thị để tìm nghiệm, khoảng đồng biến, nghịch biến."],"m":[{"t":"Tìm tập xác định của hàm số lượng giác","w":"Hàm có tan, cot hoặc phân thức chứa sin, cos ở mẫu, hoặc căn thức chứa biểu thức lượng giác.","s":["Liệt kê điều kiện: mẫu ≠ 0; biểu thức dưới căn ≥ 0; tan u cần cos u ≠ 0; cot u cần sin u ≠ 0.","Giải từng điều kiện bằng phương trình lượng giác cơ bản.","Loại các giá trị cấm khỏi ℝ, viết dạng ℝ \\ {…}.","Kết hợp nếu có nhiều điều kiện."],"n":["Đừng quên điều kiện của tan, cot dù không viết ở mẫu.","sin x ≠ 1 ⇔ x ≠ π/2 + k2π."]},{"t":"Tìm tập giá trị, GTLN, GTNN","w":"Hàm có dạng a·sin(ux + v) + b hoặc a·cos(ux + v) + b, hoặc chứa căn bậc hai của biểu thức lượng giác.","s":["Dùng −1 ≤ sin ≤ 1 và −1 ≤ cos ≤ 1.","Nhân với a (đổi chiều bất đẳng thức nếu a < 0).","Cộng b rồi áp dụng thêm căn, nghịch đảo nếu cần.","Kết luận tập giá trị, GTLN, GTNN."],"n":["Với y = a sin x + b cos x dùng công thức tập giá trị [−√(a² + b²); √(a² + b²)].","Hàm có căn thì xét thêm điều kiện biểu thức dưới căn ≥ 0."]}],"sum":["Hàm y = sin x: tập xác định ℝ, tập giá trị [−1; 1], hàm lẻ, tuần hoàn chu kì 2π, đồng biến trên (−π/2 + k2π;","Hàm y = sin x: tập xác định ℝ, tập giá trị [−1: 1], hàm lẻ, tuần hoàn chu kì 2π, đồng biến trên (−π/2 + k2π;","Hàm y = cos x: tập xác định ℝ, tập giá trị [−1: 1], hàm chẵn, tuần hoàn chu kì 2π, đồng biến trên (−π + k2π; k2π), nghịch biến trên (k2π;","Hàm y = tan x: tập xác…: Hàm y = tan x: tập xác định ℝ \\ {π/2 + kπ}, tập giá trị ℝ, hàm lẻ, tuần hoàn chu kì π, đồng biến trên mỗi khoảng (−π/2 + kπ;","Hàm số y = f(x) tuần hoàn…: Hàm số y = f(x) tuần hoàn chu kì T nếu f(x + T) = f(x) với mọi x."],"e":["Hay nhầm: ℝ \\ {kπ} là tập xác định của cot x.","Hay nhầm: tan x không xác định tại π/2 + kπ nên không phải ℝ.","Hay nhầm: [−1; 1] là tập giá trị của sin, cos.","Hay nhầm: f(−x) = −f(x) ≠ f(x), không chẵn.","Hay nhầm: f(−x) = −f(x) cho thấy lẻ.","Hay nhầm: Không thể vừa chẵn vừa lẻ trừ hàm 0."],"q":{"n":18,"lv":{"Biết":6,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 4. Phương trình lượng giác cơ bản","req":["Giải các phương trình sin x = m, cos x = m, tan x = m, cot x = m.","Giải phương trình dạng sin u = sin v, cos u = cos v, và các bài toán thực tế dao động."],"m":[{"t":"Giải phương trình lượng giác cơ bản","w":"Phương trình dạng sin x = m, cos x = m, tan x = m, cot x = m, hoặc sin(ax + b) = m… với m là số đặc biệt hoặc dùng arcsin.","s":["Kiểm tra điều kiện có nghiệm (|m| ≤ 1 với sin, cos).","Tìm một góc α sao cho giá trị lượng giác bằng m (α đặc biệt hoặc α = arcsin m, arccos m, arctan m).","Viết nghiệm theo công thức tổng quát với k ∈ ℤ.","Với góc phức tạp ax + b, giải ra x bằng cách trừ b rồi chia a (chia cả chu kì k·2π)."],"n":["Công thức sin có hai họ nghiệm; công thức tan chỉ có một họ.","Nếu đề cho độ, dùng k·360° thay k·2π."]},{"t":"Phương trình sin u = sin v, cos u = cos v","w":"Hai vế đều là hàm lượng giác cùng loại, ví dụ sin 2x = sin(x + π/3), cos 3x = cos x; hoặc khác loại (sin = cos).","s":["Nếu khác loại, đổi về cùng loại bằng góc phụ nhau.","Áp dụng sin u = sin v ⇔ u = v + k2π hoặc u = π − v + k2π; cos u = cos v ⇔ u = ±v + k2π.","Giải mỗi phương trình bậc nhất theo x.","Gộp hoặc loại nghiệm trùng nếu cần."],"n":["tan u = tan v cần thêm điều kiện cos u ≠ 0, cos v ≠ 0.","Họ nghiệm có thể gộp bằng cách thay k theo chu kì nhỏ hơn."]}],"sum":["Phương trình sin x = m và cos x = m có nghiệm khi và chỉ khi |m| ≤ 1; tan x = m, cot x = m luôn có nghiệm với mọi m.","Công thức","Phương trình sin x = m và…: Phương trình sin x = m và cos x = m có nghiệm khi và chỉ khi |m| ≤ 1; tan x = m, cot x = m luôn có nghiệm với mọi m.","Khi gặp phương trình dạng sin u…: Khi gặp phương trình dạng sin u = sin v, cos u = cos v, đưa về công thức nghiệm."],"e":["Hay nhầm: Hai họ này tương ứng với sin x = √3/2.","Hay nhầm: Họ ±α + k2π là nghiệm của cos x = cos α.","Hay nhầm: Họ α + kπ là nghiệm của tan x = tan α.","Hay nhầm: Phương trình vô nghiệm nên không có họ nghiệm nào.","Hay nhầm: Hai vế bằng nhau tại x = 0 nên có nghiệm.","Hay nhầm: Chỉ có hai họ chứ không phải bốn."],"q":{"n":18,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":6,"Nâng cao":3}}}]},{"t":"Chương II. Dãy số. Cấp số cộng và cấp số nhân","l":[{"t":"Bài 5. Dãy số","req":["Nhận biết dãy số, cách cho dãy số bằng công thức và bằng hệ thức truy hồi.","Xét tính tăng, giảm, bị chặn của dãy số và giải bài toán thực tế bằng dãy số."],"m":[{"t":"Tìm số hạng của dãy khi biết công thức hoặc hệ thức truy hồi","w":"Đề cho uₙ = f(n) hoặc u₁ và uₙ₊₁ = g(uₙ), yêu cầu tính một vài số hạng, hoặc tìm n khi biết giá trị uₙ.","s":["Công thức tổng quát: thay trực tiếp n vào f(n).","Hệ thức truy hồi: tính lần lượt u₂ từ u₁, u₃ từ u₂, … cho đến số hạng cần tìm.","Tìm n khi biết uₙ = a: giải phương trình f(n) = a, nhận nghiệm n nguyên dương.","Kiểm tra lại bằng cách thế ngược."],"n":["Với truy hồi nhiều số hạng liền trước (như Fibonacci) cần cho đủ số hạng đầu.","Nghiệm n không nguyên dương nghĩa là a không phải số hạng của dãy."]},{"t":"Xét tính tăng, giảm của dãy số","w":"Đề hỏi dãy tăng, giảm hay không tăng không giảm; thường cho uₙ dạng phân thức hoặc có (−1)ⁿ.","s":["Viết uₙ₊₁ bằng cách thay n bằng n + 1.","Lập hiệu uₙ₊₁ − uₙ và quy đồng, rút gọn.","Xét dấu của hiệu với mọi n ∈ ℕ*: dương thì dãy tăng, âm thì dãy giảm.","Nếu dấu thay đổi (ví dụ có (−1)ⁿ) thì dãy không tăng, không giảm; có thể chỉ ra bằng ba số hạng đầu."],"n":["Với uₙ > 0 có thể xét tỉ số uₙ₊₁/uₙ so với 1.","Một phản ví dụ là đủ để kết luận dãy không tăng hoặc không giảm."]}],"sum":["Mỗi hàm số u xác định trên tập ℕ* các số nguyên dương gọi là một dãy số vô hạn (dãy số). Viết u = u(n), n ∈ ℕ*; u(n) kí hiệu là uₙ và gọi là số hạng thứ n (số hạng tổng quát).","Khái niệm: Mỗi hàm số u xác định trên tập ℕ* các số nguyên dương gọi là một dãy số vô hạn (dãy số).","Có ba cách cho dãy số: Bằng công thức của số hạng tổng quát","Dãy số (uₙ) bị chặn trên nếu…: Dãy số (uₙ) bị chặn trên nếu tồn tại số M sao cho uₙ ≤ M với mọi n; bị chặn dưới nếu tồn tại m sao cho uₙ ≥ m với mọi n; bị chặn nếu vừa bị chặn…"],"e":["Hay nhầm: Đó là định nghĩa dãy giảm.","Hay nhầm: Đó là điều kiện không âm, không liên quan tính tăng.","Hay nhầm: Đó là định nghĩa dãy bị chặn trên.","Hay nhầm: Hiệu dương nên không phải dãy giảm.","Hay nhầm: Hiệu luôn dương nên dãy tăng.","Hay nhầm: Hiệu khác 0 nên không phải dãy hằng."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 6. Cấp số cộng","req":["Nhận biết cấp số cộng, tìm số hạng đầu và công sai.","Vận dụng công thức số hạng tổng quát và tổng n số hạng đầu để giải toán thực tế."],"m":[{"t":"Nhận biết cấp số cộng, tìm u₁ và d","w":"Đề cho một dãy số hoặc cho hai số hạng, yêu cầu chứng minh là cấp số cộng hoặc tìm số hạng đầu và công sai.","s":["Tính hiệu uₙ₊₁ − uₙ của hai số hạng liên tiếp.","Nếu hiệu là hằng số d thì dãy là cấp số cộng với công sai d.","Cho hai số hạng uₘ, uₖ: d = (uₖ − uₘ)/(k − m).","Tìm u₁ = uₘ − (m − 1)d."],"n":["Ba số lập cấp số cộng: dùng a + c = 2b.","Đặt ba số liên tiếp là a − d, a, a + d giúp triệt tiêu d khi cộng."]},{"t":"Tính số hạng và tổng n số hạng đầu","w":"Đề hỏi uₙ hoặc Sₙ khi biết hai yếu tố trong u₁, d, n, uₙ, Sₙ.","s":["Xác định các đại lượng đã cho (u₁, d, n, uₙ).","Dùng uₙ = u₁ + (n − 1)d để tìm đại lượng còn thiếu của số hạng.","Dùng Sₙ = n(u₁ + uₙ)/2 (nếu biết uₙ) hoặc Sₙ = n[2u₁ + (n − 1)d]/2.","Thay số, tính."],"n":["Khi biết uₙ nên dùng công thức Sₙ = n(u₁ + uₙ)/2 cho gọn.","Số số hạng của dãy a, a + d, …, b là (b − a)/d + 1."]}],"sum":["Cấp số cộng là dãy số (hữu hạn hoặc vô hạn) trong đó kể từ số hạng thứ hai, mỗi số hạng bằng số hạng đứng ngay trước nó cộng với một số d không đổi: uₙ₊₁ = uₙ + d.","Khái niệm: Cấp số cộng là dãy số (hữu hạn hoặc vô hạn) trong đó kể từ số hạng thứ hai, mỗi số hạng bằng số hạng đứng ngay trước nó cộng với một số d không đổi:…"],"e":["Hay nhầm: Dãy này là cấp số nhân (công bội 2), hiệu không đổi không có.","Hay nhầm: Các hiệu là 2, 4, 2, không đều.","Hay nhầm: Hiệu là −2, 2, −2, không đều.","Hay nhầm: Đó là điều kiện của cấp số nhân.","Hay nhầm: Số hạng giữa phải là b, không phải c.","Hay nhầm: Không có quan hệ tích như vậy."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":6,"Nâng cao":2}}},{"t":"Bài 7. Cấp số nhân","req":["Nhận biết cấp số nhân, tìm số hạng đầu và công bội.","Vận dụng công thức số hạng tổng quát và tổng n số hạng đầu để giải toán thực tế."],"m":[{"t":"Nhận biết cấp số nhân, tìm u₁ và q","w":"Đề cho một dãy số hoặc một vài số hạng, yêu cầu xác định công bội và số hạng đầu.","s":["Tính tỉ số uₙ₊₁/uₙ của hai số hạng liên tiếp (uₙ ≠ 0).","Nếu tỉ số là hằng số q thì dãy là cấp số nhân công bội q.","Cho uₘ, uₖ: qᵏ⁻ᵐ = uₖ/uₘ; giải q (chú ý dấu).","Tìm u₁ = uₘ/qᵐ⁻¹."],"n":["Ba số lập cấp số nhân thì số ở giữa thoả b² = ac.","Dãy có số hạng bằng 0 (trừ dãy 0) không là cấp số nhân."]},{"t":"Tính số hạng và tổng n số hạng đầu","w":"Đề hỏi uₙ hoặc Sₙ khi biết u₁, q, n hoặc cần tìm n.","s":["Xác định u₁, q.","Dùng uₙ = u₁qⁿ⁻¹ để tìm số hạng; khi tìm n, đưa về qⁿ⁻¹ = uₙ/u₁ rồi so sánh luỹ thừa.","Dùng Sₙ = u₁(1 − qⁿ)/(1 − q) khi q ≠ 1.","Tính cẩn thận luỹ thừa của số âm."],"n":["q = 1 thì mọi số hạng bằng nhau, Sₙ = nu₁.","Lũy thừa chẵn của số âm là số dương."]}],"sum":["Cấp số nhân là dãy số (hữu hạn hoặc vô hạn) trong đó kể từ số hạng thứ hai, mỗi số hạng bằng tích của số hạng đứng ngay trước nó với một số q không đổi: uₙ₊₁ = uₙ·q.","Khái niệm: Cấp số nhân là dãy số (hữu hạn hoặc vô hạn) trong đó kể từ số hạng thứ hai, mỗi số hạng bằng tích của số hạng đứng ngay trước nó với một số q không…"],"e":["Hay nhầm: Đây là cấp số cộng công sai 2, tỉ số không đều.","Hay nhầm: Tỉ số lần lượt 2, 3/2, 4/3: không đều.","Hay nhầm: Đây là cấp số cộng, tỉ số không đều.","Hay nhầm: Đó là điều kiện cấp số cộng.","Hay nhầm: Không phải điều kiện của bất kỳ cấp số nào.","Hay nhầm: Không đúng cho cấp số nhân."],"q":{"n":17,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":6,"Nâng cao":2}}}]},{"t":"Chương III. Các số đặc trưng đo xu thế trung tâm của mẫu số liệu ghép nhóm","l":[{"t":"Bài 8. Mẫu số liệu ghép nhóm","req":["Lập bảng tần số ghép nhóm, tính tần số tích luỹ và tần số tương đối.","Đọc và vẽ biểu đồ cột (histogram) của mẫu số liệu ghép nhóm."],"m":[{"t":"Lập bảng tần số ghép nhóm từ mẫu số liệu thô","w":"Cho danh sách giá trị (điểm, chiều cao, cân nặng, thời gian) và yêu cầu chia nhóm, lập bảng.","s":["Tìm giá trị nhỏ nhất, lớn nhất; chọn số nhóm (thường 4 đến 7) và độ rộng nhóm đều.","Chia các nhóm dạng [a; b) liên tiếp, nhóm cuối có thể là [a; b].","Đếm số giá trị rơi vào mỗi nhóm (mỗi giá trị chỉ thuộc đúng một nhóm).","Kiểm tra tổng các tần số bằng cỡ mẫu n."],"n":["Đầu mút trái thuộc nhóm, đầu mút phải thuộc nhóm kế tiếp.","Tổng tần số tương đối phải bằng 100%."]},{"t":"Tính tần số tích luỹ và tần số tương đối","w":"Cho bảng tần số và hỏi có bao nhiêu giá trị nhỏ hơn một mốc, hoặc tỉ lệ phần trăm của một nhóm.","s":["Cỡ mẫu n = tổng các tần số.","Tần số tương đối nhóm i: nᵢ/n nhân 100%.","Tần số tích luỹ nhóm i: cộng dồn từ nhóm đầu đến nhóm i.","Số giá trị nhỏ hơn mốc aᵢ₊₁ bằng tần số tích luỹ của nhóm i."],"n":["Tần số tích luỹ của nhóm cuối bằng n.","Mốc nằm giữa nhóm thì chỉ ước lượng được."]}],"sum":["Khi số liệu nhiều và phân tán, ta chia thành các nhóm [a₁; a₂), [a₂; a₃), …, [aₘ; aₘ₊₁) và đếm số giá trị rơi vào mỗi nhóm.","Khái niệm: Khi số liệu nhiều và phân tán, ta chia thành các nhóm [a₁; a₂), [a₂; a₃), …, [aₘ; aₘ₊₁) và đếm số giá trị rơi vào mỗi nhóm.","Đại diện của nhóm [aᵢ; aᵢ₊₁) là…: Đại diện của nhóm [aᵢ; aᵢ₊₁) là giá trị chính giữa xᵢ = (aᵢ + aᵢ₊₁)/2."],"e":["Hay nhầm: Cột thấp nhất mới có tần số nhỏ nhất.","Hay nhầm: Vị trí nằm trên trục hoành, không phải chiều cao.","Hay nhầm: Độ rộng các nhóm thường bằng nhau.","Hay nhầm: 100 chỉ đúng với tổng tần số tương đối (%).","Hay nhầm: Tần số tích luỹ nhóm đầu mới bằng tần số nhóm đầu.","Lưu ý: Đầu mút trái thuộc nhóm, đầu mút phải thuộc nhóm kế tiếp."],"q":{"n":17,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 9. Các số đặc trưng đo xu thế trung tâm","req":["Tính số trung bình, trung vị, tứ phân vị và mốt của mẫu số liệu ghép nhóm.","Hiểu ý nghĩa và dùng các số đặc trưng để so sánh hai mẫu số liệu."],"m":[{"t":"Tính số trung bình của mẫu ghép nhóm","w":"Cho bảng tần số ghép nhóm, yêu cầu tìm giá trị trung bình (tuổi thọ, thời gian, điểm).","s":["Lập bảng với giá trị đại diện xᵢ của mỗi nhóm.","Tính tích nᵢxᵢ rồi cộng lại.","Tính n = Σnᵢ.","x̄ = Σnᵢxᵢ / n."],"n":["Giá trị đại diện luôn là điểm giữa nhóm, không phải đầu mút.","Kết quả chỉ là ước lượng vì dùng đại diện."]},{"t":"Tính trung vị và tứ phân vị","w":"Bảng tần số ghép nhóm, cần Mₑ, Q₁, Q₃ hoặc khoảng tứ phân vị.","s":["Tính n và tần số tích luỹ từng nhóm.","Chọn mốc k = n/2 (trung vị), n/4 (Q₁), 3n/4 (Q₃); tìm nhóm đầu tiên có tích luỹ ≥ k.","Dùng công thức a_p + [(k − cf_{p−1})/n_p]·độ rộng.","Δ_Q = Q₃ − Q₁."],"n":["Cẩn thận nhầm cf_{p−1} với cf_p.","Trung vị không bị ảnh hưởng nhiều bởi giá trị ngoại lai."]}],"sum":["Tứ phân vị: Q₂ = Mₑ; Q₁ tính tương tự trung vị nhưng thay n/2 bằng n/4;","Công thức","Tứ phân vị: Q₂ = Mₑ;"],"e":["Hay nhầm: Không liên quan đến trung bình.","Hay nhầm: Q₁ phụ thuộc vị trí n/4, không chỉ tần số.","Hay nhầm: Đại diện phụ thuộc vị trí nhóm.","Hay nhầm: Tích luỹ nhỏ nhất là nhóm đầu.","Hay nhầm: Trung bình bị kéo lệch bởi giá trị lớn.","Hay nhầm: Tổng bị ảnh hưởng trực tiếp."],"q":{"n":17,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":6,"Nâng cao":2}}}]},{"t":"Chương IV. Quan hệ song song trong không gian","l":[{"t":"Bài 10. Đường thẳng và mặt phẳng trong không gian","req":["Nắm các tính chất thừa nhận và cách xác định mặt phẳng trong không gian.","Tìm giao tuyến, giao điểm; nhận biết hình chóp, hình tứ diện."],"m":[{"t":"Tìm giao tuyến của hai mặt phẳng","w":"Hai mặt phẳng (P), (Q) cho bằng các điểm, đường thẳng trong một hình chóp hoặc tứ diện.","s":["Tìm hai điểm chung phân biệt của (P) và (Q) (một điểm chung thấy ngay, như đỉnh S).","Tìm điểm chung thứ hai: gọi giao điểm của hai đường thẳng cùng nằm trong hai mặt phẳng khác nhau (ví dụ AC ∩ BD = O).","Nối hai điểm chung: đó là giao tuyến.","Ghi rõ lập luận: “S ∈ (P) ∩ (Q), O ∈ (P) ∩ (Q) ⇒ SO = (P) ∩ (Q)”."],"n":["Cần đúng hai điểm chung; một điểm chưa đủ.","Nếu hai mặt phẳng chứa hai đường thẳng song song, giao tuyến song song với chúng (Bài 11)."]},{"t":"Tìm giao điểm của đường thẳng và mặt phẳng","w":"Cho đường thẳng d và mặt phẳng (P), tìm điểm d ∩ (P).","s":["Chọn mặt phẳng phụ (Q) chứa d.","Tìm giao tuyến Δ = (P) ∩ (Q).","Trong (Q), gọi M = d ∩ Δ.","Vì M ∈ Δ ⊂ (P) và M ∈ d nên M = d ∩ (P)."],"n":["Chọn (Q) sao cho dễ tìm giao tuyến với (P).","Nếu d ∥ Δ thì d song song với (P), không có giao điểm."]}],"sum":["Trong không gian, điểm, đường thẳng, mặt phẳng là các khái niệm cơ bản. Mặt phẳng (P) không có bề dày và vô hạn; thường vẽ bằng hình bình hành.","Khái niệm: Trong không gian, điểm, đường thẳng, mặt phẳng là các khái niệm cơ bản.","Các tính chất thừa nhận: Có một và chỉ một đường thẳng đi qua hai điểm phân biệt.","Cách xác định mặt phẳng: Qua ba điểm không thẳng hàng; qua một đường thẳng và một điểm ngoài nó; qua hai đường thẳng cắt nhau; qua hai đường thẳng song song.","Hình chóp S.A₁A₂…Aₙ: đỉnh S, đáy là…: Hình chóp S.A₁A₂…Aₙ: đỉnh S, đáy là đa giác A₁A₂…Aₙ, các mặt bên là tam giác."],"e":["Hay nhầm: Ba điểm không thẳng hàng xác định duy nhất một mặt phẳng.","Hay nhầm: Chỉ có đúng một mặt phẳng.","Hay nhầm: Luôn tồn tại mặt phẳng đi qua ba điểm.","Hay nhầm: Hai đường thẳng cắt nhau xác định một mặt phẳng.","Hay nhầm: Đường thẳng và điểm ngoài nó xác định một mặt phẳng.","Hay nhầm: Hai đường thẳng song song xác định một mặt phẳng."],"q":{"n":19,"lv":{"Biết":6,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 11. Hai đường thẳng song song","req":["Nhận biết vị trí tương đối của hai đường thẳng trong không gian.","Vận dụng định lí giao tuyến song song, định lí Thalès và hình lăng trụ để chứng minh, tính toán."],"m":[{"t":"Chứng minh hai đường thẳng song song","w":"Đề yêu cầu chứng minh MN ∥ BC, hoặc giao tuyến song song với một đường cho trước.","s":["Tìm một tam giác (hoặc hình thang) chứa hai đường đó; dùng đường trung bình hoặc Thalès đảo (SM/SA = SN/SB).","Hoặc dùng định lí giao tuyến: hai mặt phẳng chứa hai đường song song ⇒ giao tuyến song song với chúng.","Hoặc chứng minh cùng song song với đường thứ ba.","Kết luận, nêu rõ quan hệ đã dùng."],"n":["M, N là trung điểm ⇒ MN là đường trung bình ⇒ MN ∥ AB, MN = AB/2.","Trong không gian cần chỉ ra hai đường đồng phẳng."]},{"t":"Tính độ dài bằng Thalès và đường trung bình","w":"Cho tỉ số các đoạn trên cạnh bên, yêu cầu tìm độ dài đoạn song song với đáy.","s":["Xác định đường thẳng MN song song cạnh đáy AB trong tam giác SAB.","Viết tỉ số SM/SA = SN/SB = MN/AB.","Thay giá trị đã cho và giải phương trình tìm đại lượng cần tìm.","Với trung điểm: SM/SA = 1/2 nên MN = AB/2."],"n":["Kiểm tra M, N cùng phía và cùng tỉ lệ.","Có thể dùng tỉ số đồng dạng để tính diện tích: tỉ số diện tích = bình phương tỉ số cạnh."]}],"sum":["Hai đường thẳng a, b trong không gian có ba vị trí tương đối: song song (cùng nằm trong một mặt phẳng, không có điểm chung); cắt nhau (có một điểm chung); chéo nhau (không cùng nằm trong một mặt…","Hai đường thẳng a, b trong không gian có ba vị trí tương đối: Song song (cùng nằm trong một mặt phẳng, không có điểm chung); cắt nhau (có một điểm chung); chéo nhau (không cùng nằm trong một mặt phẳng nào).","Qua một điểm nằm ngoài một đường…: Qua một điểm nằm ngoài một đường thẳng, có duy nhất một đường thẳng song song với đường thẳng đó.","Định lí giao tuyến: Nếu hai mặt phẳng phân biệt lần lượt chứa hai đường thẳng song song thì giao tuyến (nếu có) của chúng song song với hai đường thẳng đó hoặc trùng…"],"e":["Hay nhầm: Song song phải cùng nằm trong một mặt phẳng.","Hay nhầm: Cắt nhau có một điểm chung.","Hay nhầm: Trùng nhau có vô số điểm chung.","Hay nhầm: Không có điều kiện vuông góc.","Hay nhầm: a ∥ b nên không thể cắt nhau.","Hay nhầm: Không có quan hệ vuông góc nào."],"q":{"n":19,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 12. Đường thẳng và mặt phẳng song song","req":["Nhận biết đường thẳng song song với mặt phẳng và các điều kiện song song.","Chứng minh đường thẳng song song với mặt phẳng; tìm thiết diện, giao tuyến liên quan."],"m":[{"t":"Chứng minh đường thẳng song song với mặt phẳng","w":"Đề yêu cầu chứng minh d ∥ (P).","s":["Chỉ ra d không nằm trong (P).","Tìm đường thẳng a ⊂ (P) và chứng minh d ∥ a (đường trung bình, Thalès, hình bình hành…).","Kết luận d ∥ (P) theo điều kiện song song.","Trình bày rõ ba ý: d ⊄ (P), d ∥ a, a ⊂ (P)."],"n":["Thường a là cạnh đáy hoặc giao tuyến cần dựng.","Hai đường song song ở các mặt khác nhau cũng có thể dùng được."]},{"t":"Tìm giao tuyến của hai mặt phẳng khi biết đường song song","w":"Mặt phẳng (Q) chứa d, d ∥ (P); cần giao tuyến (P) ∩ (Q).","s":["Tìm một điểm chung của (P), (Q).","Qua điểm chung đó kẻ đường song song với d.","Giao tuyến là đường thẳng này.","Kiểm tra giao tuyến nằm trong cả hai mặt phẳng."],"n":["Cách này tránh phải tìm điểm chung thứ hai.","Nếu d ⊂ (P) thì không áp dụng được."]}],"sum":["Đường thẳng d và mặt phẳng (P) song song nếu chúng không có điểm chung, kí hiệu d ∥ (P). Điều kiện: nếu d không nằm trong (P) và d song song với một đường thẳng a nằm trong (P) thì d ∥ (P).","Khái niệm: Đường thẳng d và mặt phẳng (P) song song nếu chúng không có điểm chung, kí hiệu d ∥ (P).","Nếu đường thẳng d song song với…: Nếu đường thẳng d song song với mặt phẳng (P) thì mọi mặt phẳng (Q) chứa d mà cắt (P) đều cắt theo giao tuyến song song với d."],"e":["Hay nhầm: Cắt nhau thì có điểm chung.","Hay nhầm: d ⊂ (P) thì có vô số điểm chung.","Hay nhầm: Vuông góc là quan hệ khác.","Hay nhầm: Cắt đường a thì có điểm chung gần như chắc chắn.","Hay nhầm: Nằm trong (P) thì không song song.","Hay nhầm: Chéo nhau không kết luận được."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 13. Hai mặt phẳng song song","req":["Nhận biết hai mặt phẳng song song và các điều kiện song song.","Vận dụng định lí Thalès trong không gian và tính chất hình hộp, hình lăng trụ."],"m":[{"t":"Chứng minh hai mặt phẳng song song","w":"Cần chứng minh (P) ∥ (Q) trong hình hộp, lăng trụ, hình chóp.","s":["Chọn hai đường thẳng cắt nhau a, b nằm trong (P).","Chứng minh a ∥ (Q) và b ∥ (Q) (tìm đường trong (Q) song song với a, b).","Kết luận (P) ∥ (Q).","Nếu cần: dùng tính chất “hai mặt phẳng cùng song song mặt thứ ba thì song song”."],"n":["Hai đường phải cắt nhau, không được song song.","Trong hình hộp, hai mặt đối diện luôn song song."]},{"t":"Tính độ dài bằng Thalès trong không gian","w":"Ba (hoặc nhiều) mặt phẳng song song cắt hai đường thẳng, biết độ dài một số đoạn.","s":["Gọi các giao điểm trên hai đường thẳng: A, B, C và A′, B′, C′.","Viết AB/BC = A′B′/B′C′ (hoặc AB/AC = A′B′/A′C′).","Thay giá trị đã biết, giải phương trình bậc nhất.","Kiểm tra thứ tự các điểm cùng phía."],"n":["Chú ý đoạn nào là AB, đoạn nào là BC.","Cũng áp dụng khi hai đường thẳng chéo nhau."]}],"sum":["Hai mặt phẳng (P), (Q) song song nếu chúng không có điểm chung, kí hiệu (P) ∥ (Q). Điều kiện: nếu (P) chứa hai đường thẳng cắt nhau a, b cùng song song với (Q) thì (P) ∥ (Q).","Khái niệm: Hai mặt phẳng (P), (Q) song song nếu chúng không có điểm chung, kí hiệu (P) ∥ (Q).","Qua một điểm nằm ngoài mặt phẳng…: Qua một điểm nằm ngoài mặt phẳng (P) có duy nhất một mặt phẳng song song với (P).","Hình hộp ABCD.A′B′C′D′ có các mặt là…: Hình hộp ABCD.A′B′C′D′ có các mặt là hình bình hành; các mặt đối diện song song và bằng nhau; bốn đường chéo AC′, BD′, CA′, DB′ đồng quy tại trung…"],"e":["Hay nhầm: Một đường là chưa đủ, có thể cắt nhau.","Hay nhầm: Có điểm chung thì không song song.","Hay nhầm: Cắt nhau thì không song song.","Hay nhầm: (ABB′A′) cắt (ABCD) theo AB.","Hay nhầm: (BCC′B′) cắt (ABCD) theo BC.","Hay nhầm: (ACC′A′) cắt (ABCD) theo AC."],"q":{"n":17,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 14. Phép chiếu song song","req":["Hiểu phép chiếu song song và các tính chất bảo toàn.","Vẽ hình biểu diễn của một hình trong không gian và tính tỉ số đoạn thẳng qua phép chiếu."],"m":[{"t":"Tính tỉ số độ dài qua phép chiếu song song","w":"Biết tỉ số AB/BC hoặc điểm chia đoạn, yêu cầu tính tỉ số hoặc độ dài của ảnh.","s":["Kiểm tra các điểm thẳng hàng (hoặc các đoạn nằm trên hai đường song song).","Áp dụng bảo toàn tỉ số: A′B′/B′C′ = AB/BC.","Thay số, giải để tìm độ dài ảnh.","Lưu ý: độ dài tuyệt đối thường không giữ nguyên."],"n":["Hình chiếu của trung điểm là trung điểm.","Hình chiếu của đoạn song song với mặt chiếu cùng phương thì bằng đoạn gốc."]},{"t":"Vẽ hình biểu diễn của hình cho trước","w":"Cần vẽ hình chóp, lăng trụ, hình hộp trên giấy; hay xác định hình biểu diễn của hình vuông, hình tròn.","s":["Giữ nguyên quan hệ song song và tỉ số đoạn thẳng nằm trên một đường.","Hình phẳng đã cho: vẽ bằng hình bình hành, elip tương ứng.","Nét thấy vẽ liền, nét bị che khuất vẽ nét đứt.","Đặt tên các đỉnh theo đúng thứ tự."],"n":["Góc và độ dài tuyệt đối không được bảo toàn.","Chọn hình biểu diễn dễ thấy các quan hệ song song."]}],"sum":["Cho mặt phẳng (P) và đường thẳng Δ cắt (P). Với mỗi điểm M, đường thẳng qua M song song với Δ cắt (P) tại M′.","Cho mặt phẳng (P) và đường thẳng Δ cắt (P): Với mỗi điểm M, đường thẳng qua M song song với Δ cắt (P) tại M′.","Tính chất: Phép chiếu song song biến ba điểm thẳng hàng thành ba điểm thẳng hàng và bảo toàn thứ tự của chúng.","Hình biểu diễn của một hình trong…: Hình biểu diễn của một hình trong không gian trên mặt phẳng là hình chiếu song song của hình đó lên mặt phẳng theo một phương chiếu."],"e":["Hay nhầm: Hình thoi cần các cạnh bằng nhau, không được bảo toàn.","Hay nhầm: Hình vuông cần vuông góc, không được bảo toàn.","Hay nhầm: Hình tròn là ảnh của đường tròn.","Hay nhầm: Hình tròn chỉ khi mặt phẳng chứa đường tròn song song mặt chiếu.","Hay nhầm: Không có đỉnh nên không là hình bình hành.","Hay nhầm: Không có đỉnh nên không là hình thoi."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chương V. Giới hạn. Hàm số liên tục","l":[{"t":"Bài 15. Giới hạn của dãy số","req":["Hiểu định nghĩa giới hạn của dãy số và các giới hạn cơ bản.","Tính giới hạn dãy số dạng phân thức, có căn; tính tổng cấp số nhân lùi vô hạn."],"m":[{"t":"Tính giới hạn của dãy phân thức","w":"uₙ = P(n)/Q(n) với P, Q là đa thức của n (hoặc biểu thức có aⁿ).","s":["Tìm luỹ thừa cao nhất của n ở mẫu (hoặc cơ số lớn nhất nếu có aⁿ).","Chia cả tử và mẫu cho luỹ thừa đó.","Dùng lim 1/nᵏ = 0, lim qⁿ = 0 (|q| < 1).","Tính giới hạn của thương hai biểu thức hằng."],"n":["Bậc tử = bậc mẫu: giới hạn bằng thương hai hệ số cao nhất.","Bậc tử < bậc mẫu: giới hạn 0; bậc tử > bậc mẫu: giới hạn ±∞."]},{"t":"Giới hạn có căn: nhân lượng liên hợp","w":"Có hiệu hai căn hoặc căn trừ đi một biểu thức, ví dụ √(n² + n) − n, dạng ∞ − ∞.","s":["Nhân và chia với biểu thức liên hợp (√A + √B).","Rút gọn tử: A − B.","Chia tử và mẫu cho n (luỹ thừa cao nhất, nhớ √n² = n).","Tính giới hạn."],"n":["Với n > 0: √(n² + k) = n·√(1 + k/n²).","Đừng quên dấu căn khi chia: chia cho n thì chia vào trong căn cho n²."]}],"sum":["Dãy số (uₙ) có giới hạn 0 khi n dần tới dương vô cực nếu |uₙ| nhỏ hơn một số dương bé tuỳ ý kể từ một số hạng nào đó trở đi; kí hiệu lim uₙ = 0.","Khái niệm: Dãy số (uₙ) có giới hạn 0 khi n dần tới dương vô cực nếu |uₙ| nhỏ hơn một số dương bé tuỳ ý kể từ một số hạng nào đó trở đi; kí hiệu lim uₙ = 0.","Tổng của cấp số nhân lùi vô hạn (|q| < 1): S = u₁ + u₁q + u₁q² + … = u₁/(1 − q)."],"e":["Hay nhầm: n² luôn dương, không đến −∞.","Hay nhầm: q > 1 làm tổng tăng không giới hạn.","Hay nhầm: u₁ = 0 chỉ là trường hợp tầm thường.","Lưu ý: Bậc tử = bậc mẫu: giới hạn bằng thương hai hệ số cao nhất.","Lưu ý: Bậc tử < bậc mẫu: giới hạn 0; bậc tử > bậc mẫu: giới hạn ±∞.","Lưu ý: Với n > 0: √(n² + k) = n·√(1 + k/n²)."],"q":{"n":18,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":6,"Nâng cao":2}}},{"t":"Bài 16. Giới hạn của hàm số","req":["Hiểu giới hạn hữu hạn, giới hạn một bên và giới hạn tại vô cực của hàm số.","Tính các giới hạn dạng 0/0, dạng ∞/∞ và các giới hạn có căn."],"m":[{"t":"Giới hạn dạng 0/0: phân tích nhân tử, rút gọn","w":"Thay x = x₀ vào được 0/0 với tử và mẫu là đa thức.","s":["Thay x₀ nhận ra dạng 0/0.","Phân tích tử và mẫu có nhân tử chung (x − x₀).","Rút gọn (x − x₀) vì x ≠ x₀.","Thay x = x₀ vào biểu thức còn lại."],"n":["Dùng hằng đẳng thức a² − b², a³ − b³.","Có thể dùng chia đa thức hoặc sơ đồ Horner."]},{"t":"Giới hạn có căn: nhân lượng liên hợp","w":"Tử hoặc mẫu chứa căn và dạng 0/0, ví dụ (√(x + 1) − 1)/x khi x → 0.","s":["Nhân tử và mẫu với liên hợp của biểu thức có căn.","Dùng (a − b)(a + b) = a² − b² để khử căn.","Rút gọn nhân tử (x − x₀).","Thay x = x₀."],"n":["Liên hợp của √A − B là √A + B.","Với căn bậc ba dùng a³ − b³ = (a − b)(a² + ab + b²)."]}],"sum":["Cho hàm số f xác định trên khoảng chứa x₀ (có thể trừ x₀). Ta nói f(x) có giới hạn L khi x dần tới x₀, kí hiệu lim_{x→x₀} f(x) = L, nếu với mọi dãy (xₙ) trong tập xác định, xₙ ≠ x₀, xₙ → x₀ thì…","Cho hàm số f xác định trên khoảng chứa x₀ (có thể trừ x₀): Ta nói f(x) có giới hạn L khi x dần tới x₀, kí hiệu lim_{x→x₀} f(x) = L, nếu với mọi dãy (xₙ) trong tập xác định, xₙ ≠ x₀, xₙ → x₀ thì f(xₙ) → L.","Giới hạn một bên: Lim_{x→x₀⁺} f(x) (x > x₀) và lim_{x→x₀⁻} f(x) (x < x₀)."],"e":["Hay nhầm: lim_{x→0⁻} 1/x mới bằng −∞.","Hay nhầm: 1/x không tiến về 0 khi x → 0.","Hay nhầm: Mẫu tiến 0 nên không có giới hạn 0.","Hay nhầm: Không có giá trị hữu hạn.","Hay nhầm: f(x₀) có thể không tồn tại mà vẫn có giới hạn.","Hay nhầm: Giới hạn không đòi hỏi f xác định tại x₀."],"q":{"n":18,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":6,"Nâng cao":2}}},{"t":"Bài 17. Hàm số liên tục","req":["Nhận biết hàm số liên tục tại một điểm, trên một khoảng; xác định điểm gián đoạn.","Tìm tham số để hàm liên tục và chứng minh phương trình có nghiệm bằng tính liên tục."],"m":[{"t":"Xét tính liên tục của hàm số tại một điểm","w":"Cho hàm số cho bởi một biểu thức hoặc nhiều nhánh, hỏi hàm liên tục tại x₀ hay không.","s":["Tính f(x₀).","Tính lim_{x→x₀} f(x) (tính hai giới hạn một bên nếu hàm nhiều nhánh).","So sánh lim và f(x₀).","Bằng nhau thì liên tục; khác nhau hoặc giới hạn không tồn tại thì gián đoạn."],"n":["Hàm đa thức luôn liên tục trên ℝ.","Hàm phân thức gián đoạn tại các nghiệm của mẫu."]},{"t":"Tìm tham số để hàm số liên tục","w":"Hàm có hai nhánh hoặc có giá trị tại một điểm chứa tham số m.","s":["Tính giới hạn trái và phải (hoặc lim f) tại điểm nối.","Tính f(x₀) theo m.","Đặt phương trình lim = f(x₀) (cả hai giới hạn một bên bằng nhau).","Giải tìm m và kiểm tra."],"n":["Có khi cần hai điều kiện đồng thời.","Nhớ thay đúng nhánh khi tính f(x₀)."]}],"sum":["Hàm số y = f(x) xác định trên khoảng K, x₀ ∈ K. Hàm f liên tục tại x₀ nếu lim_{x→x₀} f(x) = f(x₀).","Hàm số y = f(x) xác định trên khoảng K, x₀ ∈ K: Hàm f liên tục tại x₀ nếu lim_{x→x₀} f(x) = f(x₀).","Các hàm đa thức, phân thức hữu…: Các hàm đa thức, phân thức hữu tỉ, lượng giác liên tục trên tập xác định của chúng."],"e":["Hay nhầm: f(x₀) = 0 không cần thiết.","Hay nhầm: Chỉ cần xác định tại và gần x₀.","Hay nhầm: tan x gián đoạn tại π/2 + kπ.","Hay nhầm: Có đổi dấu nên có nghiệm.","Hay nhầm: Không đủ để biết đúng hai nghiệm.","Hay nhầm: Có kết luận chắc chắn là có nghiệm."],"q":{"n":18,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":5,"Nâng cao":3}}}]}]},{"t":"Toán 11, tập 2","c":[{"t":"Chương VI. Hàm số mũ và hàm số lôgarit","l":[{"t":"Bài 18. Lũy thừa với số mũ thực","req":["Tính luỹ thừa với số mũ nguyên, căn bậc n, số mũ hữu tỉ và số mũ thực.","Vận dụng các tính chất của luỹ thừa để rút gọn biểu thức và so sánh."],"m":[{"t":"Tính giá trị biểu thức luỹ thừa","w":"Đề cho biểu thức số có luỹ thừa mũ âm, mũ hữu tỉ, căn.","s":["Đưa căn về luỹ thừa số mũ hữu tỉ: ⁿ√aᵐ = a^{m/n}.","Phân tích cơ số thành luỹ thừa của số nguyên tố (8 = 2³, 27 = 3³, 16 = 2⁴).","Áp dụng tính chất nhân, chia, luỹ thừa của luỹ thừa để cộng, trừ, nhân các số mũ.","Tính kết quả; số mũ âm thì lấy nghịch đảo."],"n":["Chỉ đổi mũ hữu tỉ với cơ số dương.","a⁻ⁿ = (1/a)ⁿ giúp tính nhanh luỹ thừa của phân số."]},{"t":"Rút gọn biểu thức chứa luỹ thừa","w":"Biểu thức có biến a, b > 0 cùng các luỹ thừa mũ hữu tỉ.","s":["Viết mọi căn dưới dạng luỹ thừa mũ hữu tỉ.","Nhóm các luỹ thừa cùng cơ số.","Cộng/trừ số mũ theo quy tắc.","Đưa kết quả về dạng gọn nhất, thay giá trị nếu đề cho."],"n":["Hằng đẳng thức vẫn dùng được, ví dụ (a^{1/2} + a^{−1/2})² = a + 2 + 1/a.","Chú ý điều kiện cơ số dương."]}],"sum":["Luỹ thừa với số mũ nguyên: aⁿ = a·a·…·a (n thừa số) với n nguyên dương; a⁰ = 1 (a ≠ 0); a⁻ⁿ = 1/aⁿ (a ≠ 0).","Luỹ thừa với số mũ nguyên: Aⁿ = a·a·…·a (n thừa số) với n nguyên dương; a⁰ = 1 (a ≠ 0); a⁻ⁿ = 1/aⁿ (a ≠ 0).","Nếu a > 1 thì a^α >…: Nếu a > 1 thì a^α > a^β ⇔ α > β; nếu 0 < a < 1 thì a^α > a^β ⇔ α < β."],"e":["Hay nhầm: a^{1/2} là căn bậc hai của a, không phải a².","Hay nhầm: Cơ số lớn hơn 1 nên chiều không đảo.","Hay nhầm: Hai số mũ khác nhau nên giá trị khác nhau.","Hay nhầm: Có thể so sánh bằng tính chất hàm mũ.","Lưu ý: Chỉ đổi mũ hữu tỉ với cơ số dương.","Lưu ý: a⁻ⁿ = (1/a)ⁿ giúp tính nhanh luỹ thừa của phân số."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 19. Lôgarit","req":["Hiểu định nghĩa lôgarit và tính các giá trị lôgarit cơ bản.","Vận dụng quy tắc tính và công thức đổi cơ số để biến đổi, tính giá trị biểu thức."],"m":[{"t":"Tính giá trị lôgarit theo định nghĩa","w":"Cần tính log_a b khi b là luỹ thừa hữu tỉ của a (như log₂ 8, log_{1/2} 4, log₄ 2).","s":["Đặt log_a b = x, tức aˣ = b.","Viết b dưới dạng luỹ thừa của a (hoặc đưa cả hai về cùng cơ số nguyên tố).","So sánh số mũ để tìm x.","Kiểm tra bằng cách thay lại."],"n":["log_a b có nghĩa khi a > 0, a ≠ 1, b > 0.","Cơ số nhỏ hơn 1 cho giá trị âm khi b > 1."]},{"t":"Tính, rút gọn biểu thức lôgarit bằng quy tắc","w":"Biểu thức có tổng, hiệu của nhiều lôgarit cùng cơ số, hoặc có hệ số đứng trước log.","s":["Đưa hệ số vào mũ: n·log_a M = log_a Mⁿ.","Gộp tổng thành tích, hiệu thành thương.","Rút gọn biểu thức trong dấu log về luỹ thừa của cơ số.","Tính theo định nghĩa."],"n":["Điều kiện của các biểu thức trong dấu log là dương.","Không có công thức cho log(M + N)."]}],"sum":["Cho a > 0, a ≠ 1 và b > 0. Số thực α thoả aᵅ = b gọi là lôgarit cơ số a của b, kí hiệu log_a b = α.","Cho a > 0, a ≠ 1 và b > 0: Số thực α thoả aᵅ = b gọi là lôgarit cơ số a của b, kí hiệu log_a b = α."],"e":["Hay nhầm: Không có công thức cho log(M + N).","Hay nhầm: Tích của log không bằng log của tích.","Hay nhầm: Lôgarit của thương bằng hiệu các lôgarit.","Hay nhầm: Không có công thức như vậy.","Lưu ý: log_a b có nghĩa khi a > 0, a ≠ 1, b > 0.","Lưu ý: Cơ số nhỏ hơn 1 cho giá trị âm khi b > 1."],"q":{"n":19,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 20. Hàm số mũ và hàm số lôgarit","req":["Nhận biết hàm số mũ, hàm số lôgarit; tính biến thiên và đồ thị của chúng.","Tìm tập xác định, so sánh giá trị và giải bài toán thực tế tăng trưởng."],"m":[{"t":"Tìm tập xác định của hàm số mũ, lôgarit","w":"Hàm có log_a u(x), aᵘ⁽ˣ⁾ (mũ luôn xác định), hoặc căn/phân thức chứa lôgarit.","s":["log_a u(x): điều kiện u(x) > 0 (và cơ số hợp lệ).","Căn √A: A ≥ 0; phân thức: mẫu ≠ 0.","Giải bất phương trình, hệ điều kiện.","Viết tập xác định dưới dạng khoảng/hợp khoảng."],"n":["Hàm mũ aᵘ⁽ˣ⁾ xác định khi u(x) xác định.","Kết hợp các điều kiện bằng giao các tập."]},{"t":"So sánh giá trị và xét chiều biến thiên","w":"So sánh 2^{√2} với 2^{1,4}; log₃ 5 với log₃ 7; xét hàm đồng biến hay nghịch biến.","s":["Xác định cơ số a > 1 hay 0 < a < 1.","Cùng cơ số: so sánh số mũ (hoặc biểu thức trong log) theo chiều biến thiên.","Khác cơ số: so sánh với số 1 hoặc đưa về cùng cơ số.","Kết luận."],"n":["log_a x > 0 ⇔ (a − 1)(x − 1) > 0.","Cơ số nhỏ hơn 1 đảo chiều bất đẳng thức."]}],"sum":["Hàm số mũ y = aˣ (a > 0, a ≠ 1): tập xác định ℝ, tập giá trị (0; +∞), đồng biến trên ℝ khi a > 1, nghịch biến trên ℝ khi 0 < a < 1.","Khái niệm: Hàm số mũ y = aˣ (a > 0, a ≠ 1): tập xác định ℝ, tập giá trị (0; +∞), đồng biến trên ℝ khi a > 1, nghịch biến trên ℝ khi 0 < a < 1.","Hàm số lôgarit y = log_a x…: Hàm số lôgarit y = log_a x (a > 0, a ≠ 1): tập xác định (0; +∞), tập giá trị ℝ, đồng biến khi a > 1, nghịch biến khi 0 < a < 1.","Hai hàm y = aˣ và y…: Hai hàm y = aˣ và y = log_a x là hai hàm ngược của nhau, đồ thị đối xứng qua đường thẳng y = x."],"e":["Hay nhầm: Cơ số lớn hơn 1 nên không nghịch biến.","Hay nhầm: ℝ là tập xác định của hàm mũ.","Hay nhầm: Với cơ số nhỏ hơn 1, số mũ lớn cho giá trị nhỏ hơn.","Hay nhầm: Hai số mũ khác nhau nên giá trị khác.","Hay nhầm: Cơ số 1/2 < 1 nên log₁/₂ 3 > log₁/₂ 5.","Lưu ý: Hàm mũ aᵘ⁽ˣ⁾ xác định khi u(x) xác định."],"q":{"n":18,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 21. Phương trình, bất phương trình mũ và lôgarit","req":["Giải phương trình, bất phương trình mũ và lôgarit cơ bản.","Giải bằng đưa về cùng cơ số, đặt ẩn phụ, mũ hoá và lôgarit hoá."],"m":[{"t":"Phương pháp đưa về cùng cơ số","w":"Hai vế đều có thể viết thành luỹ thừa của cùng cơ số: 2ˣ = 8, 3^{x−1} = 9, (1/2)ˣ > 4.","s":["Viết hai vế dưới dạng luỹ thừa cùng cơ số a.","Phương trình: so sánh số mũ (u = v).","Bất phương trình: xét a > 1 hay 0 < a < 1 để giữ hoặc đảo chiều.","Giải phương trình/bất phương trình bậc nhất, hợp lại."],"n":["Cơ số 0 < a < 1 làm đảo chiều bất đẳng thức.","Kiểm tra lại bằng cách thử nghiệm."]},{"t":"Đặt ẩn phụ để đưa về phương trình bậc hai","w":"Có dạng A·a^{2x} + B·aˣ + C = 0, ví dụ 4ˣ − 5·2ˣ + 4 = 0.","s":["Đặt t = aˣ (t > 0).","Giải phương trình bậc hai theo t, loại nghiệm t ≤ 0.","Với mỗi t > 0: giải aˣ = t để tìm x.","Kết luận tập nghiệm."],"n":["Nhớ điều kiện t > 0.","4ˣ = (2ˣ)² giúp chuyển cơ số."]}],"sum":["Khi giải phương trình lôgarit luôn đặt điều kiện biểu thức trong lôgarit dương, và thử lại nghiệm (đối chiếu điều kiện).","Công thức","Khi giải phương trình lôgarit luôn đặt…: Khi giải phương trình lôgarit luôn đặt điều kiện biểu thức trong lôgarit dương, và thử lại nghiệm (đối chiếu điều kiện)."],"e":["Hay nhầm: Dấu bằng làm log không xác định.","Hay nhầm: Điều kiện là x − 3 > 0, không phải x > 0.","Hay nhầm: Cơ số lớn hơn 1 giữ nguyên chiều.","Hay nhầm: x² = 4 chứ không phải x = 4.","Hay nhầm: x² = 2² = 4, không phải 16.","Lưu ý: Cơ số 0 < a < 1 làm đảo chiều bất đẳng thức."],"q":{"n":18,"lv":{"Biết":4,"Hiểu":8,"Vận dụng":4,"Nâng cao":2}}}]},{"t":"Chương VII. Quan hệ vuông góc trong không gian","l":[{"t":"Bài 22. Hai đường thẳng vuông góc","req":["Xác định góc giữa hai đường thẳng trong không gian và nhận biết hai đường thẳng vuông góc.","Tính góc giữa hai đường thẳng trong hình lập phương, hình chóp, tứ diện."],"m":[{"t":"Tính góc giữa hai đường thẳng","w":"Cho hai đường thẳng a, b (thường chéo nhau) trong hình lập phương, hình chóp, hình lăng trụ.","s":["Chọn điểm O (thường là đỉnh nằm trên một trong hai đường).","Qua O dựng đường thẳng song song với đường thẳng còn lại (dùng cạnh song song có sẵn trong hình).","Xác định tam giác chứa góc cần tìm.","Tính góc bằng tam giác đều, vuông cân, hệ thức lượng hoặc định lí côsin; kiểm tra góc ≤ 90°."],"n":["Nếu tính ra góc tù φ thì góc giữa hai đường thẳng là 180° − φ.","Trong hình lập phương mọi đường chéo mặt bằng nhau, thường xuất hiện tam giác đều."]},{"t":"Chứng minh hai đường thẳng vuông góc","w":"Đề yêu cầu chứng minh a ⟂ b trong hình không gian.","s":["Tính góc giữa a và b bằng cách đưa về hai đường cắt nhau (qua đường song song).","Chứng minh góc đó bằng 90° (định lí Pythagore đảo, tam giác vuông cân, đường chéo hình thoi, hình vuông…).","Hoặc dùng tính chất: a ∥ c và c ⟂ b thì a ⟂ b.","Hoặc dùng định lí đường thẳng vuông góc mặt phẳng (Bài 23)."],"n":["Tứ diện đều: AB ⟂ CD, AC ⟂ BD, AD ⟂ BC.","Hai đường chéo hình vuông, hình thoi vuông góc nhau."]}],"sum":["Góc giữa hai đường thẳng a và b trong không gian là góc giữa hai đường thẳng a′, b′ cùng đi qua một điểm O và lần lượt song song (hoặc trùng) với a, b.","Khái niệm: Góc giữa hai đường thẳng a và b trong không gian là góc giữa hai đường thẳng a′, b′ cùng đi qua một điểm O và lần lượt song song (hoặc trùng) với a,…","Hai đường thẳng vuông góc: Góc giữa chúng bằng 90°, kí hiệu a ⟂ b.","Cách tính góc: Chọn điểm O thích hợp (thường là một đỉnh), dựng các đường thẳng đi qua O song song với hai đường đã cho (hoặc tìm trên hình có sẵn), rồi tính góc…"],"e":["Hay nhầm: 180° chỉ dùng với góc giữa hai tia/vectơ.","Hay nhầm: Góc giữa hai đường không thể tù.","Hay nhầm: Không thể song song với c khi a ⟂ c.","Hay nhầm: Góc là 90° chứ không phải 45°.","Hay nhầm: AC và A′B tạo góc 60°, không vuông góc.","Hay nhầm: AB′ và A′D′ tạo góc 60°, không vuông góc."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 23. Đường thẳng vuông góc với mặt phẳng","req":["Nhận biết và chứng minh đường thẳng vuông góc với mặt phẳng.","Vận dụng tính chất để chứng minh hai đường vuông góc, tìm tam giác vuông và tính độ dài."],"m":[{"t":"Chứng minh đường thẳng vuông góc với mặt phẳng","w":"Cần chứng minh d ⟂ (P), thường để suy ra d vuông góc với một đường nào đó.","s":["Tìm hai đường thẳng cắt nhau a, b nằm trong (P).","Chứng minh d ⟂ a và d ⟂ b (dùng giả thiết, tam giác vuông, định lí Pythagore đảo, đường chéo hình vuông…).","Kết luận d ⟂ (P).","Suy ra d vuông góc với mọi đường trong (P)."],"n":["Hai đường a, b phải cắt nhau.","Có thể dùng a ∥ b ⟂ (P) ⇒ a ⟂ (P)."]},{"t":"Tìm tam giác vuông và tính độ dài đoạn thẳng","w":"Hình chóp có cạnh bên vuông góc đáy; cần tìm các tam giác vuông, tính SB, SC, đường chéo.","s":["Từ SA ⟂ (ABCD): SA ⟂ AB, AC, AD ⇒ các tam giác SAB, SAC, SAD vuông tại A.","Dùng thêm BC ⟂ AB, BC ⟂ SA ⇒ BC ⟂ (SAB) ⇒ BC ⟂ SB (tam giác SBC vuông tại B).","Tính độ dài bằng định lí Pythagore: SB² = SA² + AB²…","Với hình hộp chữ nhật: d² = a² + b² + c²."],"n":["Trong hình chóp tứ giác có đáy chữ nhật và SA ⟂ đáy, cả bốn mặt bên đều là tam giác vuông.","Ghi chú tính SC² = SA² + AB² + AD²."]}],"sum":["Đường thẳng d vuông góc với mặt phẳng (P), kí hiệu d ⟂ (P), nếu d vuông góc với mọi đường thẳng nằm trong (P).","Khái niệm: Đường thẳng d vuông góc với mặt phẳng (P), kí hiệu d ⟂ (P), nếu d vuông góc với mọi đường thẳng nằm trong (P).","Tính chất: Có duy nhất một mặt phẳng đi qua một điểm cho trước và vuông góc với một đường thẳng cho trước; có duy nhất một đường thẳng đi qua một điểm cho…"],"e":["Hay nhầm: Chỉ một đường là chưa đủ.","Hay nhầm: Song song không liên quan vuông góc.","Hay nhầm: Nếu nằm trong (P) thì không vuông góc với (P).","Hay nhầm: Không thể song song với (P).","Hay nhầm: Mặt phẳng chứa AB không phải trung trực.","Hay nhầm: Song song AB không là trung trực."],"q":{"n":18,"lv":{"Biết":4,"Hiểu":7,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 24. Phép chiếu vuông góc. Góc giữa đường thẳng và mặt phẳng","req":["Hiểu phép chiếu vuông góc, định lí ba đường vuông góc.","Xác định và tính góc giữa đường thẳng và mặt phẳng."],"m":[{"t":"Xác định góc giữa đường thẳng và mặt phẳng","w":"Đề yêu cầu tính (SB, (ABCD)), (SC, (ABC)), (A′C, (ABCD)) …","s":["Tìm giao điểm O của đường thẳng d với (P) (nếu có).","Tìm hình chiếu vuông góc H của một điểm M ∈ d (M ≠ O) lên (P) (dùng đường vuông góc mp có sẵn).","Góc giữa d và (P) là ∠MOH.","Tính góc trong tam giác vuông MHO bằng sin, cos hoặc tan."],"n":["Hình chiếu của đường thẳng đi qua O và H.","Góc luôn nhọn (không quá 90°)."]},{"t":"Tính độ dài hình chiếu, quãng đường theo góc nghiêng","w":"Đoạn thẳng dài ℓ hợp với mặt phẳng góc φ; cần tính độ dài hình chiếu và độ cao.","s":["Hình chiếu của đoạn lên mặt phẳng có độ dài ℓ·cos φ.","Khoảng cách từ đầu mút đến mặt phẳng (độ cao) = ℓ·sin φ.","Thay số và tính.","Kiểm tra: (ℓ cos φ)² + (ℓ sin φ)² = ℓ²."],"n":["φ = 90° thì hình chiếu là một điểm.","φ = 0° thì hình chiếu bằng chính đoạn."]}],"sum":["Phép chiếu song song lên (P) theo phương vuông góc với (P) gọi là phép chiếu vuông góc lên (P).","Khái niệm: Phép chiếu song song lên (P) theo phương vuông góc với (P) gọi là phép chiếu vuông góc lên (P).","Định lí ba đường vuông góc: Cho đường thẳng a ⊂ (P) và b là đường thẳng không vuông góc (P) với hình chiếu b′ lên (P).","Góc giữa đường thẳng d và mặt phẳng (P): Nếu d ⟂ (P) thì góc bằng 90°; nếu d ∥ hoặc d ⊂ (P) thì góc bằng 0°; nếu d cắt (P) nhưng không vuông góc thì góc giữa d và (P) là góc giữa d và hình…"],"e":["Hay nhầm: Phải là chân đường vuông góc.","Hay nhầm: Không phải giao điểm tuỳ ý.","Hay nhầm: Điểm đối xứng không phải hình chiếu.","Hay nhầm: 180° dành cho góc giữa hai tia.","Hay nhầm: BD và SC chéo nhau, không song song.","Hay nhầm: AC và SB không song song."],"q":{"n":18,"lv":{"Biết":4,"Hiểu":7,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 25. Hai mặt phẳng vuông góc","req":["Hiểu góc nhị diện, góc giữa hai mặt phẳng và điều kiện hai mặt phẳng vuông góc.","Tính góc giữa hai mặt phẳng và diện tích hình chiếu; nhận biết hình lăng trụ đứng, hình chóp đều."],"m":[{"t":"Tính góc giữa hai mặt phẳng","w":"Đề hỏi góc giữa (SBC) và (ABCD), (A′BD) và (ABCD) …","s":["Xác định giao tuyến c của hai mặt phẳng.","Trong mỗi mặt phẳng, dựng đường thẳng vuông góc với c tại cùng một điểm.","Góc giữa hai đường đó là góc phẳng nhị diện (nhận góc nhọn).","Tính góc trong tam giác vuông (tan = đối/kề)."],"n":["Nếu SA ⟂ đáy, từ A hạ AH ⟂ BC thì ∠SHA là góc giữa (SBC) và đáy.","Góc giữa hai mặt phẳng luôn không quá 90°."]},{"t":"Chứng minh hai mặt phẳng vuông góc","w":"Cần chứng minh (P) ⟂ (Q).","s":["Tìm đường thẳng d ⊂ (P).","Chứng minh d ⟂ (Q) (hai đường cắt nhau trong (Q)).","Kết luận (P) ⟂ (Q).","Có thể dùng góc phẳng nhị diện bằng 90°."],"n":["Hình chóp có SA ⟂ đáy: mọi mặt phẳng chứa SA vuông góc đáy.","Mặt bên của lăng trụ đứng vuông góc đáy."]}],"sum":["Góc nhị diện: hình gồm hai nửa mặt phẳng có chung bờ a. Góc phẳng nhị diện là góc giữa hai tia vuông góc với bờ a tại cùng một điểm, mỗi tia nằm trong một nửa mặt phẳng.","Góc nhị diện: Hình gồm hai nửa mặt phẳng có chung bờ a.","Góc giữa hai mặt phẳng cắt nhau…: Góc giữa hai mặt phẳng cắt nhau là góc nhỏ nhất trong các góc tạo bởi hai đường thẳng lần lượt vuông góc với mỗi mặt phẳng (hoặc góc giữa hai đường…","Hình lăng trụ đứng có các cạnh…: Hình lăng trụ đứng có các cạnh bên vuông góc với đáy, các mặt bên là hình chữ nhật và vuông góc với đáy."],"e":["Hay nhầm: 180° là góc nhị diện lớn nhất.","Hay nhầm: Góc giữa hai mp không tù.","Hay nhầm: Song song không phải vuông góc.","Hay nhầm: Chứa đường song song thì chưa đủ.","Hay nhầm: Không giao nhau thì song song.","Hay nhầm: (SAC) cắt (ABCD) theo AC."],"q":{"n":19,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 26. Khoảng cách","req":["Xác định và tính khoảng cách từ một điểm đến đường thẳng, mặt phẳng; giữa hai đường thẳng song song, hai mặt phẳng song song.","Tính khoảng cách giữa đường thẳng và mặt phẳng song song, và khoảng cách giữa hai đường thẳng chéo nhau trong các trường hợp đơn giản."],"m":[{"t":"Tính khoảng cách từ điểm đến mặt phẳng","w":"Cần d(A, (SBC)), d(S, (ABCD)), d(A′, (ABCD)) …","s":["Nếu điểm nằm trên đường vuông góc với mặt phẳng thì khoảng cách là độ dài đoạn đó (ví dụ SA ⟂ (ABCD) ⇒ d(S, (ABCD)) = SA).","Ngược lại, dựng mặt phẳng phụ chứa điểm và vuông góc mặt phẳng đã cho; hạ đường vuông góc xuống giao tuyến.","Hoặc quy về điểm khác bằng đường thẳng song song (d(M, (P)) bằng nhau với mọi M ∈ a ∥ (P)).","Tính độ dài đoạn vuông góc bằng hệ thức lượng."],"n":["Có thể dùng công thức thể tích: d = 3V/S.","Chú ý điểm ở các phía khác nhau."]},{"t":"Khoảng cách từ điểm đến đường thẳng","w":"Cần d(A, BD), d(S, BC)… trong mặt phẳng hoặc không gian.","s":["Xác định chân đường vuông góc H từ điểm đến đường thẳng.","Nếu trong tam giác vuông tại A: AH = AB·AC/BC.","Trong không gian: hạ đường vuông góc xuống đáy rồi dùng định lí ba đường vuông góc.","Tính bằng hệ thức lượng."],"n":["Trong hình chữ nhật AB = a, AD = b: d(A, BD) = ab/BD.","Kiểm tra Pythagore."]}],"sum":["Khoảng cách từ điểm M đến đường thẳng a là độ dài đoạn MH, với H là hình chiếu vuông góc của M trên a.","Khái niệm: Khoảng cách từ điểm M đến đường thẳng a là độ dài đoạn MH, với H là hình chiếu vuông góc của M trên a.","Khoảng cách giữa đường thẳng a và…: Khoảng cách giữa đường thẳng a và mặt phẳng (P) song song với nó là khoảng cách từ một điểm bất kì của a đến (P)."],"e":["Hay nhầm: Đoạn MA tuỳ ý thường dài hơn khoảng cách.","Hay nhầm: Khoảng cách không liên quan góc 45°.","Hay nhầm: Khoảng cách là độ dài, không phải góc.","Hay nhầm: Bằng 0 chỉ khi đường nằm trong mặt.","Hay nhầm: Đoạn tuỳ ý dài hơn khoảng cách.","Hay nhầm: Chéo nhau nên khoảng cách dương."],"q":{"n":19,"lv":{"Biết":4,"Hiểu":7,"Vận dụng":6,"Nâng cao":2}}},{"t":"Bài 27. Thể tích","req":["Nắm công thức thể tích khối chóp, khối lăng trụ, khối hộp, khối chóp cụt đều.","Tính thể tích các khối đa diện và giải bài toán thực tế."],"m":[{"t":"Tính thể tích khối chóp, khối lăng trụ","w":"Cho đáy và chiều cao, hoặc cho cạnh và yếu tố vuông góc.","s":["Xác định đáy và tính diện tích đáy S.","Xác định chiều cao h (cạnh bên vuông góc đáy; đường cao từ đỉnh đến tâm đáy).","Lăng trụ: V = S·h. Chóp: V = S·h/3.","Thay số, ghi đơn vị (thể tích)."],"n":["Chiều cao khối chóp là khoảng cách từ đỉnh đến đáy, không phải cạnh bên.","Hình chóp đều: chiều cao SO với O là tâm đáy."]},{"t":"Tính thể tích bằng phân chia, tỉ số thể tích, khối chóp cụt","w":"Khối phức tạp cần cắt thành các khối đơn giản; cho các tỉ số trên cạnh bên; chóp cụt.","s":["Phân chia khối thành chóp, lăng trụ hoặc dùng V = V₁ − V₂.","Với S.A′B′C′: V′/V = (SA′/SA)(SB′/SB)(SC′/SC).","Khối chóp cụt: V = (h/3)(S₁ + S₂ + √(S₁S₂)).","Tứ diện vuông: V = (1/6)·OA·OB·OC."],"n":["Tỉ số thể tích chỉ dùng cho khối chóp tam giác có chung đỉnh.","Kiểm tra căn số hạng chính phương."]}],"sum":["Tỉ số thể tích: cho hình chóp S.ABC, các điểm A′ ∈ SA, B′ ∈ SB, C′ ∈ SC. Khi đó V_{S.A′B′C′}/V_{S.ABC} = (SA′/SA)·(SB′/SB)·(SC′/SC).","Công thức","Tỉ số thể tích: Cho hình chóp S.ABC, các điểm A′ ∈ SA, B′ ∈ SB, C′ ∈ SC."],"e":["Hay nhầm: Đó là công thức lăng trụ.","Hay nhầm: Hệ số là 1/3, không phải 1/2.","Hay nhầm: Công thức không có hệ số 3.","Hay nhầm: Cạnh bên thường dài hơn chiều cao.","Hay nhầm: Cạnh đáy không phải chiều cao.","Hay nhầm: Đường chéo đáy không liên quan."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":4,"Nâng cao":2}}}]},{"t":"Chương VIII. Quy tắc tính xác suất","l":[{"t":"Bài 28. Biến cố hợp, biến cố giao, biến cố độc lập","req":["Nhận biết biến cố hợp, biến cố giao, biến cố xung khắc, biến cố độc lập.","Xác định các biến cố đó bằng tập hợp kết quả và tính xác suất bằng định nghĩa cổ điển."],"m":[{"t":"Xác định biến cố hợp, giao, đối bằng cách liệt kê","w":"Phép thử có ít kết quả (xúc xắc, thẻ số, đồng xu) và hai biến cố A, B cho bằng lời.","s":["Liệt kê không gian mẫu Ω và các tập con A, B.","A ∪ B: gộp mọi phần tử của A và của B (mỗi phần tử một lần).","A ∩ B: các phần tử thuộc cả A và B.","Ā: các phần tử của Ω không thuộc A."],"n":["Dùng biểu đồ Venn để khỏi sót.","Kiểm tra n(A ∪ B) = n(A) + n(B) − n(A ∩ B)."]},{"t":"Nhận biết hai biến cố xung khắc, độc lập","w":"Đề hỏi hai biến cố có xung khắc không, có độc lập không.","s":["Xung khắc: kiểm tra A ∩ B = ∅ (không thể cùng xảy ra).","Độc lập: xét xem kết quả của lần/phép thử này có tác động tới xác suất kia không (ví dụ hai lần tung độc lập, bốc có hoàn lại).","Có thể kiểm tra P(AB) = P(A)P(B).","Kết luận."],"n":["Xung khắc và độc lập là hai khái niệm khác nhau; hai biến cố có xác suất dương và xung khắc thì không độc lập.","Bốc không hoàn lại thường không độc lập."]}],"sum":["Cho không gian mẫu Ω của một phép thử, A và B là hai biến cố. Biến cố hợp A ∪ B xảy ra khi A xảy ra hoặc B xảy ra (ít nhất một trong hai).","Cho không gian mẫu Ω của một phép thử, A và B là hai biến cố: Biến cố hợp A ∪ B xảy ra khi A xảy ra hoặc B xảy ra (ít nhất một trong hai).","Hai biến cố A và B xung…: Hai biến cố A và B xung khắc nếu chúng không thể cùng xảy ra, tức A ∩ B = ∅."],"e":["Hay nhầm: Đó là điều kiện hai biến cố đối nhau.","Hay nhầm: A = B là hai biến cố trùng nhau.","Hay nhầm: Xác suất bằng nhau không đủ để xung khắc.","Hay nhầm: A ∪ B ≠ Ω nên không đối nhau.","Hay nhầm: Độc lập sẽ mâu thuẫn với xung khắc.","Hay nhầm: Không có quan hệ bao hàm."],"q":{"n":17,"lv":{"Biết":4,"Hiểu":7,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 29. Công thức cộng xác suất","req":["Vận dụng công thức cộng xác suất cho hai biến cố xung khắc và hai biến cố bất kì.","Dùng biến cố đối và biểu đồ Venn để tính xác suất “ít nhất một”."],"m":[{"t":"Tính P(A ∪ B) khi biết P(A), P(B), P(A ∩ B)","w":"Đề cho ba xác suất hoặc số phần tử, yêu cầu P(A ∪ B).","s":["Xác định A, B có xung khắc không.","Xung khắc: cộng hai xác suất. Không xung khắc: trừ P(A ∩ B).","Thay số và rút gọn.","Kiểm tra 0 ≤ P ≤ 1."],"n":["Nếu cho số phần tử: P = n/n(Ω).","P(A ∪ B) ≥ max(P(A), P(B))."]},{"t":"Tính xác suất bằng biến cố đối","w":"Bài có chữ “ít nhất”, “không phải”, “khác”.","s":["Đặt biến cố cần tìm là A; xác định biến cố đối Ā đơn giản hơn (“không có …”).","Tính P(Ā).","P(A) = 1 − P(Ā).","Kiểm tra bằng cách ước lượng."],"n":["“Ít nhất một” ⇒ đối là “không có cái nào”.","Phù hợp khi cần đếm nhiều trường hợp."]}],"sum":["Công thức cộng mở rộng cho nhiều biến cố đôi một xung khắc: P(A₁ ∪ … ∪ Aₙ) = P(A₁) + … + P(Aₙ).","Công thức","Công thức cộng mở rộng cho nhiều biến cố đôi một xung khắc: P(A₁ ∪ … ∪ Aₙ) = P(A₁) + … + P(Aₙ)."],"e":["Hay nhầm: Chỉ đúng khi A, B xung khắc.","Hay nhầm: Đó là công thức nhân cho biến cố độc lập (A ∩ B).","Hay nhầm: Không phải công thức cộng.","Hay nhầm: Không có công thức nghịch đảo.","Lưu ý: Nếu cho số phần tử: P = n/n(Ω).","Lưu ý: P(A ∪ B) ≥ max(P(A), P(B))."],"q":{"n":19,"lv":{"Biết":4,"Hiểu":7,"Vận dụng":5,"Nâng cao":3}}},{"t":"Bài 30. Công thức nhân xác suất cho hai biến cố độc lập","req":["Vận dụng công thức nhân xác suất cho hai biến cố độc lập.","Dùng sơ đồ cây và biến cố đối để giải bài toán thực tế."],"m":[{"t":"Tính xác suất xảy ra đồng thời các biến cố độc lập","w":"Hai (hoặc nhiều) người/lần thử độc lập: hai xạ thủ bắn bia, tung nhiều lần đồng xu, lấy có hoàn lại.","s":["Đặt biến cố cho từng lần/người: A₁, A₂, ….","Xác định xác suất từng biến cố.","Kiểm tra tính độc lập.","Nhân: P(A₁A₂…) = P(A₁)·P(A₂)·…."],"n":["Bốc không hoàn lại thường không độc lập.","Biểu diễn bằng sơ đồ cây để khỏi sót nhánh."]},{"t":"Xác suất “ít nhất một” với biến cố độc lập","w":"Có nhiều người/lần thử độc lập và hỏi “ít nhất một trúng/thành công”.","s":["Xác định xác suất “không thành công” của từng biến cố.","Nhân các xác suất đó (độc lập).","P(ít nhất một) = 1 − tích vừa tính.","Rút gọn."],"n":["Đối của “ít nhất một” là “không có cái nào”.","Dùng khi số trường hợp thuận lợi quá nhiều."]}],"sum":["Mở rộng: nếu A₁, A₂, …, Aₙ độc lập từng đôi và lập thành các phép thử độc lập thì P(A₁A₂…Aₙ) = P(A₁)P(A₂)…P(Aₙ).","Công thức","Mở rộng: Nếu A₁, A₂, …, Aₙ độc lập từng đôi và lập thành các phép thử độc lập thì P(A₁A₂…Aₙ) = P(A₁)P(A₂)…P(Aₙ)."],"e":["Hay nhầm: Đó là điều kiện xung khắc cho công thức cộng.","Hay nhầm: Có thể cùng xảy ra (6 và 1).","Lưu ý: Bốc không hoàn lại thường không độc lập.","Lưu ý: Biểu diễn bằng sơ đồ cây để khỏi sót nhánh.","Lưu ý: Đối của “ít nhất một” là “không có cái nào”.","Lưu ý: Dùng khi số trường hợp thuận lợi quá nhiều."],"q":{"n":18,"lv":{"Biết":4,"Hiểu":7,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chương IX. Đạo hàm","l":[{"t":"Bài 31. Định nghĩa và ý nghĩa của đạo hàm","req":["Hiểu định nghĩa đạo hàm tại một điểm và ý nghĩa hình học, ý nghĩa vật lí.","Tính đạo hàm bằng định nghĩa, viết phương trình tiếp tuyến và tính vận tốc tức thời."],"m":[{"t":"Tính đạo hàm tại một điểm bằng định nghĩa","w":"Đề yêu cầu “dùng định nghĩa” tính f′(x₀), hoặc tính giới hạn có dạng [f(x) − f(x₀)]/(x − x₀).","s":["Tính f(x₀).","Lập tỉ số [f(x) − f(x₀)]/(x − x₀) và rút gọn (phân tích nhân tử).","Tìm giới hạn khi x → x₀.","Kết luận f′(x₀) bằng giới hạn đó."],"n":["Dạng 0/0 thường rút gọn được nhân tử (x − x₀).","Tính giới hạn một bên nếu hàm cho bởi nhiều nhánh."]},{"t":"Viết phương trình tiếp tuyến","w":"Cho đồ thị y = f(x) và điểm M(x₀; y₀) hoặc hệ số góc hoặc tiếp tuyến song song một đường.","s":["Tính f′(x) và hệ số góc k = f′(x₀).","Tại điểm M(x₀; y₀): y = k(x − x₀) + y₀.","Biết hệ số góc k (hoặc song song y = kx + m): giải f′(x₀) = k tìm x₀ rồi tính y₀.","Rút gọn và viết dạng y = kx + m."],"n":["Tiếp tuyến song song ⇒ cùng hệ số góc; vuông góc ⇒ tích hệ số góc bằng −1.","Kiểm tra điểm M thuộc đồ thị."]}],"sum":["Cho hàm số y = f(x) xác định trên khoảng (a; b) và x₀ ∈ (a; b). Giới hạn hữu hạn (nếu có) của f(x) − f(x₀) trên x − x₀ khi x → x₀ gọi là đạo hàm của f tại x₀, kí hiệu f′(x₀) hay y′(x₀).","Khái niệm: Cho hàm số y = f(x) xác định trên khoảng (a; b) và x₀ ∈ (a; b).","Hàm số có đạo hàm tại x₀…: Hàm số có đạo hàm tại x₀ thì liên tục tại x₀ (ngược lại không đúng, ví dụ y = |x| tại 0)."],"e":["Hay nhầm: Tung độ là f(x₀), không phải f′(x₀).","Hay nhầm: Không phải phương trình tiếp tuyến.","Hay nhầm: Không có giá trị bằng 0 bắt buộc.","Hay nhầm: Hai đạo hàm một bên khác nhau.","Lưu ý: Dạng 0/0 thường rút gọn được nhân tử (x − x₀).","Lưu ý: Tính giới hạn một bên nếu hàm cho bởi nhiều nhánh."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 32. Các quy tắc tính đạo hàm","req":["Thuộc đạo hàm của các hàm số thường gặp và các quy tắc tổng, hiệu, tích, thương, hàm hợp.","Tính đạo hàm các hàm số và giải bài toán liên quan (tiếp tuyến, phương trình f′ = 0)."],"m":[{"t":"Tính đạo hàm bằng bảng và quy tắc tổng, hiệu, tích, thương","w":"Hàm là đa thức, phân thức, tích hoặc thương của các hàm cơ bản.","s":["Nhận dạng cấu trúc: tổng/hiệu, tích, thương.","Áp dụng quy tắc tương ứng và bảng đạo hàm từng hàm cơ bản.","Thu gọn biểu thức đạo hàm.","Thay x₀ khi cần giá trị f′(x₀)."],"n":["Tích (uv)′ = u′v + uv′; thương cần bình phương mẫu.","Có thể khai triển đa thức trước khi đạo hàm."]},{"t":"Đạo hàm của hàm số hợp","w":"Hàm có dạng (ax + b)ⁿ, sin(ax + b), e^{u}, ln u, √u.","s":["Đặt u là biểu thức bên trong (hàm trong).","Đạo hàm hàm ngoài theo u, giữ nguyên u.","Nhân thêm u′.","Rút gọn và thay giá trị nếu cần."],"n":["Quên nhân u′ là lỗi phổ biến nhất.","Dùng liên tiếp nhiều lần nếu hàm lồng nhiều tầng."]}],"sum":["Các công thức chính của bài.","Công thức"],"e":["Hay nhầm: Đó là nghịch đảo của đạo hàm.","Hay nhầm: Đó là tử thức của quy tắc thương.","Lưu ý: Tích (uv)′ = u′v + uv′; thương cần bình phương mẫu.","Lưu ý: Có thể khai triển đa thức trước khi đạo hàm.","Lưu ý: Quên nhân u′ là lỗi phổ biến nhất.","Lưu ý: Dùng liên tiếp nhiều lần nếu hàm lồng nhiều tầng."],"q":{"n":20,"lv":{"Biết":7,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 33. Đạo hàm cấp hai","req":["Hiểu khái niệm đạo hàm cấp hai và tính đạo hàm cấp hai của các hàm số thường gặp.","Hiểu ý nghĩa cơ học: gia tốc tức thời là đạo hàm cấp hai của quãng đường theo thời gian."],"m":[{"t":"Tính đạo hàm cấp hai","w":"Cho hàm số y = f(x) và yêu cầu y″ hoặc giá trị f″(x₀).","s":["Tính đạo hàm cấp một f′(x).","Tính tiếp đạo hàm của f′(x).","Thu gọn f″(x).","Thay x₀ nếu cần giá trị f″(x₀)."],"n":["Không đạo hàm hai lần trong một bước.","Có thể dùng công thức nhanh cho xⁿ, sin, cos, eˣ."]},{"t":"Tính gia tốc của chuyển động","w":"Cho s(t) (quãng đường, toạ độ theo thời gian); hỏi vận tốc, gia tốc tại t₀ hoặc thời điểm gia tốc bằng 0.","s":["v(t) = s′(t).","a(t) = v′(t) = s″(t).","Thay t₀ để tính, hoặc giải a(t) = 0 tìm thời điểm.","Ghi đơn vị (m/s²)."],"n":["Gia tốc dương: vận tốc tăng; âm: vận tốc giảm.","Chuyển động đều có a = 0."]}],"sum":["Cho hàm số y = f(x) có đạo hàm f′(x) tại mọi x ∈ (a; b). Nếu f′ lại có đạo hàm tại x thì đạo hàm của f′ gọi là đạo hàm cấp hai của f, kí hiệu f″(x) hay y″: f″(x) = (f′(x))′.","Cho hàm số y = f(x) có đạo hàm f′(x) tại mọi x ∈ (a; b): Nếu f′ lại có đạo hàm tại x thì đạo hàm của f′ gọi là đạo hàm cấp hai của f, kí hiệu f″(x) hay y″: f″(x) = (f′(x))′.","Ý nghĩa cơ học: Nếu chất điểm chuyển động theo s = s(t) thì vận tốc tức thời v(t) = s′(t) và gia tốc tức thời a(t) = v′(t) = s″(t)."],"e":["Hay nhầm: Bậc ba không phải gia tốc.","Hay nhầm: Hệ số là n(n − 1), không phải n².","Hay nhầm: y″ = −y chứ không bằng y.","Lưu ý: Không đạo hàm hai lần trong một bước.","Lưu ý: Có thể dùng công thức nhanh cho xⁿ, sin, cos, eˣ.","Lưu ý: Gia tốc dương: vận tốc tăng; âm: vận tốc giảm."],"q":{"n":19,"lv":{"Biết":7,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}}]}]}]},{"id":"ly","name":"Vật lí","b":[{"t":"Vật lí 11","c":[{"t":"Chương 1. Dao động","l":[{"t":"Bài 1. Dao động điều hoà","req":["Nêu được khái niệm dao động, dao động tuần hoàn, dao động điều hoà và các đại lượng đặc trưng: biên độ, chu kì, tần số, tần số góc, pha.","Viết được phương trình dao động điều hoà và tính li độ, chu kì, tần số, quãng đường theo chu kì."],"m":[{"t":"Xác định các đại lượng từ phương trình dao động","w":"Đề cho x = A cos(ωt + φ) và hỏi biên độ, tần số góc, chu kì, tần số, pha ban đầu, li độ tại thời điểm t.","s":["So sánh phương trình với dạng chuẩn x = A cos(ωt + φ) để đọc A, ω, φ (chú ý đổi sin về cos: sin α = cos(α − π/2)).","Tính T = 2π/ω và f = ω/2π.","Thay t vào phương trình để tính li độ và pha tại thời điểm đó.","Kiểm tra đơn vị (cm hay m, rad hay độ)."],"n":["A luôn dương; nếu hệ số trước cos là âm, thêm π vào pha.","Máy tính phải để chế độ rađian."]},{"t":"Tính chu kì, tần số từ số dao động và quãng đường trong dao động","w":"Đề cho số dao động trong một khoảng thời gian, hoặc hỏi quãng đường vật đi được trong một số chu kì.","s":["Chu kì T = t/N (t: thời gian, N: số dao động toàn phần); tần số f = N/t.","Quãng đường trong 1 chu kì là 4A; trong n chu kì là 4nA; trong nửa chu kì là 2A.","Chiều dài quỹ đạo L = 2A nên A = L/2.","Đổi t ra chu kì (t/T) để tính quãng đường."],"n":["Chỉ riêng các khoảng 1/2 hoặc 1/4 chu kì mới tính nhanh được quãng đường: T/4 từ VTCB hoặc từ biên bằng A.","Quãng đường khác độ dịch chuyển; sau 1 chu kì độ dịch chuyển bằng 0."]}],"sum":["Dao động cơ là chuyển động qua lại của vật quanh một vị trí cân bằng (VTCB). Dao động tuần hoàn là dao động mà trạng thái dao động lặp lại như cũ sau những khoảng thời gian bằng nhau.","Khái niệm: Dao động cơ là chuyển động qua lại của vật quanh một vị trí cân bằng (VTCB).","Dao động điều hoà là dao động…: Dao động điều hoà là dao động trong đó li độ x của vật là một hàm côsin (hoặc sin) của thời gian.","Trong đó: A > 0 là biên độ (độ lệch cực đại so với VTCB);"],"e":["Hay nhầm: 4A là quãng đường cả chu kì.","Hay nhầm: Đó chưa phải vận tốc trung bình mà cũng không phải tốc độ trung bình.","Hay nhầm: 4A/T là tốc độ trung bình, không phải vận tốc trung bình.","Lưu ý: A luôn dương; nếu hệ số trước cos là âm, thêm π vào pha.","Lưu ý: Máy tính phải để chế độ rađian.","Lưu ý: Chỉ riêng các khoảng 1/2 hoặc 1/4 chu kì mới tính nhanh được quãng đường: T/4 từ VTCB hoặc từ biên bằng A."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 2. Mô tả dao động điều hoà","req":["Đọc được biên độ, chu kì, pha ban đầu từ đồ thị li độ – thời gian.","Xác định được độ lệch pha giữa hai dao động cùng tần số; nhận biết hai dao động cùng pha, ngược pha, vuông pha."],"m":[{"t":"Đọc đồ thị li độ – thời gian","w":"Cho đồ thị x(t) và yêu cầu tìm A, T, f, ω hoặc viết phương trình.","s":["A bằng độ lớn li độ cực đại đọc trên trục tung.","T bằng khoảng thời gian giữa hai điểm lặp lại liên tiếp (hai đỉnh, hoặc từ vị trí x = 0 đi lên đến lần tiếp theo).","ω = 2π/T; f = 1/T.","Pha ban đầu: xét x₀ tại t = 0: cos φ = x₀/A, chọn dấu của φ theo chiều chuyển động (đồ thị đang đi lên ứng với φ âm, đi xuống ứng với φ dương)."],"n":["Xác định chiều chuyển động bằng cách nhìn độ dốc của đồ thị tại t = 0.","Một đỉnh đến đỉnh liền kề là đúng một chu kì."]},{"t":"Tính và nhận biết độ lệch pha giữa hai dao động","w":"Cho hai phương trình cùng tần số hoặc hai đồ thị; hỏi dao động nào sớm pha, hai dao động cùng pha, ngược pha, vuông pha.","s":["Đưa cả hai phương trình về cùng hàm cos với biên độ dương.","Tính Δφ = φ₂ − φ₁.","So sánh Δφ với các giá trị đặc biệt: 0, π (ngược pha), π/2 (vuông pha) cộng bội 2π.","Δφ > 0: dao động 2 sớm pha hơn."],"n":["sin α = cos(α − π/2): chú ý đưa về cùng hàm.","Độ lệch pha chỉ so sánh được khi tần số bằng nhau."]}],"sum":["Đồ thị li độ – thời gian của dao động điều hoà là đường hình sin. Từ đồ thị có thể đọc: biên độ A (giá trị cực đại của x), chu kì T (khoảng thời gian giữa hai đỉnh liên tiếp), tần số f = 1/T và pha…","Khái niệm: Đồ thị li độ – thời gian của dao động điều hoà là đường hình sin.","Δφ = 2kπ: hai dao động cùng…: Δφ = 2kπ: hai dao động cùng pha (cùng lên, cùng xuống, cùng qua VTCB).","Ví dụ thực tế: Hai vật cùng dao động tuần hoàn trên hai con lắc giống nhau nhưng được thả ở hai thời điểm khác nhau có độ lệch pha Δφ = 2π·Δt/T, với Δt là khoảng…"],"e":["Hay nhầm: (2k + 1)π/2 là vuông pha.","Hay nhầm: Không phải giá trị đặc biệt.","Hay nhầm: Pha nhỏ hơn mới chậm pha.","Hay nhầm: Ngược pha khi φ₂ − φ₁ = π.","Lưu ý: Xác định chiều chuyển động bằng cách nhìn độ dốc của đồ thị tại t = 0.","Lưu ý: Một đỉnh đến đỉnh liền kề là đúng một chu kì."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 3. Vận tốc, gia tốc trong dao động điều hoà","req":["Viết được biểu thức vận tốc, gia tốc của dao động điều hoà và nhận biết độ lệch pha giữa x, v, a.","Tính vận tốc, gia tốc tại vị trí bất kì, tốc độ cực đại, gia tốc cực đại và dùng hệ thức độc lập với thời gian."],"m":[{"t":"Tính vận tốc, gia tốc tại thời điểm hoặc vị trí cho trước","w":"Đề cho x = A cos(ωt + φ) hoặc A, ω, x và hỏi v, a.","s":["Viết v = −ωA sin(ωt + φ), a = −ω²x.","Tại thời điểm t: thay t để tính pha, rồi tính sin, cos.","Tại vị trí x: dùng v² = ω²(A² − x²) (hai dấu: chiều chuyển động) và a = −ω²x.","Kiểm tra: v_max = ωA, a_max = ω²A."],"n":["Đổi A sang m (hoặc dùng đồng bộ cm), a có đơn vị cm/s² hoặc m/s².","Dấu của v phụ thuộc chiều chuyển động."]},{"t":"Tìm A, ω từ giá trị tức thời của x, v (a)","w":"Cho hai cặp giá trị (x, v) hoặc (v, a), hoặc v_max, a_max.","s":["Từ v_max = ωA và a_max = ω²A: ω = a_max/v_max; A = v_max²/a_max.","Từ hai cặp (x₁, v₁), (x₂, v₂): giải hệ A² = x₁² + v₁²/ω² = x₂² + v₂²/ω² để tìm ω.","Tính T = 2π/ω.","Kiểm tra lại với một cặp giá trị."],"n":["Dùng ω² = (v₁² − v₂²)/(x₂² − x₁²) khi hai cặp (x, v) cho trước.","Cẩn thận đơn vị khi lấy tỉ số."]}],"sum":["Vận tốc là đạo hàm của li độ theo thời gian, gia tốc là đạo hàm của vận tốc: v = x′, a = v′.","Khái niệm: Vận tốc là đạo hàm của li độ theo thời gian, gia tốc là đạo hàm của vận tốc: v = x′, a = v′.","Tốc độ cực đại v_max = ωA khi vật qua VTCB (x = 0): Gia tốc có độ lớn cực đại a_max = ω²A khi vật ở biên (x = ±A).","Hợp lực tác dụng lên vật dao…: Hợp lực tác dụng lên vật dao động điều hoà (lực kéo về) có độ lớn tỉ lệ với li độ và hướng về VTCB: F = ma = −mω²x."],"e":["Hay nhầm: Tại A/2 tốc độ nhỏ hơn cực đại.","Hay nhầm: Không liên quan chiều chuyển động.","Hay nhầm: Đồ thị v theo x mới là elip.","Lưu ý: Đổi A sang m (hoặc dùng đồng bộ cm), a có đơn vị cm/s² hoặc m/s².","Lưu ý: Dấu của v phụ thuộc chiều chuyển động.","Lưu ý: Dùng ω² = (v₁² − v₂²)/(x₂² − x₁²) khi hai cặp (x, v) cho trước."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 4. Bài tập về dao động điều hoà","req":["Vận dụng phương trình, vận tốc, gia tốc để giải bài tập về dao động điều hoà.","Vận dụng công thức chu kì của con lắc lò xo và con lắc đơn."],"m":[{"t":"Viết phương trình dao động điều hoà","w":"Đề cho A, T (hoặc ω, f) và trạng thái ban đầu (x₀, chiều chuyển động); yêu cầu viết x(t).","s":["Tính ω = 2π/T (hoặc ω = 2πf, ω = √(k/m)).","A: từ chiều dài quỹ đạo L = 2A, hoặc v_max = ωA, hoặc x₀ và v₀.","Pha ban đầu: từ điều kiện t = 0: x₀ = A cos φ, v₀ = −ωA sin φ (v > 0 thì sin φ < 0, v < 0 thì sin φ > 0).","Viết x = A cos(ωt + φ)."],"n":["Thả nhẹ tại biên dương: φ = 0; thả tại biên âm: φ = π.","Qua VTCB theo chiều dương: φ = −π/2; theo chiều âm: φ = +π/2."]},{"t":"Tính chu kì, tần số của con lắc lò xo, con lắc đơn","w":"Cho m, k, ℓ, g; hoặc thay đổi khối lượng, độ cứng, chiều dài rồi hỏi chu kì mới.","s":["Con lắc lò xo: T = 2π√(m/k); con lắc đơn: T = 2π√(ℓ/g).","Với bài thay đổi đại lượng: lập tỉ số T′/T = √(m′/m) (lò xo) hoặc √(ℓ′/ℓ) (con lắc đơn).","Thay số, tính T, f.","Chú ý đổi đơn vị (kg, N/m, m)."],"n":["Cắt ghép lò xo: k tỉ lệ nghịch chiều dài.","Thang máy hay xe chuyển động có gia tốc: g thay bằng g hiệu dụng."]}],"sum":["Con lắc lò xo gồm vật khối lượng m gắn vào lò xo có độ cứng k, đặt nằm ngang trên mặt phẳng không ma sát.","Khái niệm: Con lắc lò xo gồm vật khối lượng m gắn vào lò xo có độ cứng k, đặt nằm ngang trên mặt phẳng không ma sát.","Chu kì của con lắc lò xo…: Chu kì của con lắc lò xo không phụ thuộc biên độ, tăng khi khối lượng tăng (T ∝ √m) và giảm khi độ cứng tăng (T ∝ 1/√k)."],"e":["Hay nhầm: Không phụ thuộc khối lượng.","Hay nhầm: Dao động nhỏ thì T không phụ thuộc biên độ.","Hay nhầm: Không phụ thuộc cách kích thích.","Hay nhầm: Đó là biểu thức của f đã sai.","Lưu ý: Thả nhẹ tại biên dương: φ = 0; thả tại biên âm: φ = π.","Lưu ý: Qua VTCB theo chiều dương: φ = −π/2; theo chiều âm: φ = +π/2."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 5. Động năng. Thế năng. Sự chuyển hoá năng lượng trong dao động điều hoà","req":["Viết được biểu thức động năng, thế năng, cơ năng của vật dao động điều hoà.","Mô tả được sự chuyển hoá giữa động năng và thế năng; tính cơ năng, động năng, thế năng tại một vị trí."],"m":[{"t":"Tính cơ năng, động năng, thế năng","w":"Cho m, k, A, ω, x (hoặc v) và hỏi W, W_đ, W_t.","s":["Cơ năng W = ½kA² = ½mω²A² (A đổi sang mét).","Thế năng tại x: W_t = ½kx².","Động năng W_đ = W − W_t (hoặc ½mv²).","Kiểm tra W_đ ≥ 0, tức |x| ≤ A."],"n":["A, x phải đổi sang mét để năng lượng ra J.","k = mω²."]},{"t":"Vị trí mà W_đ = n·W_t và thời gian giữa các lần","w":"Đề hỏi li độ tại đó động năng bằng n lần thế năng, hoặc thời gian giữa hai lần liên tiếp W_đ = W_t.","s":["W_đ = nW_t ⇒ W = (n + 1)W_t ⇒ x² = A²/(n + 1).","Vị trí: x = ±A/√(n + 1).","Thời gian giữa hai lần liên tiếp W_đ = W_t bằng T/4.","Dùng đường tròn để tìm thời gian khi cần."],"n":["n = 1: x = ±A/√2; n = 3: x = ±A/2; n = 8: x = ±A/3.","Chọn nghiệm theo dấu li độ."]}],"sum":["Khi vật dao động điều hoà, động năng và thế năng của vật biến thiên tuần hoàn theo thời gian nhưng cơ năng được bảo toàn (khi không có ma sát).","Khái niệm: Khi vật dao động điều hoà, động năng và thế năng của vật biến thiên tuần hoàn theo thời gian nhưng cơ năng được bảo toàn (khi không có ma sát).","Chuyển hoá năng lượng: Từ biên về VTCB thế năng giảm, động năng tăng; từ VTCB ra biên động năng giảm, thế năng tăng.","Động năng và thế năng biến thiên…: Động năng và thế năng biến thiên tuần hoàn với tần số góc 2ω (tần số 2f, chu kì T/2)."],"e":["Hay nhầm: Không có tác dụng làm tăng.","Hay nhầm: Không có ma sát nên không giảm.","Hay nhầm: Cơ năng không biến thiên.","Hay nhầm: Tại A/2 động năng nhỏ hơn.","Hay nhầm: Đó là khi từ biên về VTCB.","Hay nhầm: Tổng bằng hằng số nên không cùng tăng."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 6. Dao động tắt dần. Dao động cưỡng bức. Hiện tượng cộng hưởng","req":["Nêu được đặc điểm của dao động tắt dần, dao động cưỡng bức và hiện tượng cộng hưởng.","Giải thích và vận dụng cộng hưởng trong đời sống; tính điều kiện cộng hưởng."],"m":[{"t":"Nhận biết loại dao động và điều kiện cộng hưởng","w":"Đề mô tả một dao động và hỏi là tắt dần, duy trì hay cưỡng bức; khi nào xảy ra cộng hưởng.","s":["Có ngoại lực tuần hoàn tác dụng liên tục: dao động cưỡng bức.","Biên độ giảm theo thời gian do ma sát: tắt dần.","Hệ tự bổ sung năng lượng để giữ biên độ: dao động duy trì.","Cộng hưởng khi f_ngoại lực = f₀ (hay chu kì ngoại lực bằng chu kì riêng)."],"n":["Tần số dao động cưỡng bức bằng tần số ngoại lực, không phải f₀.","Cộng hưởng rõ nhất khi ma sát nhỏ."]},{"t":"Bài toán cộng hưởng về tốc độ (xe, người đi bộ, đoàn tàu)","w":"Vật chịu kích thích tuần hoàn do mấp mô, mối nối ray, bước chân; hỏi tốc độ gây cộng hưởng.","s":["Xác định chu kì ngoại lực: T_ngoại = quãng đường giữa hai kích thích liên tiếp / tốc độ = d/v.","Cộng hưởng khi T_ngoại = T₀ (chu kì riêng).","Suy ra v = d/T₀.","Đổi đơn vị (m/s ↔ km/h: nhân 3,6)."],"n":["Tốc độ khác thì biên độ nhỏ hơn.","Giảm tốc độ hoặc tăng độ cứng giúp tránh cộng hưởng."]}],"sum":["Dao động tắt dần là dao động có biên độ giảm dần theo thời gian do lực cản của môi trường.","Khái niệm: Dao động tắt dần là dao động có biên độ giảm dần theo thời gian do lực cản của môi trường.","Dao động duy trì: Bổ sung năng lượng đúng lúc để dao động không tắt dần mà vẫn giữ tần số riêng (ví dụ con lắc đồng hồ).","Biên độ dao động cưỡng bức phụ…: Biên độ dao động cưỡng bức phụ thuộc vào biên độ của ngoại lực, lực cản của môi trường và độ chênh lệch giữa tần số ngoại lực f và tần số riêng f₀:…","Cộng hưởng có lợi: Hộp đàn, hộp cộng hưởng của nhạc cụ; máy đo tần số."],"e":["Hay nhầm: Lớn hơn thì biên độ không cực đại.","Hay nhầm: Ma sát lớn làm giảm cộng hưởng.","Hay nhầm: Không có ngoại lực thì không có dao động cưỡng bức.","Hay nhầm: Không có tác dụng chắc chắn.","Hay nhầm: Cộng hưởng có thể gây hại.","Hay nhầm: Không có ngoại lực bất kì."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 7. Bài tập về sự chuyển hoá năng lượng trong dao động điều hoà","req":["Vận dụng biểu thức động năng, thế năng, cơ năng và định luật bảo toàn cơ năng vào các bài toán dao động điều hoà.","Tìm vị trí, vận tốc, thời gian liên quan đến năng lượng; giải bài toán cộng hưởng và tắt dần ở mức đơn giản."],"m":[{"t":"Bảo toàn cơ năng giữa hai vị trí","w":"Biết v tại một vị trí và cần v tại vị trí khác (hoặc biết A, tìm v tại x).","s":["Viết W = ½mv₁² + ½kx₁² = ½mv₂² + ½kx₂².","Thay các đại lượng đã biết (đổi sang đơn vị SI).","Giải tìm đại lượng chưa biết (v₂² = v₁² + (k/m)(x₁² − x₂²)).","Lấy căn, xét dấu theo chiều chuyển động nếu cần."],"n":["Cơ năng có thể tính từ v_max hoặc từ A.","Dùng m/k = 1/ω² để rút gọn."]},{"t":"Tìm li độ, thời gian khi W_đ = nW_t","w":"Đề cho tỉ số W_đ/W_t (hoặc W_t/W) tại một thời điểm; tìm x, v hoặc thời gian giữa hai lần.","s":["Từ W_đ = nW_t ⇒ W_t = W/(n + 1) ⇒ x² = A²/(n + 1).","Tính x, và v = ωA√(n/(n + 1)).","Thời gian giữa hai lần liên tiếp W_đ = W_t là T/4.","Dùng đường tròn để tính thời gian khác."],"n":["Hệ số n có thể là phân số.","Kết quả x có hai dấu."]}],"sum":["Khi W_đ = nW_t: x = ±A/√(n + 1) và v = ±ωA√(n/(n + 1)). Khi W_đ = W_t: x = ±A/√2.","Công thức","Khi W_đ = nW_t: x = ±A/√(n + 1) và v = ±ωA√(n/(n + 1)): Khi W_đ = W_t: x = ±A/√2.","Với con lắc lò xo thẳng đứng…: Với con lắc lò xo thẳng đứng, chọn VTCB làm gốc thế năng đàn hồi + trọng lực thì biểu thức thế năng của hệ vẫn có dạng ½kx² (x tính từ VTCB)."],"e":["Hay nhầm: Không phụ thuộc chu kì trực tiếp.","Hay nhầm: W = ½kA² không phụ thuộc m.","Hay nhầm: Lực cản lớn nên tắt nhanh.","Lưu ý: Cơ năng có thể tính từ v_max hoặc từ A.","Lưu ý: Dùng m/k = 1/ω² để rút gọn.","Lưu ý: Hệ số n có thể là phân số."],"q":{"n":17,"lv":{"Biết":4,"Hiểu":7,"Vận dụng":4,"Nâng cao":2}}}]},{"t":"Chương 2. Sóng","l":[{"t":"Bài 8. Mô tả sóng","req":["Nêu được sóng cơ là gì, giải thích sự tạo thành sóng và các đại lượng đặc trưng: biên độ, chu kì, tần số, bước sóng, tốc độ truyền sóng.","Vận dụng hệ thức λ = vT = v/f và đọc được đồ thị u – x của sóng hình sin."],"m":[{"t":"Tìm chu kì, tần số, bước sóng, tốc độ truyền sóng","w":"Đề cho số ngọn sóng, khoảng thời gian, khoảng cách giữa các ngọn sóng, quãng đường sóng truyền được trong thời gian t.","s":["Chu kì T = t/N (N: số dao động trong thời gian t); f = 1/T.","Tốc độ truyền sóng v = s/t (quãng đường sóng truyền / thời gian).","Bước sóng λ = vT = v/f; hoặc λ là khoảng cách giữa hai ngọn sóng liên tiếp.","Giữa n ngọn sóng liên tiếp có (n − 1) bước sóng: λ = d/(n − 1)."],"n":["Đổi đơn vị: cm → m, ms → s.","Tốc độ truyền sóng phụ thuộc môi trường, bước sóng phụ thuộc cả v và f."]},{"t":"Độ lệch pha giữa hai điểm trên phương truyền sóng","w":"Cho khoảng cách d giữa hai điểm, hỏi chúng cùng pha, ngược pha hay vuông pha, hoặc tính Δφ.","s":["Tính λ = v/f.","Độ lệch pha Δφ = 2πd/λ.","Xét tỉ số d/λ: số nguyên → cùng pha; nửa nguyên → ngược pha; (2k + 1)/4 → vuông pha.","Điểm xa nguồn hơn dao động trễ pha hơn."],"n":["Hai điểm cùng pha cách nhau kλ; ngược pha cách nhau (k + 0,5)λ.","d = λ/4 ứng với Δφ = π/2."]}],"sum":["Sóng cơ là những dao động cơ lan truyền trong môi trường đàn hồi. Có hai nguyên nhân tạo nên sóng: có nguồn dao động bên ngoài tác dụng lên môi trường và có lực liên kết giữa các phần tử của môi…","Khái niệm: Sóng cơ là những dao động cơ lan truyền trong môi trường đàn hồi.","Sóng cơ không truyền được trong chân…: Sóng cơ không truyền được trong chân không vì cần môi trường vật chất.","Các đại lượng đặc trưng: Biên độ sóng A là độ lệch lớn nhất của phần tử sóng khỏi VTCB (bằng biên độ dao động của nguồn).","Độ lệch pha giữa hai điểm trên…: Độ lệch pha giữa hai điểm trên phương truyền sóng cách nhau d là Δφ = 2πd/λ."],"e":["Hay nhầm: Có truyền được trong chất rắn.","Hay nhầm: Có truyền được trong chất lỏng.","Hay nhầm: Có truyền được trong chất khí.","Hay nhầm: Phải là hai điểm gần nhất cùng pha.","Hay nhầm: Phần tử đi được 4A, không phải λ.","Hay nhầm: Vuông pha khi d = (2k+1)λ/4."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 9. Sóng ngang, sóng dọc. Sự truyền năng lượng của sóng cơ","req":["Phân biệt được sóng ngang và sóng dọc; nêu ví dụ thực tế.","Giải thích được sóng truyền năng lượng chứ không truyền phần tử vật chất và vận dụng mô hình sóng giải thích tính chất của âm."],"m":[{"t":"Nhận biết sóng ngang, sóng dọc","w":"Cho hình vẽ hoặc mô tả thí nghiệm và hỏi sóng thuộc loại nào, truyền được trong môi trường nào.","s":["Xác định phương dao động của phần tử và phương truyền sóng.","Hai phương vuông góc → sóng ngang; trùng nhau → sóng dọc.","Sóng dọc có vùng nén – dãn; sóng ngang có ngọn – lõm.","Nhớ: chất lỏng, chất khí chỉ truyền sóng dọc (trừ sóng mặt nước)."],"n":["Sóng âm trong không khí là sóng dọc.","Sóng điện từ là sóng ngang."]},{"t":"Tính bước sóng của sóng âm và sóng ánh sáng","w":"Cho tần số, tốc độ truyền, tìm bước sóng; hoặc cho dải tần số nghe được.","s":["λ = v/f.","Bước sóng ngắn nhất ứng với tần số lớn nhất; dài nhất ứng với tần số nhỏ nhất.","Âm trong không khí v ≈ 330–340 m/s; ánh sáng c = 3·10⁸ m/s.","Đổi đơn vị m, cm, μm."],"n":["Trong chân không mọi ánh sáng có cùng tốc độ c.","λ và f tỉ lệ nghịch khi v không đổi."]}],"sum":["Sóng ngang là sóng trong đó các phần tử môi trường dao động theo phương vuông góc với phương truyền sóng (sóng trên mặt nước, sóng trên dây đàn hồi).","Khái niệm: Sóng ngang là sóng trong đó các phần tử môi trường dao động theo phương vuông góc với phương truyền sóng (sóng trên mặt nước, sóng trên dây đàn hồi).","Sóng dọc là sóng trong đó các…: Sóng dọc là sóng trong đó các phần tử môi trường dao động theo phương trùng với phương truyền sóng (sóng trên lò xo, sóng âm trong không khí).","Quá trình truyền sóng là quá trình truyền năng lượng: Sóng mang năng lượng của nguồn đến mọi nơi trên phương truyền sóng mà không mang các phần tử vật chất đi theo.","Mô hình sóng dọc trên lò xo giúp giải thích sóng âm: Nguồn âm dao động làm các phân tử không khí dao động dọc theo phương truyền, tạo ra các lớp khí nén – dãn lan truyền."],"e":["Hay nhầm: Sóng dọc dao động trùng phương truyền.","Hay nhầm: Sóng âm trong không khí là sóng dọc.","Hay nhầm: Không phải sóng vô tuyến.","Hay nhầm: Phần tử không đi theo sóng.","Hay nhầm: Tốc độ phụ thuộc môi trường.","Hay nhầm: Truyền được trong không khí."],"q":{"n":16,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 10. Thực hành: Đo tần số của sóng âm","req":["Biết cách bố trí thí nghiệm và sử dụng dao động kí để đo chu kì, tần số của sóng âm.","Xử lí số liệu: tính tần số, giá trị trung bình, sai số và so sánh với tần số ghi trên âm thoa."],"m":[{"t":"Đọc chu kì và tính tần số từ màn hình dao động kí","w":"Cho số ô ứng với một chu kì và thang thời gian TIME/DIV.","s":["Đếm số ô n theo phương ngang ứng với một chu kì (hai đỉnh liên tiếp).","T = n × (thời gian mỗi ô).","f = 1/T.","Kiểm tra bằng cách đo nhiều chu kì rồi chia N để giảm sai số."],"n":["Đo N chu kì rồi lấy T = (tổng)/N chính xác hơn đo một chu kì.","Đổi ms → s trước khi lấy nghịch đảo."]},{"t":"Xử lí số liệu: giá trị trung bình và sai số","w":"Cho ba lần đo chu kì T₁, T₂, T₃ cần tính f trung bình và sai số.","s":["Tính T̄ = (T₁ + T₂ + T₃)/3.","Tính sai số tuyệt đối từng lần |Tᵢ − T̄| rồi lấy trung bình được ΔT.","f̄ = 1/T̄, sai số tương đối δ = ΔT/T̄ = Δf/f̄.","Viết kết quả f = f̄ ± Δf."],"n":["Sai số dụng cụ cộng thêm nửa độ chia nhỏ nhất nếu đề yêu cầu.","So sánh f̄ với tần số ghi trên âm thoa để nhận xét."]}],"sum":["Dụng cụ: dao động kí điện tử và dây đo; micro; bộ khuếch đại tín hiệu; âm thoa và búa cao su; giá đỡ và kẹp giữ âm thoa.","Dụng cụ: Dao động kí điện tử và dây đo; micro; bộ khuếch đại tín hiệu;","Tiến hành: Bố trí thí nghiệm, đặt micro cách âm thoa khoảng 20 cm, nối micro và bộ khuếch đại vào dao động kí.","Giảm ảnh hưởng của tiếng ồn bên ngoài: Làm thí nghiệm ở nơi yên tĩnh, để micro gần âm thoa, hiệu chỉnh độ khuếch đại."],"e":["Hay nhầm: Độ to không giảm sai số ngẫu nhiên.","Hay nhầm: Tần số không đổi theo khoảng cách.","Lưu ý: Đo N chu kì rồi lấy T = (tổng)/N chính xác hơn đo một chu kì.","Lưu ý: Đổi ms → s trước khi lấy nghịch đảo.","Lưu ý: Sai số dụng cụ cộng thêm nửa độ chia nhỏ nhất nếu đề yêu cầu.","Lưu ý: So sánh f̄ với tần số ghi trên âm thoa để nhận xét."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 11. Sóng điện từ","req":["Nêu được sóng điện từ là gì, tốc độ truyền trong chân không và thang sóng điện từ.","Nêu được tính chất, nguồn phát, ứng dụng của các loại sóng điện từ và tính bước sóng, tần số."],"m":[{"t":"Tính bước sóng, tần số của sóng điện từ","w":"Cho tần số (hoặc bước sóng) của sóng điện từ trong chân không và hỏi đại lượng còn lại.","s":["Dùng c = λf với c = 3·10⁸ m/s.","Đổi tần số sang Hz (MHz = 10⁶ Hz, GHz = 10⁹ Hz).","Tính λ = c/f hoặc f = c/λ.","Đổi bước sóng về đơn vị phù hợp (m, cm, μm, nm)."],"n":["Chỉ trong chân không (và gần đúng trong không khí) mới có c = 3·10⁸ m/s.","Bước sóng 0,5 m ứng f = 6·10⁸ Hz."]},{"t":"Tính thời gian truyền sóng điện từ (vệ tinh, đài phát)","w":"Tính thời gian tín hiệu đi từ đài phát qua vệ tinh về mặt đất, cho khoảng cách.","s":["Xác định quãng đường s mà sóng truyền (cộng các đoạn).","Thời gian t = s/c.","Đổi km → m (1 km = 10³ m).","Chú ý thời gian lớn nhất ứng đường đi dài nhất (đến điểm xa nhất tầm phủ sóng)."],"n":["Vệ tinh địa tĩnh ở độ cao 36 600 km: lên – xuống ít nhất 2·36 600 km.","Tốc độ sóng điện từ rất lớn nên thời gian cỡ phần giây."]}],"sum":["Dựa trên lí thuyết điện từ của Faraday, Maxwell tiên đoán điện từ trường biến thiên sẽ lan truyền trong không gian dưới dạng sóng gọi là sóng điện từ.","Khái niệm: Dựa trên lí thuyết điện từ của Faraday, Maxwell tiên đoán điện từ trường biến thiên sẽ lan truyền trong không gian dưới dạng sóng gọi là sóng điện từ.","Ánh sáng nhìn thấy: Bước sóng 0,38 μm (tím) đến 0,76 μm (đỏ); nguồn: Mặt Trời, đèn, ngọn lửa.","Không có ranh giới rõ rệt giữa các dải: Sóng điện từ là sóng ngang."],"e":["Hay nhầm: Truyền được trong chân không.","Hay nhầm: Trong chân không cùng tốc độ.","Hay nhầm: Hồng ngoại chủ yếu gây nóng.","Hay nhầm: Vô tuyến không gây hại mắt.","Hay nhầm: Sóng âm không phải sóng điện từ.","Lưu ý: Chỉ trong chân không (và gần đúng trong không khí) mới có c = 3·10⁸ m/s."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 12. Giao thoa sóng","req":["Mô tả được hiện tượng giao thoa của hai sóng mặt nước, điều kiện giao thoa và hai nguồn kết hợp.","Mô tả thí nghiệm Y-âng về giao thoa ánh sáng và vận dụng i = λD/a để tính bước sóng, khoảng vân."],"m":[{"t":"Giao thoa sóng mặt nước: khoảng cực đại, hiệu đường đi","w":"Cho v, f của cần rung và hỏi khoảng cách giữa hai cực đại liền kề trên S₁S₂, hoặc xác định điểm là cực đại hay cực tiểu.","s":["Tính λ = v/f.","Khoảng cách hai cực đại (hoặc hai cực tiểu) liền kề trên S₁S₂ là λ/2.","Với điểm M: tính d₂ − d₁ rồi so với λ: số nguyên → cực đại; nửa nguyên → cực tiểu.","Đổi đơn vị cho thống nhất."],"n":["Hai nguồn cùng pha: trung điểm S₁S₂ là cực đại.","Khoảng cách một cực đại – một cực tiểu liền kề là λ/4."]},{"t":"Tính bước sóng ánh sáng, khoảng vân trong thí nghiệm Y-âng","w":"Cho a, D, i hoặc λ và hỏi đại lượng còn lại; cho khoảng cách giữa n vân.","s":["Khoảng vân i = (khoảng cách n vân sáng liên tiếp)/(n − 1).","Dùng λ = ai/D (hoặc i = λD/a).","Đổi đơn vị: mm → m, μm → m.","Tần số f = c/λ nếu hỏi."],"n":["Khoảng vân tỉ lệ thuận λ và D, tỉ lệ nghịch a.","Màn xa khe hơn thì i lớn hơn."]}],"sum":["Khi hai sóng kết hợp gặp nhau thì có những điểm ở đó hai sóng luôn đồng pha nên dao động mạnh nhất (cực đại), có những điểm hai sóng luôn ngược pha nên đứng yên (cực tiểu).","Khái niệm: Khi hai sóng kết hợp gặp nhau thì có những điểm ở đó hai sóng luôn đồng pha nên dao động mạnh nhất (cực đại), có những điểm hai sóng luôn ngược pha…","Điều kiện giao thoa: Hai nguồn phải dao động cùng phương, cùng tần số và có độ lệch pha không đổi theo thời gian (hai nguồn kết hợp).","Ánh sáng đơn sắc cho vân sáng và tối xen kẽ đều đặn: Ánh sáng trắng cho vân trung tâm trắng, hai bên có dải màu như cầu vồng (tím gần vân trung tâm hơn đỏ vì i tỉ lệ λ)."],"e":["Hay nhầm: Biên độ không phải điều kiện.","Hay nhầm: Chỉ cần lệch pha không đổi.","Hay nhầm: Không chứng minh tính hạt.","Lưu ý: Hai nguồn cùng pha: trung điểm S₁S₂ là cực đại.","Lưu ý: Khoảng cách một cực đại – một cực tiểu liền kề là λ/4.","Lưu ý: Khoảng vân tỉ lệ thuận λ và D, tỉ lệ nghịch a."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 13. Sóng dừng","req":["Mô tả được hiện tượng sóng dừng, nút sóng, bụng sóng và điều kiện để có sóng dừng trên dây hai đầu cố định.","Vận dụng L = nλ/2 để tính bước sóng, tần số, tốc độ truyền sóng; giải thích sóng dừng trong nhạc cụ."],"m":[{"t":"Dây hai đầu cố định: tìm λ, v, f, số bụng","w":"Cho chiều dài dây L và số bụng (nút) hoặc tần số, hỏi λ, tốc độ truyền sóng.","s":["Số bụng n = số nửa bước sóng trên dây: L = nλ/2 ⇒ λ = 2L/n.","Tốc độ truyền sóng v = λf.","Số nút = n + 1 (kể cả hai đầu).","Hai tần số liên tiếp gây sóng dừng khác nhau f₀ = v/(2L) (tần số cơ bản)."],"n":["Hai đầu cố định đều là nút.","Đọc đúng số bụng từ hình vẽ."]},{"t":"Sóng dừng một đầu cố định, một đầu tự do (ống khí)","w":"Cho ống một đầu kín, một đầu hở hoặc dây một đầu tự do; tìm điều kiện sóng dừng.","s":["Đầu cố định (kín) là nút, đầu tự do (hở) là bụng.","L = (2k + 1)λ/4 ⇒ λ = 4L/(2k + 1).","Âm cơ bản (k = 0): λ = 4L; f = v/(4L).","Các hoạ âm là bội số lẻ của tần số cơ bản."],"n":["Ống hai đầu hở: L = nλ/2.","Độ dài ống càng ngắn, âm càng cao."]}],"sum":["Sóng dừng là sóng tổng hợp của sóng tới và sóng phản xạ cùng truyền theo hai chiều ngược nhau trên một sợi dây.","Khái niệm: Sóng dừng là sóng tổng hợp của sóng tới và sóng phản xạ cùng truyền theo hai chiều ngược nhau trên một sợi dây.","Nhạc cụ dây (ghi-ta, vi-ô-lông, đàn tính): Hai đầu dây cố định, âm cơ bản có λ = 2L và f = v/2L;"],"e":["Hay nhầm: Là điều kiện một đầu tự do.","Hay nhầm: Dây ngắn hơn nên cao hơn.","Hay nhầm: Sóng dừng không truyền năng lượng đi xa.","Hay nhầm: Tốc độ truyền sóng như nhau.","Lưu ý: Hai đầu cố định đều là nút.","Lưu ý: Đọc đúng số bụng từ hình vẽ."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 14. Bài tập về sóng","req":["Vận dụng mối liên hệ λ = vT = v/f để tìm các đại lượng đặc trưng của sóng từ phương trình hoặc đồ thị.","Giải bài tập về giao thoa sóng, giao thoa ánh sáng và sóng dừng."],"m":[{"t":"Bài toán sóng cơ bản: tốc độ – bước sóng – tần số","w":"Cho quãng đường, thời gian, số gợn sóng, tần số nguồn.","s":["Tính v = s/t hoặc dùng λ = (khoảng cách giữa hai gợn).","λ = v/f hoặc v = λf.","Chu kì T = 1/f.","Đổi cm ↔ m cho phù hợp."],"n":["Giữa n gợn liên tiếp có (n − 1)λ.","Tần số quyết định bởi nguồn."]},{"t":"Xác định trạng thái dao động từ khoảng cách (cùng pha, ngược pha)","w":"Cho sóng truyền tới điểm R bắt đầu đi lên; hỏi các điểm cách R những khoảng nguyên, bán nguyên λ bắt đầu đi lên hay xuống.","s":["Cách R số nguyên λ: dao động cùng pha với R.","Cách R (k + ½)λ: ngược pha với R.","Từ đó suy ra chiều chuyển động (lên/xuống) tại thời điểm xét.","Dùng đường sóng để minh hoạ."],"n":["Điểm Q cách R đúng 1λ: giống R.","Điểm P cách R 1,5λ: ngược R."]}],"sum":["Chiến lược giải: (1) xác định đại lượng đề cho và cần tìm; (2) đổi đơn vị;","Công thức","Chiến lược giải: Xác định đại lượng đề cho và cần tìm"],"e":["Lưu ý: Giữa n gợn liên tiếp có (n − 1)λ.","Lưu ý: Tần số quyết định bởi nguồn.","Lưu ý: Điểm Q cách R đúng 1λ: giống R.","Lưu ý: Điểm P cách R 1,5λ: ngược R.","Lưu ý: Nếu tỉ số λ tối giản là 5/6 thì x = 5i₁.","Lưu ý: Vân trung tâm là chung."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 15. Thực hành: Đo tốc độ truyền âm","req":["Biết bố trí và tiến hành thí nghiệm đo tốc độ truyền âm trong không khí bằng ống trụ có pít-tông và nguồn âm tần số xác định.","Xử lí số liệu để tính tốc độ truyền âm v = 2(l₂ − l₁)f và sai số."],"m":[{"t":"Tính tốc độ truyền âm từ l₁, l₂ và f","w":"Cho hai vị trí âm to nhất liên tiếp và tần số nguồn.","s":["d = l₂ − l₁ = λ/2.","λ = 2d.","v = λf = 2df.","Đổi cm → m trước khi nhân."],"n":["Đo nhiều lần rồi lấy trung bình.","Âm to nhất ứng với sóng dừng."]},{"t":"Xử lí số liệu và tính sai số","w":"Có ba lần đo d₁, d₂, d₃; yêu cầu tính d̄, Δd, v̄ và sai số tỉ đối.","s":["d̄ = (d₁ + d₂ + d₃)/3; Δd = trung bình |dᵢ − d̄|.","v̄ = 2d̄f.","δ = Δd/d̄ (+ Δf/f).","Viết v = v̄ ± Δv, Δv = δ·v̄."],"n":["Sai số dụng cụ thêm nửa độ chia nhỏ nhất.","So sánh v̄ với 340 m/s."]}],"sum":["Dụng cụ: ống trụ bằng thuỷ tinh hữu cơ trong suốt (đường kính trong 40 mm, dài 670 mm, chia độ 0–660 mm); pít-tông có thể di chuyển trong ống; máy phát tần số (tín hiệu hình sin); loa nhỏ hoặc âm…","Dụng cụ: Ống trụ bằng thuỷ tinh hữu cơ trong suốt (đường kính trong 40 mm, dài 670 mm, chia độ 0–660 mm); pít-tông có thể di chuyển trong ống; máy phát tần…","Tiến hành: Đặt tần số máy phát f = 500 Hz; kéo pít-tông chậm trong ống cho đến khi nghe âm to nhất lần 1, đo chiều dài cột khí l₁; kéo tiếp đến lần âm to nhất…","Không xác định tốc độ qua l₁…: Không xác định tốc độ qua l₁ hay l₂ riêng lẻ vì sóng không phản xạ đúng tại miệng ống (hiệu chỉnh đầu ống); hiệu l₂ − l₁ loại bỏ sai số này."],"e":["Hay nhầm: Sóng dừng mới cho biên độ lớn.","Lưu ý: Đo nhiều lần rồi lấy trung bình.","Lưu ý: Âm to nhất ứng với sóng dừng.","Lưu ý: Sai số dụng cụ thêm nửa độ chia nhỏ nhất.","Lưu ý: So sánh v̄ với 340 m/s.","Lưu ý: Sau hai vị trí liên tiếp, pha thay đổi π."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}}]},{"t":"Chương 3. Điện trường","l":[{"t":"Bài 16. Lực tương tác giữa hai điện tích","req":["Nêu được hai loại điện tích, tương tác giữa các điện tích và phát biểu được định luật Coulomb.","Vận dụng biểu thức F = k|q₁q₂|/r² để tính lực, so sánh lực và tìm vị trí cân bằng của điện tích."],"m":[{"t":"Tính lực tương tác giữa hai điện tích điểm","w":"Cho q₁, q₂, khoảng cách r (và hằng số điện môi) và hỏi độ lực, chiều lực.","s":["Đổi q về coulomb (μC, nC → C) và r về mét.","F = k|q₁q₂|/r² (chia thêm ε nếu có môi trường).","Chiều: cùng dấu đẩy nhau, khác dấu hút nhau (vẽ vectơ lực trên đường thẳng nối).","Kiểm tra đơn vị N."],"n":["Dùng giá trị tuyệt đối của điện tích khi tính độ lớn.","Hai lực tương tác là cặp lực trực đối."]},{"t":"So sánh lực khi thay đổi điện tích hoặc khoảng cách","w":"Cho điện tích, khoảng cách thay đổi gấp bao nhiêu lần, hỏi lực tăng hay giảm bao nhiêu lần.","s":["F ∝ |q₁q₂| và F ∝ 1/r².","Lập tỉ số F′/F = (q₁′q₂′/q₁q₂)·(r/r′)².","Thay hệ số.","Kết luận tăng hay giảm bao nhiêu lần."],"n":["Tăng r gấp 2 thì F giảm 4 lần.","Tăng mỗi q gấp 3 thì F tăng 9 lần."]}],"sum":["Có hai loại điện tích: điện tích dương và điện tích âm. Các điện tích cùng dấu đẩy nhau, khác dấu hút nhau.","Có hai loại điện tích: Điện tích dương và điện tích âm.","Định luật Coulomb: Lực tương tác giữa hai điện tích điểm đứng yên có phương trùng với đường thẳng nối hai điện tích, có độ lớn tỉ lệ thuận với tích độ lớn hai điện…","Ứng dụng: Sơn tĩnh điện, lọc bụi tĩnh điện, máy photocopy."],"e":["Hay nhầm: V là đơn vị hiệu điện thế.","Hay nhầm: Đặt lên hai vật khác nhau.","Lưu ý: Dùng giá trị tuyệt đối của điện tích khi tính độ lớn.","Lưu ý: Hai lực tương tác là cặp lực trực đối.","Lưu ý: Tăng r gấp 2 thì F giảm 4 lần.","Lưu ý: Tăng mỗi q gấp 3 thì F tăng 9 lần."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 17. Khái niệm điện trường","req":["Nêu được khái niệm điện trường, cường độ điện trường; biểu diễn được vectơ cường độ điện trường và đường sức điện.","Tính cường độ điện trường của điện tích điểm, lực điện tác dụng lên điện tích và vận dụng nguyên lí chồng chất điện trường."],"m":[{"t":"Tính cường độ điện trường của điện tích điểm","w":"Cho Q, khoảng cách r (và ε), hỏi độ lớn, phương, chiều E.","s":["Đổi Q về C, r về m.","E = k|Q|/(εr²).","Chiều: Q > 0 hướng ra xa; Q < 0 hướng vào gần Q.","Nếu cần lực: F = |q|E (q > 0 cùng chiều E, q < 0 ngược chiều)."],"n":["E giảm 4 lần khi r tăng 2 lần.","E tại điểm rất gần điện tích rất lớn."]},{"t":"Tổng hợp điện trường của hai điện tích (cùng phương)","w":"Điểm xét nằm trên đường thẳng nối hai điện tích điểm; tính E tổng hợp hoặc tìm điểm E = 0.","s":["Tính E₁, E₂ do từng điện tích gây ra tại điểm xét; xác định chiều.","Nếu cùng chiều: E = E₁ + E₂; ngược chiều: E = |E₁ − E₂|.","Điểm E = 0: hai vectơ ngược chiều, cùng độ lớn: |Q₁|/r₁² = |Q₂|/r₂².","Hai điện tích cùng dấu: điểm E = 0 nằm trong đoạn nối; khác dấu: nằm ngoài đoạn nối, gần điện tích nhỏ hơn."],"n":["Nếu hai vectơ vuông góc: E² = E₁² + E₂².","Chọn trục và quy ước chiều dương rõ ràng."]}],"sum":["Điện trường là dạng vật chất tồn tại xung quanh điện tích và truyền tương tác giữa các điện tích.","Khái niệm: Điện trường là dạng vật chất tồn tại xung quanh điện tích và truyền tương tác giữa các điện tích.","Cường độ điện trường tại một điểm…: Cường độ điện trường tại một điểm đặc trưng cho độ mạnh yếu của điện trường tại điểm đó, được đo bằng thương số giữa lực điện tác dụng lên điện tích…","Nguyên lí chồng chất điện trường: Điện trường tổng hợp E = E₁ + E₂ + … (tổng vectơ)."],"e":["Hay nhầm: Đường sức không cắt nhau.","Lưu ý: E giảm 4 lần khi r tăng 2 lần.","Lưu ý: E tại điểm rất gần điện tích rất lớn.","Lưu ý: Nếu hai vectơ vuông góc: E² = E₁² + E₂².","Lưu ý: Chọn trục và quy ước chiều dương rõ ràng.","Lưu ý: Hạt q > 0: lực điện cùng chiều E."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 18. Điện trường đều","req":["Nêu được điện trường đều và đặc điểm đường sức điện trong điện trường đều giữa hai bản kim loại song song.","Vận dụng E = U/d, F = qE và chuyển động của điện tích trong điện trường đều."],"m":[{"t":"Tính E, U, d trong điện trường đều","w":"Cho hiệu điện thế giữa hai bản và khoảng cách, hỏi E; hoặc ngược lại.","s":["Đổi d về mét.","E = U/d; U = Ed; d = U/E.","Chiều E: từ bản dương sang bản âm.","Kiểm tra: U lớn thì E lớn (d không đổi)."],"n":["1 V/m = 1 N/C.","E đều nên không phụ thuộc vị trí giữa hai bản."]},{"t":"Chuyển động của điện tích trong điện trường đều","w":"Điện tích thả nhẹ (v₀ = 0) trong điện trường, hỏi gia tốc, vận tốc, thời gian, quãng đường.","s":["Lực F = |q|E, gia tốc a = |q|E/m.","Chọn chiều dương theo chuyển động: s = ½at², v = at, v² = 2as.","Dùng định lí động năng: ½mv² = |q|Ed.","Bỏ qua trọng lực nếu m rất nhỏ."],"n":["Điện tích dương chạy từ bản dương sang bản âm.","Với electron, đổi hướng lực ngược E."]}],"sum":["Điện trường đều là điện trường có vectơ cường độ điện trường tại mọi điểm đều bằng nhau (cùng phương, cùng chiều, cùng độ lớn).","Khái niệm: Điện trường đều là điện trường có vectơ cường độ điện trường tại mọi điểm đều bằng nhau (cùng phương, cùng chiều, cùng độ lớn).","Điện tích q khối lượng m chuyển…: Điện tích q khối lượng m chuyển động trong điện trường đều chịu lực điện không đổi F = |q|E nên có gia tốc a = |q|E/m không đổi.","Ứng dụng: Ống phóng electron (màn hình ống tia âm cực cũ), máy lọc bụi tĩnh điện, in phun, ống tia X, thiết bị tăng tốc hạt."],"e":["Hay nhầm: Đó là các mặt đẳng thế quanh điện tích điểm.","Hay nhầm: Có gia tốc nên không đều.","Lưu ý: 1 V/m = 1 N/C.","Lưu ý: E đều nên không phụ thuộc vị trí giữa hai bản.","Lưu ý: Điện tích dương chạy từ bản dương sang bản âm.","Lưu ý: Với electron, đổi hướng lực ngược E."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 19. Thế năng điện","req":["Nêu được công của lực điện trong điện trường đều không phụ thuộc đường đi và biểu thức A = qEd.","Nêu được khái niệm thế năng điện của điện tích trong điện trường đều và mối liên hệ với công của lực điện."],"m":[{"t":"Tính công của lực điện A = qEd","w":"Cho q, E, quãng đường và góc/hình chiếu so với đường sức.","s":["Xác định d = hình chiếu của quãng đường dịch chuyển lên đường sức, có dấu.","A = qEd (q có dấu).","A > 0: lực điện sinh công dương (thế năng giảm); A < 0: lực cản.","Công không phụ thuộc đường đi."],"n":["Dịch chuyển vuông góc đường sức: d = 0, A = 0.","Quỹ đạo kín: A = 0."]},{"t":"Công – thế năng – động năng","w":"Điện tích chuyển động giữa hai điểm, tìm thế năng, độ biến thiên động năng, vận tốc.","s":["A_MN = W_M − W_N.","Định lí động năng: A_MN = ΔW_đ = ½mv_N² − ½mv_M².","W_t tại điểm: W = qEd_M với mốc ở bản âm.","Tính cơ năng điện W_đ + W_t = const."],"n":["Công dương làm giảm thế năng.","Dùng đơn vị J (hoặc eV)."]}],"sum":["Khi một điện tích q di chuyển trong điện trường đều từ điểm M đến điểm N thì lực điện (không đổi) thực hiện công không phụ thuộc hình dạng đường đi mà chỉ phụ thuộc vị trí điểm đầu, điểm cuối: lực…","Khái niệm: Khi một điện tích q di chuyển trong điện trường đều từ điểm M đến điểm N thì lực điện (không đổi) thực hiện công không phụ thuộc hình dạng đường đi…","Điện tích q đặt trong điện trường…: Điện tích q đặt trong điện trường có thế năng điện bằng năng lượng mà điện tích có được nhờ nằm trong điện trường.","Khi q > 0 di chuyển cùng…: Khi q > 0 di chuyển cùng chiều đường sức, lực điện sinh công dương, thế năng điện giảm."],"e":["Hay nhầm: Chỉ phụ thuộc điểm đầu, cuối.","Hay nhầm: Chỉ bằng hiệu hai thế năng.","Lưu ý: Dịch chuyển vuông góc đường sức: d = 0, A = 0.","Lưu ý: Quỹ đạo kín: A = 0.","Lưu ý: Công dương làm giảm thế năng.","Lưu ý: Dùng đơn vị J (hoặc eV)."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 20. Điện thế","req":["Nêu được khái niệm điện thế, hiệu điện thế và đơn vị vôn; mối liên hệ U = Ed trong điện trường đều.","Tính điện thế, hiệu điện thế, công của lực điện A = qU và năng lượng theo electron-vôn."],"m":[{"t":"Tính hiệu điện thế từ công, từ E","w":"Cho công của lực điện A và q, hoặc E và d; yêu cầu U.","s":["U = A/q (A, q có dấu).","Hoặc U = Ed (d là khoảng cách theo phương đường sức).","Nếu cho V_M, V_N: U_MN = V_M − V_N.","Đổi đơn vị trước khi tính."],"n":["U_MN > 0 nghĩa là V_M > V_N.","Điện thế giảm dọc theo chiều đường sức."]},{"t":"Năng lượng hạt qua hiệu điện thế, electron-vôn","w":"Hạt tích điện (electron, proton) tăng tốc qua hiệu điện thế U; tính động năng, vận tốc.","s":["Động năng thu được W_đ = |q|U (bỏ qua động năng ban đầu).","Với electron: W_đ = U (eV).","Đổi eV → J bằng 1 eV = 1,6·10⁻¹⁹ J.","Có thể suy ra v từ ½mv² = |q|U."],"n":["Proton cũng có điện tích 1,6·10⁻¹⁹ C, hạt α có 2e.","Đơn vị eV tiện cho năng lượng nhỏ."]}],"sum":["Điện thế tại điểm M trong điện trường đặc trưng cho khả năng sinh công của điện trường khi đặt một điện tích tại đó: V_M = W_M/q = A_M∞/q.","Khái niệm: Điện thế tại điểm M trong điện trường đặc trưng cho khả năng sinh công của điện trường khi đặt một điện tích tại đó: V_M = W_M/q = A_M∞/q.","Mặt đẳng thế là tập hợp các…: Mặt đẳng thế là tập hợp các điểm có cùng điện thế; công của lực điện khi điện tích di chuyển trên mặt đẳng thế bằng 0;"],"e":["Hay nhầm: Không đổi chỉ trên mặt đẳng thế.","Lưu ý: U_MN > 0 nghĩa là V_M > V_N.","Lưu ý: Điện thế giảm dọc theo chiều đường sức.","Lưu ý: Proton cũng có điện tích 1,6·10⁻¹⁹ C, hạt α có 2e.","Lưu ý: Đơn vị eV tiện cho năng lượng nhỏ.","Lưu ý: Điểm càng xa bản dương điện thế càng thấp."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 21. Tụ điện","req":["Nêu được cấu tạo, chức năng của tụ điện, định nghĩa và đơn vị điện dung; biểu thức năng lượng tụ điện.","Tính điện dung, điện tích, năng lượng tụ điện và điện dung bộ tụ ghép nối tiếp, song song."],"m":[{"t":"Tính điện dung, điện tích, năng lượng của tụ","w":"Cho hai trong ba đại lượng C, Q, U và hỏi các đại lượng còn lại, năng lượng.","s":["C = Q/U ⇒ Q = CU, U = Q/C.","W = ½CU² = ½QU = Q²/(2C).","Đổi μF, nF, pF về F.","Kiểm tra: tụ có giới hạn U (điện áp đánh thủng)."],"n":["C chỉ phụ thuộc cấu tạo tụ (S, d, ε).","Năng lượng ∝ U²."]},{"t":"Ghép tụ điện: nối tiếp và song song","w":"Cho các tụ C₁, C₂,… ghép với nhau, tính điện dung, điện tích, hiệu điện thế mỗi tụ.","s":["Song song: C = C₁ + C₂; U chung; Q_i = C_iU.","Nối tiếp: 1/C = 1/C₁ + 1/C₂ (hai tụ: C = C₁C₂/(C₁ + C₂)); Q chung; U_i = Q/C_i.","Tính Q tổng rồi U_i hoặc Q_i.","Kiểm tra: tổng U_i = U (nối tiếp), tổng Q_i = Q (song song)."],"n":["Nối tiếp: C nhỏ hơn tụ nhỏ nhất; song song: C lớn hơn mọi tụ.","Cẩn thận phân biệt Q tổng và Q từng tụ."]}],"sum":["Tụ điện là hệ hai vật dẫn đặt gần nhau, ngăn cách bằng lớp điện môi; dùng để tích và phóng điện.","Khái niệm: Tụ điện là hệ hai vật dẫn đặt gần nhau, ngăn cách bằng lớp điện môi; dùng để tích và phóng điện.","Ghép song song: U bằng nhau, Q = Q₁ + Q₂, C = C₁ + C₂."],"e":["Hay nhầm: Song song mới có U bằng nhau.","Hay nhầm: Điện dung bằng tổng khi song song.","Lưu ý: C chỉ phụ thuộc cấu tạo tụ (S, d, ε).","Lưu ý: Năng lượng ∝ U².","Lưu ý: Nối tiếp: C nhỏ hơn tụ nhỏ nhất; song song: C lớn hơn mọi tụ.","Lưu ý: Cẩn thận phân biệt Q tổng và Q từng tụ."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}}]},{"t":"Chương 4. Dòng điện. Mạch điện","l":[{"t":"Bài 22. Cường độ dòng điện","req":["Nêu được dòng điện, chiều dòng điện quy ước và định nghĩa cường độ dòng điện, đơn vị ampe.","Vận dụng I = Δq/Δt và I = nSve để tính cường độ dòng điện, số hạt tải điện, tốc độ trôi."],"m":[{"t":"Tính cường độ dòng điện và điện lượng","w":"Cho điện lượng q và thời gian t, hoặc I và t; tìm I, q hoặc t.","s":["I = q/t; q = It; t = q/I.","Đổi đơn vị: mA → A, phút → giây.","Dòng điện không đổi: I = const.","Điện lượng q = diện tích dưới đồ thị I–t."],"n":["1 A = 1 C/s.","Đổi 1 phút = 60 s; 1 h = 3600 s."]},{"t":"Số electron qua tiết diện và tốc độ trôi","w":"Cho I, t và hỏi số electron; hoặc cho n, S, I và hỏi v.","s":["q = It.","N = q/|e| = It/(1,6·10⁻¹⁹).","Từ I = nSv|e| ⇒ v = I/(nS|e|).","Đổi đơn vị mm² → m² (1 mm² = 10⁻⁶ m²)."],"n":["Số electron rất lớn.","Tốc độ trôi nhỏ so với tốc độ tín hiệu."]}],"sum":["Dòng điện là dòng các điện tích chuyển động có hướng. Chiều dòng điện quy ước là chiều chuyển động của các điện tích dương (ngược chiều chuyển động của electron trong kim loại).","Dòng điện là dòng các điện tích chuyển động có hướng: Chiều dòng điện quy ước là chiều chuyển động của các điện tích dương (ngược chiều chuyển động của electron trong kim loại).","Tác dụng của dòng điện: Tác dụng nhiệt, từ, hoá học, sinh lí, quang.","Tốc độ trôi (tốc độ chuyển động…: Tốc độ trôi (tốc độ chuyển động có hướng) của electron rất nhỏ (cỡ 10⁻⁴ m/s), còn tín hiệu điện lan truyền cả mạch với tốc độ gần bằng tốc độ ánh…"],"e":["Hay nhầm: Electron ngược chiều dòng điện.","Hay nhầm: Ion âm ngược chiều quy ước.","Hay nhầm: Hạt trung hoà không tải điện.","Hay nhầm: Tốc độ trôi lớn hơn ở chỗ hẹp, I thì bằng nhau.","Lưu ý: 1 A = 1 C/s.","Lưu ý: Đổi 1 phút = 60 s; 1 h = 3600 s."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 23. Điện trở. Định luật Ohm","req":["Nêu được khái niệm điện trở, định luật Ohm, đặc tuyến vôn-ampe và sự phụ thuộc của điện trở vào kích thước, vật liệu, nhiệt độ.","Vận dụng I = U/R, R = ρl/S và công thức ghép điện trở nối tiếp, song song."],"m":[{"t":"Tính I, U, R theo định luật Ohm","w":"Cho hai trong ba đại lượng U, I, R của một đoạn mạch hoặc một điện trở.","s":["Viết I = U/R, U = IR hoặc R = U/I.","Đổi đơn vị (mA → A, kΩ → Ω).","Thay số.","Kiểm tra: tăng U thì I tăng (R không đổi)."],"n":["Chỉ áp dụng cho vật dẫn kim loại ở nhiệt độ không đổi.","Đồ thị I–U là đường thẳng đi qua gốc."]},{"t":"Tính điện trở dây dẫn và sự phụ thuộc nhiệt độ","w":"Cho ρ, l, S hoặc cho R ở nhiệt độ này, tìm R ở nhiệt độ khác.","s":["R = ρl/S (S đổi về m²).","So sánh tỉ lệ: R ∝ l, R ∝ 1/S.","R(t) = R₀[1 + α(t − t₀)].","Thay số."],"n":["Gấp đôi chiều dài thì R gấp đôi; gấp đôi tiết diện thì R giảm một nửa.","Kim loại: α > 0."]}],"sum":["Điện trở của vật dẫn đặc trưng cho mức độ cản trở dòng điện của vật dẫn đó: R = U/I; đơn vị ôm (Ω), 1 Ω = 1 V/A.","Khái niệm: Điện trở của vật dẫn đặc trưng cho mức độ cản trở dòng điện của vật dẫn đó: R = U/I;","Điện trở của kim loại tăng theo nhiệt độ: R = R₀[1 + α(t − t₀)] (α: hệ số nhiệt điện trở)."],"e":["Hay nhầm: Cong là bóng đèn dây tóc.","Lưu ý: Chỉ áp dụng cho vật dẫn kim loại ở nhiệt độ không đổi.","Lưu ý: Đồ thị I–U là đường thẳng đi qua gốc.","Lưu ý: Gấp đôi chiều dài thì R gấp đôi; gấp đôi tiết diện thì R giảm một nửa.","Lưu ý: Kim loại: α > 0.","Lưu ý: Hai điện trở song song: R = R₁R₂/(R₁ + R₂)."],"q":{"n":18,"lv":{"Biết":6,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 24. Nguồn điện","req":["Nêu được suất điện động, điện trở trong của nguồn điện và hiệu suất của nguồn điện.","Vận dụng định luật Ohm toàn mạch I = E/(R + r), U = E − Ir và ghép nguồn."],"m":[{"t":"Tính cường độ dòng điện và hiệu điện thế mạch kín","w":"Cho E, r, R; yêu cầu I, U, hiệu suất.","s":["I = E/(R + r).","U = IR (hoặc E − Ir).","H = U/E = R/(R + r).","Kiểm tra: U < E khi có dòng."],"n":["Khi mạch hở: I = 0, U = E.","Ngắn mạch: I = E/r."]},{"t":"Xác định E và r từ hai trạng thái (hoặc đồ thị U–I)","w":"Cho hai cặp (I₁, U₁), (I₂, U₂) hoặc đồ thị U–I.","s":["Viết U₁ = E − I₁r, U₂ = E − I₂r.","Trừ vế: r = (U₁ − U₂)/(I₂ − I₁).","E = U₁ + I₁r.","Từ đồ thị: E là giao điểm với trục tung, r là độ lớn hệ số góc."],"n":["Khi I = 0 thì U = E.","Chú ý đơn vị."]}],"sum":["Nguồn điện là thiết bị duy trì hiệu điện thế giữa hai cực để tạo dòng điện trong mạch. Nguồn điện thực hiện công đưa các điện tích dương từ cực âm sang cực dương (công của lực lạ).","Khái niệm: Nguồn điện là thiết bị duy trì hiệu điện thế giữa hai cực để tạo dòng điện trong mạch.","Ghép nguồn nối tiếp (n nguồn giống nhau): E_b = nE, r_b = nr."],"e":["Lưu ý: Khi mạch hở: I = 0, U = E.","Lưu ý: Ngắn mạch: I = E/r.","Lưu ý: Khi I = 0 thì U = E.","Lưu ý: Chú ý đơn vị.","Lưu ý: Ghép nối tiếp tăng hiệu điện thế; ghép song song giảm điện trở trong.","Lưu ý: Chỉ ghép song song các nguồn giống nhau."],"q":{"n":18,"lv":{"Biết":6,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 25. Năng lượng điện và công suất điện","req":["Nêu được công của dòng điện, công suất điện, định luật Joule – Lenz, công suất và hiệu suất của nguồn.","Vận dụng A = UIt, P = UI, Q = I²Rt để tính điện năng tiêu thụ, công suất, tiền điện."],"m":[{"t":"Tính điện năng tiêu thụ, công suất, tiền điện","w":"Cho U, I, t hoặc công suất thiết bị và thời gian dùng; giá điện 1 kWh.","s":["P = UI (W); đổi sang kW (chia 1000).","Điện năng A = Pt; t đổi giờ để ra kWh (hoặc giây để ra J).","Tiền = số kWh × giá 1 kWh.","Cộng nhiều thiết bị."],"n":["1 kWh = 3,6·10⁶ J.","Nhớ đổi W → kW và phút → giờ."]},{"t":"Công suất và nhiệt lượng trên điện trở","w":"Cho R, I (hoặc U) và thời gian; tính P, Q; hoặc tính thời gian đun nước.","s":["P = I²R = U²/R.","Q = I²Rt = Pt.","Nếu cho đun nước: Q = mcΔt; bỏ qua hao phí thì Q = A.","Tính hiệu suất H = Q_có ích/A."],"n":["Công suất tỉ lệ I² (R cố định).","Dây dẫn nóng lên do hiệu ứng Joule."]}],"sum":["Khi có dòng điện chạy qua đoạn mạch, điện năng được chuyển hoá thành các dạng năng lượng khác (nhiệt, quang, cơ,...).","Khái niệm: Khi có dòng điện chạy qua đoạn mạch, điện năng được chuyển hoá thành các dạng năng lượng khác (nhiệt, quang, cơ,...).","Đơn vị: 1 W = 1 J/s;","Tiết kiệm điện: Dùng thiết bị hiệu suất cao (đèn LED), tắt thiết bị không dùng, chọn công suất phù hợp, dùng dây dẫn tiết diện đủ lớn để giảm hao phí nhiệt trên…"],"e":["Lưu ý: 1 kWh = 3,6·10⁶ J.","Lưu ý: Nhớ đổi W → kW và phút → giờ.","Lưu ý: Công suất tỉ lệ I² (R cố định).","Lưu ý: Dây dẫn nóng lên do hiệu ứng Joule.","Lưu ý: R lớn thì H lớn nhưng P có thể nhỏ.","Lưu ý: Hai giá trị R khác nhau cho cùng P thoả R₁R₂ = r²."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 26. Thực hành: Đo suất điện động và điện trở trong của pin điện hoá","req":["Biết bố trí mạch điện (pin, biến trở, ampe kế, vôn kế) để đo hiệu điện thế và cường độ dòng điện.","Xử lí số liệu, vẽ đồ thị U – I để xác định suất điện động E và điện trở trong r."],"m":[{"t":"Xác định E và r bằng phương pháp đồ thị","w":"Có bảng (I, U); vẽ đồ thị và đọc E, r.","s":["Vẽ các điểm (I, U) trên giấy kẻ ô, vẽ đường thẳng đi gần các điểm nhất.","E là giá trị U tại I = 0 (giao trục tung).","r = |hệ số góc| = (E − U)/I tại một điểm trên đường thẳng.","Có thể kiểm tra bằng cách tính từ hai điểm xa nhau."],"n":["Chọn hai điểm trên đường thẳng, không nhất thiết là điểm đo.","Đơn vị: V và A cho r tính ra Ω."]},{"t":"Xử lí số liệu bằng bảng và tính sai số","w":"Cho vài cặp (I, U); tính r và E từ các cặp liên tiếp rồi lấy trung bình.","s":["Với mỗi cặp hai điểm tính r_i = (U₁ − U₂)/(I₂ − I₁) và E_i = U₁ + I₁r_i.","r̄ = Σr_i/n; Ē = ΣE_i/n.","Sai số tuyệt đối trung bình Δr = Σ|r_i − r̄|/n.","Viết kết quả r = r̄ ± Δr."],"n":["Đo nhiều điểm để giảm sai số ngẫu nhiên.","Bỏ các điểm lệch bất thường."]}],"sum":["Cơ sở lí thuyết: hiệu điện thế hai cực pin khi có dòng I chạy qua là U = E − Ir. Vẽ đồ thị U theo I là đường thẳng; giao điểm với trục tung cho E, độ lớn hệ số góc cho r.","Cơ sở lí thuyết: Hiệu điện thế hai cực pin khi có dòng I chạy qua là U = E − Ir.","Tiến hành: Mắc mạch theo sơ đồ, đóng khoá K.","Lưu ý: Vôn kế có điện trở rất lớn; ampe kế có điện trở rất nhỏ; chọn thang đo phù hợp; giữ dòng điện nhỏ để pin ít bị hao;"],"e":["Lưu ý: Chọn hai điểm trên đường thẳng, không nhất thiết là điểm đo.","Lưu ý: Đơn vị: V và A cho r tính ra Ω.","Lưu ý: Đo nhiều điểm để giảm sai số ngẫu nhiên.","Lưu ý: Bỏ các điểm lệch bất thường.","Lưu ý: Vôn kế phải nối trực tiếp hai cực pin.","Lưu ý: Dòng không quá lớn."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":4,"Nâng cao":2}}}]}]}]},{"id":"hoa","name":"Hoá học","b":[{"t":"Hoá học 11","c":[{"t":"Chương 1. Cân bằng hoá học","l":[{"t":"Bài 1. Khái niệm về cân bằng hoá học","req":["Trình bày được khái niệm phản ứng thuận nghịch và trạng thái cân bằng.","Viết được biểu thức hằng số cân bằng K_C và tính K_C.","Vận dụng nguyên lí Le Chatelier để giải thích ảnh hưởng của nồng độ, nhiệt độ, áp suất đến cân bằng."],"m":[{"t":"Xét chiều chuyển dịch cân bằng","w":"Đề cho một cân bằng và một tác động (nồng độ, nhiệt độ, áp suất); hỏi cân bằng chuyển dịch theo chiều nào.","s":["Viết cân bằng, xác định chiều toả nhiệt/thu nhiệt (dựa vào dấu ΔH) và số mol khí hai vế.","Xác định tác động: tăng/giảm nồng độ, nhiệt độ hoặc áp suất.","Áp dụng Le Chatelier: cân bằng chuyển dịch theo chiều làm giảm tác động đó.","Kết luận chiều thuận hay chiều nghịch."],"n":["Chất xúc tác không làm chuyển dịch cân bằng.","Chất rắn không ảnh hưởng đến cân bằng khi thay đổi lượng.","Khi số mol khí hai vế bằng nhau, áp suất không ảnh hưởng."]}],"sum":["Phản ứng một chiều chỉ xảy ra theo một chiều từ chất đầu tạo sản phẩm, sản phẩm không phản ứng lại với nhau tạo chất đầu (ví dụ đốt cháy methane, NaOH + HCl).","Khái niệm: Phản ứng một chiều chỉ xảy ra theo một chiều từ chất đầu tạo sản phẩm, sản phẩm không phản ứng lại với nhau tạo chất đầu (ví dụ đốt cháy methane,…","Trạng thái cân bằng của phản ứng…: Trạng thái cân bằng của phản ứng thuận nghịch là trạng thái tại đó tốc độ phản ứng thuận bằng tốc độ phản ứng nghịch.","Hằng số cân bằng: Với phản ứng aA + bB ⇌ cC + dD, ở trạng thái cân bằng K_C = [C]ᶜ·[D]ᵈ / ([A]ᵃ·[B]ᵇ), trong đó [X] là nồng độ mol của chất X ở trạng thái cân bằng,…","Các yếu tố ảnh hưởng đến cân bằng: Nhiệt độ (tăng nhiệt độ, cân bằng chuyển dịch theo chiều thu nhiệt; giảm nhiệt độ, theo chiều toả nhiệt), nồng độ (tăng nồng độ một chất, cân bằng…","Nguyên lí Le Chatelier: Một phản ứng thuận nghịch đang ở trạng thái cân bằng, khi chịu một tác động bên ngoài làm thay đổi nồng độ, nhiệt độ, áp suất thì cân bằng sẽ chuyển…"],"e":["Hay nhầm: Đó là phản ứng một chiều.","Hay nhầm: Không phụ thuộc nhiệt độ cao.","Hay nhầm: Nồng độ không nhất thiết bằng nhau.","Hay nhầm: Không phụ thuộc nồng độ đầu.","Hay nhầm: Không phụ thuộc áp suất đầu.","Hay nhầm: Xúc tác không làm đổi K_C."],"q":{"n":12,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":3}}},{"t":"Bài 2. Cân bằng trong dung dịch nước","req":["Nêu được khái niệm sự điện li, chất điện li, chất không điện li; phân biệt điện li mạnh, yếu.","Trình bày được thuyết acid – base của Brønsted – Lowry.","Tính được pH của dung dịch, nêu ý nghĩa pH và cách xác định pH."],"m":[{"t":"Tính pH của dung dịch acid, base mạnh","w":"Cho nồng độ acid mạnh hoặc base mạnh, yêu cầu tính [H⁺], pH hoặc ngược lại.","s":["Viết phương trình điện li hoàn toàn, tìm nồng độ ion.","Với acid: [H⁺] = n·C_acid; với base: [OH⁻] = n·C_base rồi [H⁺] = 10⁻¹⁴/[OH⁻].","Tính pH = −lg[H⁺].","So sánh với 7 để kết luận môi trường."],"n":["Acid yếu chỉ phân li một phần nên không dùng [H⁺] = C.","Nhớ hệ số: H₂SO₄ cho 2 H⁺, Ba(OH)₂ cho 2 OH⁻."]}],"sum":["Sự điện li là quá trình phân li các chất trong nước thành ion. Chất tan trong nước phân li ra ion gọi là chất điện li (dung dịch dẫn điện); chất tan không phân li ra ion gọi là chất không điện li…","Khái niệm: Sự điện li là quá trình phân li các chất trong nước thành ion.","Chất điện li mạnh phân li gần…: Chất điện li mạnh phân li gần như hoàn toàn, biểu diễn bằng mũi tên một chiều (acid mạnh HCl, HNO₃, H₂SO₄; base mạnh NaOH, KOH, Ca(OH)₂, Ba(OH)₂;…","Thuyết Brønsted – Lowry: Acid là chất cho proton (H⁺), base là chất nhận proton.","Khái niệm pH: PH = −lg[H⁺], hay [H⁺] = 10⁻ᵖᴴ.","Ý nghĩa của pH: PH máu 7,3 – 7,4; dạ dày 1,5 – 3,5; nước bọt 6,0 – 7,4; nước tiểu 4,8 – 7,0."],"e":["Hay nhầm: Cl⁻ không thuỷ phân nhưng Al³⁺ thuỷ phân.","Hay nhầm: Không dùng khái niệm đó ở đây.","Lưu ý: Acid yếu chỉ phân li một phần nên không dùng [H⁺] = C.","Lưu ý: Nhớ hệ số: H₂SO₄ cho 2 H⁺, Ba(OH)₂ cho 2 OH⁻."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 3. Ôn tập chương 1","req":["Hệ thống hoá kiến thức về cân bằng hoá học và cân bằng trong dung dịch nước.","Vận dụng tổng hợp để giải bài tập về hằng số cân bằng, chiều chuyển dịch, pH, chuẩn độ."],"e":["Hay nhầm: Chỉ không đổi, không nhất thiết bằng nhau.","Hay nhầm: NH₄⁺ là acid ở chiều nghịch.","Hay nhầm: Xúc tác không chuyển dịch.","Hay nhầm: Giảm O₂ làm lệch về nghịch."],"q":{"n":7,"lv":{"Hiểu":4,"Vận dụng":3}}}]},{"t":"Chương 2. Nitrogen – Sulfur","l":[{"t":"Bài 4. Nitrogen","req":["Phát biểu được trạng thái tự nhiên của nitrogen.","Giải thích được tính trơ của N₂ ở nhiệt độ thường qua năng lượng liên kết; trình bày tính chất hoá học của N₂.","Giải thích sự tạo và cung cấp nitrate cho đất từ nước mưa; nêu ứng dụng của nitrogen khí và lỏng."],"sum":["Nitrogen chiếm khoảng 78,1% thể tích (75,5% khối lượng) khí quyển, là nguyên tố phổ biến nhất ở khí quyển.","Khái niệm: Nitrogen chiếm khoảng 78,1% thể tích (75,5% khối lượng) khí quyển, là nguyên tố phổ biến nhất ở khí quyển.","Cấu tạo: Nguyên tử N ở ô số 7, nhóm VA, chu kì 2, độ âm điện 3,04, phi kim điển hình, cấu hình lớp ngoài cùng 2s²2p³.","Tính chất vật lí: Chất khí không màu, không mùi, không vị, khó hoá lỏng (−196 °C), tan rất ít trong nước (phân tử không phân cực, lực van der Waals yếu), không duy…","Tính chất hoá học: Ở nhiệt độ cao, áp suất cao và xúc tác Fe, N₂ tác dụng với H₂ (thể hiện tính oxi hoá): N₂ + 3H₂ ⇌ 2NH₃ (quá trình Haber – Bosch, từ năm 1913).","Ứng dụng: Tổng hợp ammonia (nguyên liệu sản xuất phân đạm, nitric acid, thuốc nổ), tạo khí quyển trơ trong bảo quản thực phẩm (nạp vào bao bì), nitrogen lỏng…"],"e":["Hay nhầm: Còn số oxi hoá thấp hơn 0.","Hay nhầm: Tính khử khi tăng số oxi hoá.","Hay nhầm: Số oxi hoá tăng nên là khử.","Hay nhầm: Ở nhiệt độ thường không xảy ra.","Hay nhầm: Không liên quan ánh sáng."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 5. Ammonia – Muối ammonium","req":["Mô tả công thức Lewis, dạng hình học NH₃; giải thích tính tan, tính base, tính khử của ammonia.","Vận dụng cân bằng hoá học, tốc độ, enthalpy cho quá trình Haber.","Trình bày tính chất muối ammonium và nhận biết ion NH₄⁺."],"m":[{"t":"Nhận biết ion NH₄⁺ và tính toán với NH₃","w":"Đề cho dung dịch muối nghi chứa NH₄⁺; hoặc tính khối lượng, thể tích NH₃ trong phản ứng.","s":["Cho dung dịch kiềm (NaOH), đun nóng nhẹ.","Đưa giấy pH ẩm (hoặc quỳ tím ẩm) vào miệng ống nghiệm: hoá xanh và có mùi khai chứng tỏ có NH₄⁺.","Viết phương trình ion rút gọn NH₄⁺ + OH⁻ → NH₃↑ + H₂O.","Tính toán lượng chất theo tỉ lệ mol của phương trình."],"n":["Phải đun nóng vì NH₃ tan nhiều trong nước.","NH₄⁺ không nhận biết bằng AgNO₃."]}],"sum":["Cấu tạo: phân tử NH₃ có dạng chóp tam giác, nguyên tử N còn một cặp electron không liên kết, ba liên kết N–H phân cực (năng lượng liên kết 386 kJ/mol).","Cấu tạo: Phân tử NH₃ có dạng chóp tam giác, nguyên tử N còn một cặp electron không liên kết, ba liên kết N–H phân cực (năng lượng liên kết 386 kJ/mol).","Tính base: NH₃ nhận H⁺ của acid hoặc của nước: NH₃ + H₂O ⇌ NH₄⁺ + OH⁻ (dung dịch base yếu, làm quỳ tím hoá xanh, phenolphthalein hoá hồng).","Tính khử: Nitrogen trong NH₃ có số oxi hoá −3 (thấp nhất).","Sản xuất ammonia bằng phản ứng N₂…: Sản xuất ammonia bằng phản ứng N₂ + 3H₂ ⇌ 2NH₃, ΔH = −91,8 kJ ở 400–450 °C, 150–200 bar, xúc tác Fe.","Ứng dụng của ammonia: Sản xuất phân đạm (urea, ammonium nitrate, ammonium sulfate), nitric acid, tác nhân làm lạnh, dung môi."],"e":["Hay nhầm: Có cặp electron không liên kết nên không phẳng.","Hay nhầm: Số oxi hoá tăng nên là khử.","Lưu ý: Phải đun nóng vì NH₃ tan nhiều trong nước.","Lưu ý: NH₄⁺ không nhận biết bằng AgNO₃."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 6. Một số hợp chất của nitrogen với oxygen","req":["Phân tích được nguồn gốc oxide của nitrogen trong không khí và nguyên nhân gây mưa acid.","Nêu được cấu tạo HNO₃, tính acid và tính oxi hoá mạnh, ứng dụng.","Giải thích được nguyên nhân, hệ quả của hiện tượng phú dưỡng."],"sum":["Oxide của nitrogen kí hiệu chung NOₓ gồm N₂O (dinitrogen oxide), NO (nitrogen monoxide), NO₂ (nitrogen dioxide), N₂O₄ (dinitrogen tetroxide); là tác nhân gây ô nhiễm không khí.","Khái niệm: Oxide của nitrogen kí hiệu chung NOₓ gồm N₂O (dinitrogen oxide), NO (nitrogen monoxide), NO₂ (nitrogen dioxide), N₂O₄ (dinitrogen tetroxide); là tác…","Mưa acid: Nước mưa bình thường pH khoảng 5,6 (do CO₂ hoà tan); mưa có pH < 5,6 gọi là mưa acid.","Nitric acid HNO₃: N có số oxi hoá +5 (cao nhất).","Phú dưỡng: Ao, hồ nhận nhiều nitrogen và phosphorus từ nước thải sinh hoạt, nông nghiệp, thức ăn dư thừa làm tảo, rong phát triển mạnh, che ánh sáng, khi chết…"],"q":{"n":10,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 7. Sulfur và sulfur dioxide","req":["Nêu trạng thái tự nhiên, cấu tạo, tính chất, ứng dụng của sulfur.","Thực hiện thí nghiệm sulfur vừa có tính oxi hoá vừa có tính khử.","Trình bày tính chất, ứng dụng, tác hại của SO₂ và biện pháp giảm phát thải."],"sum":["Sulfur (lưu huỳnh) chiếm khoảng 0,03–0,1% khối lượng vỏ Trái Đất, tồn tại ở dạng đơn chất (gần núi lửa, suối nước nóng) và hợp chất (sulfide, sulfate, protein).","Khái niệm: Sulfur (lưu huỳnh) chiếm khoảng 0,03–0,1% khối lượng vỏ Trái Đất, tồn tại ở dạng đơn chất (gần núi lửa, suối nước nóng) và hợp chất (sulfide,…","Tính chất hoá học: Tính oxi hoá khi tác dụng với kim loại và hydrogen (Fe + S → FeS;","Sulfur dioxide SO₂: Là oxide acid (SO₂ + H₂O ⇌ H₂SO₃;"],"q":{"n":10,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 8. Sulfuric acid và muối sulfate","req":["Trình bày tính chất vật lí, quy tắc an toàn, sơ cứu bỏng acid.","Trình bày tính chất của H₂SO₄ loãng và đặc; sản xuất H₂SO₄ bằng phương pháp tiếp xúc.","Nêu ứng dụng muối sulfate và nhận biết ion SO₄²⁻."],"m":[{"t":"Phân biệt dung dịch H₂SO₄ loãng và HCl; muối sulfate","w":"Đề yêu cầu nhận biết các dung dịch chứa SO₄²⁻ hoặc phân biệt acid.","s":["Chọn thuốc thử đặc trưng: BaCl₂ (hoặc Ba(OH)₂) cho SO₄²⁻.","Nhỏ thuốc thử vào mẫu, quan sát kết tủa trắng.","Kết luận mẫu có SO₄²⁻ (H₂SO₄ loãng); mẫu không kết tủa là HCl.","Viết phương trình ion rút gọn."],"n":["BaSO₄ không tan trong HCl, HNO₃ loãng.","Ag⁺ cũng tạo kết tủa với Cl⁻ nên không dùng để phân biệt acid ở đây."]}],"sum":["Cấu tạo: phân tử H₂SO₄ có S số oxi hoá +6, nhiều liên kết hydrogen giữa các phân tử. Tính chất vật lí: chất lỏng sánh như dầu, không màu, không bay hơi, hút ẩm mạnh; dung dịch 98% có khối lượng…","Cấu tạo: Phân tử H₂SO₄ có S số oxi hoá +6, nhiều liên kết hydrogen giữa các phân tử.","An toàn: Bảo quản trong chai lọ nút kín, đặt chắc chắn, cách xa chất dễ cháy nổ (chlorate, perchlorate, permanganate, dichromate); sử dụng có kính, găng tay.","H₂SO₄ loãng có tính chất của acid mạnh: Làm quỳ tím hoá đỏ; tác dụng kim loại đứng trước H (Fe + H₂SO₄ → FeSO₄ + H₂); oxide base (MgO); muối carbonate (Na₂CO₃ → CO₂); base; muối BaCl₂ (kết…","H₂SO₄ đặc ngoài tính acid còn có: Tính oxi hoá mạnh (nhất là khi đun nóng, S⁺⁶ bị khử thành SO₂, S hoặc H₂S): Cu + 2H₂SO₄ đặc → CuSO₄ + SO₂ + 2H₂O;","Sản xuất bằng phương pháp tiếp xúc…: Sản xuất bằng phương pháp tiếp xúc, nguyên liệu sulfur hoặc quặng pyrite (FeS₂): giai đoạn 1 đốt tạo SO₂; giai đoạn 2 oxi hoá SO₂ thành SO₃ (2SO₂ +…"],"e":["Lưu ý: BaSO₄ không tan trong HCl, HNO₃ loãng.","Lưu ý: Ag⁺ cũng tạo kết tủa với Cl⁻ nên không dùng để phân biệt acid ở đây."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":3}}},{"t":"Bài 9. Ôn tập chương 2","req":["Hệ thống hoá kiến thức nitrogen, ammonia, muối ammonium, nitric acid, sulfur, sulfur dioxide, sulfuric acid và muối sulfate.","Vận dụng tổng hợp giải bài tập nhận biết, chuỗi phản ứng và tính toán."],"q":{"n":7,"lv":{"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương 3. Đại cương về hoá học hữu cơ","l":[{"t":"Bài 10. Hợp chất hữu cơ và hoá học hữu cơ","req":["Nêu được khái niệm hợp chất hữu cơ, hoá học hữu cơ và đặc điểm chung.","Phân loại được hợp chất hữu cơ (hydrocarbon và dẫn xuất).","Nêu được khái niệm nhóm chức; sử dụng bảng tín hiệu phổ hồng ngoại (IR) để xác định nhóm chức."],"m":[{"t":"Dự đoán nhóm chức từ phổ IR","w":"Cho phổ IR hoặc các số sóng hấp thụ, yêu cầu xác định nhóm chức.","s":["Tìm các peak hấp thụ mạnh, ghi số sóng.","Đối chiếu với bảng số sóng đặc trưng (O–H, N–H, C=O...).","Kết hợp công thức phân tử (nếu có) để loại phương án.","Kết luận nhóm chức và loại hợp chất."],"n":["Peak rộng 3500–3200 đặc trưng cho O–H của alcohol; acid có O–H rất rộng 3300–2500.","Peak mạnh khoảng 1700 cho C=O."]}],"sum":["Hợp chất của carbon là hợp chất hữu cơ (trừ CO, CO₂, muối carbonate, cyanide, carbide...).","Khái niệm: Hợp chất của carbon là hợp chất hữu cơ (trừ CO, CO₂, muối carbonate, cyanide, carbide...).","Đặc điểm chung: Thành phần phân tử nhất thiết có carbon, thường có H, O, N, halogen, S, P; liên kết chủ yếu là liên kết cộng hoá trị; nhiệt độ nóng chảy, nhiệt độ…","Phân loại theo thành phần: Hydrocarbon (chỉ gồm C và H, ví dụ CH₄, CH₂=CH₂, CH≡CH, C₆H₆) và dẫn xuất của hydrocarbon (thay một hay nhiều H bằng nguyên tử hay nhóm nguyên tử…","Nhóm chức là nguyên tử hoặc nhóm…: Nhóm chức là nguyên tử hoặc nhóm nguyên tử gây ra những tính chất hoá học đặc trưng của hợp chất hữu cơ.","Phổ hồng ngoại (IR): Mỗi liên kết trong phân tử hấp thụ bức xạ hồng ngoại ở số sóng đặc trưng; phổ ghi độ truyền qua (%) theo số sóng (cm⁻¹); các cực tiểu truyền qua…"],"e":["Hay nhầm: Thường ít tan trong nước.","Lưu ý: Peak rộng 3500–3200 đặc trưng cho O–H của alcohol; acid có O–H rất rộng 3300–2500.","Lưu ý: Peak mạnh khoảng 1700 cho C=O."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 11. Phương pháp tách biệt và tinh chế hợp chất hữu cơ","req":["Trình bày nguyên tắc, cách tiến hành chưng cất, chiết, kết tinh và sơ lược sắc kí cột.","Vận dụng các phương pháp vào tách một số hợp chất hữu cơ trong đời sống."],"m":[{"t":"Chọn phương pháp tách tinh chế","w":"Đề cho một hỗn hợp (lỏng – lỏng, rắn – lỏng, rắn – rắn) và yêu cầu chọn phương pháp.","s":["Xác định trạng thái và tính chất khác biệt (nhiệt độ sôi, độ tan, tan hay không trong nước).","Chọn phương pháp: nhiệt độ sôi khác → chưng cất; tan trong dung môi khác nhau → chiết; độ tan thay đổi theo nhiệt độ → kết tinh; hỗn hợp nhiều chất khó tách → sắc kí cột.","Mô tả các bước tiến hành chính.","Nêu lưu ý an toàn (đá bọt, không đun cạn...)."],"n":["Hai chất lỏng không tan vào nhau tách bằng phễu chiết (không cần chưng cất).","Cho đá bọt vào bình chưng cất để tránh sôi bùng."]}],"sum":["Chưng cất: dựa vào sự khác nhau về nhiệt độ sôi của các chất trong hỗn hợp ở một áp suất nhất định.","Chưng cất: Dựa vào sự khác nhau về nhiệt độ sôi của các chất trong hỗn hợp ở một áp suất nhất định.","Chiết: Tách biệt dựa vào sự hoà tan khác nhau của các chất trong hai dung môi không trộn lẫn.","Kết tinh: Tách và tinh chế chất rắn dựa vào độ tan khác nhau và sự thay đổi độ tan theo nhiệt độ.","Sắc kí cột: Dựa vào sự phân bố khác nhau của các chất giữa pha động (dung môi, dung dịch mẫu) và pha tĩnh (chất rắn có diện tích bề mặt lớn, hấp phụ khác nhau,…"],"e":["Hay nhầm: Không phải cách thông dụng.","Lưu ý: Hai chất lỏng không tan vào nhau tách bằng phễu chiết (không cần chưng cất).","Lưu ý: Cho đá bọt vào bình chưng cất để tránh sôi bùng."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 12. Công thức phân tử hợp chất hữu cơ","req":["Nêu được khái niệm công thức phân tử, công thức đơn giản nhất.","Sử dụng phổ khối lượng (MS) xác định phân tử khối.","Lập được công thức phân tử từ dữ liệu phân tích nguyên tố và phân tử khối."],"m":[{"t":"Lập công thức phân tử từ % khối lượng và phổ MS","w":"Cho %C, %H, %O (hoặc khối lượng, thể tích sản phẩm cháy) và peak [M⁺] hoặc phân tử khối.","s":["Tính tỉ lệ x : y : z = %C/12 : %H/1 : %O/16, rút gọn thành số nguyên → công thức đơn giản nhất.","Xác định M từ peak [M⁺] trên phổ MS.","Tính n = M / khối lượng công thức đơn giản nhất.","Nhân chỉ số, viết công thức phân tử."],"n":["%O = 100 − %C − %H nếu đề không cho.","Số nguyên nhỏ nhất bằng cách chia cho số bé nhất rồi nhân thêm nếu còn lẻ."]}],"sum":["Công thức phân tử cho biết thành phần nguyên tố và số nguyên tử của mỗi nguyên tố trong phân tử (ví dụ butane C₄H₁₀, propane C₃H₈).","Khái niệm: Công thức phân tử cho biết thành phần nguyên tố và số nguyên tử của mỗi nguyên tố trong phân tử (ví dụ butane C₄H₁₀, propane C₃H₈).","Lập công thức đơn giản nhất từ phần trăm khối lượng: X : y : z = %C/12 : %H/1 : %O/16, rồi rút gọn về số nguyên nhỏ nhất.","Phân tử khối xác định từ phổ khối lượng (MS): Peak ion phân tử [M⁺] có giá trị m/z lớn nhất ứng với phân tử khối M của chất."],"e":["Hay nhầm: Đó là công thức đơn giản nhất.","Lưu ý: %O = 100 − %C − %H nếu đề không cho.","Lưu ý: Số nguyên nhỏ nhất bằng cách chia cho số bé nhất rồi nhân thêm nếu còn lẻ."],"q":{"n":10,"lv":{"Biết":4,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 13. Cấu tạo hoá học hợp chất hữu cơ","req":["Trình bày được thuyết cấu tạo hoá học (Butlerov).","Giải thích hiện tượng đồng phân; nêu khái niệm đồng đẳng, dãy đồng đẳng.","Viết được công thức cấu tạo đầy đủ, thu gọn và nhận biết đồng phân, đồng đẳng."],"m":[{"t":"Viết đồng phân cấu tạo","w":"Cho CTPT, yêu cầu viết các công thức cấu tạo (đồng phân).","s":["Tính độ bất bão hoà để biết có nối đôi, vòng hay không (k = (2C + 2 − H)/2).","Viết đồng phân mạch carbon (thẳng, nhánh) cho khung carbon.","Đặt nhóm chức hoặc nối đôi vào các vị trí khác nhau.","Kiểm tra trùng lặp, đảm bảo carbon hoá trị IV."],"n":["Chất cùng CTPT khác cấu tạo mới là đồng phân.","Cùng một chất khi vẽ xoay chiều không là đồng phân."]}],"sum":["Thuyết cấu tạo hoá học (Butlerov, 1861) có ba luận điểm chính: (1) trong phân tử hợp chất hữu cơ, các nguyên tử liên kết với nhau theo đúng hoá trị và một thứ tự nhất định (cấu tạo hoá học); thay…","Thuyết cấu tạo hoá học (Butlerov, 1861) có ba luận điểm chính: Trong phân tử hợp chất hữu cơ, các nguyên tử liên kết với nhau theo đúng hoá trị và một thứ tự nhất định (cấu tạo hoá học); thay đổi thứ tự liên kết…","Ví dụ: Ethanol CH₃CH₂OH (sôi 78,3 °C, tan vô hạn trong nước, tác dụng với sodium) và dimethyl ether CH₃OCH₃ (sôi −24,9 °C, ít tan, không tác dụng với…","Công thức cấu tạo biểu diễn cách…: Công thức cấu tạo biểu diễn cách liên kết và thứ tự liên kết giữa các nguyên tử trong phân tử; gồm công thức cấu tạo đầy đủ (vẽ hết các liên kết) và…","Đồng phân: Các hợp chất hữu cơ khác nhau nhưng có cùng công thức phân tử.","Đồng đẳng: Các chất có tính chất hoá học tương tự nhau, thành phần phân tử hơn kém nhau một hay nhiều nhóm CH₂ hợp thành dãy đồng đẳng."],"e":["Hay nhầm: Cùng cấu tạo thì là một chất.","Lưu ý: Chất cùng CTPT khác cấu tạo mới là đồng phân.","Lưu ý: Cùng một chất khi vẽ xoay chiều không là đồng phân."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":3}}},{"t":"Bài 14. Ôn tập chương 3","req":["Hệ thống hoá kiến thức đại cương hoá học hữu cơ: khái niệm, phân loại, nhóm chức, phương pháp tách, công thức phân tử, cấu tạo, đồng phân, đồng đẳng.","Vận dụng giải bài tập lập công thức phân tử, xác định đồng phân."],"q":{"n":6,"lv":{"Hiểu":3,"Vận dụng":3}}}]},{"t":"Chương 4. Hydrocarbon","l":[{"t":"Bài 15. Alkane","req":["Nêu khái niệm, công thức chung, nguồn alkane trong tự nhiên; gọi tên theo danh pháp thay thế.","Giải thích đặc điểm cấu tạo, tính chất vật lí; trình bày phản ứng thế, cracking, reforming, cháy.","Nêu ứng dụng, điều chế alkane và biện pháp hạn chế ô nhiễm không khí do giao thông."],"m":[{"t":"Gọi tên alkane mạch nhánh","w":"Cho công thức cấu tạo alkane, yêu cầu gọi tên (hoặc ngược lại).","s":["Chọn mạch carbon dài nhất, có nhiều nhánh nhất làm mạch chính.","Đánh số từ phía gần nhánh hơn sao cho tổng/vị trí nhánh nhỏ nhất.","Gọi tên nhánh, kèm số chỉ vị trí (nhiều nhánh giống nhau dùng di-, tri-; sắp xếp theo thứ tự chữ cái).","Ghép: vị trí–nhánh + tên mạch chính."],"n":["Không dùng \"1-methyl\": mạch chính phải dài hơn.","Dấu gạch nối giữa số và chữ; dấu phẩy giữa các số."]}],"sum":["Alkane là hydrocarbon no, mạch hở, trong phân tử chỉ có liên kết đơn C–C và C–H; công thức chung CₙH₂ₙ₊₂ (n ≥ 1).","Khái niệm: Alkane là hydrocarbon no, mạch hở, trong phân tử chỉ có liên kết đơn C–C và C–H; công thức chung CₙH₂ₙ₊₂ (n ≥ 1).","Danh pháp thay thế (alkane không nhánh): Tên = tiền tố chỉ số C + đuôi \"ane\": meth-, eth-, prop-, but-, pent-, hex-, hept-, oct-, non-, dec-.","Đồng phân: Từ C₄ có đồng phân mạch carbon (C₄H₁₀: butane và 2-methylpropane;","Tính chất vật lí: C₁–C₄ và neopentane ở thể khí;","Tính chất hoá học: Thế halogen khi chiếu sáng hoặc đun nóng: CH₄ + Cl₂ → CH₃Cl + HCl, tiếp tục tạo CH₂Cl₂, CHCl₃, CCl₄."],"e":["Hay nhầm: Tan trong dung môi hữu cơ.","Hay nhầm: Tan trong dung môi hữu cơ.","Hay nhầm: Tan trong dung môi hữu cơ.","Hay nhầm: Alkane không có liên kết ba.","Lưu ý: Không dùng \"1-methyl\": mạch chính phải dài hơn.","Lưu ý: Dấu gạch nối giữa số và chữ; dấu phẩy giữa các số."],"q":{"n":12,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":3}}},{"t":"Bài 16. Hydrocarbon không no","req":["Nêu khái niệm alkene, alkyne, công thức chung, cấu tạo ethylene và acetylene; đồng phân hình học; gọi tên.","Trình bày tính chất hoá học: cộng H₂, Br₂, HX, H₂O (Markovnikov), trùng hợp, phản ứng của alk-1-yne với AgNO₃/NH₃, oxi hoá.","Nêu điều chế và ứng dụng."],"m":[{"t":"Nhận biết alkane, alkene, alk-1-yne","w":"Phân biệt ethane, ethylene, acetylene (hoặc các hydrocarbon khác).","s":["Dẫn từng khí qua dung dịch AgNO₃/NH₃: chỉ alk-1-yne tạo kết tủa vàng.","Dẫn các khí còn lại qua nước bromine (hoặc KMnO₄): alkene làm mất màu.","Khí không có hiện tượng là alkane.","Viết phương trình phản ứng."],"n":["Acetylene cũng làm mất màu nước bromine nên nhận biết bằng AgNO₃/NH₃ trước.","Alkane không làm mất màu nước bromine ở điều kiện thường."]}],"sum":["Alkene là hydrocarbon mạch hở có một liên kết đôi C=C, công thức chung CₙH₂ₙ (n ≥ 2); alkyne là hydrocarbon mạch hở có một liên kết ba C≡C, công thức chung CₙH₂ₙ₋₂ (n ≥ 2).","Khái niệm: Alkene là hydrocarbon mạch hở có một liên kết đôi C=C, công thức chung CₙH₂ₙ (n ≥ 2); alkyne là hydrocarbon mạch hở có một liên kết ba C≡C, công…","Danh pháp thay thế: Chọn mạch dài nhất chứa liên kết bội;","Đồng phân: Đồng phân vị trí liên kết bội và mạch carbon; alkene có thể có đồng phân hình học cis, trans khi mỗi carbon của liên kết đôi gắn với hai nguyên tử…","Phản ứng cộng: Cộng H₂ (Ni, Pt, Pd, t°) tạo alkane; cộng Br₂ (làm mất màu nước bromine – nhận biết liên kết bội): CH₂=CH₂ + Br₂ → CH₂Br–CH₂Br; cộng HX, H₂O (acid…","Phản ứng trùng hợp alkene: NCH₂=CH₂ → (–CH₂–CH₂–)ₙ (polyethylene, PE); propene tạo polypropylene (PP)."],"e":["Hay nhầm: Là công thức của arene đơn giản.","Hay nhầm: Một C gắn hai nhóm giống nhau.","Lưu ý: Acetylene cũng làm mất màu nước bromine nên nhận biết bằng AgNO₃/NH₃ trước.","Lưu ý: Alkane không làm mất màu nước bromine ở điều kiện thường."],"q":{"n":12,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":3}}},{"t":"Bài 17. Arene (hydrocarbon thơm)","req":["Nêu khái niệm arene, viết công thức và gọi tên một số arene.","Trình bày đặc điểm cấu tạo benzene và tính chất vật lí.","Trình bày phản ứng thế, cộng, oxi hoá của arene; ứng dụng, điều chế và ứng xử an toàn khi dùng arene."],"m":[{"t":"Viết sản phẩm thế vào vòng thơm của dẫn xuất benzene","w":"Đề cho toluene (hoặc alkylbenzene) tác dụng với Br₂ (Fe) hoặc HNO₃/H₂SO₄.","s":["Nhận diện nhóm thế alkyl trên vòng (nhóm đẩy electron).","Xác định vị trí ortho và para so với nhóm –CH₃.","Viết sản phẩm thế mono ở o- và p- (sản phẩm chính).","Cân bằng phương trình."],"n":["Sản phẩm chính là hỗn hợp o- và p-, không phải m-.","Nhiệt độ cao, xúc tác Fe cho thế ở vòng; ánh sáng thế ở nhóm CH₃."]}],"sum":["Arene (hydrocarbon thơm) là hydrocarbon có chứa một hay nhiều vòng benzene. Dãy đồng đẳng của benzene có công thức CₙH₂ₙ₋₆ (n ≥ 6): benzene C₆H₆, toluene C₆H₅CH₃, xylene C₆H₄(CH₃)₂ (o-, m-, p-),…","Khái niệm: Arene (hydrocarbon thơm) là hydrocarbon có chứa một hay nhiều vòng benzene.","Cấu tạo benzene: 6 nguyên tử C tạo lục giác đều, cả 12 nguyên tử cùng nằm trên một mặt phẳng, các góc liên kết 120°, độ dài liên kết C–C đều bằng 139 pm (trung gian…","Tính chất vật lí: Benzene, toluene, xylene là chất lỏng không màu, mùi đặc trưng, dễ cháy, không tan trong nước, nhẹ hơn nước, tan trong dung môi hữu cơ; naphthalene…","Phản ứng thế: Halogen hoá (Br₂, xúc tác bột Fe hoặc FeBr₃): C₆H₆ + Br₂ → C₆H₅Br + HBr; nitro hoá (hỗn hợp HNO₃ đặc và H₂SO₄ đặc): C₆H₆ + HNO₃ → C₆H₅NO₂ + H₂O.","Phản ứng cộng: Benzene cộng hydrogen (Ni, Pt, t°, p cao) tạo cyclohexane: C₆H₆ + 3H₂ → C₆H₁₂; cộng Cl₂ (ánh sáng) tạo hexachlorocyclohexane C₆H₆Cl₆ (thuốc trừ sâu…"],"e":["Hay nhầm: Thế ở nhóm CH₃ cần ánh sáng.","Lưu ý: Sản phẩm chính là hỗn hợp o- và p-, không phải m-.","Lưu ý: Nhiệt độ cao, xúc tác Fe cho thế ở vòng; ánh sáng thế ở nhóm CH₃."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 18. Ôn tập chương 4","req":["Hệ thống hoá kiến thức alkane, alkene, alkyne, arene: công thức chung, cấu tạo, tính chất, điều chế, ứng dụng.","Vận dụng giải bài tập nhận biết, xác định công thức, tính toán."],"e":["Hay nhầm: Không tạo vinyl chloride."],"q":{"n":6,"lv":{"Hiểu":3,"Vận dụng":3}}}]},{"t":"Chương 5. Dẫn xuất halogen – Alcohol – Phenol","l":[{"t":"Bài 19. Dẫn xuất halogen","req":["Nêu khái niệm, gọi tên theo danh pháp thay thế dẫn xuất halogen.","Trình bày tính chất vật lí; phản ứng thế nguyên tử halogen bằng OH⁻ và phản ứng tách HX theo quy tắc Zaitsev.","Nêu ứng dụng và tác hại (CFC, thuốc trừ sâu); ứng xử hợp lí."],"m":[{"t":"Xác định sản phẩm chính của phản ứng tách HX","w":"Cho dẫn xuất halogen, đun với NaOH/ethanol, yêu cầu viết alkene.","s":["Xác định carbon mang halogen.","Liệt kê các carbon bên cạnh có H.","Chọn tách H ở carbon bậc cao hơn (nhiều nhóm alkyl hơn) → sản phẩm chính.","Viết sản phẩm phụ (nếu có)."],"n":["Không tách ra khỏi cùng carbon mang X.","Sản phẩm chính thường là alkene có nhiều nhóm thế hơn quanh C=C."]}],"sum":["Dẫn xuất halogen của hydrocarbon là hợp chất thu được khi thay H của hydrocarbon bằng nguyên tử halogen; công thức tổng quát RXₙ (X là F, Cl, Br, I).","Khái niệm: Dẫn xuất halogen của hydrocarbon là hợp chất thu được khi thay H của hydrocarbon bằng nguyên tử halogen; công thức tổng quát RXₙ (X là F, Cl, Br, I).","Liên kết C–X phân cực (C mang…: Liên kết C–X phân cực (C mang δ⁺, X mang δ⁻); năng lượng liên kết giảm từ C–F (486), C–Cl (327), C–Br (285) đến C–I (214 kJ/mol) nên khả năng bị…","Phản ứng thế (thuỷ phân trong kiềm): R–X + OH⁻ → R–OH + X⁻ (X gắn carbon no), ví dụ CH₃CH₂CH₂Cl + NaOH → CH₃CH₂CH₂OH + NaCl.","Phản ứng tách HX (NaOH/C₂H₅OH, đun nóng)…: Phản ứng tách HX (NaOH/C₂H₅OH, đun nóng) tạo alkene theo quy tắc Zaitsev: halogen bị tách cùng H ở carbon bên cạnh có bậc cao hơn (sản phẩm chính).","Ứng dụng: Dung môi (CH₂Cl₂, CHCl₃), sản xuất polymer (PVC, teflon), dược phẩm, chất làm lạnh (CFC trước đây; hiện dùng HFC như R32)."],"e":["Lưu ý: Không tách ra khỏi cùng carbon mang X.","Lưu ý: Sản phẩm chính thường là alkene có nhiều nhóm thế hơn quanh C=C."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 20. Alcohol","req":["Nêu khái niệm alcohol, công thức tổng quát, bậc alcohol; gọi tên theo danh pháp thay thế.","Giải thích tính chất vật lí bằng liên kết hydrogen; trình bày tính chất hoá học: thế H, tạo ether, tách nước, oxi hoá, cháy, phản ứng với Cu(OH)₂.","Nêu ứng dụng, tác hại của lạm dụng rượu bia và điều chế ethanol, glycerol."],"m":[{"t":"Phân biệt alcohol bậc I, II, III và sản phẩm oxi hoá","w":"Đề cho alcohol, yêu cầu viết sản phẩm oxi hoá bằng CuO hoặc phân biệt các alcohol.","s":["Xác định bậc của carbon gắn –OH.","Bậc I → aldehyde cùng số C; bậc II → ketone; bậc III → không phản ứng.","Viết phương trình RCH₂OH + CuO → RCHO + Cu + H₂O.","Với polyalcohol liền kề, dùng Cu(OH)₂ nhận biết."],"n":["Chất rắn đen CuO chuyển đỏ (Cu) khi phản ứng.","Oxi hoá hoàn toàn (cháy) cho CO₂, H₂O."]}],"sum":["Alcohol là hợp chất hữu cơ có nhóm –OH liên kết với nguyên tử carbon no. Alcohol no, đơn chức, mạch hở: CₙH₂ₙ₊₁OH (n ≥ 1).","Khái niệm: Alcohol là hợp chất hữu cơ có nhóm –OH liên kết với nguyên tử carbon no.","Danh pháp thay thế: Tên hydrocarbon bỏ \"e\" + số chỉ vị trí + \"ol\": CH₃OH methanol, C₂H₅OH ethanol, CH₃CH₂CH₂OH propan-1-ol, CH₃CH(OH)CH₃ propan-2-ol, CH₂=CH–CH₂OH…","Tính chất vật lí: Các liên kết O–H và C–O phân cực; giữa các phân tử alcohol có liên kết hydrogen nên nhiệt độ sôi cao hơn hydrocarbon và ether cùng phân tử khối…","Phản ứng thế H của –OH: 2ROH + 2Na → 2RONa + H₂.","Oxi hoá không hoàn toàn bằng CuO (đun nóng): Alcohol bậc I → aldehyde (RCH₂OH + CuO → RCHO + Cu + H₂O); alcohol bậc II → ketone; alcohol bậc III không bị oxi hoá trong điều kiện này."],"e":["Lưu ý: Chất rắn đen CuO chuyển đỏ (Cu) khi phản ứng.","Lưu ý: Oxi hoá hoàn toàn (cháy) cho CO₂, H₂O."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 21. Phenol","req":["Nêu khái niệm phenol, đặc điểm cấu tạo và tính chất vật lí.","Trình bày tính acid yếu và phản ứng thế vòng thơm (bromine, nitric acid).","Nêu ứng dụng và điều chế phenol (từ cumene)."],"m":[{"t":"Phân biệt phenol với alcohol và benzene","w":"Cho ethanol, phenol, benzene, yêu cầu nhận biết.","s":["Phenol: tác dụng NaOH (tan), nước bromine tạo kết tủa trắng.","Alcohol: không phản ứng với NaOH, không làm mất màu nước Br₂.","Benzene: lớp lỏng không tan, không phản ứng với nước Br₂ thường (chỉ chiết Br₂).","Kết luận theo hiện tượng."],"n":["Kết tủa trắng 2,4,6-tribromophenol là phản ứng đặc trưng.","Phenol không làm đổi màu quỳ tím."]}],"sum":["Phenol là hợp chất hữu cơ có nhóm –OH liên kết trực tiếp với nguyên tử carbon của vòng benzene;","Khái niệm: Phenol là hợp chất hữu cơ có nhóm –OH liên kết trực tiếp với nguyên tử carbon của vòng benzene;","Tính chất vật lí: Chất rắn không màu, nóng chảy 43 °C;","Tính acid yếu: Phenol tác dụng với dung dịch NaOH, và cả Na₂CO₃ (tạo NaHCO₃): C₆H₅OH + NaOH → C₆H₅ONa + H₂O.","Phản ứng thế ở vòng: Với nước bromine ở nhiệt độ thường tạo kết tủa trắng 2,4,6-tribromophenol (không cần xúc tác, khác benzene): C₆H₅OH + 3Br₂ → C₆H₂Br₃OH↓ + 3HBr.","Ứng dụng: Nguyên liệu tổng hợp nhựa phenol–formaldehyde, bisphenol A (polycarbonate), cyclohexanol, thuốc nhuộm, dược phẩm, thuốc diệt nấm, chất sát trùng."],"e":["Hay nhầm: Phenol không đổi màu quỳ.","Lưu ý: Kết tủa trắng 2,4,6-tribromophenol là phản ứng đặc trưng.","Lưu ý: Phenol không làm đổi màu quỳ tím."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 22. Ôn tập chương 5","req":["Hệ thống hoá dẫn xuất halogen, alcohol, phenol: cấu tạo, tính chất, chuyển hoá.","Vận dụng giải bài tập nhận biết và tính toán."],"e":["Hay nhầm: Không thay đổi số oxi hoá."],"q":{"n":6,"lv":{"Hiểu":3,"Vận dụng":3}}}]},{"t":"Chương 6. Hợp chất carbonyl – Carboxylic acid","l":[{"t":"Bài 23. Hợp chất carbonyl","req":["Nêu khái niệm aldehyde, ketone; gọi tên theo danh pháp thay thế.","Mô tả cấu tạo nhóm carbonyl; tính chất vật lí.","Trình bày phản ứng khử, oxi hoá aldehyde (Br₂, Tollens, Cu(OH)₂), cộng HCN, tạo iodoform; ứng dụng và điều chế."],"m":[{"t":"Nhận biết aldehyde, ketone","w":"Phân biệt các chất carbonyl (ethanal, propanone, ...).","s":["Dùng thuốc thử Tollens (hoặc Cu(OH)₂/OH⁻, đun nóng): chỉ aldehyde cho Ag↓ (hoặc Cu₂O đỏ gạch).","Dùng I₂/NaOH: chất có nhóm CH₃CO– cho CHI₃ vàng.","Kết hợp hai thuốc thử để phân biệt.","Viết phương trình."],"n":["Tỉ lệ aldehyde đơn chức : Ag = 1 : 2 (trừ HCHO: 1 : 4).","Ketone không tráng bạc."]}],"sum":["Aldehyde là hợp chất hữu cơ có nhóm –CHO liên kết với carbon (gốc hydrocarbon hoặc –CHO) hoặc với hydrogen.","Khái niệm: Aldehyde là hợp chất hữu cơ có nhóm –CHO liên kết với carbon (gốc hydrocarbon hoặc –CHO) hoặc với hydrogen.","Danh pháp thay thế: Aldehyde = tên hydrocarbon bỏ \"e\" + \"al\" (nhóm –CHO ở C1): methanal HCHO, ethanal CH₃CHO, 3-methylbutanal, but-3-enal.","Tính chất vật lí: Phân cực nên nhiệt độ sôi cao hơn hydrocarbon cùng phân tử khối (nhưng thấp hơn alcohol vì không có liên kết hydrogen giữa các phân tử); methanal…","Phản ứng khử (NaBH₄ hoặc LiAlH₄): Aldehyde + 2[H] → alcohol bậc I; ketone + 2[H] → alcohol bậc II.","Phản ứng cộng HCN vào nhóm C=O…: Phản ứng cộng HCN vào nhóm C=O tạo cyanohydrin: CH₃CHO + HCN → CH₃CH(OH)CN."],"e":["Lưu ý: Tỉ lệ aldehyde đơn chức : Ag = 1 : 2 (trừ HCHO: 1 : 4).","Lưu ý: Ketone không tráng bạc."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":3}}},{"t":"Bài 24. Carboxylic acid","req":["Nêu khái niệm, gọi tên carboxylic acid; đặc điểm cấu tạo nhóm –COOH và acetic acid.","Giải thích tính chất vật lí; trình bày tính acid và phản ứng ester hoá.","Nêu ứng dụng, điều chế (lên men giấm, oxi hoá alkane)."],"m":[{"t":"Giải bài toán ester hoá có hiệu suất","w":"Cho khối lượng acid, alcohol, ester thu được; tính hiệu suất.","s":["Viết phương trình RCOOH + R′OH ⇌ RCOOR′ + H₂O.","Tính số mol từng chất tham gia, xác định chất thiếu (theo tỉ lệ 1 : 1).","Tính khối lượng ester lí thuyết theo chất thiếu.","H = m thực tế / m lí thuyết × 100%."],"n":["Ester hoá thuận nghịch nên hiệu suất < 100%.","Hiệu suất tính theo chất phản ứng hết (chất thiếu)."]}],"sum":["Carboxylic acid là hợp chất hữu cơ có nhóm carboxyl –COOH liên kết với carbon (gốc hydrocarbon hoặc –COOH) hoặc hydrogen; công thức đơn chức RCOOH.","Khái niệm: Carboxylic acid là hợp chất hữu cơ có nhóm carboxyl –COOH liên kết với carbon (gốc hydrocarbon hoặc –COOH) hoặc hydrogen; công thức đơn chức RCOOH.","Cấu tạo: Nhóm –COOH gồm >C=O và –OH liền nhau; nhóm C=O hút electron nên liên kết O–H phân cực mạnh hơn alcohol, phenol; dễ phân li H⁺ nên tính chất đặc…","Tính chất vật lí: Nhiệt độ sôi cao hơn hydrocarbon, alcohol, aldehyde cùng phân tử khối (acetic acid 118 °C; propan-1-ol 97 °C; propanal 49 °C); acid mạch ngắn…","Tính acid (yếu): Làm quỳ tím hoá đỏ nhạt; phản ứng với kim loại trước H, oxide base, base, muối carbonate: 2CH₃COOH + Mg → (CH₃COO)₂Mg + H₂;","Phản ứng ester hoá: RCOOH + R′OH ⇌ RCOOR′ + H₂O (H₂SO₄ đặc, đun nóng), thuận nghịch."],"e":["Lưu ý: Ester hoá thuận nghịch nên hiệu suất < 100%.","Lưu ý: Hiệu suất tính theo chất phản ứng hết (chất thiếu)."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":3}}},{"t":"Bài 25. Ôn tập chương 6","req":["Hệ thống hoá hợp chất carbonyl và carboxylic acid: cấu tạo, tính chất, chuyển hoá.","Vận dụng giải bài tập nhận biết, tính toán."],"q":{"n":5,"lv":{"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương 1. Cân bằng hoá học","l":[{"t":"Bài tập nâng cao · Chương 1. Cân bằng hoá học (7 câu)","q":{"n":7,"lv":{"Nâng cao":7}}}]},{"t":"Chương 2. Nitrogen – Sulfur","l":[{"t":"Bài tập nâng cao · Chương 2. Nitrogen – Sulfur (14 câu)","q":{"n":14,"lv":{"Nâng cao":14}}}]},{"t":"Chương 3. Đại cương về hoá học hữu cơ","l":[{"t":"Bài tập nâng cao · Chương 3. Đại cương về hoá học hữu cơ (10 câu)","q":{"n":10,"lv":{"Nâng cao":10}}}]},{"t":"Chương 4. Hydrocarbon","l":[{"t":"Bài tập nâng cao · Chương 4. Hydrocarbon (12 câu)","q":{"n":12,"lv":{"Nâng cao":12}}}]},{"t":"Chương 5. Dẫn xuất halogen – Alcohol – Phenol","l":[{"t":"Bài tập nâng cao · Chương 5. Dẫn xuất halogen – Alcohol – Phenol (10 câu)","e":["Hay nhầm: Không tạo từ alcohol này."],"q":{"n":10,"lv":{"Nâng cao":10}}}]},{"t":"Chương 6. Hợp chất carbonyl – Carboxylic acid","l":[{"t":"Bài tập nâng cao · Chương 6. Hợp chất carbonyl – Carboxylic acid (9 câu)","e":["Hay nhầm: Nước làm cân bằng chuyển nghịch."],"q":{"n":9,"lv":{"Nâng cao":9}}}]}]}]},{"id":"sinh","name":"Sinh học","b":[{"t":"Sinh học 11","c":[{"t":"Chương 1. Trao đổi chất và chuyển hoá năng lượng ở sinh vật","l":[{"t":"Bài 1. Khái quát về trao đổi chất và chuyển hoá năng lượng","req":["Phân tích được vai trò của trao đổi chất và chuyển hoá năng lượng đối với sinh vật.","Nêu được các dấu hiệu đặc trưng của trao đổi chất và chuyển hoá năng lượng.","Dựa vào sơ đồ, mô tả được tóm tắt ba giai đoạn chuyển hoá năng lượng: tổng hợp, phân giải và huy động năng lượng."],"sum":["Sinh vật không thể tồn tại và phát triển nếu không thực hiện trao đổi chất và chuyển hoá năng lượng.","Khái niệm: Sinh vật không thể tồn tại và phát triển nếu không thực hiện trao đổi chất và chuyển hoá năng lượng.","Các dấu hiệu đặc trưng của trao đổi chất và chuyển hoá năng lượng: Tiếp nhận các chất từ môi trường và vận chuyển các chất (thực vật lấy nước, khoáng, CO₂ và ánh sáng; hầu hết động vật lấy chất dinh dưỡng nhờ hệ…","Đồng hoá là quá trình tổng hợp…: Đồng hoá là quá trình tổng hợp chất hữu cơ phức tạp từ các chất đơn giản, kèm theo tích luỹ năng lượng trong các liên kết hoá học.","Chuyển hoá năng lượng trong sinh giới gồm ba giai đoạn: Tổng hợp (tích luỹ trong các chất hữu cơ): năng lượng khởi đầu là quang năng mặt trời; chất diệp lục của cây xanh thu nhận quang năng để tổng hợp…","Mối quan hệ giữa trao đổi chất…: Mối quan hệ giữa trao đổi chất và chuyển hoá năng lượng ở cấp tế bào và cơ thể: chất dinh dưỡng cơ thể lấy vào được chuyển tới tế bào, tham gia đồng…"],"e":["Hay nhầm: Thải chất là dấu hiệu khác của trao đổi chất, không phải định nghĩa đồng hoá.","Hay nhầm: Hấp thụ O₂ là tiếp nhận chất từ môi trường.","Hay nhầm: Phải có tổng hợp trước rồi mới phân giải.","Hay nhầm: Huy động năng lượng là bước cuối.","Hay nhầm: Phân giải xảy ra trước khi huy động.","Hay nhầm: Nhiệt là dạng năng lượng cuối cùng của chuyển hoá."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 2. Trao đổi nước và khoáng ở thực vật","req":["Trình bày được vai trò của nước đối với thực vật và mô tả ba giai đoạn trao đổi nước: hấp thụ ở rễ, vận chuyển ở thân, thoát hơi nước ở lá.","Trình bày được cơ chế hấp thụ nước và khoáng ở tế bào lông hút của rễ.","Nêu được hai dòng vận chuyển các chất: mạch gỗ và mạch rây."],"sum":["Nước và chất khoáng là những chất dinh dưỡng của thực vật. Dinh dưỡng ở thực vật là quá trình hấp thụ nước, chất khoáng và đồng hoá chúng thành chất sống của cơ thể.","Nước và chất khoáng là những chất dinh dưỡng của thực vật: Dinh dưỡng ở thực vật là quá trình hấp thụ nước, chất khoáng và đồng hoá chúng thành chất sống của cơ thể.","Trong cơ thể thực vật có hơn…: Trong cơ thể thực vật có hơn 50 nguyên tố nhưng chỉ khoảng 17 nguyên tố là thiết yếu (thiếu thì cây không hoàn thành chu kì sống).","Trao đổi nước ở thực vật diễn ra qua ba giai đoạn: Hấp thụ nước ở rễ, vận chuyển nước ở thân và thoát hơi nước ở lá.","Hấp thụ ở rễ: Thực vật trên cạn hấp thụ nước và khoáng chủ yếu qua lông hút.","Nước và khoáng đi từ lông hút vào mạch gỗ của rễ theo hai con đường: Gian bào (qua thành tế bào và khoảng giữa các tế bào, đến nội bì gặp vành đai Caspary không thấm nước nên phải xuyên qua màng tế bào nội bì, nhờ đó…"],"e":["Hay nhầm: Khí khổng thoát hơi nước.","Hay nhầm: Mạch rây vận chuyển chất hữu cơ.","Hay nhầm: Đó là chức năng của mạch rây.","Hay nhầm: Mạch gỗ chủ yếu nước và khoáng.","Hay nhầm: Không vận chuyển chất thải.","Hay nhầm: Tinh bột không tan để vận chuyển."],"q":{"n":14,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":4}}},{"t":"Bài 3. Thực hành: Trao đổi nước và khoáng ở thực vật","req":["Thực hiện được các thí nghiệm chứng minh sự hấp thụ nước ở rễ, vận chuyển nước ở thân và thoát hơi nước ở lá.","Quan sát được cấu tạo khí khổng ở lá; thực hành tưới nước hợp lí cho cây.","Nêu được quy trình trồng cây thuỷ canh, khí canh và so sánh với trồng cây trên đất."],"sum":["Dụng cụ, hoá chất, mẫu vật: lam kính, ống nghiệm, cốc thuỷ tinh 100 mL, chậu trồng cây, kim mũi mác, kẹp, giấy thấm, dao lam, kính hiển vi; dung dịch màu thực phẩm, xanh methylene, dung dịch cobalt…","Dụng cụ, hoá chất, mẫu vật: Lam kính, ống nghiệm, cốc thuỷ tinh 100 mL, chậu trồng cây, kim mũi mác, kẹp, giấy thấm, dao lam, kính hiển vi; dung dịch màu thực phẩm, xanh…","Chứng minh sự hấp thụ nước ở rễ: Nguyên lí: dựa vào sự thay đổi lượng nước cung cấp cho cây trước và sau thí nghiệm.","Chứng minh vận chuyển nước ở thân: Nguyên lí: dùng dung dịch màu đánh dấu đường đi của nước trong hệ mạch.","Chứng minh thoát hơi nước ở lá: Nguyên lí: giấy tẩm cobalt chloride khô có màu xanh, gặp hơi ẩm chuyển hồng.","Quan sát khí khổng: Dùng kim mũi mác bóc lớp biểu bì mỏng ở mặt dưới lá thài lài tía, đặt lên lam kính, nhỏ một giọt nước cất, quan sát dưới kính ở vật kính 10× và 40×;…"],"e":["Hay nhầm: Thoát hơi nước dùng giấy cobalt.","Hay nhầm: Quang hợp cần ánh sáng và CO₂.","Hay nhầm: Hô hấp không liên quan thí nghiệm.","Hay nhầm: Thuỷ canh nhúng rễ vào dung dịch.","Hay nhầm: Trồng đất dùng đất làm giá thể.","Hay nhầm: Cutin cản thoát hơi nước."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 4. Quang hợp ở thực vật","req":["Phát biểu được khái niệm quang hợp, viết được phương trình quang hợp và nêu vai trò của quang hợp.","Trình bày được vai trò của hệ sắc tố trong hấp thụ năng lượng ánh sáng và các sản phẩm của pha sáng.","Nêu được các con đường đồng hoá carbon C₃, C₄, CAM và chứng minh sự thích nghi của thực vật C₄, CAM."],"sum":["Quang hợp ở thực vật là quá trình lục lạp hấp thụ và sử dụng năng lượng ánh sáng để chuyển hoá CO₂ và nước thành hợp chất hữu cơ (C₆H₁₂O₆) đồng thời giải phóng O₂.","Khái niệm: Quang hợp ở thực vật là quá trình lục lạp hấp thụ và sử dụng năng lượng ánh sáng để chuyển hoá CO₂ và nước thành hợp chất hữu cơ (C₆H₁₂O₆) đồng thời…","Hệ sắc tố quang hợp gồm hai nhóm: Diệp lục (chlorophyll, chủ yếu diệp lục a, hấp thụ ánh sáng đỏ và xanh tím, tạo màu xanh của lá) và carotenoid (xanthophyll và carotene, tạo màu…","Quang hợp diễn ra trong lục lạp theo hai pha: Pha sáng xảy ra trên màng thylakoid, có sự tham gia của ánh sáng và sắc tố, giống nhau ở mọi nhóm thực vật: nước phân li 2H₂O → 4H⁺ + 4e⁻ + O₂;…","Thực vật C₃ (lúa, khoai, sắn, rau…: Thực vật C₃ (lúa, khoai, sắn, rau, đậu; chủ yếu ôn đới, cận nhiệt đới): chất nhận CO₂ đầu tiên là RuBP, sản phẩm đầu tiên là hợp chất 3C là 3-PGA;","Thực vật C₄ và CAM có thêm…: Thực vật C₄ và CAM có thêm chu trình sơ bộ cố định CO₂, đảm bảo nguồn cung cấp CO₂ cho quang hợp trong điều kiện nóng, hạn nên thích nghi tốt với…"],"e":["Hay nhầm: Chất nền là nơi diễn ra pha tối.","Hay nhầm: CO₂ và H₂O là nguyên liệu.","Hay nhầm: ADP, NADP⁺ là chất bị biến đổi.","Hay nhầm: PEP là chất nhận ở thực vật C₄.","Hay nhầm: OAA là sản phẩm đầu tiên ở C₄.","Hay nhầm: G3P là sản phẩm của chu trình."],"q":{"n":14,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 5. Thực hành: Quang hợp ở thực vật","req":["Quan sát được lục lạp trong tế bào thực vật.","Nhận biết và tách chiết được các sắc tố (diệp lục a, b, carotene, xanthophyll) trong lá cây.","Thiết kế và thực hiện được thí nghiệm về sự hình thành tinh bột và sự thải O₂ trong quang hợp."],"sum":["Quan sát lục lạp: lục lạp là bào quan có màu, di chuyển trong dịch tế bào. Lấy lá rong mái chèo tươi, bóc lớp biểu bì, đặt lên lam kính, nhỏ một giọt nước cất, đậy lamen và quan sát dưới kính ở vật…","Quan sát lục lạp: Lục lạp là bào quan có màu, di chuyển trong dịch tế bào.","Tách chiết sắc tố: Một số dung môi hữu cơ phá vỡ liên kết giữa diệp lục, lipid và protein trong lá nên chiết sắc tố thành dung dịch; sắc kí giấy tách các sắc tố.","Sự tạo thành tinh bột: Iodine là thuốc thử tinh bột, nhỏ vào tinh bột thì chuyển màu xanh tím.","Sự thải oxygen: Lấy hai cành rong đuôi chó cho vào hai phễu thuỷ tinh (ngọn ở phía miệng phễu), úp phễu vào hai cốc nước và úp ống nghiệm chứa đầy nước lên cuống…","Trả lời câu hỏi thường gặp: Phải để chậu cây trong bóng tối 2 ngày để lá cạn tinh bột sẵn có, đảm bảo tinh bột tìm thấy sau đó chỉ do quang hợp tạo ra."],"e":["Hay nhầm: Cobalt chloride nhận biết nước.","Hay nhầm: Acetone là dung môi chiết sắc tố.","Hay nhầm: Xanh methylene là thuốc nhuộm.","Hay nhầm: Nước cất hoà tan kém sắc tố.","Hay nhầm: Iodine là thuốc thử tinh bột.","Hay nhầm: Phần được chiếu sáng mới xanh tím."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 6. Hô hấp ở thực vật","req":["Nêu được khái niệm hô hấp và phân tích được vai trò của hô hấp ở thực vật.","Trình bày được sơ đồ các giai đoạn của hô hấp hiếu khí và lên men.","Phân tích được ảnh hưởng của các điều kiện môi trường đến hô hấp; vận dụng vào bảo quản nông sản và trồng trọt."],"sum":["Hô hấp là quá trình phân giải các hợp chất hữu cơ phức tạp, phổ biến là carbohydrate, thành các chất đơn giản, đồng thời tạo ra ATP và nhiệt năng.","Khái niệm: Hô hấp là quá trình phân giải các hợp chất hữu cơ phức tạp, phổ biến là carbohydrate, thành các chất đơn giản, đồng thời tạo ra ATP và nhiệt năng.","Vai trò: ATP cung cấp năng lượng cho hầu hết hoạt động sống (tổng hợp, vận chuyển chất, sinh trưởng, cảm ứng); nhiệt năng giúp duy trì nhiệt độ cơ thể; các…","Hô hấp hiếu khí gồm ba giai đoạn: Đường phân xảy ra ở tế bào chất, không cần O₂: 1 glucose thành 2 pyruvate, thu 2 ATP và 2 NADH.","Lên men xảy ra khi thiếu O₂ (rễ ngập úng, hạt ngâm trong nước lâu): Gồm đường phân (giống hô hấp hiếu khí) rồi lên men pyruvate thành ethanol hoặc lactate;","Các yếu tố ảnh hưởng: Nước (trong giới hạn, cường độ hô hấp tỉ lệ thuận với hàm lượng nước; hạt khô 11 – 12% nước hô hấp rất yếu, khi hút nước và nảy mầm hô hấp tăng…"],"e":["Hay nhầm: Chu trình Krebs chỉ có ở hiếu khí.","Hay nhầm: Chuỗi truyền electron chỉ ở hiếu khí.","Hay nhầm: Oxy hoá pyruvate chỉ ở hiếu khí.","Hay nhầm: Đường phân ở tế bào chất.","Hay nhầm: Chuỗi truyền electron ở màng trong.","Hay nhầm: Thiếu năng lượng nên không hút được khoáng."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 7. Thực hành: Hô hấp ở thực vật","req":["Thực hành được thí nghiệm chứng minh hô hấp ở hạt nảy mầm bằng cách phát hiện CO₂.","Giải thích được kết quả và vai trò của các điều kiện thí nghiệm."],"sum":["Chuẩn bị: tủ sấy (nếu có), đĩa Petri, bông hoặc giấy thấm, cốc thuỷ tinh, nước ấm khoảng 40 °C, hai chuông thuỷ tinh; nước vôi trong; hạt đậu tương, đậu đen, đậu xanh, lạc hoặc vừng.","Chuẩn bị: Tủ sấy (nếu có), đĩa Petri, bông hoặc giấy thấm, cốc thuỷ tinh, nước ấm khoảng 40 °C, hai chuông thuỷ tinh; nước vôi trong; hạt đậu tương, đậu đen,…","Nguyên lí: CO₂ do hạt nảy mầm hô hấp tạo ra được nước vôi trong hấp thụ tạo kết tủa CaCO₃, làm nước vôi vẩn đục (váng trắng trên bề mặt).","Bước 1 – chuẩn bị hạt nảy mầm: Chọn khoảng 5 g hạt chắc, không vỡ, không mọt; ngâm trong nước ấm khoảng 40 °C khoảng 2 giờ; vớt hạt, rải vào đĩa Petri có lót giấy thấm; phủ giấy…","Bước 2 – tiến hành: Dán nhãn hai chuông A, B; chuông A đặt đĩa hạt nảy mầm và một cốc nước vôi trong; chuông B chỉ đặt một cốc nước vôi trong (đối chứng);","Kết quả: Nước vôi ở chuông A vẩn đục rõ, ở chuông B hầu như trong."],"e":["Hay nhầm: Iodine nhận biết tinh bột.","Hay nhầm: Cobalt chloride nhận biết nước."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 8. Dinh dưỡng và tiêu hoá ở động vật","req":["Nêu được quá trình dinh dưỡng gồm lấy thức ăn, tiêu hoá, hấp thụ và đồng hoá.","Dựa vào sơ đồ, trình bày được các hình thức tiêu hoá ở động vật.","Vận dụng được hiểu biết để xây dựng chế độ ăn uống khoa học; giải thích vai trò của thực phẩm sạch."],"sum":["Dinh dưỡng ở động vật và người là quá trình lấy chất dinh dưỡng cần thiết dưới dạng thức ăn và tổng hợp thành chất sống của cơ thể.","Khái niệm: Dinh dưỡng ở động vật và người là quá trình lấy chất dinh dưỡng cần thiết dưới dạng thức ăn và tổng hợp thành chất sống của cơ thể.","Lấy thức ăn có ba kiểu chính: Ăn lọc (lọc nước qua bộ phận chuyên hoá, ví dụ trai có tấm mang lọc sinh vật nhỏ);","Tiêu hoá là quá trình biến đổi…: Tiêu hoá là quá trình biến đổi thức ăn có cấu tạo phức tạp thành các phân tử nhỏ, đơn giản mà cơ thể hấp thụ được.","Các hình thức tiêu hoá: Động vật chưa có cơ quan tiêu hoá (ngành Thân lỗ) tiêu hoá nội bào nhờ tế bào cổ áo, tế bào amip;","Ở người, ống tiêu hoá cùng gan…: Ở người, ống tiêu hoá cùng gan, tuỵ và các tuyến nước bọt tạo thành hệ tiêu hoá."],"e":["Hay nhầm: Không thể tiêu hoá trước khi lấy thức ăn.","Hay nhầm: Glucose có sau ở ruột non.","Hay nhầm: Ruột già chủ yếu hấp thụ nước.","Hay nhầm: Thực quản chỉ dẫn thức ăn.","Hay nhầm: Thành mỏng chứ không dày.","Hay nhầm: Protein do pepsin, trypsin."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 9. Hô hấp ở động vật","req":["Phân tích được vai trò của hô hấp ở động vật.","Trình bày được các hình thức trao đổi khí và giải thích một số hiện tượng thực tiễn.","Tìm hiểu được bệnh đường hô hấp, tác hại của thuốc lá và ô nhiễm không khí; vai trò của thể dục thể thao đối với hô hấp."],"sum":["Hô hấp là quá trình lấy O₂ liên tục từ môi trường cung cấp cho hô hấp tế bào, tạo năng lượng cho hoạt động sống, đồng thời thải CO₂ sinh ra ra ngoài, giúp cân bằng môi trường trong cơ thể.","Khái niệm: Hô hấp là quá trình lấy O₂ liên tục từ môi trường cung cấp cho hô hấp tế bào, tạo năng lượng cho hoạt động sống, đồng thời thải CO₂ sinh ra ra…","Trao đổi khí qua bề mặt cơ thể: Gặp ở Ruột khoang, Giun dẹp, và cả Giun đốt, ếch (da ẩm, nhiều mạch máu); khí O₂, CO₂ khuếch tán qua toàn bộ bề mặt cơ thể.","Trao đổi khí qua mang: Ở động vật sống dưới nước (thân mềm, chân khớp, cá, nòng nọc).","Trao đổi khí qua phổi: Ở bò sát, chim, thú (lưỡng cư có phổi nhưng ít phế nang nên chủ yếu qua da).","Phổi chim có hệ thống túi khí…: Phổi chim có hệ thống túi khí, không có phế nang; phế quản phân nhánh thành mao mạch khí; dòng khí trong mao mạch khí chảy ngược chiều với máu."],"e":["Hay nhầm: Phổi ở động vật trên cạn.","Hay nhầm: Mang ở động vật dưới nước.","Hay nhầm: Phổi ở động vật có xương sống.","Hay nhầm: Có hệ ống khí chuyên hoá.","Hay nhầm: Ngược chiều chứ không cùng chiều.","Hay nhầm: Cả khi thở ra vẫn có khí giàu O₂ qua."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 10. Tuần hoàn ở động vật","req":["Trình bày được khái quát hệ vận chuyển và các dạng hệ tuần hoàn ở động vật.","Mô tả được cấu tạo, hoạt động của tim, hệ mạch và vận chuyển máu trong hệ mạch.","Nêu được cơ chế điều hoà hoạt động tim mạch."],"sum":["Hệ tuần hoàn gồm dịch tuần hoàn (máu hoặc hỗn hợp máu – dịch mô), tim (bơm hút và đẩy máu), hệ thống mạch máu gồm động mạch (đưa máu từ tim đến cơ quan), tĩnh mạch (đưa máu từ cơ quan về tim) và mao…","Khái niệm: Hệ tuần hoàn gồm dịch tuần hoàn (máu hoặc hỗn hợp máu – dịch mô), tim (bơm hút và đẩy máu), hệ thống mạch máu gồm động mạch (đưa máu từ tim đến cơ…","Hệ tuần hoàn hở (đa số chân khớp, một số thân mềm): Tim bơm máu vào động mạch với áp lực thấp, máu chảy vào xoang cơ thể trộn với dịch mô, trao đổi chất trực tiếp với tế bào rồi về tim theo ống góp;…","Tim người có bốn buồng: Hai tâm nhĩ nhỏ nhận máu từ tĩnh mạch, hai tâm thất lớn bơm máu ra động mạch; giữa nhĩ và thất, giữa thất và động mạch có van giúp máu chảy một chiều.","Chu kì tim gồm tâm thu (pha co) và tâm trương (pha dãn): Tâm nhĩ co (0,1 s), tâm thất co (0,3 s), dãn chung (0,4 s), tổng 0,8 s ứng với 75 chu kì/phút ở người trưởng thành.","Động mạch và tĩnh mạch có ba…: Động mạch và tĩnh mạch có ba lớp (biểu mô, cơ trơn và sợi đàn hồi, mô liên kết); tĩnh mạch ở chân có van; mao mạch chỉ gồm một lớp tế bào biểu mô…"],"e":["Hay nhầm: Giun dẹp chưa có hệ tuần hoàn.","Hay nhầm: Nút nhĩ thất truyền xung.","Hay nhầm: Purkinje lan vào cơ tâm thất.","Hay nhầm: Ba lớp là động mạch, tĩnh mạch.","Hay nhầm: Mao mạch không có cơ dày.","Hay nhầm: Không có mô liên kết dày."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 11. Thực hành: Một số thí nghiệm về tuần hoàn","req":["Thực hành đo được huyết áp, đếm nhịp tim ở người ở các trạng thái hoạt động khác nhau và giải thích kết quả.","Mổ được tim ếch, tìm hiểu tính tự động của tim, vai trò của dây giao cảm, đối giao cảm và tác động của adrenalin."],"sum":["Đếm nhịp tim: đếm mạch đập ở cổ tay trong 1 phút khi nghỉ ngơi (ngửa tay, ấn ba ngón trỏ, giữa, áp út vào rãnh quay), rồi đếm ngay sau khi chạy nhanh tại chỗ và sau khi nghỉ để so sánh.","Đếm nhịp tim: Đếm mạch đập ở cổ tay trong 1 phút khi nghỉ ngơi (ngửa tay, ấn ba ngón trỏ, giữa, áp út vào rãnh quay), rồi đếm ngay sau khi chạy nhanh tại chỗ và…","Đo huyết áp bằng huyết áp kế điện tử: Ngồi nghỉ vài phút, đặt vòng bọc ở cánh tay ngang tim, bấm công tắc, máy tự bơm và xả khí; màn hình hiển thị huyết áp tâm thu (trên), tâm trương…","Tính tự động của tim ếch: Phá tuỷ sống ếch, ghim ngửa trên khay mổ; cắt da ngực hình tam giác, nâng xương ức, cắt bỏ mảnh lồng ngực, cắt màng bao tim để lộ tim;","Vai trò dây thần kinh: Tách dây thần kinh hỗn hợp (giao cảm và đối giao cảm) đặt vào điện cực kích thích 5 s; dây giao cảm làm tim đập nhanh, mạnh; dây đối giao cảm làm…"],"e":["Hay nhầm: Khuỷu tay không bắt mạch tiện.","Hay nhầm: Nước cất không làm nhanh.","Hay nhầm: Dung dịch sinh lí giữ tim hoạt động bình thường.","Hay nhầm: Phải chờ ~3 phút giữa hai lần đo.","Hay nhầm: Số liệu cao hơn bình thường."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 12. Miễn dịch ở người và động vật","req":["Nêu được nguyên nhân bên trong và bên ngoài gây bệnh; giải thích vì sao nguy cơ mắc bệnh lớn nhưng xác suất bị bệnh nhỏ.","Nêu được khái niệm miễn dịch, phân biệt miễn dịch không đặc hiệu và đặc hiệu.","Trình bày được cơ chế miễn dịch đặc hiệu, đáp ứng nguyên phát, thứ phát và vai trò của vaccine."],"sum":["Bệnh là sự sai lệch hoặc tổn thương về cấu trúc và chức năng của một bộ phận, cơ quan hay hệ thống của cơ thể, biểu hiện bằng bộ triệu chứng đặc trưng.","Khái niệm: Bệnh là sự sai lệch hoặc tổn thương về cấu trúc và chức năng của một bộ phận, cơ quan hay hệ thống của cơ thể, biểu hiện bằng bộ triệu chứng đặc…","Miễn dịch là khả năng cơ thể…: Miễn dịch là khả năng cơ thể chống lại các tác nhân gây bệnh, đảm bảo cơ thể khoẻ mạnh.","Miễn dịch không đặc hiệu có sẵn, chống mọi mầm bệnh: Hàng rào vật lí, hoá học: da (lớp sừng, vi khuẩn vô hại), lysozyme trong nước bọt, acid và pepsin ở dạ dày, dịch nhầy và lông rung ở đường hô hấp,…","Miễn dịch đặc hiệu (thích ứng) chỉ…: Miễn dịch đặc hiệu (thích ứng) chỉ có ở động vật có xương sống, là phản ứng chống lại từng mầm bệnh riêng biệt giữa tế bào miễn dịch, kháng thể và…","Cơ chế: Tế bào trình diện kháng nguyên báo hiệu cho tế bào T hỗ trợ; tế bào T hỗ trợ tiết cytokine."],"e":["Hay nhầm: Gan, thận có chức năng khác.","Hay nhầm: Dạ dày, ruột là tiêu hoá.","Hay nhầm: Phổi, tim là hô hấp, tuần hoàn.","Hay nhầm: Côn trùng chỉ có miễn dịch không đặc hiệu.","Hay nhầm: T độc tiêu diệt tế bào nhiễm.","Hay nhầm: Bạch cầu ưa acid diệt giun."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 13. Bài tiết và cân bằng nội môi","req":["Phát biểu được khái niệm và vai trò của bài tiết; trình bày vai trò của thận.","Nêu được khái niệm nội môi, cân bằng nội môi và cơ chế chung điều hoà nội môi.","Nêu được vai trò của thận, gan, phổi và một số hằng số nội môi."],"sum":["Bài tiết là quá trình loại bỏ ra khỏi cơ thể các chất sinh ra từ chuyển hoá mà cơ thể không sử dụng, các chất độc hại và chất dư thừa (CO₂, urea, uric acid, creatinine, bilirubin...).","Khái niệm: Bài tiết là quá trình loại bỏ ra khỏi cơ thể các chất sinh ra từ chuyển hoá mà cơ thể không sử dụng, các chất độc hại và chất dư thừa (CO₂, urea,…","Thận ở người gồm hai quả thuộc…: Thận ở người gồm hai quả thuộc hệ tiết niệu, mỗi thận có khoảng một triệu nephron (đơn vị chức năng), gồm cầu thận (búi mao mạch và nang Bowman) và…","Nội môi là môi trường trong cơ…: Nội môi là môi trường trong cơ thể gồm máu, bạch huyết và dịch mô.","Hệ thống điều hoà cân bằng nội…: Hệ thống điều hoà cân bằng nội môi gồm bộ phận tiếp nhận kích thích, bộ phận điều khiển (trung ương thần kinh hoặc tuyến nội tiết) và bộ phận thực…","Thận, gan và phổi là các cơ quan quan trọng hàng đầu: Thận điều hoà muối, nước, duy trì áp suất thẩm thấu (ví dụ khi áp suất thẩm thấu tăng, vùng dưới đồi gây cảm giác khát và tiết ADH làm tăng tái hấp…"],"e":["Hay nhầm: Tế bào chất là bên trong tế bào.","Hay nhầm: Không phải tuyến nước bọt.","Hay nhầm: Kích thích là tín hiệu ban đầu.","Hay nhầm: Bài tiết là chức năng khác.","Hay nhầm: Không phải ức chế tế bào.","Hay nhầm: Thận không tái tạo như vậy."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}}]},{"t":"Chương 2. Cảm ứng ở sinh vật","l":[{"t":"Bài 14. Khái quát về cảm ứng ở sinh vật","req":["Phát biểu được khái niệm cảm ứng ở sinh vật.","Trình bày được vai trò và cơ chế cảm ứng ở sinh vật."],"sum":["Cảm ứng là sự tiếp nhận và phản ứng của sinh vật đối với những thay đổi của môi trường (trong và ngoài), đảm bảo cho sinh vật thích ứng với môi trường sống.","Khái niệm: Cảm ứng là sự tiếp nhận và phản ứng của sinh vật đối với những thay đổi của môi trường (trong và ngoài), đảm bảo cho sinh vật thích ứng với môi…","Vai trò: Cảm ứng là đặc điểm thích nghi với thay đổi của môi trường, đảm bảo sinh vật tồn tại và phát triển.","Cơ chế cảm ứng thông qua các bộ phận: Tiếp nhận kích thích, dẫn truyền thông tin, xử lí thông tin và đáp ứng."],"e":["Hay nhầm: Sinh sản là chức năng khác.","Hay nhầm: Thực vật không có xung thần kinh.","Hay nhầm: Thực vật không có cơ vân.","Hay nhầm: Nảy mầm do nhiều yếu tố sinh trưởng.","Hay nhầm: Quả rụng không phải đáp ứng kích thích.","Hay nhầm: Đây là người, không phải thực vật."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 15. Cảm ứng ở thực vật","req":["Nêu được khái niệm, vai trò và đặc điểm cảm ứng ở thực vật.","Trình bày được hướng động và ứng động, cơ chế của chúng.","Vận dụng được hiểu biết về cảm ứng ở thực vật để giải thích hiện tượng thực tiễn và ứng dụng trong sản xuất."],"sum":["Cảm ứng ở thực vật là sự tiếp nhận và trả lời của thực vật đối với kích thích từ môi trường, biểu hiện bằng vận động của cơ quan, bộ phận (leo giàn của tua cuốn, uốn cong rễ, thân non, nở hoặc khép…","Khái niệm: Cảm ứng ở thực vật là sự tiếp nhận và trả lời của thực vật đối với kích thích từ môi trường, biểu hiện bằng vận động của cơ quan, bộ phận (leo giàn…","Cảm ứng gồm hướng động (vận động…: Cảm ứng gồm hướng động (vận động định hướng theo tác nhân kích thích từ một hướng xác định) và ứng động (vận động cảm ứng với kích thích không định…","Các kiểu hướng động: Hướng sáng (thân, ngọn cong về phía sáng: dương; rễ thường tránh sáng: âm); hướng hoá (sinh trưởng về phía chất dinh dưỡng, dương; rễ tránh kim loại…","Cơ chế hướng động liên quan hormone auxin: Khi chiếu sáng một phía, auxin dồn về phía tối làm tế bào phía tối dài ra nhanh hơn nên thân cong về phía sáng.","Ứng động không sinh trưởng là vận…: Ứng động không sinh trưởng là vận động thuận nghịch do thay đổi sức trương nước của cơ quan đáp ứng hoặc do kích thích lan truyền trong mô chuyên…"],"e":["Hay nhầm: Không liên quan trọng lực.","Hay nhầm: Rễ không hướng sáng dương.","Hay nhầm: Quang hợp không điều khiển.","Hay nhầm: Hô hấp không phải cơ chế.","Hay nhầm: Thực vật không tiêu hoá như vậy.","Hay nhầm: Không liên quan hoá chất."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 16. Thực hành: Cảm ứng ở thực vật","req":["Thực hiện được một số thí nghiệm về cảm ứng ở thực vật (hướng sáng, hướng trọng lực, hướng hoá).","Quan sát và phân loại được các hiện tượng cảm ứng của thực vật trong tự nhiên."],"sum":["Dụng cụ, mẫu vật: cốc nhựa hoặc chậu trong suốt, ống đong thuỷ tinh 250 mL, giấy thấm khổ lớn, băng dính; phân NPK hoặc phân đơn; cát, đất; hạt ngô, đậu xanh, đậu đen.","Dụng cụ, mẫu vật: Cốc nhựa hoặc chậu trong suốt, ống đong thuỷ tinh 250 mL, giấy thấm khổ lớn, băng dính; phân NPK hoặc phân đơn; cát, đất; hạt ngô, đậu xanh, đậu đen.","Hướng sáng: Gieo hạt đậu vào hai cốc; một cốc đặt nơi chiếu sáng đầy đủ, cốc còn lại cạnh cửa sổ (hoặc trong hộp giấy đục lỗ bên cạnh) để ánh sáng chiếu từ một…","Hướng trọng lực: Dán hạt ngô lên hai dải băng dính, một dải rốn hạt quay xuống, một dải rốn hạt quay lên; dán lên giấy thấm, cuộn tròn bỏ vào ống đong chứa khoảng 30…","Hướng hoá: Đặt cốc có phân NPK tập trung ở một phía (cát, đất ẩm), gieo 5 – 7 hạt ngô sát thành cốc phía đối diện, đặt nơi ánh sáng nhẹ, tưới ẩm đều; sau 7 –…"],"e":["Hay nhầm: Đều mọi phía không tạo hướng.","Hay nhầm: Bóng tối không có kích thích.","Hay nhầm: Nước cất không tạo hướng hoá.","Hay nhầm: Trọng lực cho hướng trọng lực.","Hay nhầm: Chỉ mọc thẳng khi chiếu đều.","Hay nhầm: Không phải tăng quang hợp."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 17. Cảm ứng ở động vật","req":["Trình bày được các hình thức cảm ứng ở các nhóm động vật; phân biệt hệ thần kinh dạng lưới, chuỗi hạch và ống.","Nêu được cấu tạo, chức năng của neuron; điện thế nghỉ, điện thế hoạt động; cấu tạo synapse và truyền tin qua synapse.","Nêu được khái niệm phản xạ, cung phản xạ; các thụ thể cảm giác; cơ chế thu nhận của mắt, tai."],"sum":["Động vật chưa có tổ chức thần kinh (thân lỗ) cảm ứng chậm, chỉ ở mức tế bào. Hệ thần kinh dạng lưới (ruột khoang): các tế bào thần kinh nằm rải rác khắp cơ thể liên hệ thành mạng lưới; khi bị kích…","Khái niệm: Động vật chưa có tổ chức thần kinh (thân lỗ) cảm ứng chậm, chỉ ở mức tế bào.","Neuron (tế bào thần kinh) là đơn…: Neuron (tế bào thần kinh) là đơn vị cấu tạo và chức năng của hệ thần kinh, gồm thân, sợi nhánh (tiếp nhận thông tin đưa về thân) và sợi trục (truyền…","Điện thế nghỉ là chênh lệch điện…: Điện thế nghỉ là chênh lệch điện thế giữa hai bên màng khi tế bào không bị kích thích: trong màng tích điện âm, ngoài màng tích điện dương.","Synapse là diện tiếp xúc giữa neuron…: Synapse là diện tiếp xúc giữa neuron với neuron hoặc giữa neuron với tế bào cơ, tuyến; phổ biến là synapse hoá học gồm chuỳ synapse (chứa túi chất…","Phản xạ là phản ứng của cơ…: Phản xạ là phản ứng của cơ thể trả lời kích thích từ môi trường trong hoặc ngoài thông qua hệ thần kinh, thực hiện nhờ cung phản xạ gồm thụ thể (cảm…"],"e":["Hay nhầm: Là khi chưa bị kích thích.","Hay nhầm: Adrenalin cũng có nhưng không phải thần kinh – cơ.","Hay nhầm: Thở nhanh là không điều kiện.","Hay nhầm: Rụt tay là không điều kiện."],"q":{"n":13,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 18. Tập tính ở động vật","req":["Nêu được tập tính, vai trò của tập tính và các dạng tập tính phổ biến.","Phân biệt tập tính bẩm sinh và học được; vai trò của pheromone.","Nêu được các hình thức học tập ở động vật, cơ chế học tập ở người và ứng dụng tập tính."],"sum":["Tập tính là những hành động của động vật trả lời kích thích từ môi trường trong và ngoài, đảm bảo cho động vật tồn tại và phát triển.","Khái niệm: Tập tính là những hành động của động vật trả lời kích thích từ môi trường trong và ngoài, đảm bảo cho động vật tồn tại và phát triển.","Tập tính bẩm sinh sinh ra đã…: Tập tính bẩm sinh sinh ra đã có, di truyền từ bố mẹ, đặc trưng cho loài, bền vững, khó thay đổi (nhện giăng tơ ngay lần đầu – bản năng; chim non mổ…","Một số dạng tập tính phổ biến: Kiếm ăn (lợi là chất dinh dưỡng, bất lợi là tiêu tốn năng lượng và nguy cơ bị săn); bảo vệ lãnh thổ (kiểm soát khu vực sống chống lại cá thể khác để…","Pheromone là chất hoá học do động…: Pheromone là chất hoá học do động vật tiết ra môi trường, gây đáp ứng ở các cá thể cùng loài; có cấu tạo đặc trưng loài nên là tín hiệu hoá học giao…","Các hình thức học tập: Quen nhờn (đơn giản nhất, phớt lờ kích thích lặp lại không nguy hiểm, ví dụ rùa không rụt đầu khi thả đá nhiều lần); in vết (chim non mới nở đi theo…"],"e":["Hay nhầm: Không phải kiếm ăn đơn giản.","Hay nhầm: Không phải chất dinh dưỡng.","Hay nhầm: Không phải điều kiện hoá.","Hay nhầm: Không phải khi trưởng thành.","Hay nhầm: Không liên quan ngủ đông.","Hay nhầm: Đó là điều kiện hoá đáp ứng."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}}]},{"t":"Chương 3. Sinh trưởng và phát triển ở sinh vật","l":[{"t":"Bài 19. Khái quát về sinh trưởng và phát triển ở sinh vật","req":["Nêu được khái niệm và các dấu hiệu đặc trưng của sinh trưởng và phát triển.","Phân tích được mối quan hệ giữa sinh trưởng và phát triển.","Nêu được khái niệm vòng đời, tuổi thọ; ứng dụng hiểu biết về vòng đời và các yếu tố ảnh hưởng đến tuổi thọ của con người."],"sum":["Sinh trưởng là quá trình tăng kích thước và khối lượng của cơ thể. Phát triển là toàn bộ những biến đổi diễn ra trong chu kì sống của cá thể, gồm thay đổi về số lượng tế bào, cấu trúc, hình thái và…","Khái niệm: Sinh trưởng là quá trình tăng kích thước và khối lượng của cơ thể.","Quan hệ: Ba quá trình sinh trưởng, phân hoá tế bào và phát sinh hình thái cơ quan, cơ thể gắn bó mật thiết, đan xen, không tách rời.","Vòng đời là quá trình lặp lại…: Vòng đời là quá trình lặp lại theo trình tự nhất định các thay đổi mà một cá thể trải qua từ khi sinh ra, lớn lên, trưởng thành, sinh sản rồi già và…","Ứng dụng hiểu biết vòng đời: Biết vòng đời côn trùng (trứng, sâu, nhộng, trưởng thành) để diệt sâu hại ở giai đoạn dễ tổn thương;"],"e":["Hay nhầm: Đó là một phần của phát triển.","Hay nhầm: Phân hoá là dấu hiệu khác.","Hay nhầm: Chết không phải sinh trưởng.","Hay nhầm: Sinh sản là chức năng khác.","Hay nhầm: Giao tử tạo trước hợp tử.","Hay nhầm: Bào tử ở sinh sản bào tử."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 20. Sinh trưởng và phát triển ở thực vật","req":["Nêu được đặc điểm và các yếu tố ngoại cảnh ảnh hưởng đến sinh trưởng, phát triển ở thực vật.","Trình bày được mô phân sinh; sinh trưởng sơ cấp và thứ cấp.","Phân biệt các hormone thực vật và tương quan giữa chúng; ứng dụng."],"sum":["Đặc điểm: sinh trưởng và phát triển ở thực vật diễn ra liên tục suốt đời sống, một số cơ quan (rễ, thân) sinh trưởng không giới hạn, lá, hoa, quả giới hạn; chịu ảnh hưởng của yếu tố di truyền và…","Đặc điểm: Sinh trưởng và phát triển ở thực vật diễn ra liên tục suốt đời sống, một số cơ quan (rễ, thân) sinh trưởng không giới hạn, lá, hoa, quả giới hạn;…","Mô phân sinh là nhóm tế bào…: Mô phân sinh là nhóm tế bào chưa phân hoá, có khả năng phân chia tạo tế bào mới suốt đời sống của thực vật, gồm mô phân sinh đỉnh (đỉnh thân, đỉnh…","Sinh trưởng sơ cấp là kết quả…: Sinh trưởng sơ cấp là kết quả hoạt động của mô phân sinh đỉnh và mô phân sinh lóng, làm tăng chiều cao cây và chiều dài rễ; cây một lá mầm và cây…","Hormone thực vật (phytohormone) là các chất…: Hormone thực vật (phytohormone) là các chất hữu cơ có hoạt tính sinh học cao, tổng hợp với lượng nhỏ ở một số cơ quan, tham gia điều tiết các hoạt…","Tương quan chung giữa nhóm kích thích và ức chế: Khi cây còn non hormone kích thích nhiều; sang giai đoạn sinh sản, già hoá thì hormone ức chế tăng dần."],"e":["Hay nhầm: Mô phân sinh lóng ở lóng thân.","Hay nhầm: Mô phân sinh bên ở thân gỗ.","Hay nhầm: Lá không có mô phân sinh đỉnh.","Hay nhầm: Mô phân sinh bên ở hai lá mầm.","Hay nhầm: Rễ không làm thân cao lên.","Hay nhầm: Thanh long ra hoa khi đêm ngắn."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 21. Thực hành: Bấm ngọn, tỉa cành, xử lí kích thích tố và tính tuổi cây","req":["Thực hành, quan sát được tác dụng của bấm ngọn, tỉa cành, phun kích thích tố lên cây.","Tính được tuổi cây bằng đếm vòng gỗ."],"sum":["Chuẩn bị: kéo cắt cành, thước dây, cân điện tử, cốc, ống đong, bút chì, giấy nhám; α-NAA (α-naphthalene acetic acid); cây rau ăn lá (rau muống, mùng tơi, rau đay) có 3 – 4 đốt thân chưa phân nhánh;…","Chuẩn bị: Kéo cắt cành, thước dây, cân điện tử, cốc, ống đong, bút chì, giấy nhám;","Bấm ngọn: Dùng kéo cắt bỏ phần ngọn trên một đốt thân (giữ lại 2 – 3 đốt), để một số cây không bấm làm đối chứng; theo dõi 1 – 2 tuần.","Tỉa cành: Chọn cây có cành cần tỉa; cắt cách phần tiếp giáp thân chính, nơi có đốt thân phát sinh cành khoảng 1,5 – 2 cm; vệ sinh vết cắt; quan sát kết quả…","Đánh giá ảnh hưởng hormone: Pha dung dịch α-NAA ở ba nồng độ 25 ppm, 75 ppm, 150 ppm; công thức đối chứng dùng nước máy; phun vào hai giai đoạn 25 ngày và 35 ngày sau trồng;","Tính tuổi cây: Hằng năm tầng sinh mạch (mô phân sinh bên) tạo lớp mạch gỗ; mùa mưa tế bào lớn, màu sáng; mùa khô tế bào nhỏ, màu sẫm; hai lớp tạo thành một vòng gỗ…"],"e":["Hay nhầm: Insulin là hormone động vật.","Hay nhầm: Adrenalin là hormone động vật.","Hay nhầm: Ethanol không phải hormone.","Hay nhầm: Đó là công thức thí nghiệm.","Hay nhầm: Ngừng thì không có vòng mới."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 22. Sinh trưởng và phát triển ở động vật","req":["Nêu được đặc điểm, các giai đoạn sinh trưởng và phát triển ở động vật; phân biệt phát triển không qua và qua biến thái.","Nêu được ảnh hưởng của các yếu tố bên trong, bên ngoài, vai trò của hormone.","Phân tích đặc điểm tuổi dậy thì và vận dụng bảo vệ sức khoẻ; vận dụng vào thực tiễn chăn nuôi."],"sum":["Đặc điểm sinh trưởng, phát triển ở động vật: tốc độ không đều theo thời gian; các phần cơ thể phát triển không giống nhau; cơ quan, hệ cơ quan của phôi thai hình thành ở thời điểm khác nhau (ở người…","Đặc điểm sinh trưởng, phát triển ở động vật: Tốc độ không đều theo thời gian; các phần cơ thể phát triển không giống nhau; cơ quan, hệ cơ quan của phôi thai hình thành ở thời điểm khác nhau (ở…","Động vật đẻ trứng gồm giai đoạn phôi và hậu phôi: Động vật đẻ con (thú, người) gồm giai đoạn phôi thai và sau sinh.","Phát triển không qua biến thái: Con non mới nở hoặc mới sinh đã có cấu tạo giống con trưởng thành (đa số động vật có xương sống như người, chim, thú).","Nhân tố bên trong: Di truyền (quy định giới hạn tốc độ và kích thước) và hormone (hormone sinh trưởng GH kích thích phân chia, tăng kích thước tế bào, xương dài ra;…","Tuổi dậy thì là giai đoạn chuyển…: Tuổi dậy thì là giai đoạn chuyển từ thiếu niên sang thanh niên, kéo dài khoảng 5 năm; nữ trung bình khoảng 11 tuổi (8 – 13), nam khoảng 12 tuổi (9 –…"],"e":["Hay nhầm: Bướm biến thái hoàn toàn.","Hay nhầm: Châu chấu biến thái không hoàn toàn.","Hay nhầm: Không hoàn toàn không có nhộng.","Hay nhầm: Không qua biến thái không có.","Hay nhầm: Thyroxine kích thích chuyển hoá.","Hay nhầm: Insulin điều hoà đường huyết."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 23. Thực hành: Quan sát biến thái ở động vật","req":["Quan sát, mô tả được hình dạng bên ngoài của sâu, nhộng, bướm tằm trưởng thành.","Quan sát, mô tả được hình dạng bên ngoài của nòng nọc, ếch trưởng thành."],"sum":["Chuẩn bị: kính lúp, đĩa đựng mẫu, panh; mẫu vật sâu bướm (tằm), nhộng, bướm trưởng thành; nòng nọc và ếch trưởng thành.","Chuẩn bị: Kính lúp, đĩa đựng mẫu, panh; mẫu vật sâu bướm (tằm), nhộng, bướm trưởng thành; nòng nọc và ếch trưởng thành.","Quan sát sâu, nhộng, bướm tằm: Sâu (ấu trùng) thân dài, mềm, nhiều đốt, có chân giả, có hàm nhai, ăn lá dâu; nhộng được bọc kén tơ, không ăn, ít cử động; bướm trưởng thành có…","Quan sát nòng nọc và ếch: Nòng nọc có đuôi dài dẹt, thở bằng mang, chưa có chân (sau mọc chân sau rồi chân trước), sống dưới nước, ăn thực vật;"],"e":["Hay nhầm: Ếch trưởng thành có phổi.","Hay nhầm: Không hoàn toàn thì ấu trùng giống con lớn."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 4. Sinh sản ở sinh vật","l":[{"t":"Bài 24. Khái quát về sinh sản ở sinh vật","req":["Phát biểu được khái niệm sinh sản, sinh sản vô tính, sinh sản hữu tính và nêu các dấu hiệu đặc trưng.","Trình bày được vai trò của sinh sản và phân biệt các hình thức sinh sản."],"sum":["Sinh sản là quá trình tạo ra cơ thể mới, đảm bảo sự phát triển liên tục của loài. Sinh sản vô tính là hình thức tạo ra cơ thể mới có đặc điểm giống cá thể ban đầu mà không có sự đóng góp vật chất di…","Khái niệm: Sinh sản là quá trình tạo ra cơ thể mới, đảm bảo sự phát triển liên tục của loài.","Dấu hiệu đặc trưng: Sinh sản vô tính – vật chất di truyền của các con giống nhau và giống mẹ, được truyền nguyên vẹn qua nguyên phân, điều hoà chủ yếu bởi hệ thống kiểm…","Vai trò: Sinh sản vô tính cho phép tạo nhiều cá thể nhanh, ổn định đặc tính tốt trong môi trường ổn định, ít tốn năng lượng, nhưng ít đa dạng di truyền nên…"],"e":["Hay nhầm: Có ảnh hưởng nhưng không điều hoà chính.","Hay nhầm: Có ảnh hưởng nhưng không điều hoà chính.","Hay nhầm: Vô tính ít tốn năng lượng.","Hay nhầm: Lí do chính là giữ đặc tính."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 25. Sinh sản ở thực vật","req":["Trình bày được sinh sản sinh dưỡng, sinh sản bằng bào tử và các phương pháp nhân giống vô tính ở thực vật.","So sánh được sinh sản hữu tính với vô tính ở thực vật.","Trình bày được cấu tạo hoa và quá trình sinh sản hữu tính ở thực vật có hoa: hình thành hạt phấn, túi phôi, thụ phấn, thụ tinh, hạt, quả."],"sum":["Sinh sản vô tính (sinh sản sinh dưỡng) ở thực vật là hình thức cây con được tạo ra từ các bộ phận sinh dưỡng của cây mẹ như củ, thân, rễ, lá (chuối nảy chồi từ thân ngầm, khoai tây từ củ, thuốc bỏng…","Khái niệm: Sinh sản vô tính (sinh sản sinh dưỡng) ở thực vật là hình thức cây con được tạo ra từ các bộ phận sinh dưỡng của cây mẹ như củ, thân, rễ, lá (chuối…","Nhân giống vô tính nhân tạo: Giâm cành (đoạn cành bánh tẻ ra rễ, dùng cho hoa hồng, mía, sắn, tạo nhiều cây giống nhanh); chiết cành (khoanh vỏ cành, xử lí chất kích thích, bó…","Hoa là chồi sinh sản, gồm bộ…: Hoa là chồi sinh sản, gồm bộ phận bất thụ (lá đài bảo vệ chồi, cánh hoa sặc sỡ thu hút côn trùng) và bộ phận hữu thụ (nhị gồm chỉ nhị và bao phấn…","Quá trình sinh sản hữu tính có ba giai đoạn: Hình thành hạt phấn: tế bào mẹ tiểu bào tử (2n) trong bao phấn giảm phân tạo 4 bào tử đơn bội (n), mỗi bào tử nguyên phân tạo hạt phấn gồm nhân tế…","Thụ phấn là hạt phấn phát tán…: Thụ phấn là hạt phấn phát tán và rơi lên núm nhuỵ; tự thụ phấn (trong cùng hoa hoặc cùng cây) và thụ phấn chéo (giữa hai cây khác nhau)."],"e":["Hay nhầm: Quả là bầu nhuỵ phát triển.","Hay nhầm: Hạt trần không có thụ tinh kép."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 26. Thực hành: Nhân giống vô tính và thụ phấn cho cây","req":["Thực hành được nhân giống cây bằng giâm cành, chiết cành, ghép mắt.","Thực hành hoặc quan sát được thụ phấn nhân tạo ở cây ngô."],"sum":["Chuẩn bị: dao, kéo cắt cành, kéo nhỏ sắc, dây buộc; cây dâu tằm, hoa hồng, rau muống, rau ngót, dây khoai lang và giá thể; cây ngô đang ra hoa.","Chuẩn bị: Dao, kéo cắt cành, kéo nhỏ sắc, dây buộc; cây dâu tằm, hoa hồng, rau muống, rau ngót, dây khoai lang và giá thể; cây ngô đang ra hoa.","Giâm cành: Chọn cành bánh tẻ khoẻ, cắt thành đoạn có 2 – 3 mắt, bỏ bớt lá; xử lí chất kích thích ra rễ (nếu có); cắm vào giá thể ẩm; che nắng, tưới giữ ẩm; sau…","Chiết cành: Bước 1 khoanh vỏ cành trên cây mẹ; bước 2 xử lí vết khoanh bằng chất kích thích ra rễ (nếu có); bước 3 bao vết khoanh bằng bùn, đất ẩm và bọc kín…","Ghép mắt (kĩ thuật ghép cửa sổ): Mở gốc ghép bằng cách rạch và cắt bỏ phần vỏ tạo miệng cửa sổ; cắt mắt ghép có hình dạng, kích thước khớp với miệng vết ghép;","Thụ phấn cho ngô: Chọn bông cờ ở giai đoạn bung phấn; cắt một nhánh bông cờ chứa nhiều bao phấn; chọn các bắp đã phun râu; chải hoặc lắc để hạt phấn rơi lên râu ngô."],"e":["Hay nhầm: Không phải nguyên nhân chính.","Hay nhầm: Không phải nguyên nhân chính."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 27. Sinh sản ở động vật","req":["Phân biệt được các hình thức sinh sản vô tính, hữu tính ở động vật.","Trình bày được quá trình sinh sản hữu tính ở người và cơ chế điều hoà sinh sản.","Trình bày được ứng dụng điều khiển sinh sản, thụ tinh trong ống nghiệm, sinh đẻ có kế hoạch và các biện pháp tránh thai."],"sum":["Sinh sản vô tính ở động vật gặp ở loài có cấu tạo đơn giản gồm: phân đôi (một cá thể thành hai cá thể bằng nhau, ví dụ hải quỳ); nảy chồi (chồi mọc trên cơ thể mẹ rồi tách ra, ví dụ thuỷ tức); phân…","Sinh sản vô tính ở động vật gặp ở loài có cấu tạo đơn giản gồm: Phân đôi (một cá thể thành hai cá thể bằng nhau, ví dụ hải quỳ); nảy chồi (chồi mọc trên cơ thể mẹ rồi tách ra, ví dụ thuỷ tức); phân mảnh (cơ thể…","Sinh sản hữu tính ở động vật chia theo nơi phát triển phôi: Đẻ trứng (trứng thụ tinh trong cơ thể con cái rồi đẻ ra ngoài phát triển, ví dụ chim, bò sát), đẻ trứng thai (hợp tử phát triển trong ống dẫn trứng…","Sinh sản hữu tính ở người gồm bốn giai đoạn: Hình thành giao tử, thụ tinh, phát triển phôi thai và sinh con.","Điều hoà sinh sản bằng hệ nội tiết với liên hệ ngược: Vùng dưới đồi tiết GnRH kích thích tuyến yên tiết FSH, LH tác động lên tinh hoàn (kích thích sinh tinh, tế bào kẽ tiết testosterone) hoặc buồng…","Ứng dụng điều khiển sinh sản ở động vật: Thụ tinh nhân tạo (bơm tinh trùng chọn lọc vào tử cung đúng lúc trứng rụng; với cá dùng hormone kích thích trứng chín rồi thụ tinh nhân tạo ngoài cơ…"],"e":["Hay nhầm: Insulin điều hoà đường huyết.","Hay nhầm: Thyroxine điều hoà chuyển hoá.","Hay nhầm: Testosterone ở tinh hoàn.","Hay nhầm: Ức chế chứ không kích thích.","Hay nhầm: Tính ngày kinh không bảo vệ."],"q":{"n":12,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":4}}}]},{"t":"Chương 5. Mối quan hệ giữa các quá trình sinh lí trong cơ thể sinh vật và một số ngành nghề liên quan đến sinh học cơ thể","l":[{"t":"Bài 28. Mối quan hệ giữa các quá trình sinh lí trong cơ thể sinh vật","req":["Trình bày được mối quan hệ giữa các quá trình sinh lí trong cơ thể thực vật và động vật.","Chứng minh được cơ thể là một hệ thống mở, tự điều chỉnh."],"sum":["Trong cơ thể thực vật diễn ra nhiều quá trình sinh lí như trao đổi nước, dinh dưỡng khoáng, quang hợp, hô hấp...","Khái niệm: Trong cơ thể thực vật diễn ra nhiều quá trình sinh lí như trao đổi nước, dinh dưỡng khoáng, quang hợp, hô hấp...","Ở động vật có tiêu hoá, hô…: Ở động vật có tiêu hoá, hô hấp, tuần hoàn, bài tiết, thần kinh, nội tiết...","Cơ thể sinh vật là hệ thống mở: Thường xuyên trao đổi chất và năng lượng với môi trường (lấy vào chất cần thiết, thải ra chất thải)."],"e":["Hay nhầm: Chất hữu cơ từ quang hợp."],"q":{"n":8,"lv":{"Biết":2,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 29. Một số ngành nghề liên quan đến sinh học cơ thể","req":["Nêu được một số ngành nghề liên quan đến sinh học cơ thể và triển vọng trong tương lai."],"sum":["Y học – Dược học: cơ thể người là đối tượng của ngành này; hiểu biết giải phẫu, sinh lí học, sinh lí bệnh, lâm sàng là cơ sở chẩn đoán, điều trị, điều chế thuốc, nâng cao sức khoẻ.","Y học – Dược học: Cơ thể người là đối tượng của ngành này; hiểu biết giải phẫu, sinh lí học, sinh lí bệnh, lâm sàng là cơ sở chẩn đoán, điều trị, điều chế thuốc, nâng…","Nuôi trồng thuỷ sản (nước ngọt, mặn, lợ): Ứng dụng kĩ thuật tiên tiến cải tạo giống, cải thiện điều kiện nuôi dưỡng (thức ăn, nước), kiểm soát dịch bệnh nhằm nâng cao năng suất, chất lượng.","Trồng trọt, chăn nuôi, thú y: Hiểu đặc điểm sinh học cây trồng, vật nuôi để chọn giống phù hợp, bón phân, tưới nước, điều chỉnh nhiệt độ, thức ăn, sản xuất tinh, thụ tinh nhân…","Lâm nghiệp: Lựa chọn loài cây phù hợp để trồng rừng, trồng cây đô thị; biện pháp sinh học bảo vệ rừng và động vật quý hiếm; tương lai: nuôi cấy mô nhân nhanh…","Hiểu biết về sinh học cơ thể…: Hiểu biết về sinh học cơ thể giúp chọn ngành nghề phù hợp năng lực, sở thích, đồng thời đáp ứng nhu cầu nhân lực của xã hội."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương 1. Trao đổi chất và chuyển hoá năng lượng ở sinh vật","l":[{"t":"Bài tập nâng cao · Chương 1. Trao đổi chất và chuyển hoá năng lượng ở sinh vật (22 câu)","e":["Hay nhầm: Nhiệt không chuyển ngược thành quang năng ở sinh vật.","Hay nhầm: CO₂ không được tổng hợp bằng nhiệt.","Hay nhầm: Chúng liên quan chặt chẽ.","Hay nhầm: Cả hai quá trình đều có ở mọi sinh vật.","Hay nhầm: Dị hoá giải phóng năng lượng.","Hay nhầm: Thoát hơi nước làm giảm nước ở lá."],"q":{"n":22,"lv":{"Nâng cao":22}}}]},{"t":"Chương 2. Cảm ứng ở sinh vật","l":[{"t":"Bài tập nâng cao · Chương 2. Cảm ứng ở sinh vật (9 câu)","e":["Hay nhầm: Động vật dùng cả hormone.","Hay nhầm: Thực vật không có hệ thần kinh.","Hay nhầm: Thân cũng nhạy, ngưỡng khác.","Hay nhầm: Sợi giao cảm vẫn có xung.","Hay nhầm: Tổng hợp không bị ảnh hưởng.","Hay nhầm: Không dùng động vật mới bắt."],"q":{"n":9,"lv":{"Nâng cao":9}}}]},{"t":"Chương 3. Sinh trưởng và phát triển ở sinh vật","l":[{"t":"Bài tập nâng cao · Chương 3. Sinh trưởng và phát triển ở sinh vật (8 câu)","e":["Hay nhầm: Không phải triệu chứng chính.","Hay nhầm: Bướm giao phối, đẻ trứng."],"q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương 4. Sinh sản ở sinh vật","l":[{"t":"Bài tập nâng cao · Chương 4. Sinh sản ở sinh vật (6 câu)","e":["Hay nhầm: Hữu tính thường chậm hơn.","Hay nhầm: Có hàng triệu tinh trùng."],"q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 5. Mối quan hệ giữa các quá trình sinh lí trong cơ thể sinh vật và một số ngành nghề liên quan đến sinh học cơ thể","l":[{"t":"Bài tập nâng cao · Chương 5. Mối quan hệ giữa các quá trình sinh lí trong cơ thể sinh vật và một số ngành nghề liên…","q":{"n":2,"lv":{"Nâng cao":2}}}]}]}]},{"id":"anh","name":"Tiếng Anh","b":[{"t":"Tiếng Anh 11","c":[{"t":"Cụm 1. Unit 1–3 (Ôn tập 1)","l":[{"t":"Unit 1. A long and healthy life (Một cuộc sống lâu dài và khoẻ mạnh)","req":["Dùng đúng thì quá khứ đơn và hiện tại hoàn thành.","Hiểu và dùng từ vựng về sức khoẻ, bệnh tật và thể lực.","Đọc hiểu một bài viết về thói quen sống khoẻ."],"sum":["Quá khứ đơn: mốc đã kết thúc (yesterday, in 2019, ago). Hiện tại hoàn thành: have/has + V3, kinh nghiệm, kéo dài (for, since), vừa xảy ra.","Quá khứ đơn: Hành động đã kết thúc tại thời điểm xác định trong quá khứ.","Hiện tại hoàn thành: Diễn tả kinh nghiệm (ever / never), hành động bắt đầu trong quá khứ và còn kéo dài (for, since), hoặc vừa xảy ra (just, already, yet). Không dùng…","Từ chỉ thời gian","Dạng yếu (weak forms): Trợ động từ như have, has, was, can, must thường đọc nhẹ."],"e":["Sai: I have seen him yesterday. → Đúng: I saw him yesterday. (Mốc đã kết thúc (yesterday) → quá khứ đơn.)","Hay nhầm: Germ là vi trùng nói chung, không phải tên gọi vi khuẩn chuẩn.","Hay nhầm: Suffer from là mắc phải bệnh.","Hay nhầm: Make up không đúng nghĩa.","Hay nhầm: Recipe là công thức nấu ăn.","Hay nhầm: Hiện tại hoàn thành không đi với mốc đã kết thúc."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 2. The generation gap (Khoảng cách thế hệ)","req":["Dùng đúng must, have to và should để nói về nghĩa vụ, cấm đoán và lời khuyên.","Hiểu và dùng từ vựng về khác biệt giữa các thế hệ.","Đọc hiểu một bài viết về các thế hệ trong gia đình."],"sum":["must: nghĩa vụ từ người nói; mustn’t: cấm. have to: nghĩa vụ từ bên ngoài; don’t have to: không cần. should: lời khuyên.","Must và mustn’t: Must diễn tả nghĩa vụ hoặc quy định do người nói đặt ra; mustn’t diễn tả điều bị cấm.","Have to và don’t have to: Have to là nghĩa vụ do hoàn cảnh hoặc luật lệ bên ngoài. Don’t have to là không cần thiết.","Should: Lời khuyên, điều nên hoặc không nên làm.","Mustn’t và don’t have to"],"e":["Hay nhầm: Nuclear family là gia đình hạt nhân.","Hay nhầm: Extended family là gia đình đa thế hệ.","Hay nhầm: Individualism là chủ nghĩa cá nhân.","Hay nhầm: Characteristic là đặc điểm.","Hay nhầm: Don’t have to là không cần.","Hay nhầm: Should not là lời khuyên."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 3. Cities of the future (Thành phố của tương lai)","req":["Dùng đúng động từ chỉ trạng thái (stative verbs) ở dạng đơn và tiếp diễn.","Hiểu và dùng từ vựng về thành phố thông minh và đô thị bền vững.","Đọc hiểu một bài viết về đặc điểm của thành phố tương lai."],"sum":["Động từ trạng thái (know, believe, want, like, need, belong, seem, understand) không dùng tiếp diễn. Một số động từ đổi nghĩa khi dùng tiếp diễn: think, have, feel, see.","Động từ trạng thái: Diễn tả cảm xúc, suy nghĩ, sở hữu, giác quan; thường không dùng ở dạng tiếp diễn.","Cùng động từ, hai nghĩa","Nối âm (linking): Từ trước kết thúc bằng phụ âm, từ sau bắt đầu bằng nguyên âm thì nối lại."],"e":["Sai: I am knowing the answer. → Đúng: I know the answer. (know là động từ trạng thái.)","Hay nhầm: Cycle path là làn xe đạp.","Hay nhầm: Pedestrian là người đi bộ.","Hay nhầm: Roof garden là vườn trên mái.","Hay nhầm: Urban centre là trung tâm đô thị.","Hay nhầm: Card reader là thiết bị đọc thẻ."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Cụm 2. Unit 4–5 (Ôn tập 2)","l":[{"t":"Unit 4. ASEAN and Viet Nam (ASEAN và Việt Nam)","req":["Dùng đúng danh động từ (gerund) làm chủ ngữ và tân ngữ.","Hiểu và dùng từ vựng về ASEAN, cộng đồng và hợp tác khu vực.","Đọc hiểu các tin tức về các nước ASEAN."],"sum":["Danh động từ (V-ing) làm chủ ngữ, tân ngữ, đứng sau giới từ. Theo sau enjoy, avoid, consider, finish, suggest, practise, mind, admit, keep.","Danh động từ: V-ing đóng vai trò danh từ.","Động từ + V-ing: Enjoy, avoid, consider, finish, suggest, practise, mind, admit, keep.","Lược nguyên âm (elision): Trong lời nói nhanh, một số nguyên âm không phát âm đầy đủ."],"e":["Sai: I enjoy to read news. → Đúng: I enjoy reading news. (Sau enjoy và suggest dùng V-ing; sau want, decide dùng to V.)","Hay nhầm: Contribution là sự đóng góp.","Hay nhầm: Leadership skills là kĩ năng lãnh đạo.","Hay nhầm: Current issue là vấn đề hiện tại.","Hay nhầm: Live-stream là phát sóng trực tiếp.","Hay nhầm: Qualify là đủ tiêu chuẩn."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 5. Global warming (Sự nóng lên toàn cầu)","req":["Dùng đúng hiện tại phân từ (present participle) và quá khứ phân từ trong mệnh đề rút gọn.","Hiểu và dùng từ vựng về môi trường, khí hậu và phát thải.","Đọc hiểu một bài báo về Hội nghị Biến đổi khí hậu của Liên Hợp Quốc."],"sum":["Mệnh đề rút gọn: V-ing thay mệnh đề quan hệ chủ động; V3 thay mệnh đề bị động. Chỉ dùng khi hai vế cùng chủ ngữ.","Hiện tại phân từ (V-ing): Thay cho mệnh đề quan hệ chủ động.","Quá khứ phân từ (V3): Thay cho mệnh đề quan hệ bị động.","Lưu ý","Trọng âm câu: Từ mang nghĩa chính được nhấn, từ chức năng đọc nhẹ."],"e":["Hay nhầm: Farmland là đất canh tác.","Hay nhầm: Carbon dioxide là khí CO₂.","Hay nhầm: Lived là quá khứ phân từ, dùng cho bị động.","Hay nhầm: Destroying là chủ động, không đúng nghĩa.","Hay nhầm: Signing là chủ động, không đúng nghĩa.","Hay nhầm: To sign không dùng ở đây."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Cụm 3. Unit 6–8 (Ôn tập 3)","l":[{"t":"Unit 6. Preserving our heritage (Bảo tồn di sản của chúng ta)","req":["Dùng đúng to-infinitive để chỉ mục đích và sau một số động từ, tính từ.","Hiểu và dùng từ vựng về di sản, kiến trúc và văn hoá dân gian.","Đọc hiểu một bài viết về cuộc thi ý tưởng bảo tồn di sản."],"sum":["To V chỉ mục đích; sau want, decide, plan, hope, learn, need; sau tính từ; too + adj + to V, adj + enough + to V.","Mục đích","Sau động từ: Want, decide, plan, hope, learn, need + to V.","Sau tính từ","Too và enough","Ngữ điệu: Câu kể và câu mệnh lệnh xuống giọng. Khi liệt kê, mỗi mục lên nhẹ, mục cuối xuống."],"e":["Sai: They decided restoring the citadel. → Đúng: They decided to restore the citadel. (Sau enjoy, avoid dùng V-ing, nhưng sau decide dùng to V.)","Hay nhầm: Trending là đang thịnh hành.","Hay nhầm: Crowdfunding là huy động vốn cộng đồng.","Hay nhầm: Protecting không chỉ mục đích trong cấu trúc này.","Hay nhầm: Decide không đi với V-ing.","Hay nhầm: Sau tính từ important thường dùng to-infinitive."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 7. Education options for school-leavers (Lựa chọn học tập sau trung học)","req":["Dùng đúng danh động từ hoàn thành (perfect gerund) và phân từ hoàn thành (perfect participle).","Hiểu và dùng từ vựng về các con đường học tập sau trung học phổ thông.","Đọc hiểu một bài viết về các lựa chọn học tập sau khi tốt nghiệp."],"sum":["Having + V3: hành động xảy ra trước. Dùng sau giới từ hoặc mở đầu mệnh đề. Hai việc gần đồng thời thì dùng V-ing.","Danh động từ hoàn thành: Having + V3 dùng sau giới từ để nhấn mạnh hành động xảy ra trước.","Phân từ hoàn thành: Having + V3 mở đầu mệnh đề, diễn tả hành động xảy ra trước hành động của mệnh đề chính.","Lưu ý","Ngữ điệu câu hỏi"],"e":["Hay nhầm: Sixth-form college là trường 16–19 tuổi học A-levels.","Hay nhầm: Academic là có tính học thuật.","Hay nhầm: Brochure là tờ giới thiệu.","Hay nhầm: Doctorate là bằng tiến sĩ.","Hay nhầm: Qualification là văn bằng.","Hay nhầm: Institution là cơ sở đào tạo."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}},{"t":"Unit 8. Becoming independent (Trở nên tự lập)","req":["Dùng đúng cấu trúc câu chẻ (cleft sentence) với It is/was ... that/who.","Hiểu và dùng từ vựng về tính tự lập, kĩ năng sống và học tập.","Đọc hiểu một bài viết về cách thanh thiếu niên trở nên tự lập."],"sum":["Câu chẻ: It is/was + thành phần nhấn mạnh + that/who + phần còn lại. Who cho người, that cho người hoặc vật.","Câu chẻ: Nhấn mạnh một thành phần của câu.","Who và that: Who cho người, that cho người hoặc vật. Is / was phải phù hợp với thì của câu gốc.","Ngữ điệu khi mời, đề nghị: Giọng lên nhẹ khi mời, giọng mềm mại khi đề nghị lịch sự."],"e":["Hay nhầm: Learning goal là mục tiêu học tập.","Hay nhầm: Life skill là kĩ năng sống.","Hay nhầm: Whom dùng cho người tân ngữ.","Hay nhầm: What không dùng trong câu chẻ này.","Hay nhầm: Thiếu that/who nối hai vế, không thành câu chẻ.","Hay nhầm: Xuống mạnh không phù hợp lời mời."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Cụm 4. Unit 9–10 (Ôn tập 4)","l":[{"t":"Unit 9. Social issues (Các vấn đề xã hội)","req":["Dùng đúng các từ nối (linking words) như however, therefore, moreover, as a result.","Hiểu và dùng từ vựng về các vấn đề xã hội như bắt nạt, áp lực bạn bè và nghèo đói.","Đọc hiểu một bài viết về áp lực từ bạn bè."],"sum":["Đối lập: however, on the other hand, nevertheless. Kết quả: therefore, as a result, consequently. Bổ sung: moreover, in addition, furthermore.","Từ nối","Ví dụ","Ngữ điệu câu hỏi lựa chọn: Lên giọng ở lựa chọn thứ nhất, xuống giọng ở lựa chọn cuối."],"e":["Hay nhầm: Overpopulation là quá tải dân số.","Hay nhầm: Offensive là gây xúc phạm.","Hay nhầm: Self-confidence là sự tự tin.","Hay nhầm: However diễn tả đối lập, không đúng.","Hay nhầm: Moreover diễn tả bổ sung.","Hay nhầm: Otherwise diễn tả điều kiện trái ngược."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 10. The ecosystem (Hệ sinh thái)","req":["Dùng đúng danh từ ghép (compound nouns) trong các chủ đề về môi trường.","Hiểu và dùng từ vựng về hệ sinh thái, đa dạng sinh học và bảo tồn.","Đọc hiểu một bài viết về một vườn quốc gia."],"sum":["Danh từ ghép: N + N hoặc adj + N, trọng âm thường ở từ thứ nhất. Câu hỏi đuôi: khẳng định → đuôi phủ định; phủ định → đuôi khẳng định.","Danh từ ghép: Hai hoặc nhiều từ tạo thành một nghĩa mới, thường có trọng âm ở từ thứ nhất.","Câu hỏi đuôi: Dùng để xác nhận thông tin. Câu khẳng định thì đuôi phủ định; câu phủ định thì đuôi khẳng định.","Ngữ điệu câu hỏi đuôi"],"e":["Hay nhầm: Habitat là môi trường sống của một loài.","Hay nhầm: Fauna là động vật của một vùng.","Hay nhầm: Delta là đồng bằng châu thổ.","Hay nhầm: Habitat là môi trường sống.","Hay nhầm: National park là vườn quốc gia.","Hay nhầm: Natural resources là tài nguyên thiên nhiên."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]}]}]},{"id":"lichsu","name":"Lịch sử","b":[{"t":"Lịch sử 11","c":[{"t":"Chủ đề 1. Cách mạng tư sản và sự phát triển của chủ nghĩa tư bản","l":[{"t":"Bài 1. Một số vấn đề chung về cách mạng tư sản","req":["Trình bày được tiền đề của các cuộc cách mạng tư sản về kinh tế, chính trị, xã hội, tư tưởng.","Phân tích được mục tiêu, nhiệm vụ, giai cấp lãnh đạo, động lực của các cuộc cách mạng tư sản.","Trình bày được kết quả, ý nghĩa của các cuộc cách mạng tư sản."],"m":[{"t":"Lập bảng tóm tắt về một cuộc cách mạng tư sản","w":"Đề yêu cầu trình bày hoặc so sánh các cuộc cách mạng tư sản.","s":["Xác định tên, thời gian, nước diễn ra cách mạng.","Nêu tiền đề (kinh tế, chính trị, xã hội, tư tưởng).","Xác định mục tiêu, nhiệm vụ, giai cấp lãnh đạo, động lực.","Nêu kết quả, ý nghĩa và hình thức nhà nước được thiết lập."],"n":["Nhiệm vụ dân tộc và dân chủ có thể nổi bật khác nhau ở từng nước.","Quần chúng tham gia càng đông thì cách mạng càng triệt để."]}],"sum":["Cách mạng tư sản là cuộc cách mạng do giai cấp tư sản lãnh đạo nhằm chống lại chế độ phong kiến, thiết lập nhà nước tư sản, mở đường cho chủ nghĩa tư bản phát triển.","Khái niệm: Cách mạng tư sản là cuộc cách mạng do giai cấp tư sản lãnh đạo nhằm chống lại chế độ phong kiến, thiết lập nhà nước tư sản, mở đường cho chủ nghĩa…","Tiền đề kinh tế: Kinh tế tư bản chủ nghĩa ra đời và phát triển trong lòng chế độ phong kiến hoặc chế độ thuộc địa.","Tiền đề chính trị: Chính sách cai trị của nhà nước phong kiến, thực dân gây bất mãn cho tư sản và các tầng lớp khác.","Tiền đề xã hội: Giai cấp tư sản và đồng minh (quý tộc mới ở Anh, chủ nô ở Bắc Mỹ) giàu có nhưng không có quyền lực chính trị tương xứng nên tập hợp quần chúng làm…","Tiền đề tư tưởng: Tư sản cần hệ tư tưởng chống lại tư tưởng phong kiến bảo thủ."],"e":["Hay nhầm: Công nhân lãnh đạo cách mạng vô sản.","Hay nhầm: Nông dân là động lực, không lãnh đạo.","Hay nhầm: Tăng lữ thuộc chế độ phong kiến.","Hay nhầm: Tăng lữ là đối tượng cách mạng.","Hay nhầm: Chủ trương hạn chế quyền vua.","Hay nhầm: Chủ trương quân chủ sáng suốt."],"q":{"n":12,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":3}}},{"t":"Bài 2. Sự xác lập và phát triển của chủ nghĩa tư bản","req":["Trình bày được sự xác lập của chủ nghĩa tư bản ở châu Âu và Bắc Mỹ; quá trình mở rộng xâm lược thuộc địa và phát triển của chủ nghĩa tư bản.","Trình bày được sự phát triển của chủ nghĩa tư bản từ tự do cạnh tranh sang độc quyền.","Nêu được khái niệm, tiềm năng và thách thức của chủ nghĩa tư bản hiện đại."],"sum":["Sự xác lập ở châu Âu và Bắc Mỹ: sau Cách mạng tư sản Anh và đặc biệt là Cách mạng tư sản Pháp, chủ nghĩa tư bản từng bước được xác lập; chiến tranh giành độc lập của 13 thuộc địa Bắc Mỹ đánh dấu sự…","Sự xác lập ở châu Âu và Bắc Mỹ: Sau Cách mạng tư sản Anh và đặc biệt là Cách mạng tư sản Pháp, chủ nghĩa tư bản từng bước được xác lập; chiến tranh giành độc lập của 13 thuộc địa…","Chủ nghĩa đế quốc và xâm lược thuộc địa: Sự phát triển nhanh của CNTB kéo theo nhu cầu nguyên liệu, nhân công, thị trường, dẫn tới tăng cường xâm lược thuộc địa.","Mở rộng và phát triển: Nửa đầu thế kỉ XIX, phong trào giành độc lập ở Mỹ La-tinh lật đổ ách thống trị Tây Ban Nha, Bồ Đào Nha, lập các quốc gia tư sản.","Từ tự do cạnh tranh sang độc quyền: Cạnh tranh gay gắt làm xí nghiệp vừa và nhỏ phá sản, xuất hiện xí nghiệp khổng lồ và tổ chức độc quyền – liên minh giữa các nhà tư bản lớn để tập…","Chủ nghĩa tư bản hiện đại là…: Chủ nghĩa tư bản hiện đại là giai đoạn phát triển của CNTB từ sau Chiến tranh thế giới thứ hai đến nay, với biểu hiện tiêu biểu là sự kết hợp giữa…"],"e":["Hay nhầm: Không thực sự thủ tiêu phong kiến.","Hay nhầm: Không phải nội dung chính."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}}]},{"t":"Chủ đề 2. Chủ nghĩa xã hội từ năm 1917 đến nay","l":[{"t":"Bài 3. Sự hình thành Liên bang Cộng hoà xã hội chủ nghĩa Xô viết","req":["Trình bày được quá trình hình thành Liên bang Cộng hoà xã hội chủ nghĩa Xô viết.","Phân tích được ý nghĩa sự ra đời của Liên bang Cộng hoà xã hội chủ nghĩa Xô viết."],"m":[{"t":"Lập bảng tóm tắt quá trình hình thành Liên Xô","w":"Đề yêu cầu trình bày quá trình hình thành theo mốc thời gian.","s":["Ghi mốc 1917: Chính quyền Xô viết ra đời.","Ghi giai đoạn 1918–1920: các nước Cộng hoà Xô viết liên minh chống thù trong giặc ngoài.","Ghi mốc 30-12-1922: Tuyên ngôn thành lập Liên Xô (4 nước).","Ghi mốc 1-1924: Hiến pháp đầu tiên, hoàn thành việc thành lập."],"n":["Phân biệt ngày 25-10 (lịch cũ) và 7-11 (lịch mới) 1917.","Ban đầu 4 nước, 1940 là 15 nước."]}],"sum":["Sau thắng lợi của Cách mạng tháng Mười Nga, nhiệm vụ hàng đầu của Chính quyền Xô viết là đập tan bộ máy nhà nước cũ, xây dựng nhà nước mới của người lao động.","Khái niệm: Sau thắng lợi của Cách mạng tháng Mười Nga, nhiệm vụ hàng đầu của Chính quyền Xô viết là đập tan bộ máy nhà nước cũ, xây dựng nhà nước mới của người…","Trong cuộc chiến đấu chống thù trong…: Trong cuộc chiến đấu chống thù trong, giặc ngoài, các nước Cộng hoà Xô viết đã đoàn kết, giúp đỡ nhau giữ vững chính quyền.","Ngày 30-12-1922, tại Mát-xcơ-va, Đại hội lần…: Ngày 30-12-1922, tại Mát-xcơ-va, Đại hội lần thứ nhất các Xô viết toàn Liên bang thông qua Tuyên ngôn thành lập Liên bang Cộng hoà xã hội chủ nghĩa…","Ý nghĩa: Việc thành lập Liên Xô phù hợp với lợi ích chung của các dân tộc; sức mạnh đoàn kết, hợp tác tạo điều kiện phát triển nhanh kinh tế, xã hội của tất…"],"e":["Lưu ý: Phân biệt ngày 25-10 (lịch cũ) và 7-11 (lịch mới) 1917.","Lưu ý: Ban đầu 4 nước, 1940 là 15 nước."],"q":{"n":10,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 4. Sự phát triển của chủ nghĩa xã hội từ sau Chiến tranh thế giới thứ hai đến nay","req":["Trình bày được sự phát triển của CNXH ở Đông Âu sau Chiến tranh thế giới thứ hai; sự mở rộng ở châu Á và Mỹ La-tinh.","Giải thích được nguyên nhân sụp đổ mô hình CNXH ở Đông Âu và Liên Xô.","Nêu được nét chính về CNXH từ năm 1991 đến nay và thành tựu cải cách – mở cửa ở Trung Quốc."],"sum":["Đông Âu: thắng lợi của Hồng quân Liên Xô tiêu diệt phát xít tạo điều kiện cho nhân dân Đông Âu giành chính quyền, lập nhà nước dân chủ nhân dân: Ba Lan (1944), Ru-ma-ni (1944), Hung-ga-ri, Tiệp…","Đông Âu: Thắng lợi của Hồng quân Liên Xô tiêu diệt phát xít tạo điều kiện cho nhân dân Đông Âu giành chính quyền, lập nhà nước dân chủ nhân dân: Ba Lan…","Châu Á và Mỹ La-tinh: Năm 1949 nước CHND Trung Hoa thành lập, chọn con đường XHCN; năm 1954 miền Bắc Việt Nam được giải phóng và đi lên CNXH, sau 1975–1976 cả nước xây…","Khủng hoảng, sụp đổ: Từ nửa sau những năm 70, tăng trưởng Đông Âu suy giảm; những năm 80 lâm vào suy thoái, khủng hoảng kinh tế – xã hội trầm trọng; cuối những năm 80…","Nguyên nhân cơ bản: Đường lối lãnh đạo chủ quan, duy ý chí, áp dụng máy móc mô hình kinh tế tập trung, quan liêu, bao cấp, chậm đổi mới","CNXH từ 1991 đến nay: Trung Quốc, Việt Nam, Lào từng bước cải cách, mở cửa, đổi mới, kiên định con đường XHCN."],"e":["Hay nhầm: Việt Nam giải phóng miền Bắc.","Hay nhầm: Là số liệu Liên Xô trước chiến tranh."],"q":{"n":12,"lv":{"Biết":5,"Hiểu":4,"Vận dụng":3}}}]},{"t":"Chủ đề 3. Quá trình giành độc lập dân tộc của các quốc gia Đông Nam Á","l":[{"t":"Bài 5. Quá trình xâm lược và cai trị của chủ nghĩa thực dân ở Đông Nam Á","req":["Trình bày được quá trình thực dân phương Tây xâm lược và thiết lập nền thống trị ở Đông Nam Á hải đảo và lục địa.","Trình bày được công cuộc cải cách ở Xiêm.","Giải thích được vì sao Xiêm là nước duy nhất ở Đông Nam Á không trở thành thuộc địa."],"m":[{"t":"Xây dựng trục thời gian quá trình xâm lược","w":"Đề yêu cầu lập trục thời gian về quá trình thực dân xâm lược Đông Nam Á.","s":["Liệt kê các mốc: 1511, giữa XVI, cuối XVI, 1824–1885, 1858–1893, 1898, đầu XX.","Sắp xếp theo thứ tự thời gian trên trục.","Ghi tên nước thực dân và nước bị xâm lược ở mỗi mốc.","Nhận xét: hải đảo trước (từ TK XVI), lục địa sau (TK XIX)."],"n":["Phân biệt hải đảo và lục địa.","Kết thúc bằng mốc đầu thế kỉ XX hoàn thành thôn tính."]}],"sum":["Xâm lược: hải đảo trước (từ đầu thế kỉ XVI, mở đầu 1511 Ma-lắc-ca), lục địa sau (thế kỉ XIX). Đầu thế kỉ XX thực dân hoàn thành thôn tính; chỉ Xiêm giữ được độc lập nhờ cải cách và ngoại giao mềm…","Vì sao phương Tây xâm nhập Đông Nam Á?: Từ đầu thế kỉ XVI, phương Tây vào qua buôn bán và truyền giáo, lập thương điếm.","Đông Nam Á hải đảo (từ thế kỉ XVI)","Đông Nam Á lục địa (từ thế kỉ XIX)","Ai chiếm nước nào?","Chính sách cai trị: chính trị: Duy trì thế lực phong kiến địa phương làm công cụ."],"e":["Lưu ý: Phân biệt hải đảo và lục địa.","Lưu ý: Kết thúc bằng mốc đầu thế kỉ XX hoàn thành thôn tính."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 6. Hành trình đi đến độc lập dân tộc ở Đông Nam Á","req":["Tóm tắt được nét chính về đấu tranh chống thực dân xâm lược ở Đông Nam Á hải đảo và lục địa.","Nêu được các giai đoạn phát triển của cuộc đấu tranh giành độc lập dân tộc ở Đông Nam Á.","Nêu được ảnh hưởng của chế độ thực dân và tóm tắt quá trình tái thiết, phát triển ở Đông Nam Á."],"sum":["Hải đảo: ở In-đô-nê-xi-a, từ thế kỉ XVI–XIX phong trào chống Hà Lan bùng nổ, nổi bật là khởi nghĩa của Hoàng tử Đi-pô-nê-gô-rô (1825–1830) trên đảo Gia-va, tuy thất bại nhưng gây tổn thất nặng nề…","Hải đảo: Ở In-đô-nê-xi-a, từ thế kỉ XVI–XIX phong trào chống Hà Lan bùng nổ, nổi bật là khởi nghĩa của Hoàng tử Đi-pô-nê-gô-rô (1825–1830) trên đảo Gia-va,…","Lục địa: Ở Miến Điện, Anh phải trải qua 3 cuộc chiến tranh hơn 60 năm (1821–1885) và đối phó chiến tranh du kích hơn 10 năm sau.","Ba giai đoạn giành độc lập: Cuối thế kỉ XIX đến 1920: khởi đầu cuộc đấu tranh giành độc lập dân tộc","Ảnh hưởng của chế độ thực dân: Kinh tế nông nghiệp lạc hậu, lệ thuộc nước ngoài, \"vựa lúa\" nhưng thiếu lương thực (Xin-ga-po sau 150 năm thuộc Anh chỉ là hải cảng trung chuyển,…","Tái thiết và phát triển: In-đô-nê-xi-a, Ma-lai-xi-a, Phi-líp-pin, Xin-ga-po công nghiệp hoá từ giữa những năm 50 – giai đoạn đầu thay thế nhập khẩu (xây dựng kinh tế độc lập…"],"e":["Hay nhầm: Là thời gian chiếm cả Đông Dương."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}}]},{"t":"Chủ đề 4. Chiến tranh bảo vệ Tổ quốc và chiến tranh giải phóng dân tộc trong lịch sử Việt Nam (trước Cách mạng tháng Tám năm 1945)","l":[{"t":"Bài 7. Chiến tranh bảo vệ Tổ quốc trong lịch sử Việt Nam","req":["Nêu được vị trí địa chiến lược của Việt Nam; phân tích vai trò, ý nghĩa của chiến tranh bảo vệ Tổ quốc.","Trình bày được nội dung chính của các cuộc kháng chiến thắng lợi tiêu biểu và không thành công.","Giải thích được nguyên nhân thắng lợi và không thành công; rút ra bài học lịch sử."],"m":[{"t":"Lập sơ đồ tư duy về một cuộc kháng chiến","w":"Đề yêu cầu tóm tắt một cuộc kháng chiến (thời gian, kẻ thù, người chỉ huy, trận quyết chiến, kết quả).","s":["Ghi tên cuộc kháng chiến ở trung tâm.","Nhánh 1: thời gian và kẻ thù xâm lược.","Nhánh 2: người lãnh đạo, chỉ huy.","Nhánh 3: trận quyết chiến chiến lược và kết quả, ý nghĩa."],"n":["Ghi đúng địa danh (tỉnh/thành ngày nay).","Nêu được nguyên nhân thắng lợi nổi bật."]}],"sum":["Vị trí địa chiến lược: Việt Nam thuộc Đông Nam Á – khu vực nằm trên trục giao thông kết nối châu Á và châu Đại Dương, Ấn Độ Dương và Thái Bình Dương; là cầu nối giữa Trung Quốc với Đông Nam Á, giữa…","Vị trí địa chiến lược: Việt Nam thuộc Đông Nam Á – khu vực nằm trên trục giao thông kết nối châu Á và châu Đại Dương, Ấn Độ Dương và Thái Bình Dương; là cầu nối giữa Trung…","Vai trò, ý nghĩa: Chiến tranh bảo vệ Tổ quốc có vai trò quan trọng đối với sự sinh tồn và phát triển của dân tộc; thắng lợi góp phần bảo vệ độc lập, giữ gìn bản sắc…","Một số cuộc kháng chiến thắng lợi: Chống Nam Hán (938, Ngô Quyền, Bạch Đằng); chống Tống lần 1 (981, Lê Hoàn, Bạch Đằng); chống Tống lần 2 (1075–1077, Lý Thường Kiệt, phòng tuyến Như…","Nguyên nhân thắng lợi: Các cuộc kháng chiến đều là chiến tranh chính nghĩa bảo vệ độc lập","Một số cuộc kháng chiến không thành công: Chống quân Triệu của An Dương Vương (179 TCN – Triệu Đà giảng hoà để dò bí mật thành Cổ Loa rồi đánh úp); chống quân Minh của nhà Hồ (1406–1407 –…"],"e":["Hay nhầm: Nhân dân chiến đấu quyết liệt.","Lưu ý: Ghi đúng địa danh (tỉnh/thành ngày nay).","Lưu ý: Nêu được nguyên nhân thắng lợi nổi bật."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 8. Một số cuộc khởi nghĩa và chiến tranh giải phóng trong lịch sử Việt Nam (từ thế kỉ III TCN đến cuối thế kỉ XIX)","req":["Trình bày được nội dung chính và ý nghĩa của các cuộc khởi nghĩa tiêu biểu thời Bắc thuộc.","Nêu được bối cảnh, diễn biến chính, ý nghĩa của khởi nghĩa Lam Sơn và phong trào Tây Sơn.","Rút ra được bài học lịch sử của các cuộc khởi nghĩa và chiến tranh giải phóng."],"m":[{"t":"Xây dựng trục thời gian phong trào Tây Sơn","w":"Đề yêu cầu lập trục thời gian các sự kiện chính.","s":["Liệt kê các mốc 1771, 1773, 1777, 1778, 1785, 1786, 1788, 1789.","Vẽ trục, chia khoảng tương đối theo năm.","Ghi ngắn gọn sự kiện ở mỗi mốc (địa danh, kết quả).","Nhấn mạnh hai chiến thắng chống ngoại xâm: 1785 (Xiêm) và 1789 (Thanh)."],"n":["Phân biệt lật đổ chúa Nguyễn (1777) và lật đổ họ Trịnh (1786).","Nguyễn Nhạc xưng đế 1778, Nguyễn Huệ xưng đế 1788."]}],"sum":["Khởi nghĩa thời Bắc thuộc: Hai Bà Trưng (năm 40, chống Hán, từ Hát Môn đánh chiếm Mê Linh, Cổ Loa, Luy Lâu;","Khởi nghĩa thời Bắc thuộc: Hai Bà Trưng (năm 40, chống Hán, từ Hát Môn đánh chiếm Mê Linh, Cổ Loa, Luy Lâu;","Khởi nghĩa Lam Sơn (1418–1427) – bối cảnh: Năm 1407 nhà Hồ thất bại, nhà Minh đô hộ (1407–1427): đặt thành quận Giao Chỉ, thuế nặng, bắt người tài, đồng hoá văn hoá (đục bia, đốt sách).","Diễn biến: 1416 Hội thề Lũng Nhai;","Phong trào Tây Sơn – bối cảnh: Giữa thế kỉ XVIII Đàng Trong khủng hoảng: chúa Nguyễn Phúc Thuần lên ngôi lúc 12 tuổi, quyền hành trong tay Trương Phúc Loan; bộ máy cồng kềnh, tham…","Diễn biến: 1773 chiếm phủ thành Quy Nhơn;"],"e":["Hay nhầm: Thủ lĩnh dân tộc thiểu số.","Lưu ý: Phân biệt lật đổ chúa Nguyễn (1777) và lật đổ họ Trịnh (1786).","Lưu ý: Nguyễn Nhạc xưng đế 1778, Nguyễn Huệ xưng đế 1788."],"q":{"n":12,"lv":{"Biết":5,"Hiểu":4,"Vận dụng":3}}}]},{"t":"Chủ đề 5. Một số cuộc cải cách lớn trong lịch sử Việt Nam (trước năm 1858)","l":[{"t":"Bài 9. Cuộc cải cách của Hồ Quý Ly và triều Hồ","req":["Trình bày được bối cảnh lịch sử, nội dung, kết quả, ý nghĩa cuộc cải cách của Hồ Quý Ly và triều Hồ.","Có ý thức trân trọng giá trị cuộc cải cách."],"sum":["Bối cảnh kinh tế – xã hội: từ nửa sau thế kỉ XIV, nhà nước không chăm lo nông nghiệp, đê điều, thuỷ lợi nên mất mùa, đói kém; vương hầu, quý tộc, địa chủ chiếm nhiều ruộng đất, nông dân phải bán…","Bối cảnh kinh tế – xã hội: Từ nửa sau thế kỉ XIV, nhà nước không chăm lo nông nghiệp, đê điều, thuỷ lợi nên mất mùa, đói kém; vương hầu, quý tộc, địa chủ chiếm nhiều ruộng…","Cải cách là sự đổi mới cho…: Cải cách là sự đổi mới cho tiến bộ hơn, phù hợp với sự phát triển chung của xã hội mà không đụng tới nền tảng của chế độ hiện hành.","Kinh tế – xã hội: Chính sách hạn điền hạn chế sở hữu lớn về ruộng đất (đại vương, trưởng công chúa không hạn chế, thứ dân chỉ 10 mẫu); phát hành tiền giấy (đổi 1 quan…","Kết quả, ý nghĩa: Có nhiều điểm tiến bộ, đưa đất nước thoát khỏi khủng hoảng, củng cố quyền lực chính quyền trung ương; hạn điền, hạn nô làm suy yếu quý tộc Trần,…"],"q":{"n":10,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 10. Cuộc cải cách của Lê Thánh Tông (thế kỉ XV)","req":["Trình bày được bối cảnh lịch sử, nội dung, kết quả, ý nghĩa cuộc cải cách của Lê Thánh Tông.","Có ý thức trân trọng giá trị cuộc cải cách."],"m":[{"t":"Vẽ sơ đồ tổ chức bộ máy nhà nước","w":"Đề yêu cầu vẽ sơ đồ bộ máy nhà nước thời Lê Thánh Tông (hoặc Minh Mạng).","s":["Đặt vua (hoàng đế) ở đỉnh, nắm toàn quyền.","Tầng trung ương: các cơ quan chuyên môn (lục Bộ, lục Tự, lục Khoa...).","Tầng địa phương: đạo thừa tuyên (tỉnh) → phủ → huyện/châu → xã.","Ghi chú cơ quan giám sát và người đứng đầu mỗi cấp."],"n":["Lục Khoa giám sát lục Bộ; ba ty ở thừa tuyên ngang quyền.","Số đạo thừa tuyên: 12 (1466) rồi 13 (1471)."]}],"sum":["Bối cảnh: năm 1460 Lê Thánh Tông lên ngôi khi đất nước đã từng bước ổn định nhưng bộ máy hành chính bộc lộ hạn chế.","Bối cảnh: Năm 1460 Lê Thánh Tông lên ngôi khi đất nước đã từng bước ổn định nhưng bộ máy hành chính bộc lộ hạn chế.","Hành chính: Ở trung ương, xoá bỏ hầu hết chức quan đại thần quyền lực lớn, vua trực tiếp chỉ đạo các cơ quan; hoàn thiện lục Bộ (Lại, Hộ, Lễ, Binh, Hình, Công),…","Pháp luật: Năm 1483 ban hành Quốc triều hình luật (Luật Hồng Đức) 722 điều, nhiều quy định mang tính dân tộc sâu sắc: bảo vệ phụ nữ (con gái được trả lại đồ lễ…","Kết quả, ý nghĩa: Bộ máy nhà nước quy củ, chặt chẽ, tập trung cao độ, đề cao quyền hành toàn diện của hoàng đế; chức năng các cơ quan rõ ràng, giám sát tăng cường,…"],"e":["Lưu ý: Lục Khoa giám sát lục Bộ; ba ty ở thừa tuyên ngang quyền.","Lưu ý: Số đạo thừa tuyên: 12 (1466) rồi 13 (1471)."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 11. Cuộc cải cách của Minh Mạng (nửa đầu thế kỉ XIX)","req":["Trình bày được bối cảnh lịch sử, nội dung, kết quả, ý nghĩa cuộc cải cách của Minh Mạng.","Có ý thức trân trọng giá trị của các cuộc cải cách trong lịch sử dân tộc."],"sum":["Bối cảnh: năm 1802 triều Nguyễn thành lập, cai quản đất nước rộng lớn vừa trải qua chiến tranh, chia cắt.","Bối cảnh: Năm 1802 triều Nguyễn thành lập, cai quản đất nước rộng lớn vừa trải qua chiến tranh, chia cắt.","Nội dung – trọng tâm là hành chính: Ở trung ương: 1820 đổi Thị thư viện thành Văn thư phòng;","Ở địa phương: Chia cả nước thành 30 tỉnh và phủ Thừa Thiên;","Kết quả, ý nghĩa: Xây dựng chế độ quân chủ trung ương tập quyền cao độ (vua nắm lập pháp, hành pháp, tư pháp, thống lĩnh quân đội); thống nhất đơn vị hành chính địa…"],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}}]},{"t":"Chủ đề 6. Lịch sử bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông","l":[{"t":"Bài 12. Vị trí và tầm quan trọng của Biển Đông","req":["Xác định được vị trí của Biển Đông; giải thích tầm quan trọng chiến lược về giao thông, vị trí chiến lược, tài nguyên.","Xác định vị trí các đảo, quần đảo ở Biển Đông; giải thích tầm quan trọng chiến lược của quần đảo Hoàng Sa và Trường Sa."],"sum":["Vị trí: Biển Đông thuộc Thái Bình Dương, trải từ khoảng 3°N đến 26°B và 100°Đ đến 121°Đ; diện tích khoảng 3,5 triệu km², dài khoảng 3 000 km theo trục đông bắc – tây nam, nối Thái Bình Dương với Ấn…","Vị trí: Biển Đông thuộc Thái Bình Dương, trải từ khoảng 3°N đến 26°B và 100°Đ đến 121°Đ; diện tích khoảng 3,5 triệu km², dài khoảng 3 000 km theo trục đông…","Tuyến giao thông huyết mạch: Tập trung các tuyến đường biển chiến lược nối Thái Bình Dương – Ấn Độ Dương, châu Âu – châu Á, Trung Đông – Đông Á;","Địa bàn chiến lược ở châu Á – Thái Bình Dương: Quan trọng về quốc phòng – an ninh, giao thông vận tải, kinh tế; là đường di chuyển ngắn nhất nối Thái Bình Dương và Ấn Độ Dương; các nước ven biển…","Hoàng Sa và Trường Sa thuộc chủ…: Hoàng Sa và Trường Sa thuộc chủ quyền Việt Nam, nằm ở trung tâm Biển Đông, là sự nối tiếp của lục địa Việt Nam ra biển.","Tầm quan trọng của các đảo, quần đảo: Nằm trên tuyến hàng hải quốc tế nên có ý nghĩa chiến lược về quốc phòng – an ninh, giúp kiểm soát, bảo đảm an ninh các tuyến giao thông biển; là cơ…"],"e":["Hay nhầm: Quan trọng nhưng không phải nhất."],"q":{"n":10,"lv":{"Biết":5,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 13. Việt Nam và Biển Đông","req":["Nêu được tầm quan trọng chiến lược của Biển Đông đối với Việt Nam về quốc phòng, an ninh và kinh tế.","Nêu được Việt Nam là nhà nước đầu tiên xác lập chủ quyền và quản lí liên tục Hoàng Sa, Trường Sa; trình bày cuộc đấu tranh bảo vệ, thực thi chủ quyền.","Nêu được chủ trương giải quyết tranh chấp bằng biện pháp hoà bình."],"m":[{"t":"Dùng tư liệu chứng minh chủ quyền của Việt Nam","w":"Đề yêu cầu chứng minh Việt Nam là nhà nước đầu tiên xác lập, quản lí liên tục Hoàng Sa, Trường Sa.","s":["Nêu bằng chứng bản đồ, thư tịch (trước 1884) của Việt Nam và phương Tây.","Nêu hoạt động mang tính nhà nước: đội Hoàng Sa, Bắc Hải; thuỷ quân thời Nguyễn; tổ chức hành chính.","Nêu sự quản lí liên tục 1884–1975 (Pháp, Hội nghị Xan Phran-xi-xcô, chính quyền Sài Gòn).","Nêu quản lí từ 1975 đến nay (huyện Hoàng Sa, Trường Sa; đấu tranh pháp lí)."],"n":["Nhấn mạnh tính \"liên tục\" và \"hoà bình\" của việc chiếm hữu.","Trích tư liệu có giá trị pháp lí cao."]}],"sum":["Tầm quan trọng với Việt Nam: Việt Nam giáp Biển Đông ở ba phía (đông, nam, tây nam), bờ biển dài khoảng 3 260 km từ Quảng Ninh đến Kiên Giang, 28 tỉnh thành giáp biển, cứ 100 km² đất liền có 1 km bờ…","Tầm quan trọng với Việt Nam: Việt Nam giáp Biển Đông ở ba phía (đông, nam, tây nam), bờ biển dài khoảng 3 260 km từ Quảng Ninh đến Kiên Giang, 28 tỉnh thành giáp biển, cứ 100…","Việt Nam là nhà nước đầu tiên…: Việt Nam là nhà nước đầu tiên xác lập chủ quyền và quản lí liên tục Hoàng Sa, Trường Sa.","Từ 1884 đến 1975: Chính quyền Pháp (đại diện ngoại giao của triều Nguyễn) tiếp tục khẳng định, quản lí: 1909 nêu rõ khảo sát của Trung Quốc ở Hoàng Sa là trái phép;…","Sau 1975: Nhà nước CHXHCN Việt Nam tiếp tục quản lí; năm 1982 lập huyện Hoàng Sa (tỉnh Quảng Nam – Đà Nẵng, từ 1997 thuộc TP Đà Nẵng) và huyện Trường Sa…","Chủ trương: Thực hiện biện pháp toàn diện về chính trị, ngoại giao, kinh tế, quân sự; giải quyết tranh chấp bằng biện pháp hoà bình, tinh thần hiểu biết, tôn…"],"e":["Lưu ý: Nhấn mạnh tính \"liên tục\" và \"hoà bình\" của việc chiếm hữu.","Lưu ý: Trích tư liệu có giá trị pháp lí cao."],"q":{"n":12,"lv":{"Biết":5,"Hiểu":4,"Vận dụng":3}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chủ đề 1. Cách mạng tư sản và sự phát triển của chủ nghĩa tư bản","l":[{"t":"Bài tập nâng cao · Chủ đề 1. Cách mạng tư sản và sự phát triển của chủ nghĩa tư bản (5 câu)","q":{"n":5,"lv":{"Nâng cao":5}}}]},{"t":"Chủ đề 2. Chủ nghĩa xã hội từ năm 1917 đến nay","l":[{"t":"Bài tập nâng cao · Chủ đề 2. Chủ nghĩa xã hội từ năm 1917 đến nay (5 câu)","q":{"n":5,"lv":{"Nâng cao":5}}}]},{"t":"Chủ đề 3. Quá trình giành độc lập dân tộc của các quốc gia Đông Nam Á","l":[{"t":"Bài tập nâng cao · Chủ đề 3. Quá trình giành độc lập dân tộc của các quốc gia Đông Nam Á (5 câu)","q":{"n":5,"lv":{"Nâng cao":5}}}]},{"t":"Chủ đề 4. Chiến tranh bảo vệ Tổ quốc và chiến tranh giải phóng dân tộc trong lịch sử Việt Nam (trước Cách mạng tháng Tám năm 1945)","l":[{"t":"Bài tập nâng cao · Chủ đề 4. Chiến tranh bảo vệ Tổ quốc và chiến tranh giải phóng dân tộc trong lịch sử Việt Nam…","e":["Hay nhầm: Có thành Đa Bang, Tây Đô.","Hay nhầm: Không phải nguyên nhân chính.","Hay nhầm: Tây Sơn không chống Minh."],"q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chủ đề 5. Một số cuộc cải cách lớn trong lịch sử Việt Nam (trước năm 1858)","l":[{"t":"Bài tập nâng cao · Chủ đề 5. Một số cuộc cải cách lớn trong lịch sử Việt Nam (trước năm 1858) (8 câu)","e":["Hay nhầm: Lê Thánh Tông thành công."],"q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chủ đề 6. Lịch sử bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông","l":[{"t":"Bài tập nâng cao · Chủ đề 6. Lịch sử bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]}]}]},{"id":"diali","name":"Địa lí","b":[{"t":"Địa lí 11","c":[{"t":"Phần một. Một số vấn đề kinh tế - xã hội thế giới","l":[{"t":"Bài 1. Sự khác biệt về trình độ phát triển kinh tế - xã hội của các nhóm nước","req":["Trình bày được các chỉ tiêu phân chia nhóm nước: GNI/người, cơ cấu kinh tế, HDI.","So sánh được sự khác biệt về kinh tế và xã hội giữa nước phát triển và nước đang phát triển."],"m":[{"t":"Phân loại một nước theo trình độ phát triển","w":"Đề yêu cầu xác định nhóm nước của một quốc gia dựa trên số liệu cho sẵn.","s":["Xác định GNI/người và đối chiếu với ngưỡng của Ngân hàng Thế giới.","Xác định HDI và đối chiếu với các mức của Liên hợp quốc.","Nhận xét cơ cấu GDP: tỉ trọng dịch vụ và công nghiệp.","Kết luận nước phát triển hay đang phát triển và nêu lí do."],"n":["Chỉ tiêu nào cũng cần xét đồng thời, không dựa vào một chỉ tiêu duy nhất.","Số liệu nên lấy đúng năm được yêu cầu."]}],"sum":["Thế giới có hơn 200 quốc gia và vùng lãnh thổ, được phân thành nhóm nước phát triển và đang phát triển dựa trên ba chỉ tiêu chủ yếu: tổng thu nhập quốc gia bình quân đầu người (GNI/người), cơ cấu…","Khái niệm: Thế giới có hơn 200 quốc gia và vùng lãnh thổ, được phân thành nhóm nước phát triển và đang phát triển dựa trên ba chỉ tiêu chủ yếu: tổng thu nhập…","GNI/người được tính bằng tổng thu nhập…: GNI/người được tính bằng tổng thu nhập quốc gia chia cho số dân; phản ánh mức sống và năng suất lao động.","Cơ cấu kinh tế theo ngành gồm…: Cơ cấu kinh tế theo ngành gồm nông nghiệp, lâm nghiệp, thuỷ sản; công nghiệp và xây dựng; dịch vụ.","HDI là thước đo tổng hợp về sức khoẻ, học vấn và thu nhập: Liên hợp quốc chia thành bốn mức: rất cao (từ 0,800 trở lên), cao (0,700 đến dưới 0,800), trung bình (0,550 đến dưới 0,700) và thấp (dưới 0,550).","Về kinh tế: Các nước phát triển có quy mô GDP lớn, tăng trưởng ổn định, tiến hành công nghiệp hoá sớm và có dịch vụ đóng góp nhiều nhất vào GDP."],"e":["Hay nhầm: Không phải chỉ tiêu phát triển chủ yếu.","Hay nhầm: Không đủ và không chính xác.","Hay nhầm: Không phản ánh trình độ phát triển.","Hay nhầm: Nông nghiệp chiếm tỉ trọng nhỏ.","Hay nhầm: Không đúng với nước đang phát triển.","Hay nhầm: Đặc điểm không phải của nước phát triển."],"q":{"n":10,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 2. Toàn cầu hoá và khu vực hoá kinh tế","req":["Trình bày được biểu hiện, hệ quả của toàn cầu hoá và khu vực hoá kinh tế.","Phân tích được ảnh hưởng và ý nghĩa của toàn cầu hoá, khu vực hoá đối với các nước."],"m":[{"t":"Phân tích ảnh hưởng của toàn cầu hoá đến một quốc gia","w":"Đề yêu cầu phân tích tác động của toàn cầu hoá đối với một nước cụ thể.","s":["Nêu biểu hiện của toàn cầu hoá đang diễn ra ở nước đó (thương mại, đầu tư, công ty đa quốc gia).","Phân tích mặt tích cực với số liệu minh hoạ.","Phân tích mặt tiêu cực (phụ thuộc, môi trường, phân hoá giàu nghèo).","Kết luận và đề xuất giải pháp khai thác tích cực, hạn chế tiêu cực."],"n":["Luôn nêu cả hai mặt tích cực và tiêu cực.","Số liệu cần có nguồn và năm cụ thể."]}],"sum":["Toàn cầu hoá là quá trình liên kết các quốc gia trên thế giới về nhiều mặt, từ kinh tế đến văn hoá, khoa học.","Khái niệm: Toàn cầu hoá là quá trình liên kết các quốc gia trên thế giới về nhiều mặt, từ kinh tế đến văn hoá, khoa học.","Biểu hiện của toàn cầu hoá kinh tế: Các dòng hàng hoá, dịch vụ, vốn, lao động và tri thức ngày càng được tự do dịch chuyển; các giao dịch về thương mại, đầu tư, tài chính tăng nhanh;…","Hệ quả của toàn cầu hoá kinh tế: Tăng cường chuyên môn hoá và hợp tác hoá; thúc đẩy phân công lao động quốc tế; tạo sự dịch chuyển các yếu tố sản xuất (lao động, vốn, công nghệ, tri…","Ảnh hưởng của toàn cầu hoá kinh…: Ảnh hưởng của toàn cầu hoá kinh tế có cả mặt tích cực lẫn tiêu cực.","Khu vực hoá kinh tế là quá…: Khu vực hoá kinh tế là quá trình liên kết, hợp tác kinh tế giữa các nước trong cùng một khu vực, trên cơ sở tương đồng về địa lí, văn hoá, xã hội…"],"e":["Hay nhầm: Đó là khu vực hoá, không phải toàn cầu hoá.","Hay nhầm: Là tổ chức các nước xuất khẩu dầu mỏ.","Hay nhầm: APEC là châu Á – Thái Bình Dương.","Lưu ý: Luôn nêu cả hai mặt tích cực và tiêu cực.","Lưu ý: Số liệu cần có nguồn và năm cụ thể."],"q":{"n":10,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":2}}},{"t":"Thực hành: Tìm hiểu về cơ hội và thách thức của toàn cầu hoá và khu vực hoá kinh tế","req":["Sưu tầm, hệ thống hoá tư liệu về toàn cầu hoá và khu vực hoá kinh tế.","Viết được báo cáo về cơ hội và thách thức đối với các nước đang phát triển."],"m":[{"t":"Viết báo cáo về cơ hội và thách thức","w":"Thực hành yêu cầu viết báo cáo có số liệu và nhận định.","s":["Sưu tầm số liệu, nguồn tư liệu tin cậy và ghi rõ nguồn.","Lập dàn ý theo hai phần: toàn cầu hoá và khu vực hoá.","Với mỗi phần, nêu cơ hội và thách thức riêng.","Kết luận và đề xuất giải pháp cho nước đang phát triển."],"n":["Số liệu phải có năm và nguồn cụ thể.","Nên nêu ví dụ thực tế của Việt Nam nếu có."]}],"sum":["Nội dung thực hành: sưu tầm và hệ thống hoá tư liệu, số liệu về toàn cầu hoá và khu vực hoá kinh tế; trao đổi, thảo luận về cơ hội và thách thức đối với các nước đang phát triển; viết báo cáo về các…","Nội dung thực hành: Sưu tầm và hệ thống hoá tư liệu, số liệu về toàn cầu hoá và khu vực hoá kinh tế; trao đổi, thảo luận về cơ hội và thách thức đối với các nước đang…","Nguồn tư liệu: Sách, báo cáo liên quan; các trang web có độ tin cậy cao của tổ chức quốc tế và Việt Nam (ví dụ UNCTAD về thương mại và đầu tư toàn cầu;"],"e":["Hay nhầm: Rào cản là đặc điểm khác.","Lưu ý: Số liệu phải có năm và nguồn cụ thể.","Lưu ý: Nên nêu ví dụ thực tế của Việt Nam nếu có."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}},{"t":"Bài 4. Một số tổ chức quốc tế và khu vực, an ninh toàn cầu","req":["Trình bày được năm thành lập, mục tiêu hoạt động và vai trò của một số tổ chức quốc tế và khu vực (UN, WTO, IMF, APEC).","Nêu được một số vấn đề an ninh toàn cầu và sự cần thiết phải bảo vệ hoà bình thế giới."],"m":[{"t":"Lập bảng so sánh các tổ chức quốc tế","w":"Đề yêu cầu so sánh hoặc trình bày về một tổ chức quốc tế hoặc khu vực.","s":["Xác định năm thành lập.","Xác định số thành viên và thời điểm Việt Nam gia nhập.","Nêu mục tiêu hoạt động chính.","Nhận xét vai trò của tổ chức đối với Việt Nam và thế giới."],"n":["Số thành viên cần ghi rõ năm số liệu.","Phân biệt tổ chức toàn cầu (UN, WTO, IMF) và tổ chức khu vực (APEC)."]}],"sum":["4 tổ chức cần nhớ: IMF 1944, UN 1945, APEC 1989, WTO 1995. UN, WTO, IMF là tổ chức toàn cầu; APEC là tổ chức khu vực. An ninh gồm truyền thống (quân sự, chính trị) và phi truyền thống (kinh tế,…","So sánh bốn tổ chức: Các nước lập nhiều tổ chức để đảm bảo hòa bình và điều tiết hoạt động kinh tế toàn cầu.","Liên hợp quốc (UN): Thành lập 1945, tôn chỉ bảo đảm hòa bình và trật tự thế giới bền vững.","Tổ chức Thương mại Thế giới (WTO): Thành lập và hoạt động từ 1995.","Quỹ Tiền tệ Quốc tế (IMF): Thành lập 1944, sớm nhất trong bốn tổ chức.","Diễn đàn APEC: Thành lập 1989, nhằm thúc đẩy tự do thương mại, đầu tư và mở cửa trong khu vực."],"e":["Hay nhầm: 1944 là năm IMF thành lập.","Hay nhầm: 24% là dự báo tăng đến 2050.","Lưu ý: Số thành viên cần ghi rõ năm số liệu.","Lưu ý: Phân biệt tổ chức toàn cầu (UN, WTO, IMF) và tổ chức khu vực (APEC)."],"q":{"n":11,"lv":{"Biết":5,"Hiểu":4,"Vận dụng":2}}},{"t":"Thực hành: Viết báo cáo về đặc điểm và biểu hiện của nền kinh tế tri thức","req":["Nêu được khái niệm nền kinh tế tri thức.","Trình bày được đặc điểm và biểu hiện của nền kinh tế tri thức qua báo cáo."],"m":[{"t":"Viết báo cáo về nền kinh tế tri thức","w":"Đề yêu cầu viết báo cáo về đặc điểm và biểu hiện.","s":["Nêu khái niệm tri thức và nền kinh tế tri thức.","Liệt kê các đặc điểm chính.","Nêu các biểu hiện cụ thể (ví dụ: công nghệ, thực tế ảo, lao động tri thức).","Kết luận và đánh giá cơ hội, thách thức đối với Việt Nam."],"n":["Tìm tư liệu từ các nguồn đáng tin cậy.","Trình bày ngắn gọn, có ví dụ thực tế."]}],"sum":["Kinh tế tri thức là nền kinh tế sử dụng hiệu quả tri thức cho sự phát triển kinh tế – xã hội.","Khái niệm: Kinh tế tri thức là nền kinh tế sử dụng hiệu quả tri thức cho sự phát triển kinh tế – xã hội.","Đặc trưng: Tri thức trở thành lực lượng sản xuất trực tiếp và nguồn vốn cơ bản; sản xuất công nghệ là hình thức sản xuất quan trọng nhất; lao động tri thức…","Lợi thế: Sản xuất ít gây ô nhiễm môi trường, tạo tiền đề phát triển bền vững; sản xuất theo nhu cầu tiêu dùng, cân bằng cung cầu và hạn chế hàng tồn kho;…"],"e":["Lưu ý: Tìm tư liệu từ các nguồn đáng tin cậy.","Lưu ý: Trình bày ngắn gọn, có ví dụ thực tế."],"q":{"n":7,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":1}}}]},{"t":"Chương 2. Khu vực Mỹ La-tinh","l":[{"t":"Bài 6. Vị trí địa lí, điều kiện tự nhiên, dân cư và xã hội khu vực Mỹ La-tinh","req":["Trình bày được vị trí địa lí, phạm vi lãnh thổ và ảnh hưởng của chúng đến phát triển kinh tế – xã hội.","Trình bày được đặc điểm điều kiện tự nhiên, tài nguyên và dân cư, đô thị hoá của khu vực."],"m":[{"t":"Phân tích ảnh hưởng của điều kiện tự nhiên đến phát triển kinh tế","w":"Đề yêu cầu phân tích tác động của một điều kiện tự nhiên hoặc tài nguyên.","s":["Xác định đặc điểm của yếu tố tự nhiên (địa hình, khí hậu, khoáng sản...).","Nêu thuận lợi đối với các ngành kinh tế (nông nghiệp, công nghiệp, du lịch...).","Nêu khó khăn hoặc hạn chế (thiên tai, địa hình chia cắt, khai thác quá mức).","Kết luận về ảnh hưởng tổng hợp."],"n":["Phân tích cả thuận lợi và khó khăn.","Dẫn số liệu hoặc ví dụ cụ thể của một nước."]}],"sum":["Khu vực Mỹ La-tinh có diện tích khoảng 20 triệu km², gồm Mê-hi-cô, eo đất Trung Mỹ, các đảo trong vùng biển Ca-ri-bê và toàn bộ lục địa Nam Mỹ.","Khái niệm: Khu vực Mỹ La-tinh có diện tích khoảng 20 triệu km², gồm Mê-hi-cô, eo đất Trung Mỹ, các đảo trong vùng biển Ca-ri-bê và toàn bộ lục địa Nam Mỹ.","Vị trí địa lí: Phía bắc giáp Bắc Mỹ (Hoa Kỳ, Ca-na-đa) là thị trường tiêu thụ rộng lớn và nguồn đầu tư quan trọng.","Địa hình phía tây là miền núi cao: Sơn nguyên Mê-hi-cô, vùng núi trẻ Trung Mỹ và hệ thống An-đét đồ sộ bậc nhất thế giới (dài khoảng 9 000 km, độ cao trung bình 3 000–5 000 m).","Khí hậu chủ yếu nóng ẩm và phân hoá thành nhiều đới: Xích đạo, cận xích đạo, nhiệt đới, cận nhiệt, ôn đới và khí hậu núi cao.","Khoáng sản phong phú, tập trung ở…: Khoáng sản phong phú, tập trung ở vùng An-đét và đông nam sơn nguyên Bra-xin: sắt (Bra-xin), đồng (Chi-lê), chì – kẽm, bạc (Bô-li-vi-a, Pê-ru,…"],"e":["Hay nhầm: Đó là diện tích thuộc địa của Anh năm 1914.","Hay nhầm: Tai-ga thuộc vùng ôn đới.","Lưu ý: Phân tích cả thuận lợi và khó khăn.","Lưu ý: Dẫn số liệu hoặc ví dụ cụ thể của một nước."],"q":{"n":11,"lv":{"Biết":7,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 7. Kinh tế khu vực Mỹ La-tinh","req":["Trình bày được tình hình phát triển kinh tế, quy mô GDP và tốc độ tăng trưởng của khu vực.","Phân tích được đặc điểm nổi bật của nông nghiệp, công nghiệp và dịch vụ."],"m":[{"t":"Phân tích đặc điểm một ngành kinh tế","w":"Đề yêu cầu trình bày đặc điểm của nông nghiệp, công nghiệp hoặc dịch vụ.","s":["Nêu vai trò của ngành trong GDP (tỉ trọng, xu hướng).","Nêu các sản phẩm hoặc hoạt động chủ yếu, kèm địa phương tiêu biểu.","Phân tích điều kiện thuận lợi và hạn chế.","Kết luận về xu hướng phát triển."],"n":["Dùng số liệu để chứng minh nhận định.","Liên hệ với đặc điểm tự nhiên và dân cư đã học."]}],"sum":["Khu vực Mỹ La-tinh đóng góp khoảng 6% GDP thế giới năm 2020. Quy mô GDP các nước rất chênh lệch: năm 2020, Bra-xin (1 448,7 tỉ USD) và Mê-hi-cô (1 073,9 tỉ USD) là hai nền kinh tế lớn nhất khu vực.","Khu vực Mỹ La-tinh đóng góp khoảng 6% GDP thế giới năm 2020: Quy mô GDP các nước rất chênh lệch: năm 2020, Bra-xin (1 448,7 tỉ USD) và Mê-hi-cô (1 073,9 tỉ USD) là hai nền kinh tế lớn nhất khu vực.","Khu vực tiến hành công nghiệp hoá khá sớm (thế kỉ XIX): Tuy nhiên, nền kinh tế phụ thuộc nhiều vào nước ngoài về vốn, công nghệ, thị trường; cùng với bất ổn chính trị – xã hội nên tốc độ tăng trưởng GDP…","Nông nghiệp có nhiều điều kiện thuận…: Nông nghiệp có nhiều điều kiện thuận lợi, cơ cấu cây trồng đa dạng gồm lương thực (ngô, lúa mì), cây công nghiệp (cà phê, ca cao, đậu tương, mía,…","Công nghiệp khai khoáng rất phát triển: Mỹ La-tinh sản xuất khoảng 45% lượng đồng, 50% lượng bạc, 21% lượng kẽm của thế giới; khai thác nhiều dầu mỏ và khí tự nhiên ở Vê-nê-du-ê-la,…","Dịch vụ đóng góp nhiều nhất vào GDP và có xu hướng tăng: Ngoại thương là lĩnh vực quan trọng: xuất khẩu quặng khoáng sản, dầu thô, nông sản nhiệt đới, thịt, sữa; năm 2020 trị giá xuất khẩu đạt 1 189,1 tỉ…"],"e":["Hay nhầm: Chi-lê có GDP 252,9 tỉ USD.","Hay nhầm: Ác-hen-ti-na có GDP 389,3 tỉ USD.","Hay nhầm: Pa-na-ma không có trong bảng.","Hay nhầm: Ô tô, máy bay là sản phẩm chế tạo, không phải chủ yếu.","Hay nhầm: Đúng một phần, nhưng không đầy đủ.","Lưu ý: Dùng số liệu để chứng minh nhận định."],"q":{"n":10,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":2}}},{"t":"Thực hành: Viết báo cáo về tình hình phát triển kinh tế – xã hội ở Cộng hoà Liên bang Bra-xin","req":["Viết được báo cáo về tình hình phát triển kinh tế và những vấn đề xã hội cần giải quyết ở Bra-xin.","Sử dụng số liệu để nhận xét về GDP và cơ cấu kinh tế của Bra-xin."],"m":[{"t":"Viết báo cáo về một quốc gia","w":"Thực hành viết báo cáo có số liệu và nhận định.","s":["Giới thiệu diện tích, số dân và vị trí.","Trình bày đặc điểm và nguyên nhân phát triển kinh tế, có số liệu theo bảng.","Nêu các vấn đề xã hội, phân tích hậu quả.","Kết luận và nêu hướng giải quyết."],"n":["Ghi rõ năm và nguồn số liệu.","Đối chiếu số liệu với các mốc thời gian."]}],"sum":["Nội dung thực hành: viết báo cáo về tình hình phát triển kinh tế – xã hội và những vấn đề xã hội cần giải quyết ở Cộng hoà Liên bang Bra-xin.","Nội dung thực hành: Viết báo cáo về tình hình phát triển kinh tế – xã hội và những vấn đề xã hội cần giải quyết ở Cộng hoà Liên bang Bra-xin.","Cấu trúc gợi ý: Diện tích, số dân; tình hình phát triển kinh tế (đặc điểm và nguyên nhân); những vấn đề xã hội cần giải quyết (mức sống, phân hoá giàu nghèo, thất…","GDP của Bra-xin tăng từ 655,5 tỉ…: GDP của Bra-xin tăng từ 655,5 tỉ USD (2000) lên 2 208,9 tỉ USD (2010), sau đó giảm còn 1 448,6 tỉ USD (2020).","Những vấn đề xã hội cần giải quyết: Chênh lệch thu nhập rất lớn (10% giàu nhất chiếm hơn 40% GDP, 10% nghèo nhất chỉ khoảng 1% GDP); phân hoá vùng (Đông Nam có trên 40% dân số và trên…"],"e":["Lưu ý: Ghi rõ năm và nguồn số liệu.","Lưu ý: Đối chiếu số liệu với các mốc thời gian."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 3. Liên minh châu Âu và Cộng hoà Liên bang Đức","l":[{"t":"Bài 9. Liên minh châu Âu – Một liên kết kinh tế khu vực lớn","req":["Trình bày được quy mô, mục tiêu và thể chế hoạt động của EU.","Phân tích được vị thế của EU trong nền kinh tế thế giới.","Phân tích được một số biểu hiện của hợp tác và liên kết trong EU."],"m":[{"t":"Phân tích biểu hiện hợp tác trong EU","w":"Đề yêu cầu phân tích một biểu hiện hợp tác, liên kết trong khu vực EU.","s":["Nêu nội dung hợp tác (tự do, tiền tệ, bền vững, công nghệ...).","Nêu mục tiêu của hợp tác và cơ sở pháp lí (hiệp ước).","Dẫn chứng cụ thể (ví dụ: đồng Ơ-rô, Thoả thuận Xanh).","Nhận xét tác động đến kinh tế và vị thế EU."],"n":["Hợp tác là điều kiện để thị trường chung vận hành.","Liên kết kinh tế mạnh giúp các nước phối hợp chính sách."]}],"sum":["Liên minh châu Âu (EU) là liên kết kinh tế khu vực lớn nhất thế giới về nhiều mặt. Năm 1957, Cộng đồng kinh tế châu Âu được thành lập với 6 nước; năm 1967 hợp nhất với Cộng đồng Than và Thép châu Âu…","Khái niệm: Liên minh châu Âu (EU) là liên kết kinh tế khu vực lớn nhất thế giới về nhiều mặt.","Quy mô: Năm 2021 EU có 27 quốc gia thành viên, chiếm khoảng 5,8% số dân và đóng góp 17,8% GDP toàn thế giới.","Mục tiêu: Theo Hiệp ước Ma-xtrích (1993), EU xây dựng liên minh kinh tế và tiền tệ với đơn vị tiền tệ chung; liên minh chính trị với chính sách đối ngoại và…","Thể chế: Gồm Hội đồng châu Âu (cơ quan quyền lực cao nhất, gồm 27 nguyên thủ, thường họp 4 lần một năm), Nghị viện châu Âu (cơ quan làm luật, đại diện công…","Vị thế kinh tế: GDP năm 2021 của EU chiếm 17,8% GDP toàn cầu, lớn thứ ba thế giới sau Hoa Kỳ và Trung Quốc;"],"e":["Hay nhầm: Năm Cộng đồng kinh tế châu Âu ra đời.","Hay nhầm: Thời điểm hiệp ước Li-xbon ký.","Hay nhầm: Năm hợp nhất các cộng đồng.","Hay nhầm: Số đồng tiền chung năm 2021.","Hay nhầm: Cơ quan quyền lực cao nhất.","Hay nhầm: Cơ quan làm luật, đại diện công dân."],"q":{"n":10,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":2}}},{"t":"Thực hành: Viết báo cáo về sự phát triển công nghiệp của Cộng hoà Liên bang Đức","req":["Viết được báo cáo về sự phát triển công nghiệp của Cộng hoà Liên bang Đức.","Sử dụng số liệu để nhận xét về vị trí của công nghiệp Đức trong EU."],"m":[{"t":"Viết báo cáo về phát triển công nghiệp một nước","w":"Thực hành viết báo cáo có số liệu và nhận định.","s":["Khái quát vai trò của công nghiệp trong GDP và lao động.","Lập bảng số liệu giá trị sản xuất, tỉ lệ đóng góp theo năm.","Nêu các ngành nổi bật và phân bố sản xuất.","Nhận xét xu hướng và đánh giá điều kiện phát triển."],"n":["Số liệu cần ghi đơn vị và năm.","Nên so sánh với vị trí của nước đó trong EU."]}],"sum":["Nội dung thực hành: viết báo cáo tìm hiểu sự phát triển công nghiệp của Cộng hoà Liên bang Đức.","Nội dung thực hành: Viết báo cáo tìm hiểu sự phát triển công nghiệp của Cộng hoà Liên bang Đức.","Cấu trúc gợi ý: Khái quát chung về ngành công nghiệp (vai trò, vị thế trong nền kinh tế Đức và thế giới)","Công nghiệp và xây dựng chiếm khoảng…: Công nghiệp và xây dựng chiếm khoảng 30% GDP và sử dụng khoảng 24% lực lượng lao động."],"e":["Lưu ý: Số liệu cần ghi đơn vị và năm.","Lưu ý: Nên so sánh với vị trí của nước đó trong EU."],"q":{"n":7,"lv":{"Biết":3,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 4. Khu vực Đông Nam Á","l":[{"t":"Bài 11. Vị trí địa lí, điều kiện tự nhiên, dân cư và xã hội khu vực Đông Nam Á","req":["Trình bày được vị trí địa lí, phạm vi lãnh thổ và ảnh hưởng của vị trí đến phát triển kinh tế – xã hội khu vực Đông Nam Á.","Trình bày được đặc điểm tự nhiên, tài nguyên, dân cư và xã hội của khu vực."],"m":[{"t":"Phân tích ảnh hưởng của điều kiện tự nhiên đến nông nghiệp","w":"Đề yêu cầu phân tích thuận lợi và khó khăn của thiên nhiên đối với sản xuất.","s":["Nêu đặc điểm khí hậu (nhiệt, ẩm, mưa) và đất, địa hình.","Nêu thuận lợi cho cây trồng nhiệt đới và chăn nuôi.","Nêu khó khăn: bão, lũ, khô hạn, biến đổi khí hậu.","Kết luận và đề xuất giải pháp thích ứng."],"n":["Luôn gắn đặc điểm tự nhiên với sản phẩm cụ thể.","Dẫn ví dụ của một nước trong khu vực."]}],"sum":["Khu vực Đông Nam Á có diện tích khoảng 4,5 triệu km², gồm 11 quốc gia, chia thành hai bộ phận: Đông Nam Á lục địa và Đông Nam Á hải đảo.","Khái niệm: Khu vực Đông Nam Á có diện tích khoảng 4,5 triệu km², gồm 11 quốc gia, chia thành hai bộ phận: Đông Nam Á lục địa và Đông Nam Á hải đảo.","Vị trí địa lí tạo thuận lợi…: Vị trí địa lí tạo thuận lợi cho giao lưu và phát triển kinh tế, đồng thời khu vực chịu nhiều thiên tai như bão, động đất, núi lửa, sóng thần.","Địa hình lục địa bị chia cắt…: Địa hình lục địa bị chia cắt mạnh bởi các dãy núi, xen các đồng bằng châu thổ như đồng bằng sông Hồng, sông Mê Nam, sông I-ra-oa-đi, sông Mê Công.","Khí hậu chủ yếu xích đạo và nhiệt đới: Nhiệt độ trung bình 21–27°C, độ ẩm trên 80%, lượng mưa 1 000–2 000 mm.","Khoáng sản đa dạng do nằm trong vành đai sinh khoáng: Thiếc, than đá, sắt, bô-xít, dầu mỏ, khí tự nhiên."],"e":["Hay nhầm: Hồ Tô-ba ở In-đô-nê-xi-a.","Lưu ý: Luôn gắn đặc điểm tự nhiên với sản phẩm cụ thể.","Lưu ý: Dẫn ví dụ của một nước trong khu vực."],"q":{"n":9,"lv":{"Biết":4,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 12. Kinh tế khu vực Đông Nam Á","req":["Trình bày được tình hình phát triển kinh tế và tốc độ tăng GDP của khu vực.","Phân tích được đặc điểm của các ngành nông nghiệp, công nghiệp, dịch vụ ở Đông Nam Á."],"m":[{"t":"Phân tích sự phát triển một ngành kinh tế của Đông Nam Á","w":"Đề yêu cầu trình bày và giải thích sự phát triển của một ngành.","s":["Nêu vị trí của ngành trong GDP hoặc xuất khẩu.","Nêu sản phẩm và các nước phát triển tiêu biểu.","Giải thích nguyên nhân (điều kiện tự nhiên, lao động, đầu tư).","Nêu thách thức và xu hướng phát triển."],"n":["Giải thích cần dựa vào điều kiện tự nhiên và kinh tế.","Nêu số liệu cụ thể."]}],"sum":["Quy mô GDP của Đông Nam Á tăng liên tục giai đoạn 2000–2020, từ 614,9 tỉ USD lên 3 083,3 tỉ USD, nhưng năm 2020 chỉ chiếm khoảng 3,6% GDP toàn cầu.","Khái niệm: Quy mô GDP của Đông Nam Á tăng liên tục giai đoạn 2000–2020, từ 614,9 tỉ USD lên 3 083,3 tỉ USD, nhưng năm 2020 chỉ chiếm khoảng 3,6% GDP toàn cầu.","Cơ cấu kinh tế của hầu hết…: Cơ cấu kinh tế của hầu hết các nước đang chuyển dịch theo hướng công nghiệp hoá, hiện đại hoá; một số nước chú trọng phát triển kinh tế tri thức.","Nông nghiệp: Trồng lúa gạo là ngành chính, In-đô-nê-xi-a là nước có sản lượng lúa gạo lớn nhất khu vực (54,6 triệu tấn năm 2020);","Công nghiệp: Cơ khí chế tạo là động lực tăng trưởng và nâng cao khả năng cạnh tranh;","Dịch vụ: Thương mại nội khối phát triển nhanh; ngoại thương có vai trò then chốt, phần lớn các nước xuất siêu;"],"e":["Hay nhầm: Xuất khẩu hàng đầu, nhưng sản lượng nhỏ hơn.","Lưu ý: Giải thích cần dựa vào điều kiện tự nhiên và kinh tế.","Lưu ý: Nêu số liệu cụ thể."],"q":{"n":9,"lv":{"Biết":4,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 13. Hiệp hội các quốc gia Đông Nam Á (ASEAN)","req":["Trình bày được mục tiêu và cơ chế hoạt động của ASEAN.","Trình bày được một số hợp tác kinh tế, văn hoá, y tế và thành tựu, thách thức của ASEAN.","Nêu được vai trò của Việt Nam trong ASEAN."],"m":[{"t":"Phân tích vai trò của một tổ chức khu vực","w":"Đề yêu cầu trình bày mục tiêu, hợp tác và vai trò của ASEAN hoặc một thành viên.","s":["Nêu mục tiêu chung (hoà bình, ổn định, phát triển).","Nêu hợp tác tiêu biểu theo từng lĩnh vực.","Nêu vai trò của quốc gia thành viên (ví dụ Việt Nam).","Đánh giá thành tựu và thách thức."],"n":["Dẫn chứng cụ thể về hội nghị, hiệp định.","Đánh giá khách quan."]}],"sum":["ASEAN được thành lập ngày 8-8-1967 tại Băng Cốc (Thái Lan) với 5 nước ban đầu: In-đô-nê-xi-a, Ma-lai-xi-a, Phi-líp-pin, Xin-ga-po và Thái Lan.","Khái niệm: ASEAN được thành lập ngày 8-8-1967 tại Băng Cốc (Thái Lan) với 5 nước ban đầu: In-đô-nê-xi-a, Ma-lai-xi-a, Phi-líp-pin, Xin-ga-po và Thái Lan.","Mục tiêu: Hiến chương ASEAN (có hiệu lực năm 2008) khẳng định các mục tiêu trong Tuyên bố Băng Cốc (1967) và bổ sung thêm nhiều mục tiêu, như thúc đẩy tăng…","Cơ chế hoạt động: Nguyên tắc chủ đạo là không can thiệp vào công việc nội bộ của nhau; tham vấn và ra quyết định bằng đồng thuận.","Hợp tác kinh tế nội khối: Khu vực thương mại tự do ASEAN (AFTA) thành lập năm 1992 nhằm xoá bỏ hàng rào thuế quan;","Hợp tác văn hoá, giáo dục, y tế: Xây dựng Cộng đồng Văn hoá – Xã hội ASEAN với khẩu hiệu \"Thống nhất trong đa dạng\", các hoạt động như Liên hoan nghệ thuật ASEAN, số hoá di sản,…"],"e":["Hay nhầm: Trụ sở tại Gia-các-ta, nhưng không phải nơi thành lập.","Lưu ý: Dẫn chứng cụ thể về hội nghị, hiệp định.","Lưu ý: Đánh giá khách quan."],"q":{"n":10,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":2}}},{"t":"Thực hành: Tìm hiểu hoạt động kinh tế đối ngoại của khu vực Đông Nam Á","req":["Vẽ được biểu đồ thể hiện trị giá xuất, nhập khẩu hàng hoá và dịch vụ của khu vực Đông Nam Á giai đoạn 2010–2020.","Nhận xét và giải thích được về hoạt động thương mại và du lịch."],"m":[{"t":"Vẽ và nhận xét biểu đồ cột hai chuỗi số liệu","w":"Thực hành vẽ biểu đồ và nhận xét xu hướng.","s":["Chọn biểu đồ cột nhóm (xuất và nhập) theo các năm.","Ghi đơn vị (tỉ USD), tên biểu đồ và chú giải.","Nhận xét xu hướng tăng và so sánh xuất – nhập.","Giải thích nguyên nhân."],"n":["Ghi đủ đơn vị và năm.","Phần nhận xét cần có số liệu cụ thể."]}],"sum":["Nội dung thực hành: viết bài giới thiệu ngắn về hoạt động du lịch của khu vực Đông Nam Á; vẽ biểu đồ thể hiện trị giá xuất khẩu, nhập khẩu hàng hoá và dịch vụ giai đoạn 2010–2020, nhận xét và giải…","Nội dung thực hành: Viết bài giới thiệu ngắn về hoạt động du lịch của khu vực Đông Nam Á; vẽ biểu đồ thể hiện trị giá xuất khẩu, nhập khẩu hàng hoá và dịch vụ giai đoạn…","Bảng số liệu: Trị giá xuất khẩu hàng hoá và dịch vụ của Đông Nam Á năm 2010 là 1 244,9 tỉ USD, năm 2015 là 1 506,0 tỉ USD, năm 2020 là 1 676,3 tỉ USD; trị giá…","Nhận xét: Xuất khẩu và nhập khẩu đều tăng từ 2010 đến 2020; xuất khẩu luôn cao hơn nhập khẩu, cho thấy khu vực xuất siêu.","Du lịch: Năm 2019 khu vực đón 138,5 triệu lượt khách quốc tế, tăng mạnh so với mức 49,3 triệu lượt năm 2005; khu vực thu hút khoảng 10% tổng lượng khách du…"],"e":["Lưu ý: Ghi đủ đơn vị và năm.","Lưu ý: Phần nhận xét cần có số liệu cụ thể."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 5. Khu vực Tây Nam Á","l":[{"t":"Bài 15. Vị trí địa lí, điều kiện tự nhiên, dân cư và xã hội khu vực Tây Nam Á","req":["Trình bày được vị trí địa lí, phạm vi lãnh thổ và ảnh hưởng của vị trí đến phát triển kinh tế – xã hội.","Trình bày được đặc điểm tự nhiên, tài nguyên, dân cư và xã hội của khu vực."],"m":[{"t":"Phân tích ảnh hưởng của đặc điểm dân cư đến kinh tế","w":"Đề yêu cầu phân tích ảnh hưởng của dân cư đối với phát triển kinh tế – xã hội.","s":["Nêu đặc điểm dân cư (số dân, cơ cấu tuổi, tỉ lệ thành thị, lao động nhập cư).","Phân tích thuận lợi: lực lượng lao động, thị trường.","Phân tích khó khăn: phân bố không đều, bất ổn xã hội.","Kết luận."],"n":["Gắn đặc điểm dân cư với kinh tế cụ thể.","Dùng số liệu của bảng 15.2 hoặc hình 15.4."]}],"sum":["Tây Nam Á gồm 20 quốc gia, diện tích đất khoảng 7 triệu km², nằm ở phía tây nam châu Á, trong khoảng 12°B–42°B và 27°Đ–73°Đ.","Khái niệm: Tây Nam Á gồm 20 quốc gia, diện tích đất khoảng 7 triệu km², nằm ở phía tây nam châu Á, trong khoảng 12°B–42°B và 27°Đ–73°Đ.","Khu vực tiếp giáp nhiều biển và vịnh: Biển Đỏ, biển A-ráp, vịnh Péc-xích, Địa Trung Hải, Biển Đen; thông ra Đại Tây Dương ở phía bắc và Ấn Độ Dương ở phía nam.","Vị trí tạo nên khu vực có…: Vị trí tạo nên khu vực có vị trí địa chính trị quan trọng, án ngữ tuyến đường giao thông bậc nhất thế giới;","Địa hình gồm núi, sơn nguyên và đồng bằng: Đồng bằng Lưỡng Hà do sông Ti-grơ và Ơ-phrát bồi đắp là đồng bằng lớn nhất, đất phù sa màu mỡ, thuận lợi cho nông nghiệp và cư trú.","Khí hậu cận nhiệt và nhiệt đới, kiểu khí hậu lục địa: Khô nóng vào mùa hè, khô lạnh vào mùa đông."],"e":["Lưu ý: Gắn đặc điểm dân cư với kinh tế cụ thể.","Lưu ý: Dùng số liệu của bảng 15.2 hoặc hình 15.4."],"q":{"n":9,"lv":{"Biết":4,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 16. Kinh tế khu vực Tây Nam Á","req":["Trình bày được tình hình phát triển kinh tế, tăng trưởng và cơ cấu kinh tế của khu vực.","Phân tích được đặc điểm của nông nghiệp, công nghiệp, dịch vụ ở Tây Nam Á."],"m":[{"t":"Phân tích một ngành kinh tế nổi bật của Tây Nam Á","w":"Đề yêu cầu trình bày đặc điểm nổi bật của một ngành kinh tế.","s":["Nêu vị trí của ngành trong GDP hoặc xuất khẩu.","Nêu sản phẩm, vùng/nước tiêu biểu.","Giải thích điều kiện thuận lợi và khó khăn (tự nhiên, chính trị).","Nêu xu hướng phát triển."],"n":["Với dầu khí, cần nói rõ vai trò trong xuất khẩu.","Nêu cả mặt hạn chế (phụ thuộc, biến động giá)."]}],"sum":["Năm 2020, GDP toàn khu vực Tây Nam Á đạt khoảng 3 184 tỉ USD, chiếm khoảng 3,7% GDP toàn cầu.","Khái niệm: Năm 2020, GDP toàn khu vực Tây Nam Á đạt khoảng 3 184 tỉ USD, chiếm khoảng 3,7% GDP toàn cầu.","Thế kỉ XX, nhiều nước chuyển từ…: Thế kỉ XX, nhiều nước chuyển từ nền kinh tế nông nghiệp và thủ công sang nền kinh tế dựa vào công nghiệp dầu khí.","Cơ cấu kinh tế: Nông nghiệp chiếm khoảng 10% GDP và 25% lực lượng lao động (2020), sản xuất khó khăn do khí hậu khô hạn, đất canh tác ít;","Nông nghiệp: Trồng cây lương thực (lúa gạo, lúa mì), cây công nghiệp (bông, thuốc lá, cà phê, ô-liu) và cây ăn quả; chăn nuôi chưa phát triển, chủ yếu chăn thả…","Công nghiệp: Khai thác và chế biến dầu khí là ngành then chốt, đóng góp lớn vào GDP nhiều quốc gia."],"e":["Lưu ý: Với dầu khí, cần nói rõ vai trò trong xuất khẩu.","Lưu ý: Nêu cả mặt hạn chế (phụ thuộc, biến động giá)."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Thực hành: Viết báo cáo về vấn đề dầu mỏ của khu vực Tây Nam Á","req":["Trình bày được đặc điểm tài nguyên dầu mỏ của khu vực Tây Nam Á.","Nêu được tình hình khai thác và xuất khẩu dầu mỏ của khu vực."],"m":[{"t":"Viết báo cáo về một tài nguyên","w":"Thực hành viết báo cáo có số liệu so sánh với thế giới.","s":["Nêu trữ lượng của khu vực và của thế giới, tính tỉ lệ.","Nêu phân bố tài nguyên theo quốc gia.","Nêu sản lượng khai thác và xuất khẩu.","Nhận xét vai trò của dầu mỏ đối với kinh tế và các vấn đề chính trị."],"n":["Ghi rõ năm và đơn vị (tỉ tấn, triệu tấn).","Tỉ lệ nên làm tròn một chữ số thập phân."]}],"sum":["Nội dung thực hành: viết báo cáo về đặc điểm tài nguyên dầu mỏ của Tây Nam Á và việc khai thác dầu mỏ của khu vực.","Nội dung thực hành: Viết báo cáo về đặc điểm tài nguyên dầu mỏ của Tây Nam Á và việc khai thác dầu mỏ của khu vực.","Cấu trúc gợi ý: Đặc điểm tài nguyên gồm trữ lượng và phân bố"],"e":["Hay nhầm: Là khai thác khu vực (không phải xuất khẩu).","Lưu ý: Ghi rõ năm và đơn vị (tỉ tấn, triệu tấn).","Lưu ý: Tỉ lệ nên làm tròn một chữ số thập phân."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 6. Hợp chúng quốc Hoa Kỳ","l":[{"t":"Bài 18. Vị trí địa lí, điều kiện tự nhiên và dân cư Hoa Kỳ","req":["Trình bày được đặc điểm vị trí địa lí, lãnh thổ và điều kiện tự nhiên, tài nguyên của Hoa Kỳ.","Trình bày được đặc điểm dân cư, đô thị hoá và tác động của chúng đến kinh tế – xã hội."],"m":[{"t":"Phân tích tác động của đặc điểm dân cư đến kinh tế","w":"Đề yêu cầu phân tích tác động của dân cư đối với một quốc gia.","s":["Nêu đặc điểm dân cư (quy mô, cơ cấu tuổi, nhập cư, phân bố, đô thị hoá).","Phân tích thuận lợi: lao động, thị trường tiêu thụ.","Phân tích khó khăn: già hoá, chi phí phúc lợi, phân bố không đều.","Kết luận."],"n":["Dẫn số liệu từ bảng và hình.","Gắn với các khu vực kinh tế đã học."]}],"sum":["Hoa Kỳ có diện tích khoảng 9,5 triệu km², gồm phần trung tâm Bắc Mỹ (khoảng 8 triệu km²), bán đảo A-la-xca và quần đảo Ha-oai.","Khái niệm: Hoa Kỳ có diện tích khoảng 9,5 triệu km², gồm phần trung tâm Bắc Mỹ (khoảng 8 triệu km²), bán đảo A-la-xca và quần đảo Ha-oai.","Địa hình phân hoá từ tây sang đông: Phía tây là hệ thống núi Coóc-đi-e với các dãy trẻ, cao như Rốc-ki và các bồn địa, cao nguyên; giữa là đồng bằng Trung tâm và đồng bằng Lớn có đất…","Khí hậu đa dạng: Phía bắc ôn đới (lục địa và hải dương), phía nam cận nhiệt;","Khoáng sản phong phú: Năng lượng (than đá, dầu mỏ, khí tự nhiên) tập trung ở phía đông bắc và ven vịnh Mê-hi-cô; kim loại đen (sắt, crôm) ở phía nam Ngũ Hồ; kim loại màu…","Dân cư: Năm 2020 Hoa Kỳ có 331,5 triệu người, đứng thứ ba thế giới."],"e":["Hay nhầm: A-pa-lát là dãy núi già ở phía đông.","Hay nhầm: Đó là mức trung bình thế giới.","Lưu ý: Dẫn số liệu từ bảng và hình.","Lưu ý: Gắn với các khu vực kinh tế đã học."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 19. Kinh tế Hoa Kỳ","req":["Trình bày được vị trí hàng đầu của kinh tế Hoa Kỳ và nguyên nhân.","Trình bày được sự phát triển của các ngành kinh tế (nông nghiệp, công nghiệp, dịch vụ) và sự phân hoá lãnh thổ kinh tế."],"m":[{"t":"Phân tích sự phát triển của một ngành kinh tế Hoa Kỳ","w":"Đề yêu cầu trình bày sự phát triển và phân bố của một ngành.","s":["Nêu vị trí của ngành trong GDP và lao động.","Nêu sản phẩm và số liệu minh hoạ.","Nêu phân bố theo khu vực kinh tế.","Giải thích nguyên nhân và xu hướng."],"n":["Giải thích dựa trên điều kiện tự nhiên và trình độ kĩ thuật.","So sánh số liệu theo năm."]}],"sum":["Từ cuối thế kỉ XIX, Hoa Kỳ vươn lên trở thành nền kinh tế đứng đầu thế giới. Năm 2020, GDP của Hoa Kỳ lớn nhất thế giới, chiếm 24,6% GDP toàn cầu;","Khái niệm: Từ cuối thế kỉ XIX, Hoa Kỳ vươn lên trở thành nền kinh tế đứng đầu thế giới.","Nguyên nhân: Vị trí địa lí thuận lợi cho giao lưu; tài nguyên thiên nhiên phong phú; nguồn lao động dồi dào, trình độ kĩ thuật và năng suất cao; tham gia toàn…","Cơ cấu kinh tế đa dạng, dịch…: Cơ cấu kinh tế đa dạng, dịch vụ chiếm tỉ trọng rất cao và tăng liên tục.","Nông nghiệp: Quy mô lớn, năng suất cao, sản xuất theo trang trại với máy móc hiện đại.","Công nghiệp: Là cường quốc công nghiệp, giá trị sản xuất đứng thứ hai thế giới với hơn 10% lực lượng lao động."],"e":["Hay nhầm: Không phải tỉ trọng lớn nhất.","Lưu ý: Giải thích dựa trên điều kiện tự nhiên và trình độ kĩ thuật.","Lưu ý: So sánh số liệu theo năm."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 7. Liên bang Nga","l":[{"t":"Bài 20. Vị trí địa lí, điều kiện tự nhiên, dân cư và xã hội Liên bang Nga","req":["Trình bày được vị trí địa lí, phạm vi lãnh thổ và ảnh hưởng đến phát triển kinh tế – xã hội của Liên bang Nga.","Trình bày được đặc điểm tự nhiên, tài nguyên, dân cư và xã hội của Liên bang Nga."],"m":[{"t":"Phân tích ảnh hưởng của dân cư đến phát triển kinh tế","w":"Đề yêu cầu phân tích tác động của đặc điểm dân cư.","s":["Nêu quy mô, cơ cấu tuổi và tỉ lệ tăng tự nhiên.","Nêu phân bố không đều và tác động đến khai thác tài nguyên.","Nêu thuận lợi (khoa học, lao động có trình độ) và khó khăn (thiếu lao động, già hoá).","Kết luận và đề xuất chính sách dân số."],"n":["Dẫn số liệu bảng 20.2.","Liên hệ đặc điểm phân bố với tài nguyên ở vùng ít dân."]}],"sum":["Liên bang Nga có diện tích khoảng 17 triệu km², là quốc gia rộng lớn nhất thế giới, nằm trên cả châu Âu và châu Á.","Khái niệm: Liên bang Nga có diện tích khoảng 17 triệu km², là quốc gia rộng lớn nhất thế giới, nằm trên cả châu Âu và châu Á.","Vị trí và lãnh thổ rộng lớn…: Vị trí và lãnh thổ rộng lớn tạo thuận lợi cho giao thương, phát triển kinh tế và văn hoá, nhưng cũng gây khó khăn trong khai thác lãnh thổ và bảo…","Địa hình cao ở phía đông, thấp ở phía tây: Phần phía tây có đồng bằng Đông Âu (màu mỡ, tập trung đông dân) và đồng bằng Tây Xi-bia (nhiều đầm lầy); dãy U-ran là ranh giới tự nhiên giữa châu…","Khí hậu chủ yếu là ôn đới, phân hoá theo lãnh thổ: Phía bắc cận cực khắc nghiệt, phía nam có ôn đới hải dương (phía tây), ôn đới lục địa (nội địa châu Á) và ôn đới gió mùa (ven Thái Bình Dương).","Rừng đứng đầu thế giới, chiếm khoảng…: Rừng đứng đầu thế giới, chiếm khoảng 20% diện tích rừng thế giới; rừng tai-ga (lá kim) chiếm khoảng 60% diện tích rừng cả nước."],"e":["Lưu ý: Dẫn số liệu bảng 20.2.","Lưu ý: Liên hệ đặc điểm phân bố với tài nguyên ở vùng ít dân."],"q":{"n":9,"lv":{"Biết":4,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 21. Kinh tế Liên bang Nga","req":["Trình bày được tình hình phát triển kinh tế, quy mô GDP và cơ cấu kinh tế của Liên bang Nga.","Phân tích được đặc điểm các ngành nông nghiệp, công nghiệp, dịch vụ và các vùng kinh tế."],"m":[{"t":"Phân tích đặc điểm một ngành kinh tế của Liên bang Nga","w":"Đề yêu cầu trình bày và giải thích đặc điểm một ngành.","s":["Nêu tỉ trọng ngành trong GDP và lao động.","Nêu sản phẩm nổi bật và số liệu minh hoạ.","Nêu phân bố và các trung tâm lớn.","Giải thích nguyên nhân và nhận xét xu hướng."],"n":["Dùng số liệu của bảng 21.1–21.3.","Gắn với điều kiện tự nhiên và tài nguyên."]}],"sum":["Năm 2020, GDP Liên bang Nga đạt khoảng 1,5 nghìn tỉ USD, chiếm khoảng 1,7% GDP toàn cầu. Tốc độ tăng trưởng GDP không ổn định (năm 2000 tăng 10,0%, năm 2020 giảm 3,0%).","Khái niệm: Năm 2020, GDP Liên bang Nga đạt khoảng 1,5 nghìn tỉ USD, chiếm khoảng 1,7% GDP toàn cầu.","Nông nghiệp, lâm nghiệp và thuỷ sản…: Nông nghiệp, lâm nghiệp và thuỷ sản đóng góp 4,0% GDP và thu hút khoảng 6% lao động (năm 2020).","Lâm nghiệp: Diện tích rừng lớn nhất thế giới, khoảng 815 triệu ha; sản lượng gỗ tròn tăng từ 158,1 triệu m³ (2000) lên 217,0 triệu m³ (2020), đứng thứ tư thế…","Công nghiệp và xây dựng chiếm 30%…: Công nghiệp và xây dựng chiếm 30% GDP và thu hút khoảng 27% lao động (2020); công nghiệp giữ vai trò chủ đạo với năng lượng, chế tạo và luyện kim.","Dịch vụ chiếm 56,3% GDP và thu hút 67,3% lao động (2020): Đa dạng và hiện đại hoá."],"e":["Lưu ý: Dùng số liệu của bảng 21.1–21.3.","Lưu ý: Gắn với điều kiện tự nhiên và tài nguyên."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Thực hành: Tìm hiểu về công nghiệp khai thác dầu khí của Liên bang Nga","req":["Vẽ được biểu đồ thể hiện sản lượng khai thác dầu mỏ và khí tự nhiên của Liên bang Nga giai đoạn 2000–2020.","Nhận xét được về sự phát triển của công nghiệp khai thác dầu khí."],"m":[{"t":"Vẽ và nhận xét biểu đồ cột về khai thác khoáng sản","w":"Thực hành vẽ biểu đồ và nhận xét xu hướng.","s":["Chọn biểu đồ cột (hoặc đường) cho chuỗi số liệu theo năm.","Ghi đơn vị, tên biểu đồ, chú giải.","Nhận xét xu hướng tăng, giảm và mức chênh lệch.","Giải thích nguyên nhân (đầu tư, khai thác ở Tây Xi-bia, nhu cầu thị trường)."],"n":["Ghi đơn vị đúng (triệu tấn, tỉ m³).","Nhận xét cần có số liệu cụ thể."]}],"sum":["Nội dung thực hành: vẽ biểu đồ thể hiện sản lượng khai thác dầu mỏ và khí tự nhiên của Liên bang Nga giai đoạn 2000–2020, sau đó nhận xét về sự phát triển của công nghiệp khai thác dầu khí.","Nội dung thực hành: Vẽ biểu đồ thể hiện sản lượng khai thác dầu mỏ và khí tự nhiên của Liên bang Nga giai đoạn 2000–2020, sau đó nhận xét về sự phát triển của công…","Bảng 22.1 cho biết sản lượng khai…: Bảng 22.1 cho biết sản lượng khai thác dầu mỏ (triệu tấn) và khí tự nhiên (tỉ m³) qua các mốc năm."],"e":["Lưu ý: Ghi đơn vị đúng (triệu tấn, tỉ m³).","Lưu ý: Nhận xét cần có số liệu cụ thể."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 8. Nhật Bản","l":[{"t":"Bài 23. Vị trí địa lí, điều kiện tự nhiên, dân cư và xã hội Nhật Bản","req":["Trình bày được vị trí địa lí và ảnh hưởng của vị trí đến phát triển kinh tế – xã hội Nhật Bản.","Trình bày được đặc điểm tự nhiên, tài nguyên, dân cư và xã hội của Nhật Bản."],"m":[{"t":"Phân tích ảnh hưởng của vị trí và điều kiện tự nhiên đến phát triển kinh tế","w":"Đề yêu cầu phân tích ảnh hưởng của vị trí địa lí và điều kiện tự nhiên.","s":["Nêu vị trí và đặc điểm địa hình, khoáng sản.","Phân tích thuận lợi: giao thương, cảng biển, ngư trường.","Phân tích khó khăn: thiên tai, nghèo khoáng sản.","Kết luận về biện pháp khắc phục (nhập khẩu, công nghệ, kinh tế biển)."],"n":["Dẫn số liệu về khoáng sản và thiên tai.","Liên hệ với ngành công nghiệp và thương mại."]}],"sum":["Nhật Bản là quốc gia quần đảo ở phía đông bắc châu Á, gồm hàng nghìn đảo; bốn đảo lớn là Hô-cai-đô, Hôn-su, Xi-cô-cư và Kiu-xiu.","Khái niệm: Nhật Bản là quốc gia quần đảo ở phía đông bắc châu Á, gồm hàng nghìn đảo; bốn đảo lớn là Hô-cai-đô, Hôn-su, Xi-cô-cư và Kiu-xiu.","Vị trí thuận lợi cho giao thương…: Vị trí thuận lợi cho giao thương quốc tế, nằm trong khu vực kinh tế năng động châu Á – Thái Bình Dương và có nhiều điều kiện xây dựng cảng, phát…","Điều kiện tự nhiên và tài nguyên không thực sự thuận lợi: Đồi núi chiếm khoảng 4/5 diện tích, đồng bằng nhỏ hẹp ven biển; khoáng sản nghèo nên phải nhập khẩu phần lớn.","Dân cư: Năm 2020 có 126,2 triệu người, đứng thứ 11 thế giới; tỉ lệ tăng dân số dưới 0% từ 2008 (năm 2020 là −0,3%).","Dân cư phân bố không đều: Mật độ trung bình khoảng 338 người/km²; khoảng 60% dân cư sống trên 3% diện tích, chủ yếu ở đồng bằng ven biển (dải ven Thái Bình Dương trên Hôn-su)."],"e":["Lưu ý: Dẫn số liệu về khoáng sản và thiên tai.","Lưu ý: Liên hệ với ngành công nghiệp và thương mại."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 24. Kinh tế Nhật Bản","req":["Trình bày được quá trình phát triển kinh tế và vị thế của Nhật Bản trong kinh tế thế giới.","Trình bày được sự phát triển và phân bố của các ngành nông nghiệp, công nghiệp, dịch vụ và các vùng kinh tế."],"m":[{"t":"Trình bày và giải thích tình hình phát triển kinh tế Nhật Bản","w":"Đề yêu cầu trình bày và giải thích các giai đoạn phát triển.","s":["Nêu các giai đoạn và tốc độ tăng trưởng.","Giải thích nguyên nhân thăng trầm (khủng hoảng năng lượng, bong bóng kinh tế, khủng hoảng 2008).","Nêu thách thức hiện nay.","Kết luận về hướng phát triển kinh tế số."],"n":["Dẫn số liệu bảng 24.1 khi có thể.","Phân biệt các giai đoạn tăng trưởng cao và trì trệ."]}],"sum":["Thế kỉ XX chứng kiến sự phát triển thần kì của kinh tế Nhật Bản. Giai đoạn 1955–1972, tốc độ tăng GDP bình quân khoảng 10%/năm; từ năm 1968 kinh tế Nhật Bản vươn lên đứng thứ hai thế giới, sau Hoa Kỳ.","Khái niệm: Thế kỉ XX chứng kiến sự phát triển thần kì của kinh tế Nhật Bản.","Trong cơ cấu GDP, dịch vụ chiếm…: Trong cơ cấu GDP, dịch vụ chiếm tỉ trọng cao nhất (khoảng 70%), nông nghiệp nhỏ nhất (khoảng 1%)."],"e":["Lưu ý: Dẫn số liệu bảng 24.1 khi có thể.","Lưu ý: Phân biệt các giai đoạn tăng trưởng cao và trì trệ."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Thực hành: Viết báo cáo về hoạt động kinh tế đối ngoại của Nhật Bản","req":["Viết được báo cáo về hoạt động kinh tế đối ngoại của Nhật Bản theo gợi ý cấu trúc.","Phân tích được số liệu về đầu tư trực tiếp nước ngoài và thương mại của Nhật Bản."],"m":[{"t":"Viết báo cáo về kinh tế đối ngoại của Nhật Bản","w":"Đề yêu cầu viết báo cáo theo cấu trúc gợi ý.","s":["Mở đầu: khái quát vai trò kinh tế đối ngoại.","Xuất nhập khẩu: trị giá, mặt hàng và đối tác.","Đầu tư trực tiếp nước ngoài: giá trị, nước nhận đầu tư.","Kết luận: ý nghĩa và xu hướng."],"n":["Dùng số liệu bảng 25.1 và 25.2.","Ghi rõ nguồn số liệu."]}],"sum":["Nội dung thực hành: viết báo cáo về hoạt động kinh tế đối ngoại của Nhật Bản. Cấu trúc gợi ý gồm: khái quát về hoạt động kinh tế đối ngoại; xuất nhập khẩu (hiện trạng và ý nghĩa);","Nội dung thực hành: Viết báo cáo về hoạt động kinh tế đối ngoại của Nhật Bản.","Nhật Bản là cường quốc thương mại: Khoảng 55% trị giá thương mại với các nước phát triển (nhiều nhất là Hoa Kỳ và EU), khoảng 45% với các nước đang phát triển, đặc biệt là châu Á.","Nhật Bản là quốc gia có giá…: Nhật Bản là quốc gia có giá trị đầu tư ra bên ngoài rất lớn; chi phí nhân công thấp ở nước nhận đầu tư là một nguyên nhân chính."],"e":["Hay nhầm: Đó là tỉ trọng với nước đang phát triển.","Hay nhầm: Đó là tỉ trọng với nước phát triển.","Hay nhầm: Đó là tỉ trọng với nước đang phát triển.","Lưu ý: Dùng số liệu bảng 25.1 và 25.2.","Lưu ý: Ghi rõ nguồn số liệu."],"q":{"n":7,"lv":{"Biết":3,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 9. Trung Quốc","l":[{"t":"Bài 26. Vị trí địa lí, điều kiện tự nhiên, dân cư và xã hội Trung Quốc","req":["Trình bày được vị trí địa lí, điều kiện tự nhiên, tài nguyên thiên nhiên của Trung Quốc.","Trình bày được đặc điểm dân cư, xã hội và ảnh hưởng đến phát triển kinh tế – xã hội."],"m":[{"t":"Phân tích ảnh hưởng của dân cư đến phát triển kinh tế – xã hội","w":"Đề yêu cầu nêu đặc điểm và phân tích tác động của một đặc điểm dân cư.","s":["Nêu quy mô dân số, cơ cấu tuổi và phân bố.","Phân tích thuận lợi: thị trường lớn, nguồn lao động dồi dào.","Phân tích khó khăn: già hoá, chênh lệch vùng miền.","Kết luận và giải pháp."],"n":["Dẫn số liệu bảng 26.1 và hình 26.4.","Liên hệ với thị trường tiêu thụ và đô thị hoá."]}],"sum":["Trung Quốc nằm ở Đông Á, có diện tích khoảng 9,6 triệu km². Phần đất liền trải dài từ khoảng 20°B đến 53°B và từ 73°Đ đến 135°Đ.","Trung Quốc nằm ở Đông Á, có diện tích khoảng 9,6 triệu km²: Phần đất liền trải dài từ khoảng 20°B đến 53°B và từ 73°Đ đến 135°Đ.","Lãnh thổ rộng lớn, thiên nhiên phân…: Lãnh thổ rộng lớn, thiên nhiên phân hoá giữa các vùng, tài nguyên phong phú tạo điều kiện phát triển nền kinh tế đa dạng.","Địa hình thấp dần từ tây sang…: Địa hình thấp dần từ tây sang đông, ranh giới giữa miền Đông và miền Tây là kinh tuyến 105°Đ.","Khí hậu: Miền Đông gió mùa, mưa nhiều vào mùa hạ, dễ gây lũ lụt ở hạ lưu sông; miền Tây ôn đới lục địa khắc nghiệt, lượng mưa trung bình khoảng 250 mm, hình…","Khoáng sản phong phú với gần 150 loại: Than đá có trữ lượng hơn 143 tỉ tấn;"],"e":["Lưu ý: Dẫn số liệu bảng 26.1 và hình 26.4.","Lưu ý: Liên hệ với thị trường tiêu thụ và đô thị hoá."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 27. Kinh tế Trung Quốc","req":["Trình bày được thành tựu và vị thế của nền kinh tế Trung Quốc trên thế giới.","Trình bày được sự phát triển và phân bố của các ngành nông nghiệp, công nghiệp, dịch vụ và nguyên nhân phát triển."],"m":[{"t":"Trình bày sự phát triển của một ngành dịch vụ ở Trung Quốc","w":"Đề yêu cầu trình bày sự phát triển của thương mại, giao thông, du lịch hoặc tài chính.","s":["Nêu vị trí của ngành trong GDP và lao động.","Nêu số liệu minh hoạ (doanh thu, khách, hạ tầng).","Nêu phân bố và các trung tâm lớn.","Giải thích nguyên nhân và xu hướng."],"n":["Dẫn số liệu từ mục 3 và bảng 27.4.","Gắn với chính sách mở cửa và đô thị hoá."]}],"sum":["Từ năm 1978, Trung Quốc cải cách từ nền kinh tế kế hoạch hoá tập trung sang nền kinh tế theo định hướng thị trường và đạt nhiều thành tựu.","Khái niệm: Từ năm 1978, Trung Quốc cải cách từ nền kinh tế kế hoạch hoá tập trung sang nền kinh tế theo định hướng thị trường và đạt nhiều thành tựu.","Tốc độ tăng GDP tuy biến động nhưng luôn ở mức cao: Cơ cấu GDP chuyển dịch theo hướng công nghiệp hoá, hiện đại hoá: tỉ trọng công nghiệp – xây dựng và dịch vụ tăng, tỉ trọng nông nghiệp giảm.","Nguyên nhân: Nguồn lực tự nhiên đa dạng; nguồn lao động dồi dào, trình độ ngày càng cao, tiếp nhận công nghệ mới; cơ sở hạ tầng phát triển và thị trường rộng…","Nông nghiệp, lâm nghiệp và thuỷ sản…: Nông nghiệp, lâm nghiệp và thuỷ sản đóng góp 7,7% GDP và thu hút khoảng 22% lao động (2020).","Công nghiệp: Công nghiệp và xây dựng đóng góp 37,8% GDP (2020)."],"e":["Lưu ý: Dẫn số liệu từ mục 3 và bảng 27.4.","Lưu ý: Gắn với chính sách mở cửa và đô thị hoá."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Thực hành: Viết báo cáo về sự thay đổi của kinh tế vùng duyên hải Trung Quốc","req":["Viết được báo cáo về sự phát triển kinh tế của vùng duyên hải Trung Quốc theo gợi ý.","Sử dụng được số liệu về GDP và xuất nhập khẩu để nhận xét sự thay đổi của vùng."],"m":[{"t":"Viết báo cáo về sự thay đổi của kinh tế vùng duyên hải","w":"Đề yêu cầu viết báo cáo theo cấu trúc gợi ý.","s":["Giới thiệu vùng duyên hải và các tỉnh, thành chính.","Nêu thay đổi về GDP (dẫn số liệu năm, tỉ trọng).","Nêu thay đổi về xuất nhập khẩu và thu hút FDI.","Nêu vai trò của vùng đối với cả nước, kết luận."],"n":["Ghi rõ nguồn số liệu.","So sánh với miền Tây để thấy vai trò động lực."]}],"sum":["Nội dung thực hành: viết báo cáo về sự phát triển kinh tế tại vùng duyên hải Trung Quốc. Tư liệu gồm thông tin trên internet, sách, báo, tạp chí.","Nội dung thực hành: Viết báo cáo về sự phát triển kinh tế tại vùng duyên hải Trung Quốc. Tư liệu gồm thông tin trên internet, sách, báo, tạp chí. Cấu trúc gợi ý:","Vùng duyên hải gồm các tỉnh, thành phố giáp biển ở phía đông: Liêu Ninh, Thiên Tân, Hà Bắc, Sơn Đông, Giang Tô, Thượng Hải, Chiết Giang, Phúc Kiến, Quảng Đông, Quảng Tây, Hải Nam."],"e":["Hay nhầm: Đó là tỉ trọng GDP của Trung Quốc so với thế giới.","Lưu ý: Ghi rõ nguồn số liệu.","Lưu ý: So sánh với miền Tây để thấy vai trò động lực."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 11. Cộng hoà Nam Phi","l":[{"t":"Bài 30. Vị trí địa lí, điều kiện tự nhiên, dân cư và xã hội Cộng hoà Nam Phi","req":["Trình bày được vị trí địa lí, ảnh hưởng của vị trí đến phát triển kinh tế – xã hội của Cộng hoà Nam Phi.","Trình bày được đặc điểm tự nhiên, tài nguyên, dân cư và xã hội của Cộng hoà Nam Phi."],"m":[{"t":"Phân tích tác động của đặc điểm dân cư đến phát triển kinh tế – xã hội","w":"Đề yêu cầu phân tích thuận lợi và khó khăn của dân cư.","s":["Nêu quy mô, tăng trưởng và cơ cấu tuổi (bảng 30.2).","Nêu phân bố không đều và đô thị hoá nhanh.","Phân tích thuận lợi: thị trường, lao động.","Phân tích khó khăn: thất nghiệp, nhà ở, giàu nghèo."],"n":["Dẫn số liệu từ bảng 30.2.","Liên hệ với vấn đề việc làm."]}],"sum":["Cộng hoà Nam Phi nằm hoàn toàn ở bán cầu Nam, là vùng đất cuối cùng ở phía nam châu Phi, có diện tích khoảng 1,2 triệu km².","Khái niệm: Cộng hoà Nam Phi nằm hoàn toàn ở bán cầu Nam, là vùng đất cuối cùng ở phía nam châu Phi, có diện tích khoảng 1,2 triệu km².","Nam Phi án ngữ con đường biển…: Nam Phi án ngữ con đường biển quan trọng giữa Đại Tây Dương và Ấn Độ Dương, thuận lợi phát triển kinh tế biển và giao lưu kinh tế – xã hội với thế…","Địa hình chủ yếu là cao nguyên…: Địa hình chủ yếu là cao nguyên cao khoảng 2 000 m, chia thành ba khu vực: cao nguyên nội địa tương đối bằng phẳng; dãy Đrê-ken-béc dài hơn 1 000 km;…","Sông ngắn và dốc, mùa lũ trùng…: Sông ngắn và dốc, mùa lũ trùng mùa mưa; sông có giá trị thuỷ điện nhưng ít giá trị giao thông.","Dân cư: Năm 2020 có 59,3 triệu người, là một trong sáu quốc gia đông dân nhất châu Phi; tỉ lệ tăng tự nhiên giảm từ 1,6% (2010) xuống 1,2% (2020)."],"e":["Lưu ý: Dẫn số liệu từ bảng 30.2.","Lưu ý: Liên hệ với vấn đề việc làm."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 31. Kinh tế Cộng hoà Nam Phi","req":["Trình bày được đặc điểm nổi bật của nền kinh tế Nam Phi và vị thế trong châu Phi.","Trình bày được đặc điểm các ngành nông nghiệp, công nghiệp, dịch vụ của Nam Phi."],"m":[{"t":"Trình bày đặc điểm một ngành kinh tế của Cộng hoà Nam Phi","w":"Đề yêu cầu trình bày và giải thích đặc điểm một ngành.","s":["Nêu tỉ trọng ngành trong GDP và lao động.","Nêu sản phẩm và số liệu minh hoạ.","Nêu phân bố và trung tâm lớn.","Giải thích nguyên nhân và thách thức."],"n":["Dùng bảng 31.1–31.4.","Gắn với điều kiện tự nhiên và tài nguyên."]}],"sum":["Nam Phi là một trong những quốc gia phát triển nhất châu Phi, là một trong ba nền kinh tế lớn nhất châu Phi (cùng Ni-giê-ri-a và Ai Cập) và là quốc gia duy nhất ở châu Phi thuộc G20 (năm 2020).","Khái niệm: Nam Phi là một trong những quốc gia phát triển nhất châu Phi, là một trong ba nền kinh tế lớn nhất châu Phi (cùng Ni-giê-ri-a và Ai Cập) và là quốc…","Cơ cấu GDP chuyển dịch: Dịch vụ tăng từ 61,2% (2000) lên 64,6% (2020), công nghiệp và xây dựng giảm từ 28,2% xuống 23,4%; nông, lâm, thuỷ sản chỉ chiếm 2,5%.","Nông nghiệp đóng góp 2,5% GDP nhưng…: Nông nghiệp đóng góp 2,5% GDP nhưng quan trọng vì tạo việc làm ở nông thôn, xuất khẩu nông sản và bảo đảm an ninh lương thực.","Lâm nghiệp đóng góp 0,6% GDP, cung…: Lâm nghiệp đóng góp 0,6% GDP, cung cấp nguyên liệu cho sản xuất giấy, bột giấy; rừng trồng có thể cung cấp 15–18 triệu m³ gỗ mỗi năm.","Công nghiệp chiếm 23,4% GDP và khoảng 25% lao động (2020): Công nghiệp khai thác khoáng sản là ngành mũi nhọn, tạo việc làm cho 451,4 nghìn người và thu ngoại tệ;"],"e":["Hay nhầm: Đó là diện tích trồng trọt.","Lưu ý: Dùng bảng 31.1–31.4.","Lưu ý: Gắn với điều kiện tự nhiên và tài nguyên."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Phần một. Một số vấn đề kinh tế - xã hội thế giới","l":[{"t":"Bài tập nâng cao · Phần một. Một số vấn đề kinh tế - xã hội thế giới (8 câu)","e":["Hay nhầm: Không phải ý nghĩa duy nhất."],"q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương 2. Khu vực Mỹ La-tinh","l":[{"t":"Bài tập nâng cao · Chương 2. Khu vực Mỹ La-tinh (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 3. Liên minh châu Âu và Cộng hoà Liên bang Đức","l":[{"t":"Bài tập nâng cao · Chương 3. Liên minh châu Âu và Cộng hoà Liên bang Đức (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chương 4. Khu vực Đông Nam Á","l":[{"t":"Bài tập nâng cao · Chương 4. Khu vực Đông Nam Á (8 câu)","q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương 5. Khu vực Tây Nam Á","l":[{"t":"Bài tập nâng cao · Chương 5. Khu vực Tây Nam Á (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 6. Hợp chúng quốc Hoa Kỳ","l":[{"t":"Bài tập nâng cao · Chương 6. Hợp chúng quốc Hoa Kỳ (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chương 7. Liên bang Nga","l":[{"t":"Bài tập nâng cao · Chương 7. Liên bang Nga (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 8. Nhật Bản","l":[{"t":"Bài tập nâng cao · Chương 8. Nhật Bản (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 9. Trung Quốc","l":[{"t":"Bài tập nâng cao · Chương 9. Trung Quốc (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 11. Cộng hoà Nam Phi","l":[{"t":"Bài tập nâng cao · Chương 11. Cộng hoà Nam Phi (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]}]}]},{"id":"gdktpl","name":"Giáo dục kinh tế và pháp luật","b":[{"t":"Giáo dục kinh tế và pháp luật 11","c":[{"t":"Chủ đề 1. Cạnh tranh, cung – cầu trong nền kinh tế thị trường","l":[{"t":"Bài 1. Cạnh tranh trong nền kinh tế thị trường","req":["Nêu được khái niệm cạnh tranh.","Giải thích được nguyên nhân dẫn đến cạnh tranh.","Phân tích được vai trò của cạnh tranh trong nền kinh tế."],"m":[{"t":"Nhận diện cạnh tranh lành mạnh và không lành mạnh","w":"Khi phải đánh giá một hành vi trên thị trường.","s":["Xem hành vi có dựa trên chất lượng, giá cả, dịch vụ hợp pháp hay không.","Kiểm tra có vi phạm pháp luật, nguyên tắc thiện chí, trung thực, tập quán thương mại không.","Kiểm tra có gây nhầm lẫn, gièm pha đối thủ, xâm phạm bí mật kinh doanh không.","Kết luận: nếu có, đó là cạnh tranh không lành mạnh cần phê phán và ngăn chặn."],"n":["Cạnh tranh không lành mạnh có thể gây thiệt hại cho doanh nghiệp khác, người tiêu dùng và môi trường kinh doanh.","Cạnh tranh lành mạnh tuân theo pháp luật và tạo lợi ích cho cả doanh nghiệp lẫn người tiêu dùng."]}],"sum":["Trong nền kinh tế thị trường, các chủ thể kinh tế được tự do sản xuất, kinh doanh và mua bán hàng hoá nên phải cạnh tranh với nhau để tồn tại và phát triển.","Khái niệm: Trong nền kinh tế thị trường, các chủ thể kinh tế được tự do sản xuất, kinh doanh và mua bán hàng hoá nên phải cạnh tranh với nhau để tồn tại và…","Khái niệm: Cạnh tranh kinh tế là sự tranh đua giữa các chủ thể kinh tế nhằm giành những ưu thế trong sản xuất, tiêu thụ hàng hoá, qua đó thu lợi ích tối đa.","Nguyên nhân: Có nhiều chủ sở hữu là các đơn vị kinh tế độc lập, tự do sản xuất kinh doanh, với điều kiện sản xuất và lợi ích khác nhau nên phải tìm lợi thế để có…","Vai trò tích cực của cạnh tranh: Tạo động lực phát triển cho doanh nghiệp và toàn bộ nền kinh tế."],"e":["Hay nhầm: Hợp tác không phải là cạnh tranh.","Hay nhầm: Đó là phân phối theo kế hoạch.","Hay nhầm: Đó là hoạt động mua bán, không phải cạnh tranh.","Hay nhầm: Khi chỉ có một chủ thể thì không có cạnh tranh.","Hay nhầm: Cấm kinh doanh sẽ làm mất cạnh tranh.","Hay nhầm: Không có nhu cầu thì không có thị trường để cạnh tranh."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 2. Cung – cầu trong nền kinh tế thị trường","req":["Nêu được khái niệm cung, cầu và các nhân tố ảnh hưởng đến cung, cầu.","Phân tích được mối quan hệ và vai trò của quan hệ cung – cầu trong nền kinh tế thị trường.","Phân tích được quan hệ cung – cầu trong hoạt động sản xuất kinh doanh cụ thể."],"m":[{"t":"Phân tích quan hệ cung – cầu của một hàng hoá","w":"Khi cần giải thích vì sao giá một hàng hoá thay đổi.","s":["Xác định lượng cung và lượng cầu của hàng hoá trên thị trường.","So sánh cung và cầu: bằng, lớn hơn hay nhỏ hơn.","Dự đoán xu hướng giá: ổn định, giảm hoặc tăng.","Nêu tác động đến nhà sản xuất và người tiêu dùng."],"n":["Cần nêu nguyên nhân làm thay đổi cung hoặc cầu (giá đầu vào, thu nhập, thị hiếu, hàng thay thế).","Phân biệt sự thay đổi của lượng cầu do giá với sự thay đổi của cầu do các yếu tố khác."]}],"sum":["Trên thị trường, lượng hàng hoá đưa ra bán không phải lúc nào cũng cân đối với nhu cầu mua sắm của người tiêu dùng.","Khái niệm: Trên thị trường, lượng hàng hoá đưa ra bán không phải lúc nào cũng cân đối với nhu cầu mua sắm của người tiêu dùng.","Cung là số lượng hàng hoá, dịch…: Cung là số lượng hàng hoá, dịch vụ mà nhà cung cấp sẵn sàng đáp ứng cho thị trường với mức giá xác định trong một khoảng thời gian nhất định.","Cầu là số lượng hàng hoá, dịch…: Cầu là số lượng hàng hoá, dịch vụ mà người tiêu dùng sẵn sàng mua với một mức giá nhất định trong một khoảng thời gian xác định.","Mối quan hệ cung – cầu: Hai yếu tố tác động và quy định lẫn nhau.","Khi cung bằng cầu, giá ổn định: Khi cung lớn hơn cầu, giá có xu hướng giảm; khi cung nhỏ hơn cầu, giá có xu hướng tăng."],"e":["Hay nhầm: Đó là chi tiêu, không phải cung.","Hay nhầm: Đó là yếu tố ảnh hưởng đến cầu, không phải cung.","Hay nhầm: Đó là tồn kho, không phải cầu.","Hay nhầm: Đó là giá, không phải cầu.","Hay nhầm: Đó là kết quả kinh doanh.","Hay nhầm: Giá đầu vào tăng làm giảm cung."],"q":{"n":8,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":3}}}]},{"t":"Chủ đề 2. Lạm phát, thất nghiệp","l":[{"t":"Bài 3. Lạm phát","req":["Nêu được khái niệm lạm phát và liệt kê được các loại hình lạm phát.","Giải thích được nguyên nhân dẫn đến lạm phát.","Mô tả được hậu quả của lạm phát đối với nền kinh tế và xã hội."],"m":[{"t":"Phân tích nguyên nhân lạm phát từ một tình huống","w":"Khi giá nhiều mặt hàng cùng tăng và cần xác định nguyên nhân.","s":["Xác định mức giá chung hay chỉ một vài hàng hoá tăng.","Đo mức tăng bằng CPI và tính tỉ lệ lạm phát.","Kiểm tra các nguyên nhân: chi phí đầu vào, cầu tăng, phát hành thừa tiền.","Nêu hậu quả và vai trò điều hành của Nhà nước."],"n":["Tăng giá một vài hàng hoá chưa chắc là lạm phát; lạm phát là mức giá chung tăng liên tục.","Cần so sánh CPI giữa hai kì để tính tỉ lệ lạm phát đúng công thức."]}],"sum":["Lạm phát là hiện tượng mức giá chung của các hàng hoá, dịch vụ trong nền kinh tế tăng lên liên tục trong một thời gian nhất định.","Khái niệm: Lạm phát là hiện tượng mức giá chung của các hàng hoá, dịch vụ trong nền kinh tế tăng lên liên tục trong một thời gian nhất định.","Tỉ lệ lạm phát được tính bằng: (CPI của thời điểm sau − CPI của thời điểm trước) ÷ CPI của thời điểm trước × 100%.","Theo mức độ, lạm phát chia thành ba loại: Lạm phát vừa phải, mức tăng giá dưới 10% mỗi năm, nền kinh tế được coi là ổn định","Nguyên nhân chủ yếu: Chi phí sản xuất tăng cao khi giá các yếu tố đầu vào như xăng, dầu, điện, nguyên liệu tăng","Hậu quả: Lạm phát cao làm tăng chi phí sản xuất, thu hẹp đầu tư, kinh tế suy thoái và thất nghiệp gia tăng; hàng hoá bị đầu cơ, tích trữ gây khan hiếm và…"],"e":["Hay nhầm: Tăng giá một mặt hàng không phải lạm phát.","Hay nhầm: GDP không đo giá tiêu dùng.","Hay nhầm: Thất nghiệp là chỉ tiêu khác.","Hay nhầm: Dân số không phải chỉ số giá.","Hay nhầm: Chi tiêu giảm có tác dụng kiềm chế lạm phát.","Hay nhầm: Năng suất tăng làm giá giảm."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 4. Thất nghiệp","req":["Nêu được khái niệm thất nghiệp và liệt kê được các loại hình thất nghiệp.","Giải thích được nguyên nhân dẫn đến thất nghiệp.","Mô tả được hậu quả của thất nghiệp đối với nền kinh tế và xã hội."],"m":[{"t":"Xác định loại thất nghiệp từ tình huống","w":"Khi cần phân biệt thất nghiệp tự nguyện và không tự nguyện, hoặc theo nguồn gốc.","s":["Xác định người lao động có muốn làm việc hay không.","Nếu muốn làm nhưng không tìm được việc: thất nghiệp không tự nguyện.","Xác định nguyên nhân: thay đổi công nghệ (cơ cấu), suy thoái (chu kì), chuyển công việc (tạm thời).","Nêu hướng giải quyết của Nhà nước và cá nhân."],"n":["Người lao động chuyển sang việc khác để có việc tốt hơn vẫn có thể tạm thời thất nghiệp.","Cần phân biệt thất nghiệp tạm thời với thất nghiệp kéo dài vì nguyên nhân và cách giải quyết khác nhau."]}],"sum":["Thất nghiệp là hiện tượng tất yếu trong nền kinh tế thị trường, ảnh hưởng trực tiếp đến chính trị, kinh tế và xã hội.","Khái niệm: Thất nghiệp là hiện tượng tất yếu trong nền kinh tế thị trường, ảnh hưởng trực tiếp đến chính trị, kinh tế và xã hội.","Theo nguồn gốc, thất nghiệp gồm: Thất nghiệp tự nhiên, mức thất nghiệp bình thường luôn tồn tại trong xã hội, bao gồm thất nghiệp tạm thời (do người lao động dịch chuyển giữa các…","Theo tính chất, thất nghiệp gồm: Thất nghiệp tự nguyện, xảy ra khi người lao động không muốn làm việc vì điều kiện làm việc và mức lương chưa phù hợp; và thất nghiệp không tự…","Nguyên nhân: Chủ quan, như bị đuổi việc vì vi phạm kỉ luật, tự thôi việc vì không hài lòng, thiếu kĩ năng làm việc","Hậu quả: Đối với người thất nghiệp, thu nhập giảm, đời sống khó khăn, kiến thức nghề nghiệp bị mai một;"],"e":["Hay nhầm: Đó là thất nghiệp tự nguyện, không phải định nghĩa chung.","Hay nhầm: Nghỉ hưu không thuộc thất nghiệp.","Hay nhầm: Khi phát triển thì thất nghiệp chu kì thấp.","Hay nhầm: Đó là thất nghiệp cơ cấu.","Hay nhầm: Đó là thất nghiệp tạm thời.","Hay nhầm: Đó là thất nghiệp tạm thời."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chủ đề 3. Thị trường lao động và việc làm","l":[{"t":"Bài 5. Thị trường lao động và việc làm","req":["Nêu được các khái niệm: lao động, việc làm, thị trường lao động, thị trường việc làm.","Chỉ ra được mối quan hệ giữa thị trường lao động và thị trường việc làm.","Nhận ra được xu hướng tuyển dụng lao động của thị trường."],"m":[{"t":"Chọn nghề nghiệp, việc làm phù hợp","w":"Khi định hướng nghề nghiệp sau trung học phổ thông.","s":["Tìm hiểu xu hướng tuyển dụng và các nhóm ngành, nghề có nhu cầu lớn.","Tự đánh giá sở trường, nguyện vọng và điều kiện bản thân.","Trang bị kiến thức nghề, rèn kĩ năng mềm, ngoại ngữ, công nghệ thông tin.","Lựa chọn nghề phù hợp và kiểm tra lại theo thời gian."],"n":["Chủ động học tập và rèn luyện là trách nhiệm của mỗi người khi tham gia thị trường lao động.","Chọn nghề cần dựa trên xu hướng thị trường và năng lực bản thân, không chỉ theo ý kiến người khác."]}],"sum":["Lao động và việc làm là nhu cầu cơ bản của con người, tạo ra của cải vật chất và giúp mỗi người phát triển toàn diện.","Khái niệm: Lao động và việc làm là nhu cầu cơ bản của con người, tạo ra của cải vật chất và giúp mỗi người phát triển toàn diện.","Lao động là hoạt động có mục…: Lao động là hoạt động có mục đích, có ý thức của con người nhằm tạo ra sản phẩm phục vụ nhu cầu đời sống xã hội.","Thị trường lao động là nơi thực…: Thị trường lao động là nơi thực hiện quan hệ giữa người bán sức lao động (người lao động làm thuê) và người mua sức lao động (người sử dụng lao…","Việc làm là hoạt động lao động…: Việc làm là hoạt động lao động tạo ra thu nhập và không bị pháp luật cấm.","Mối quan hệ: Thị trường việc làm là cầu nối, giúp người lao động tìm được chỗ làm phù hợp và người sử dụng lao động tìm được người thích hợp, từ đó thị trường…"],"e":["Hay nhầm: Đó là thị trường hàng hoá.","Hay nhầm: Đó là thị trường tín dụng.","Hay nhầm: Đó là thị trường tiền tệ.","Hay nhầm: Hoạt động không thu nhập không phải việc làm.","Hay nhầm: Việc làm không chỉ ở cơ quan nhà nước.","Hay nhầm: Học tập không phải việc làm."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chủ đề 4. Ý tưởng, cơ hội kinh doanh và các năng lực cần thiết của người kinh doanh","l":[{"t":"Bài 6. Ý tưởng, cơ hội kinh doanh và các năng lực cần thiết của người kinh doanh","req":["Nêu được thế nào là ý tưởng kinh doanh và cơ hội kinh doanh.","Giải thích được tầm quan trọng của việc xây dựng ý tưởng kinh doanh và xác định, đánh giá cơ hội kinh doanh.","Nhận biết được các nguồn giúp tạo ý tưởng kinh doanh."],"m":[{"t":"Đánh giá một cơ hội kinh doanh bằng phân tích SWOT","w":"Trước khi quyết định triển khai một ý tưởng kinh doanh.","s":["Liệt kê điểm mạnh (nguồn lực, kinh nghiệm, lợi thế riêng).","Liệt kê điểm yếu (vốn, kĩ năng, hạn chế của bản thân hoặc sản phẩm).","Liệt kê cơ hội (nhu cầu thị trường, chính sách, xu hướng).","Liệt kê thách thức (đối thủ, rủi ro, biến động thị trường) và đưa ra kết luận có nên triển khai không."],"n":["Kết quả đánh giá là cơ sở để phát huy điểm mạnh, khai thác cơ hội, khắc phục điểm yếu và vượt qua thách thức.","Cơ hội chỉ nên triển khai khi đã cân nhắc đủ bốn tiêu chí, tránh chạy theo cảm tính."]}],"sum":["Trong nền kinh tế thị trường, cạnh tranh ngày càng cao đòi hỏi các chủ thể kinh tế phải rèn luyện năng lực, xây dựng ý tưởng kinh doanh tốt và biết nắm bắt cơ hội để kinh doanh thành công.","Khái niệm: Trong nền kinh tế thị trường, cạnh tranh ngày càng cao đòi hỏi các chủ thể kinh tế phải rèn luyện năng lực, xây dựng ý tưởng kinh doanh tốt và biết…","Ý tưởng kinh doanh là ý tưởng…: Ý tưởng kinh doanh là ý tưởng mang tính sáng tạo, khả thi, có khả năng mang lại lợi nhuận trong hoạt động kinh doanh.","Nguồn giúp tạo ý tưởng kinh doanh gồm: Lợi thế nội tại, xuất phát từ đam mê, hiểu biết, khả năng huy động nguồn lực của chủ thể kinh doanh","Cơ hội kinh doanh là sự xuất…: Cơ hội kinh doanh là sự xuất hiện của những điều kiện, hoàn cảnh thuận lợi để thực hiện mục tiêu kinh doanh.","Năng lực cần thiết của người kinh doanh gồm: Năng lực lãnh đạo (định hướng chiến lược, năng động, sáng tạo, nắm bắt cơ hội); năng lực quản lí (tổ chức, thiết lập mối quan hệ kinh doanh); năng…"],"e":["Hay nhầm: Không chỉ là suy nghĩ chung.","Hay nhầm: Không phải kế hoạch nhà nước.","Hay nhầm: Sao chép không phải ý tưởng sáng tạo.","Hay nhầm: Đó không phải vấn đề cơ bản.","Hay nhầm: Không liên quan trực tiếp.","Hay nhầm: Không liên quan trực tiếp."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chủ đề 5. Đạo đức kinh doanh và văn hoá tiêu dùng","l":[{"t":"Bài 7. Đạo đức kinh doanh","req":["Nêu được quan niệm, vai trò của đạo đức kinh doanh.","Chỉ ra được các biểu hiện của đạo đức kinh doanh.","Biết tìm tòi, học hỏi phẩm chất đạo đức của nhà kinh doanh."],"sum":["Đạo đức kinh doanh là yếu tố cơ bản tạo nên uy tín của nhà kinh doanh, giúp doanh nghiệp hoạt động thành công, tồn tại và phát triển.","Khái niệm: Đạo đức kinh doanh là yếu tố cơ bản tạo nên uy tín của nhà kinh doanh, giúp doanh nghiệp hoạt động thành công, tồn tại và phát triển.","Đạo đức kinh doanh là tập hợp…: Đạo đức kinh doanh là tập hợp các nguyên tắc, chuẩn mực đạo đức cơ bản được thể hiện cụ thể trong lĩnh vực kinh doanh, có tác dụng điều chỉnh, đánh…","Biểu hiện của đạo đức kinh doanh thể hiện qua các phẩm chất: Trách nhiệm (hoàn thành nhiệm vụ, tạo giá trị cho xã hội, tuân thủ pháp luật, bảo vệ môi trường); trung thực (giữ chữ tín, công bằng, liêm chính);…","Thực hiện tốt đạo đức kinh doanh…: Thực hiện tốt đạo đức kinh doanh giúp điều chỉnh hành vi của chủ thể kinh doanh theo hướng tích cực, nâng cao chất lượng và uy tín doanh nghiệp, làm…","Khi các phẩm chất này được coi…: Khi các phẩm chất này được coi trọng, doanh nghiệp có thể tạo môi trường kinh doanh lành mạnh, xây dựng thương hiệu được tin cậy và duy trì phát…"],"e":["Hay nhầm: Đây không phải chuẩn mực đạo đức.","Hay nhầm: Đây là quy định lao động.","Hay nhầm: Đây là gian dối nhãn mác.","Hay nhầm: Đây là vi phạm bí mật kinh doanh.","Hay nhầm: Gây thiệt hại cho khách hàng.","Hay nhầm: Trốn tránh trách nhiệm là vi phạm."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 8. Văn hoá tiêu dùng","req":["Nêu được vai trò của tiêu dùng đối với sự phát triển kinh tế.","Nêu được khái niệm và vai trò của văn hoá tiêu dùng.","Mô tả được một số đặc điểm trong văn hoá tiêu dùng Việt Nam và các biện pháp xây dựng văn hoá tiêu dùng."],"sum":["Tiêu dùng được ví như \"đơn đặt hàng\" của xã hội đối với sản xuất; tiêu dùng là mục đích và động lực thúc đẩy sản xuất phát triển.","Khái niệm: Tiêu dùng được ví như \"đơn đặt hàng\" của xã hội đối với sản xuất; tiêu dùng là mục đích và động lực thúc đẩy sản xuất phát triển.","Văn hoá tiêu dùng là bộ phận…: Văn hoá tiêu dùng là bộ phận của văn hoá dân tộc, là những nét đẹp trong tập quán, thói quen tiêu dùng của cộng đồng được hình thành và phát triển…","Vai trò của văn hoá tiêu dùng: Là cơ sở để doanh nghiệp đưa ra chiến lược kinh doanh phù hợp và tạo thiện cảm với người tiêu dùng; là cơ sở duy trì tiêu dùng bền vững; góp phần…","Đặc điểm văn hoá tiêu dùng Việt Nam: Cần cù, chăm chỉ đi đôi với tiết kiệm; văn hoá tiêu dùng đang chuyển dịch theo hướng giảm nhu cầu vật chất tối thiểu, tăng nhu cầu tinh thần và hàng…","Biện pháp xây dựng văn hoá tiêu dùng: Nhà nước ban hành chính sách và thực hiện Luật Bảo vệ quyền lợi người tiêu dùng; doanh nghiệp chủ động sản xuất sản phẩm xanh, sạch, bền vững; giáo…"],"e":["Hay nhầm: Không đồng nghĩa với mua sắm nhiều.","Hay nhầm: Đây không phải khái niệm đúng.","Hay nhầm: Đây không phải khái niệm đúng.","Hay nhầm: Không phải mục tiêu duy nhất.","Hay nhầm: Không phải nguồn vốn cố định.","Hay nhầm: Tiêu dùng thúc đẩy sản xuất, không làm giảm."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chủ đề 6. Quyền bình đẳng của công dân trước pháp luật","l":[{"t":"Bài 9. Quyền bình đẳng của công dân trước pháp luật","req":["Nêu được các quy định cơ bản của pháp luật về quyền bình đẳng của công dân trước pháp luật (bình đẳng về quyền, nghĩa vụ và trách nhiệm pháp lí).","Nhận biết được ý nghĩa của quyền bình đẳng của công dân trước pháp luật đối với đời sống con người và xã hội.","Đánh giá được các hành vi vi phạm quyền bình đẳng của công dân trước pháp luật trong các tình huống đơn giản."],"m":[{"t":"Xác định hành vi vi phạm quyền bình đẳng","w":"Khi gặp tình huống có dấu hiệu phân biệt đối xử.","s":["Xác định hành vi có đối xử khác biệt dựa trên giới tính, dân tộc, tôn giáo, địa vị hay độ tuổi không.","Đối chiếu với quy định của Hiến pháp và pháp luật liên quan.","Nếu vi phạm, giải thích cho người liên quan hoặc phản ánh đến cơ quan có thẩm quyền."],"n":["Sự khác biệt về hoàn cảnh không đồng nghĩa với phân biệt đối xử khi pháp luật áp dụng đúng quy định.","Bình đẳng trước pháp luật là áp dụng cùng một quy định cho mọi người trong điều kiện như nhau."]}],"sum":["Quyền bình đẳng là quyền cơ bản của con người, được Hiến pháp và pháp luật ghi nhận. Không ai bị phân biệt đối xử trước pháp luật; mọi người có quyền, nghĩa vụ ngang nhau và được pháp luật bảo vệ…","Khái niệm: Quyền bình đẳng là quyền cơ bản của con người, được Hiến pháp và pháp luật ghi nhận.","Theo Hiến pháp năm 2013 (Điều 16)…: Theo Hiến pháp năm 2013 (Điều 16), mọi người đều bình đẳng trước pháp luật; không ai bị phân biệt đối xử trong đời sống chính trị, dân sự, kinh tế,…","Công dân bình đẳng về quyền và nghĩa vụ: Mọi công dân, không phân biệt giới tính, dân tộc, tín ngưỡng, tôn giáo, thành phần, địa vị xã hội, độ tuổi, nếu đủ điều kiện theo quy định thì đều…","Công dân bình đẳng về trách nhiệm pháp lí: Mọi người phạm tội đều bình đẳng trước pháp luật; người vi phạm hành chính, vi phạm nghĩa vụ dân sự đều phải chịu trách nhiệm theo quy định.","Ý nghĩa: Tôn trọng sự khác biệt giữa các công dân, tạo điều kiện để mỗi người, nhất là người yếu thế, có điều kiện phát triển; góp phần xây dựng xã hội đoàn…"],"e":["Hay nhầm: Pháp luật không phân biệt địa vị.","Hay nhầm: Không chỉ giới hạn ở độ tuổi lao động.","Hay nhầm: Thực hiện nghĩa vụ là đúng pháp luật.","Hay nhầm: Tuân thủ quy tắc là nghĩa vụ công dân.","Hay nhầm: Không phân biệt giàu nghèo khi nộp thuế.","Hay nhầm: Nghĩa vụ không miễn cho địa vị."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 10. Bình đẳng giới trong các lĩnh vực","req":["Nêu được các quy định cơ bản của pháp luật Việt Nam về bình đẳng giới.","Nhận biết được ý nghĩa của bình đẳng giới đối với đời sống của con người và xã hội.","Đánh giá được các hành vi vi phạm pháp luật về bình đẳng giới trong các tình huống đơn giản."],"sum":["Bình đẳng giới là sự bình đẳng giữa nam và nữ trong các lĩnh vực chính trị, kinh tế, lao động, giáo dục và đào tạo, trong gia đình.","Khái niệm: Bình đẳng giới là sự bình đẳng giữa nam và nữ trong các lĩnh vực chính trị, kinh tế, lao động, giáo dục và đào tạo, trong gia đình.","Lĩnh vực chính trị: Nam, nữ bình đẳng trong tham gia quản lí nhà nước, hoạt động xã hội; bình đẳng trong việc tự ứng cử và được giới thiệu ứng cử đại biểu Quốc hội, đại…","Lĩnh vực kinh tế: Nam, nữ bình đẳng trong việc thành lập doanh nghiệp, tiến hành sản xuất, kinh doanh, quản lí doanh nghiệp, tiếp cận thông tin, nguồn vốn, thị trường…","Lĩnh vực lao động: Nam, nữ bình đẳng về tiêu chuẩn, độ tuổi khi tuyển dụng và được đối xử bình đẳng về việc làm, tiền công, tiền thưởng, bảo hiểm xã hội, điều kiện lao…","Lĩnh vực giáo dục và đào tạo: Nam, nữ bình đẳng về độ tuổi đi học, lựa chọn ngành nghề học tập và tiếp cận chính sách giáo dục (Điều 14)."],"e":["Hay nhầm: Không chỉ là nam với nam.","Hay nhầm: Không phải ưu tiên tuyệt đối.","Hay nhầm: Mức này thấp hơn quy định.","Hay nhầm: Đây là vi phạm pháp luật.","Hay nhầm: Đây là cách tuyển dụng đúng.","Hay nhầm: Đây là cách trả lương đúng."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 11. Quyền bình đẳng giữa các dân tộc","req":["Nêu được các quy định cơ bản của pháp luật về quyền bình đẳng giữa các dân tộc.","Nhận biết được ý nghĩa quyền bình đẳng giữa các dân tộc đối với đời sống con người và xã hội.","Đánh giá được các hành vi vi phạm quyền bình đẳng giữa các dân tộc trong các tình huống đơn giản."],"m":[{"t":"Nhận diện hành vi vi phạm bình đẳng giữa các dân tộc","w":"Khi gặp tình huống có dấu hiệu phân biệt dân tộc.","s":["Xác định hành vi có đối xử khác biệt chỉ vì thành phần dân tộc không.","Đối chiếu với Hiến pháp và pháp luật liên quan (tuyển dụng, bầu cử, giáo dục).","Nếu vi phạm, giải thích hoặc phản ánh đến cơ quan có thẩm quyền."],"n":["Chính sách ưu tiên hợp pháp dành cho người dân tộc thiểu số không phải là phân biệt đối xử.","Phân biệt đối xử vì dân tộc là hành vi bị pháp luật nghiêm cấm trong mọi lĩnh vực."]}],"sum":["Việt Nam là quốc gia thống nhất của các dân tộc cùng sinh sống. Hiến pháp năm 2013 (Điều 5) khẳng định các dân tộc bình đẳng, đoàn kết, tôn trọng và giúp nhau cùng phát triển; nghiêm cấm mọi hành vi…","Khái niệm: Việt Nam là quốc gia thống nhất của các dân tộc cùng sinh sống.","Bình đẳng về chính trị: Các dân tộc có quyền và nghĩa vụ trung thành với Tổ quốc, tham gia tổ chức và hoạt động của Nhà nước.","Bình đẳng về kinh tế: Các dân tộc được Đảng và Nhà nước tạo điều kiện phát triển kinh tế;","Bình đẳng về văn hoá, giáo dục: Các dân tộc có quyền dùng tiếng nói, chữ viết, giữ gìn và phát huy phong tục, tập quán, văn hoá tốt đẹp của mình; mọi công dân không phân biệt dân…","Ý nghĩa: Bình đẳng giữa các dân tộc là cơ sở của khối đại đoàn kết toàn dân tộc, tạo điều kiện để mỗi dân tộc phát huy truyền thống tốt đẹp và cùng xây dựng…"],"e":["Hay nhầm: Không có ưu tiên tuyệt đối.","Hay nhầm: Các dân tộc được dùng tiếng nói riêng.","Hay nhầm: Tiếng Việt là ngôn ngữ quốc gia nhưng không phải duy nhất được dùng.","Hay nhầm: Các dân tộc được giữ phong tục.","Hay nhầm: Không bị giới hạn như vậy.","Hay nhầm: Chính sách không nhằm hạn chế."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 12. Quyền bình đẳng giữa các tôn giáo","req":["Nêu được các quy định cơ bản của pháp luật về quyền bình đẳng giữa các tôn giáo.","Nhận biết được ý nghĩa quyền bình đẳng giữa các tôn giáo đối với đời sống con người và xã hội.","Đánh giá được các hành vi vi phạm quyền bình đẳng giữa các tôn giáo trong các tình huống đơn giản."],"sum":["Các tôn giáo đều bình đẳng về quyền, nghĩa vụ và trách nhiệm pháp lí. Công dân thuộc các tôn giáo khác nhau, người có tôn giáo hoặc không có tôn giáo đều bình đẳng về quyền và nghĩa vụ công dân,…","Khái niệm: Các tôn giáo đều bình đẳng về quyền, nghĩa vụ và trách nhiệm pháp lí.","Bình đẳng về quyền: Hiến pháp năm 2013 (Điều 24) quy định mọi người có quyền tự do tín ngưỡng, tôn giáo, theo hoặc không theo tôn giáo nào; các tôn giáo bình đẳng trước…","Luật Tín ngưỡng, tôn giáo năm 2016…: Luật Tín ngưỡng, tôn giáo năm 2016 quy định các tổ chức tôn giáo đều được hoạt động trong khuôn khổ pháp luật, được xuất bản kinh sách, sinh hoạt…","Bình đẳng về nghĩa vụ: Tổ chức, cá nhân tham gia hoạt động tín ngưỡng, tôn giáo phải tuân thủ Hiến pháp và pháp luật; chức sắc, nhà tu hành có trách nhiệm hướng dẫn tín đồ…","Bình đẳng về trách nhiệm pháp lí: Pháp luật nghiêm cấm phân biệt đối xử, kì thị vì lí do tín ngưỡng, tôn giáo; cấm ép buộc, mua chuộc hoặc cản trở người khác theo hoặc không theo tôn…"],"e":["Hay nhầm: Pháp luật bảo hộ tất cả các tôn giáo.","Hay nhầm: Không có điều kiện như vậy.","Hay nhầm: Người có tôn giáo cũng được bình đẳng.","Hay nhầm: Không phải chỉ người không có tôn giáo.","Hay nhầm: Người có tôn giáo không bị hạn chế.","Hay nhầm: Pháp luật có quy định về tôn giáo."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chủ đề 7. Một số quyền dân chủ cơ bản của công dân","l":[{"t":"Bài 13. Quyền và nghĩa vụ của công dân trong tham gia quản lí nhà nước và xã hội","req":["Nêu được một số quy định cơ bản của pháp luật về quyền và nghĩa vụ của công dân trong tham gia quản lí nhà nước và xã hội.","Nhận biết được hậu quả của hành vi vi phạm quyền và nghĩa vụ của công dân trong tham gia quản lí nhà nước và xã hội.","Tự giác thực hiện các quy định của pháp luật về quyền và nghĩa vụ của công dân trong tham gia quản lí nhà nước và xã hội."],"sum":["Quyền tham gia quản lí nhà nước và xã hội là quyền chính trị quan trọng của công dân, được Hiến pháp và pháp luật quy định.","Khái niệm: Quyền tham gia quản lí nhà nước và xã hội là quyền chính trị quan trọng của công dân, được Hiến pháp và pháp luật quy định.","Theo Hiến pháp năm 2013 (Điều 28)…: Theo Hiến pháp năm 2013 (Điều 28), công dân có quyền tham gia quản lí nhà nước và xã hội, tham gia thảo luận và kiến nghị với cơ quan nhà nước về…","Các quyền cụ thể gồm: Quyền bình đẳng; quyền bầu cử và ứng cử đại biểu; quyền biểu quyết khi Nhà nước trưng cầu ý dân (công dân đủ 18 tuổi trở lên); quyền khiếu nại, tố…","Nghĩa vụ: Tuân theo Hiến pháp và pháp luật; tham gia bảo vệ an ninh quốc gia, trật tự, an toàn xã hội; chấp hành quy tắc sinh hoạt công cộng; trung thành và…","Hậu quả của hành vi vi phạm: Đối với xã hội, ảnh hưởng đến hoạt động của cơ quan nhà nước, xâm phạm trật tự quản lí hành chính;"],"e":["Hay nhầm: Quy chế nội bộ không đủ là căn cứ pháp lí chung.","Hay nhầm: Phong tục không phải nguồn luật này.","Hay nhầm: Điều lệ doanh nghiệp không áp dụng cho quyền công dân.","Hay nhầm: Công dân được tham gia góp ý.","Hay nhầm: Góp ý xây dựng là thực hiện quyền.","Hay nhầm: Đây là thực hiện đúng quyền."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 14. Quyền và nghĩa vụ của công dân về bầu cử và ứng cử","req":["Nêu được một số quy định cơ bản của pháp luật về quyền và nghĩa vụ của công dân về bầu cử và ứng cử.","Nhận biết được hậu quả của hành vi vi phạm quyền và nghĩa vụ của công dân về bầu cử và ứng cử.","Tự giác thực hiện các quy định của pháp luật về quyền và nghĩa vụ của công dân về bầu cử và ứng cử."],"sum":["Quyền bầu cử và quyền ứng cử là quyền chính trị cơ bản của công dân được Hiến pháp và pháp luật quy định.","Khái niệm: Quyền bầu cử và quyền ứng cử là quyền chính trị cơ bản của công dân được Hiến pháp và pháp luật quy định.","Theo Hiến pháp năm 2013 (Điều 27)…: Theo Hiến pháp năm 2013 (Điều 27), công dân từ đủ 18 tuổi trở lên có quyền bầu cử, và từ đủ 21 tuổi trở lên có quyền ứng cử vào Quốc hội, Hội đồng…","Quyền của cử tri: Bỏ phiếu bầu đại biểu Quốc hội và Hội đồng nhân dân các cấp; bình đẳng về bầu cử; tiếp cận thông tin bầu cử; khiếu nại nếu danh sách cử tri có sai…","Quyền của người ứng cử: Tự ứng cử hoặc được giới thiệu ứng cử;","Nghĩa vụ: Tuân thủ quy định về bầu cử và ứng cử; cử tri phải tự mình đi bầu cử và xuất trình thẻ cử tri; không nhờ người khác bỏ phiếu thay (trừ trường hợp…"],"e":["Hay nhầm: Đây không phải tuổi bầu cử.","Hay nhầm: Tuổi này không đúng với quy định.","Hay nhầm: Tuổi này không đúng với quy định.","Hay nhầm: Không nhờ người bỏ phiếu thay trong trường hợp này.","Hay nhầm: Phải bỏ phiếu theo ý của mình.","Hay nhầm: Vẫn có thời hạn để khiếu nại."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 15. Quyền và nghĩa vụ của công dân về khiếu nại, tố cáo","req":["Nêu được một số quy định cơ bản của pháp luật về quyền và nghĩa vụ của công dân về khiếu nại, tố cáo.","Nhận biết được hậu quả của hành vi vi phạm quyền và nghĩa vụ của công dân về khiếu nại, tố cáo.","Tự giác thực hiện các quy định của pháp luật về quyền và nghĩa vụ của công dân về khiếu nại, tố cáo."],"sum":["Quyền khiếu nại và quyền tố cáo là quyền dân chủ cơ bản của công dân được Hiến pháp và pháp luật quy định.","Khái niệm: Quyền khiếu nại và quyền tố cáo là quyền dân chủ cơ bản của công dân được Hiến pháp và pháp luật quy định.","Khiếu nại là việc công dân, cơ…: Khiếu nại là việc công dân, cơ quan, tổ chức hoặc cán bộ, công chức đề nghị cơ quan có thẩm quyền xem xét lại quyết định hành chính, hành vi hành…","Quyền của người khiếu nại: Tự mình khiếu nại hoặc uỷ quyền cho người khác; nhờ luật sư tư vấn; tham gia đối thoại;","Nghĩa vụ của người khiếu nại: Khiếu nại đến đúng người có thẩm quyền; trình bày trung thực, cung cấp thông tin, tài liệu và chịu trách nhiệm trước pháp luật; chấp hành quyết định…","Tố cáo là việc cá nhân báo…: Tố cáo là việc cá nhân báo cho cơ quan có thẩm quyền biết về hành vi vi phạm pháp luật của bất kì cơ quan, tổ chức, cá nhân nào gây thiệt hại hoặc…"],"e":["Hay nhầm: Đây là định nghĩa tố cáo.","Hay nhầm: Đây không phải khiếu nại.","Hay nhầm: Đây không phải khiếu nại.","Hay nhầm: Người tố cáo được đề nghị bảo vệ.","Hay nhầm: Người tố cáo được khen thưởng.","Hay nhầm: Trình bày sai là vi phạm."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 16. Quyền và nghĩa vụ của công dân về bảo vệ Tổ quốc","req":["Nêu được một số quy định cơ bản của pháp luật về quyền và nghĩa vụ của công dân về bảo vệ Tổ quốc.","Nhận biết được hậu quả của hành vi vi phạm quyền và nghĩa vụ của công dân về bảo vệ Tổ quốc.","Tự giác thực hiện các quy định của pháp luật về quyền và nghĩa vụ của công dân về bảo vệ Tổ quốc."],"sum":["Bảo vệ Tổ quốc là bảo vệ độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ, bảo vệ chế độ xã hội chủ nghĩa và Nhà nước Cộng hoà xã hội chủ nghĩa Việt Nam.","Khái niệm: Bảo vệ Tổ quốc là bảo vệ độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ, bảo vệ chế độ xã hội chủ nghĩa và Nhà nước Cộng hoà xã hội chủ nghĩa…","Quyền của công dân về bảo vệ Tổ quốc: Được tuyên truyền, phổ biến về quốc phòng, giáo dục quốc phòng và an ninh;","Nghĩa vụ của công dân về bảo vệ Tổ quốc: Trung thành với Tổ quốc (Hiến pháp năm 2013, Điều 44); thực hiện nghĩa vụ quân sự (Điều 45); tham gia bảo vệ an ninh quốc gia, trật tự, an toàn xã…","Hậu quả của vi phạm: Gây mất an ninh chính trị, trật tự, an toàn xã hội, ảnh hưởng đến khối đại đoàn kết và cản trở sự phát triển đất nước;"],"e":["Hay nhầm: Đây không phải trách nhiệm riêng.","Hay nhầm: Đây không chỉ dành cho công an.","Hay nhầm: Không chỉ khi có chiến tranh.","Hay nhầm: Đóng thuế không là nghĩa vụ duy nhất.","Hay nhầm: Công dân phải tham gia bảo vệ an ninh.","Hay nhầm: Đây không phải quy định của Hiến pháp."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chủ đề 8. Một số quyền tự do cơ bản của công dân","l":[{"t":"Bài 17. Quyền bất khả xâm phạm về thân thể và quyền được pháp luật bảo hộ về tính mạng, sức khoẻ, danh dự, nhân phẩm…","req":["Nêu được một số quy định cơ bản của pháp luật về quyền bất khả xâm phạm về thân thể và quyền được pháp luật bảo hộ về tính mạng, sức khoẻ, danh dự, nhân phẩm của công dân.","Nhận biết được hậu quả của hành vi vi phạm các quyền này.","Hiểu được trách nhiệm của học sinh trong việc thực hiện các quyền này."],"sum":["Quyền bất khả xâm phạm về thân thể và quyền được pháp luật bảo hộ về tính mạng, sức khoẻ, danh dự, nhân phẩm là những quyền con người quan trọng, được Hiến pháp và pháp luật ghi nhận.","Khái niệm: Quyền bất khả xâm phạm về thân thể và quyền được pháp luật bảo hộ về tính mạng, sức khoẻ, danh dự, nhân phẩm là những quyền con người quan trọng,…","Quyền bất khả xâm phạm về thân thể (Hiến pháp năm 2013, Điều 20): Mọi người không bị tra tấn, bạo lực, truy bức, nhục hình; không ai bị bắt nếu không có quyết định của Toà án, quyết định hoặc phê chuẩn của Viện…","Quyền được bảo hộ về tính mạng…: Quyền được bảo hộ về tính mạng, sức khoẻ (Bộ luật Dân sự năm 2015, Điều 33): cá nhân có quyền sống, không ai bị tước đoạt tính mạng trái luật; khi…","Quyền được bảo vệ danh dự, nhân phẩm, uy tín (Điều 34): Cá nhân có quyền yêu cầu Toà án bác bỏ thông tin làm ảnh hưởng xấu, yêu cầu gỡ bỏ, cải chính, xin lỗi công khai và bồi thường thiệt hại.","Hậu quả của vi phạm: Gây tổn hại về sức khoẻ, tính mạng, tâm lí, danh dự, kinh tế cho người bị xâm phạm; gây mất ổn định an ninh, trật tự xã hội."],"e":["Hay nhầm: Quyền không giới hạn độ tuổi.","Hay nhầm: Quyền không phụ thuộc việc làm.","Hay nhầm: Quyền không phụ thuộc nhà ở.","Hay nhầm: Nghi ngờ không đủ căn cứ.","Hay nhầm: Không liên quan đến việc bắt.","Hay nhầm: Đăng video không đáp ứng trách nhiệm."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 18. Quyền bất khả xâm phạm về chỗ ở của công dân","req":["Nêu được một số quy định cơ bản của pháp luật về quyền bất khả xâm phạm về chỗ ở của công dân.","Nhận biết được hậu quả của hành vi vi phạm quyền bất khả xâm phạm về chỗ ở của công dân.","Hiểu được trách nhiệm của học sinh trong việc thực hiện quyền này."],"sum":["Quyền bất khả xâm phạm về chỗ ở là một trong các quyền tự do cơ bản của công dân, được Hiến pháp và pháp luật quy định.","Khái niệm: Quyền bất khả xâm phạm về chỗ ở là một trong các quyền tự do cơ bản của công dân, được Hiến pháp và pháp luật quy định.","Chỗ ở là nhà ở, phương tiện…: Chỗ ở là nhà ở, phương tiện hoặc nhà khác mà công dân sử dụng để cư trú, thuộc quyền sở hữu của công dân hoặc được cho thuê, cho mượn, cho ở nhờ…","Việc khám xét chỗ ở chỉ được…: Việc khám xét chỗ ở chỉ được tiến hành khi có căn cứ và phải có quyết định của cơ quan nhà nước có thẩm quyền.","Hậu quả của vi phạm: Gây mất ổn định an ninh, trật tự xã hội;","Trường hợp được phép: Người đang gặp nguy hiểm như cháy, chập điện, hoặc trẻ em đang bị nguy hiểm mà người lớn vắng mặt, việc vào chỗ ở để cứu giúp là hành động hợp lí,…"],"e":["Hay nhầm: Không chỉ người có nhà riêng.","Hay nhầm: Không phụ thuộc vào việc được cấp nhà.","Hay nhầm: Hàng xóm không có thẩm quyền.","Hay nhầm: Người bị nghi ngờ không tự quyết định.","Hay nhầm: Không phải người nào cũng có quyền.","Hay nhầm: Không được tiến hành tùy tiện."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 19. Quyền được bảo đảm an toàn và bí mật thư tín, điện thoại, điện tín của công dân","req":["Nêu được một số quy định cơ bản của pháp luật về quyền được bảo đảm an toàn và bí mật thư tín, điện thoại, điện tín của công dân.","Nhận biết được hậu quả của hành vi vi phạm quyền này.","Hiểu được trách nhiệm của học sinh trong việc thực hiện quyền này."],"sum":["Quyền được bảo đảm an toàn và bí mật thư tín, điện thoại, điện tín là quyền cơ bản của công dân, thuộc quyền về bí mật đời tư của cá nhân, được cơ quan nhà nước, cán bộ, công chức và mọi người tôn…","Khái niệm: Quyền được bảo đảm an toàn và bí mật thư tín, điện thoại, điện tín là quyền cơ bản của công dân, thuộc quyền về bí mật đời tư của cá nhân, được cơ…","Hiến pháp năm 2013 (Điều 21) quy…: Hiến pháp năm 2013 (Điều 21) quy định mọi người có quyền bí mật thư tín, điện thoại, điện tín và các hình thức trao đổi thông tin riêng tư khác;…","Bộ luật Dân sự năm 2015 (Điều…: Bộ luật Dân sự năm 2015 (Điều 38) quy định thư tín, điện thoại, điện tín, cơ sở dữ liệu điện tử của cá nhân được bảo đảm an toàn và bí mật; việc bóc…","Việc khám xét thư tín, điện tín…: Việc khám xét thư tín, điện tín, bưu kiện, dữ liệu điện tử chỉ được thực hiện khi có căn cứ để nhận định chúng liên quan đến vụ án, theo trình tự,…","Hậu quả của vi phạm: Xâm phạm đời sống riêng tư và bí mật cá nhân; gây ảnh hưởng đến danh dự, nhân phẩm, tâm lí, tiền bạc và công việc của người bị xâm phạm; người vi…"],"e":["Hay nhầm: Không có quyền kiểm soát người khác.","Hay nhầm: Bạn bè không có quyền này.","Hay nhầm: Người đưa thư không có quyền này.","Hay nhầm: Không phải quyền của em trai.","Hay nhầm: Gia đình không có quyền này.","Hay nhầm: Mượn điện thoại không cho phép xem nội dung riêng tư."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 20. Quyền và nghĩa vụ của công dân về tự do ngôn luận, báo chí và tiếp cận thông tin","req":["Nêu được một số quy định cơ bản của pháp luật về quyền và nghĩa vụ của công dân về tự do ngôn luận, báo chí và tiếp cận thông tin.","Nhận biết được hậu quả của hành vi vi phạm quyền và nghĩa vụ này.","Hiểu được trách nhiệm của học sinh trong việc thực hiện quyền và nghĩa vụ này."],"sum":["Quyền tự do ngôn luận, báo chí và tiếp cận thông tin là quyền tự do cơ bản của con người, giúp công dân chủ động và tích cực tham gia quản lí nhà nước và xã hội, đồng thời phát triển bản thân toàn…","Khái niệm: Quyền tự do ngôn luận, báo chí và tiếp cận thông tin là quyền tự do cơ bản của con người, giúp công dân chủ động và tích cực tham gia quản lí nhà…","Quyền tự do báo chí (Luật Báo chí năm 2016, Điều 10): Sáng tạo tác phẩm báo chí; cung cấp thông tin cho báo chí; phản hồi thông tin trên báo chí; tiếp cận thông tin báo chí; liên kết với cơ quan báo…","Quyền tự do ngôn luận trên báo chí (Điều 11): Phát biểu ý kiến về tình hình đất nước và thế giới; tham gia ý kiến xây dựng đường lối, chính sách của Đảng và pháp luật của Nhà nước; góp ý, phê…","Quyền tiếp cận thông tin (Luật Tiếp cận thông tin năm 2016, Điều 8): Công dân được cung cấp thông tin đầy đủ, chính xác, kịp thời; có quyền khiếu nại, khởi kiện, tố cáo hành vi vi phạm pháp luật về tiếp cận thông tin.","Nghĩa vụ của công dân: Tuân thủ pháp luật về ngôn luận, báo chí và tiếp cận thông tin; trung thực, không làm sai lệch nội dung thông tin; chịu trách nhiệm về phát biểu,…"],"e":["Hay nhầm: Công dân có quyền nêu ý kiến.","Hay nhầm: Công dân có quyền bày tỏ ý kiến.","Hay nhầm: Cơ quan không giữ kín thông tin cần thiết.","Hay nhầm: Không có quyền sửa đổi thông tin của cơ quan.","Hay nhầm: Không được tự ý thay đổi.","Hay nhầm: Cần kiểm chứng thông tin."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 21. Quyền và nghĩa vụ của công dân về tự do tín ngưỡng và tôn giáo","req":["Nêu được một số quy định cơ bản của pháp luật về quyền và nghĩa vụ của công dân về tự do tín ngưỡng và tôn giáo.","Nhận biết được hậu quả của hành vi vi phạm quyền và nghĩa vụ của công dân về tự do tín ngưỡng và tôn giáo.","Hiểu được trách nhiệm của học sinh trong việc thực hiện quyền và nghĩa vụ này."],"sum":["Tự do tín ngưỡng và tôn giáo là một trong các quyền tự do cơ bản của công dân, được Hiến pháp và pháp luật quy định;","Khái niệm: Tự do tín ngưỡng và tôn giáo là một trong các quyền tự do cơ bản của công dân, được Hiến pháp và pháp luật quy định;","Hiến pháp năm 2013 (Điều 24) quy…: Hiến pháp năm 2013 (Điều 24) quy định mọi người có quyền tự do tín ngưỡng, tôn giáo, theo hoặc không theo một tôn giáo nào; các tôn giáo bình đẳng…","Luật Tín ngưỡng, tôn giáo năm 2016…: Luật Tín ngưỡng, tôn giáo năm 2016 (Điều 6) quy định mỗi người có quyền bày tỏ niềm tin, thực hành lễ nghi, tham gia lễ hội, học tập giáo lí; người…","Nghĩa vụ của công dân: Tuân thủ Hiến pháp và Luật Tín ngưỡng, tôn giáo; tôn trọng quyền tự do tín ngưỡng, tôn giáo của người khác; không thực hiện hành vi bị pháp luật cấm…","Các hành vi bị nghiêm cấm: Phân biệt đối xử, kì thị, ép buộc hoặc cản trở người khác theo hoặc không theo tôn giáo; xúc phạm tín ngưỡng, tôn giáo; lợi dụng tín ngưỡng, tôn…"],"e":["Hay nhầm: Nhà nước không chọn tôn giáo cho công dân.","Hay nhầm: Không bắt buộc theo tôn giáo.","Hay nhầm: Công dân được tham gia lễ hội.","Hay nhầm: Tự quyết định là chưa đủ.","Hay nhầm: Đây là quyền của công dân.","Hay nhầm: Đây là quyền của công dân."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chủ đề 1. Cạnh tranh, cung – cầu trong nền kinh tế thị trường","l":[{"t":"Bài tập nâng cao · Chủ đề 1. Cạnh tranh, cung – cầu trong nền kinh tế thị trường (2 câu)","e":["Hay nhầm: Lợi nhuận không biện minh cho hành vi trái pháp luật.","Hay nhầm: Không phải luôn làm tăng giá.","Hay nhầm: Người tiêu dùng là người quyết định cầu.","Hay nhầm: Cầu có ảnh hưởng trực tiếp đến sản xuất."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chủ đề 2. Lạm phát, thất nghiệp","l":[{"t":"Bài tập nâng cao · Chủ đề 2. Lạm phát, thất nghiệp (2 câu)","e":["Hay nhầm: Đó là CPI, không phải tỉ lệ.","Hay nhầm: Phục hồi làm thất nghiệp giảm.","Hay nhầm: Đào tạo nghề giúp giảm thất nghiệp.","Hay nhầm: Công nghệ mới có thể gây thất nghiệp cơ cấu, không phải chu kì."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chủ đề 3. Thị trường lao động và việc làm","l":[{"t":"Bài tập nâng cao · Chủ đề 3. Thị trường lao động và việc làm (1 câu)","e":["Hay nhầm: Không nằm trong nhóm lớn nhất.","Hay nhầm: Không nằm trong nhóm lớn nhất.","Hay nhầm: Không nằm trong nhóm lớn nhất."],"q":{"n":1,"lv":{"Nâng cao":1}}}]},{"t":"Chủ đề 4. Ý tưởng, cơ hội kinh doanh và các năng lực cần thiết của người kinh doanh","l":[{"t":"Bài tập nâng cao · Chủ đề 4. Ý tưởng, cơ hội kinh doanh và các năng lực cần thiết của người kinh doanh (1 câu)","e":["Hay nhầm: Chuyên môn là kiến thức ngành, chưa đủ để định hướng chiến lược."],"q":{"n":1,"lv":{"Nâng cao":1}}}]},{"t":"Chủ đề 5. Đạo đức kinh doanh và văn hoá tiêu dùng","l":[{"t":"Bài tập nâng cao · Chủ đề 5. Đạo đức kinh doanh và văn hoá tiêu dùng (2 câu)","e":["Hay nhầm: Quảng cáo phóng đại làm mất tín nhiệm.","Hay nhầm: Lợi nhuận ngắn hạn không đảm bảo lâu dài.","Hay nhầm: Đối thủ không quyết định chữ tín.","Hay nhầm: Doanh nghiệp cần đổi mới.","Hay nhầm: Nhu cầu đang chuyển sang hàng xanh."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chủ đề 6. Quyền bình đẳng của công dân trước pháp luật","l":[{"t":"Bài tập nâng cao · Chủ đề 6. Quyền bình đẳng của công dân trước pháp luật (4 câu)","e":["Hay nhầm: Luật không phân biệt giới trong quyền kinh doanh.","Hay nhầm: Luật không cho phép doanh nghiệp tuyển lao động theo giới.","Hay nhầm: Luật không cho phép doanh nghiệp tuyển lao động theo giới.","Hay nhầm: Không liên quan đến đảng phái.","Hay nhầm: Không làm giảm số đại biểu.","Hay nhầm: Không loại trừ người dân tộc đa số."],"q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chủ đề 7. Một số quyền dân chủ cơ bản của công dân","l":[{"t":"Bài tập nâng cao · Chủ đề 7. Một số quyền dân chủ cơ bản của công dân (4 câu)","e":["Hay nhầm: Gây mất trật tự là vi phạm.","Hay nhầm: Không chỉ áp dụng cho người nước ngoài.","Hay nhầm: Hình phạt của tội này rất nặng."],"q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chủ đề 8. Một số quyền tự do cơ bản của công dân","l":[{"t":"Bài tập nâng cao · Chủ đề 8. Một số quyền tự do cơ bản của công dân (5 câu)","e":["Hay nhầm: Nói thật không phải vu khống.","Hay nhầm: Góp ý không phải vu khống.","Hay nhầm: Bảo vệ người oan không phải vu khống.","Hay nhầm: Phải có đại diện chính quyền.","Hay nhầm: Phải có người chứng kiến.","Hay nhầm: Phải có người đang ở hoặc người thân thành niên."],"q":{"n":5,"lv":{"Nâng cao":5}}}]}]}]}]};
